visits = (rng.poisson(20, (7, 9)) + np.array([0, 5, 10, 15, 8, 20, 25, 12, 4])).astype(int)
visits[6] //= 3                                   # শুক্রবার কম

fig, ax = plt.subplots(figsize=(11, 5.4), facecolor="white")
im = ax.imshow(visits, cmap="magma_r", aspect="auto")
