ax.set_yticks(np.arange(-0.5, len(days)), minor=True)
ax.grid(which="minor", color="white", linewidth=3)
ax.tick_params(which="both", length=0)
for s in ax.spines.values():
    s.set_visible(False)
for i in range(len(days)):
    for j in range(len(hours)):
        v = visits[i, j]
        ax.text(j, i, v, ha="center", va="center", fontsize=10,
                color="white" if v > visits.max() * 0.55 else "#140e29", fontweight="bold")
pi, pj = np.unravel_index(visits.argmax(), visits.shape)
ax.add_patch(plt.Rectangle((pj - 0.5, pi - 0.5), 1, 1, fill=False, ec="#22d3ee", lw=3))
cbar = fig.colorbar(im, ax=ax, fraction=0.03, pad=0.02)
cbar.outline.set_visible(False)
cbar.set_label("Visitors")
ax.set_title(f"Busiest slot: {days[pi]} at {hours[pj]}", loc="left", fontsize=18, fontweight="bold", pad=26)
ax.text(0, 1.03, "Library visitors by day and hour", transform=ax.transAxes, color="#666")
plt.tight_layout()
