TRANSFORMERS_JS_DEMO = '''// দ্রষ্টব্য: প্রথমবার ~৬৫ MB মডেল Hugging Face থেকে নামবে, তারপর ব্রাউজারে cache থাকে
const app = document.getElementById("app");
app.innerHTML = `
  <div style="font:15px system-ui;max-width:560px;margin:auto;padding:8px">
    <b style="font-size:18px">Sentiment, running in your browser</b>
    <textarea id="t" rows="3" style="width:100%;margin:10px 0;font:15px system-ui;padding:8px;border-radius:10px;border:1px solid #c4b5fd">I love how fast this library is!</textarea>
    <button id="go">Analyse</button> <span id="s" style="color:#6b6288">loading model…</span>
    <div id="out" style="margin-top:14px"></div>
  </div>`;
const status = document.getElementById("s"), out = document.getElementById("out");
const bar = (label, p, c) => `<div style="margin:6px 0">${label} ${(p * 100).toFixed(1)}%
  <div style="height:12px;border-radius:9px;background:#f3e8ff"><div style="height:100%;width:${p * 100}%;background:${c};border-radius:9px"></div></div></div>`;

(async () => {
  try {
    const { pipeline } = await import("https://cdn.jsdelivr.net/npm/@huggingface/transformers@3.0.2");
    const classify = await pipeline("sentiment-analysis", "Xenova/distilbert-base-uncased-finetuned-sst-2-english");
    status.textContent = "ready ✔";
    const run = async () => {
      status.textContent = "thinking…";
      const [r] = await classify(document.getElementById("t").value);
      const pos = r.label === "POSITIVE" ? r.score : 1 - r.score;
      out.innerHTML = bar("😊 Positive", pos, "#0d9488") + bar("☹️ Negative", 1 - pos, "#e11d48");
      status.textContent = "ready ✔";
    };
    document.getElementById("go").onclick = run;
    run();
  } catch (e) {
    status.textContent = "মডেল লোড হয়নি (ইন্টারনেট লাগে): " + e.message;
  }
})();'''

