pylib("litestar",
    about=("Litestar হলো FastAPI-র মতোই টাইপ-হিন্ট নির্ভর আধুনিক ASGI ফ্রেমওয়ার্ক, তবে এতে dependency injection, "
           "DTO, ক্যাশ, রেট-লিমিট আর OpenAPI ডক সব বিল্ট-ইন। dataclass বা msgspec মডেল সরাসরি রিকোয়েস্ট ও রেসপন্সে ব্যবহার করা যায়।"),
    install="pip install litestar uvicorn",
    examples=[
        ex("বইয়ের সার্চ API",
           "dataclass দিয়ে বইয়ের মডেল, query parameter দিয়ে খোঁজা; /schema/swagger-এ নিজে নিজে ডক তৈরি হয়।",
           '''from dataclasses import dataclass
from litestar import Litestar, get

@dataclass
class Book:
    id: int
    title: str
    author: str

BOOKS = [
    Book(1, "পথের পাঁচালী", "বিভূতিভূষণ"),
    Book(2, "লালসালু", "সৈয়দ ওয়ালীউল্লাহ"),
    Book(3, "পদ্মা নদীর মাঝি", "মানিক বন্দ্যোপাধ্যায়"),
]

@get("/books")
async def search(q: str = "") -> list[Book]:
    return [b for b in BOOKS if q in b.title or q in b.author]

@get("/books/{book_id:int}")
async def one(book_id: int) -> Book:
    return next(b for b in BOOKS if b.id == book_id)

app = Litestar([search, one])
# চালাও:  uvicorn main:app --reload
# ডক:     http://127.0.0.1:8000/schema/swagger'''),
        ex("Dependency injection ও POST",
           "ডাটাবেসের বদলে একটা ভাগ করা সার্ভিস inject করা হয়; ভুল ডেটা এলে Litestar নিজেই 400 ফেরত দেয়।",
           '''from dataclasses import dataclass
from litestar import Litestar, get, post
from litestar.di import Provide

@dataclass
class Note:
    text: str
    pinned: bool = False

class Store:
    def __init__(self):
        self.items: list[Note] = []

store = Store()

def get_store() -> Store:
    return store

@post("/notes", dependencies={"db": Provide(get_store, sync_to_thread=False)})
async def add(data: Note, db: Store) -> Note:
    db.items.append(data)
    return data

@get("/notes", dependencies={"db": Provide(get_store, sync_to_thread=False)})
async def all_notes(db: Store) -> list[Note]:
    return db.items

app = Litestar([add, all_notes])'''),
    ],
    level="মাঝারি", tag="FastAPI-র আধুনিক বিকল্প, সবকিছু বিল্ট-ইন।",
    tasks=["টাইপ-সেফ REST API", "WebSocket ও stream", "ক্যাশ, রেট-লিমিট, auth"],
    caps=["DTO ও dependency injection", "OpenAPI ডক নিজে তৈরি", "ORM প্লাগইন (SQLAlchemy, Piccolo)"],
    limits=["কমিউনিটি ও টিউটোরিয়াল FastAPI-র চেয়ে কম", "ASGI সার্ভার (uvicorn) আলাদা লাগে"],
    alt="FastAPI, Starlette, Sanic",
)

