    caps=["ObjectType, Mutation", "graphene-django, graphene-sqlalchemy", "Relay সাপোর্ট"],
    limits=["নতুন প্রজেক্টে টাইপ-হিন্ট ভিত্তিক Strawberry আধুনিক", "উন্নয়ন ধীর"],
