pylib("twisted",
    about=("Twisted হলো পুরোনো event-driven নেটওয়ার্ক ফ্রেমওয়ার্ক: TCP, UDP, SSH, DNS সহ অনেক প্রোটোকল সঙ্গে আসে। "
           "কলব্যাক ও Deferred দিয়ে অ্যাসিঙ্ক্রোনাস কাজ হয়। async/await আসার আগে থেকেই এটা ছিল।"),
    install="pip install twisted",
    examples=[
        ex("echo সার্ভার",
           "Protocol ক্লাসে dataReceived ফাংশন লিখলেই হলো; reactor ঘটনার অপেক্ষায় বসে থাকে।",
           '''from twisted.internet import protocol, reactor

class Echo(protocol.Protocol):
    def dataReceived(self, data):
        self.transport.write(b"echo: " + data)

class EchoFactory(protocol.Factory):
    def buildProtocol(self, addr):
        return Echo()

reactor.listenTCP(8000, EchoFactory())
print("localhost:8000-এ শুনছি")
reactor.run()'''),
        ex("লোকাল instrument-এর status collector",
           "প্রতি ২ সেকেন্ডে একটা কাজ চালানো (LoopingCall) আর ফল জমা করা; async/await দিয়েও লেখা যায়।",
           '''import random
from twisted.internet import task, reactor

readings = []

def poll():
    v = round(random.uniform(20, 30), 1)          # আসল প্রজেক্টে instrument থেকে পড়া
    readings.append(v)
    print(f"রিডিং #{len(readings)}: {v}")
    if len(readings) == 5:
        reactor.stop()

task.LoopingCall(poll).start(2.0)
reactor.run()
print("গড়:", round(sum(readings) / len(readings), 2))'''),
    ],
    level="উন্নত", tag="অনেক প্রোটোকলসহ পুরোনো নেটওয়ার্ক ফ্রেমওয়ার্ক।",
    tasks=["নিজস্ব প্রোটোকল সার্ভার", "পুরোনো সিস্টেম রক্ষণাবেক্ষণ", "SSH/DNS সার্ভার"],
    caps=["TCP, UDP, SSH, DNS", "Deferred ও async/await", "প্রোটোকল ক্লাস"],
    limits=["শেখা কঠিন", "নতুন কাজে asyncio-ই সাধারণত যথেষ্ট"],
    alt="asyncio, Tornado",
)

