pylib("rq",
    about=("RQ (Redis Queue) সবচেয়ে সোজা: যেকোনো পাইথন ফাংশনকে Redis-এ কিউ করা যায়, আলাদা `rq worker` সেটা তুলে চালায়। "
           "টাস্ক ডেকোরেটরও লাগে না। ছোট থেকে মাঝারি প্রজেক্টে সহজে বোঝা যায়।"),
    install="pip install rq",
    examples=[
        ex("বড় CSV import-এর status tracker",
           "ফাংশন যেমন আছে তেমনই কিউতে; job.get_status() দিয়ে অবস্থা জানা যায় আর ফল পরে নেওয়া যায়।",
           '''# jobs.py
import time
def import_csv(path):
    time.sleep(3)                      # ভারী কাজ
    return {"rows": 12000, "file": path}

# main.py
from redis import Redis
from rq import Queue
from jobs import import_csv

q = Queue(connection=Redis())
job = q.enqueue(import_csv, "data.csv", job_timeout=600)

print(job.id, job.get_status())        # queued
# অন্য টার্মিনালে:  rq worker
# একটু পরে:         job.refresh(); print(job.get_status(), job.result)'''),
        ex("পুনরায় চেষ্টা ও শিডিউল",
           "ব্যর্থ হলে আবার চেষ্টা, আর নির্দিষ্ট সময়ে চালানোর জন্য enqueue_in।",
           '''from datetime import timedelta
from redis import Redis
from rq import Queue, Retry
from jobs import import_csv

q = Queue(connection=Redis())
q.enqueue(import_csv, "retry.csv", retry=Retry(max=3, interval=[10, 30, 60]))
q.enqueue_in(timedelta(minutes=5), import_csv, "later.csv")      # ৫ মিনিট পর'''),
    ],
    level="শুরু", tag="সবচেয়ে সহজ Redis-ভিত্তিক কিউ।",
    tasks=["ফাংশন ব্যাকগ্রাউন্ডে চালানো", "ছোট প্রজেক্টে কিউ", "কাজের অবস্থা ট্র্যাক"],
    caps=["যেকোনো ফাংশন কিউ", "retry, দেরি, ডিপেন্ডেন্সি", "rq-dashboard"],
    limits=["শুধু Redis", "Windows-এ worker সীমিত (WSL ভালো)"],
    alt="Celery, Huey, Dramatiq",
)

