PYPLAY_RUNNER = r'''
import sys, os, re, json, base64, tempfile, traceback
os.environ["MPLBACKEND"] = "Agg"
os.environ["DJANGO_ALLOW_ASYNC_UNSAFE"] = "true"     # ব্রাউজারে সব কোড একটা ইভেন্ট লুপের ভেতরে চলে
_src = __pp_src
# asyncio.run(...) ব্রাউজারের ইভেন্ট লুপে চলে না → টপ-লেভেল await বানাই
_src = re.sub(r"^(\s*)asyncio\.run\((.+)\)\s*$", r"\1await \2", _src, flags=re.M)
_src = re.sub(r"^(\s*)(?:anyio|trio)\.run\(([\w.]+)\s*(?:,[^)]*)?\)\s*(#.*)?$", r"\1await \2()", _src, flags=re.M)
_wd = tempfile.mkdtemp(prefix="run_")
os.chdir(_wd)
_ns = {"__name__": "__main__"}
if __pp_pre:
    exec(__pp_pre, _ns)
if "matplotlib" in _src or "seaborn" in _src:
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as _plt
    _plt.show = lambda *a, **k: None
    _plt.close("all")
_err = None
try:
    from pyodide.code import eval_code_async
    await eval_code_async(_src, _ns, filename="main.py")
except SystemExit:
    pass
except BaseException as _e:
    _tb = [f for f in traceback.extract_tb(_e.__traceback__) if f.filename == "main.py"]
    _where = f"লাইন {_tb[-1].lineno}: {(_tb[-1].line or '').strip()}\n" if _tb else ""
    _err = _where + "".join(traceback.format_exception_only(_e)).strip()
_figs = []
if "matplotlib.pyplot" in sys.modules:
    import io
    import matplotlib.pyplot as _plt
    for _n in _plt.get_fignums():
        _b = io.BytesIO()
        _plt.figure(_n).savefig(_b, format="png", dpi=110, bbox_inches="tight", facecolor="auto")
        _figs.append(base64.b64encode(_b.getvalue()).decode())
    _plt.close("all")
_TEXT = (".csv", ".json", ".txt", ".md", ".sql", ".yaml", ".yml", ".xml", ".log", ".ini", ".toml", ".py", ".jsonl", ".html")
_IMG = {".png": "png", ".jpg": "jpeg", ".jpeg": "jpeg", ".gif": "gif", ".webp": "webp", ".svg": "svg+xml"}
_files = []
for _root, _dirs, _names in os.walk(_wd):
    for _f in sorted(_names):
        _p = os.path.join(_root, _f)
        _rel = os.path.relpath(_p, _wd)
        _ext = os.path.splitext(_f)[1].lower()
        _info = {"name": _rel, "size": os.path.getsize(_p)}
        if _ext in _IMG and _info["size"] < 1_500_000:
            _info["img"] = f"data:image/{_IMG[_ext]};base64," + base64.b64encode(open(_p, "rb").read()).decode()
        elif _ext in _TEXT:
            _info["text"] = open(_p, encoding="utf-8", errors="replace").read(1500)
        _files.append(_info)
        if len(_files) >= 12:
            break
__pp_ns, __pp_wd = _ns, _wd
json.dumps({"err": _err, "figs": _figs, "files": _files})
'''

PYPLAY_SQL = r'''
def __pp_con():
    import sqlite3, os
    for v in list(__pp_ns.values()):
        if isinstance(v, sqlite3.Connection):
            try:
                v.execute("select 1")
                return v
            except Exception:
                pass
        t = type(v).__name__
        if t == "Engine" and getattr(v.url, "drivername", "").startswith("sqlite") and v.url.database not in (None, "", ":memory:"):
            return sqlite3.connect(os.path.join(__pp_wd, v.url.database))
        if t in ("SqliteDatabase", "SqliteExtDatabase"):
            try:
                return v.connection()
            except Exception:
                pass
    for root, _, names in os.walk(__pp_wd):
        for f in names:
            if f.endswith((".db", ".sqlite", ".sqlite3")):
                return sqlite3.connect(os.path.join(root, f))
    return None

def __pp_sql(q):
    import json
    con = __pp_con()
    if con is None:
        return json.dumps({"err": "কোনো sqlite ডেটাবেস পাওয়া যায়নি – আগে ▶ চালাও"})
    tables = [r[0] for r in con.execute("select name from sqlite_master where type in ('table','view') and name not like 'sqlite_%' order by name")]
    if not q.strip():
        return json.dumps({"tables": tables})
    try:
        cur = con.execute(q)
        cols = [d[0] for d in cur.description] if cur.description else []
        rows = cur.fetchmany(200) if cols else []
        if not cols:
            con.commit()
        rows = [[x if isinstance(x, (int, float)) or x is None else str(x) for x in r] for r in rows]
        return json.dumps({"cols": cols, "rows": rows, "n": cur.rowcount, "tables": tables})
    except Exception as e:
        return json.dumps({"err": f"{type(e).__name__}: {e}", "tables": tables})
'''

