work("chef-A", 3)
work("chef-B", 2, crash=True)
work("chef-A", 5)

pending = r.xpending("orders", "kitchen")
print(f"\nঝুলে আছে: {pending['pending']}টা (consumer: {[c['name'] for c in pending['consumers']]})")
_, claimed, _ = r.xautoclaim("orders", "kitchen", "chef-A", min_idle_time=0, start_id="0")
for mid, f in claimed:
    r.xack("orders", "kitchen", mid)
print("chef-A উদ্ধার করে রান্না করল:", [f["item"] for _, f in claimed])
print("এখন ঝুলে আছে:", r.xpending("orders", "kitchen")["pending"])
total = sum(int(f["taka"]) for _, f in r.xrange("orders"))
