VALKEY_PRE = r'''
import fakeredis, valkey
_fake_server = fakeredis.FakeServer()
class _V(fakeredis.FakeRedis):
    def __init__(self, *a, **k):
        k.pop("host", None); k.pop("port", None)
        super().__init__(*a, server=_fake_server, **k)
    @classmethod
    def from_url(cls, url, **k):
        return cls(**k)
valkey.Valkey = _V
valkey.from_url = _V.from_url
def _register_script(self, script):        # ব্রাউজারের fakeredis-এ Lua নেই: এই ডেমোর স্ক্রিপ্টটা পাইথনে
    def run(keys=(), args=(), client=None):
        return self.delete(keys[0]) if self.get(keys[0]) == args[0] else 0
    return run
_V.register_script = _register_script
'''

