jslib("PouchDB",
    about=("PouchDB হলো ব্রাউজারে চলা ডকুমেন্ট ডেটাবেস যা CouchDB-র সাথে সিঙ্ক করে – অফলাইনে কাজ চলে, ইন্টারনেট এলে নিজে মিলিয়ে নেয়। "
           "প্রতিটা ডকুমেন্টের রিভিশন (_rev) থাকে, তাই দুই জায়গায় একসাথে বদল হলে কনফ্লিক্ট ধরা পড়ে, কিছু হারায় না।"),
    install="npm install pouchdb-browser",
    examples=[
        jlive("pouchdb", "রিভিশন ও কনফ্লিক্ট বোঝা",
              "একটা নোট সেভ করো – প্রতি সেভে _rev বদলায়। 'পুরনো রিভিশন দিয়ে সেভ' চাপলে PouchDB 409 conflict দিয়ে আটকায় – "
              "অর্থাৎ অন্যের বদল চুপচাপ মুছে যায় না।",
              r'''const db = new PouchDB("notes-demo");
let doc;
try { doc = await db.get("note-1"); }
catch { await db.put({ _id: "note-1", text: "প্রথম খসড়া" }); doc = await db.get("note-1"); }

const app = document.getElementById("app");
app.innerHTML = `<textarea id="t" rows="3" style="width:100%"></textarea>
  <div class="row"><button class="pri" id="save">সেভ</button><button id="stale">পুরনো রিভিশন দিয়ে সেভ</button></div>
  <div class="card mono" id="rev"></div><div id="log" style="margin-top:8px"></div>`;
const $ = s => app.querySelector(s);
let staleRev = doc._rev;
$("#t").value = doc.text;

async function showRevs() {
  const d = await db.get("note-1", { revs_info: true });
  $("#rev").innerHTML = "_rev এখন: <b>" + d._rev + "</b><br>ইতিহাস: " + d._revs_info.map(r => r.rev.split("-")[0]).join(" ← ");
}
const log = (msg, cls = "") => $("#log").insertAdjacentHTML("afterbegin", `<div class="${cls}">${new Date().toLocaleTimeString()} · ${msg}</div>`);

$("#save").onclick = async () => {
  const cur = await db.get("note-1");
  staleRev = cur._rev;                            // এটাকে পরে 'পুরনো' হিসেবে ব্যবহার করব
  const res = await db.put({ ...cur, text: $("#t").value });
  log(`✓ সেভ হলো → নতুন rev ${res.rev.slice(0, 12)}…`, "ok");
  showRevs();
};
$("#stale").onclick = async () => {
  try {
    await db.put({ _id: "note-1", _rev: staleRev, text: $("#t").value + " (অন্য ট্যাব থেকে)" });
    log("সেভ হলো (rev তখনো সর্বশেষ ছিল) – এখন আবার চাপো", "ok");
    staleRev = (await db.get("note-1"))._rev;
  } catch (e) {
    log(`✗ ${e.status} ${e.name}: পুরনো _rev দিয়ে লেখা যায় না – আগে সর্বশেষটা পড়ো`, "err");
  }
  showRevs();
};
showRevs();''', hint="দুটো বোতাম পালা করে চাপো", shim=POUCH_SHIM),
        jlive("pouchdb", "দুই ডিভাইসের লাইভ সিঙ্ক: অফলাইন বদল ও কনফ্লিক্ট সমাধান",
              "📱 ফোন আর 💻 ল্যাপটপ – দুটো আলাদা ডেটাবেস, দুই দিকে লাইভ সিঙ্ক। একটায় লিখলে অন্যটায় সাথে সাথে দেখায়। "
              "ফোনকে 'অফলাইন' করে দুই জায়গায় একই আইটেম বদলাও, তারপর অনলাইন করো – PouchDB দুটোই রাখে, একটাকে জয়ী করে, "
              "আর আমরা কনফ্লিক্ট দেখিয়ে মিলিয়ে দিই।",
              r'''const phone = new PouchDB("phone-demo"), laptop = new PouchDB("laptop-demo");
if (!(await phone.allDocs()).rows.length)       // শুধু ফোনে ডেটা; ল্যাপটপ পাবে সিঙ্ক দিয়ে
  await phone.bulkDocs([{ _id: "rice", qty: 2, by: "phone" }, { _id: "fish", qty: 1, by: "phone" }, { _id: "tea", qty: 1, by: "phone" }]);

const app = document.getElementById("app");
app.innerHTML = `<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">
  ${["phone", "laptop"].map(n => `<div class="card" id="${n}">
    <b>${n === "phone" ? "📱 ফোন" : "💻 ল্যাপটপ"}</b> <span class="muted" data-st></span>
    <div data-list></div>
    <div class="row" data-add><input placeholder="নতুন জিনিস" style="width:100px"><button>যোগ</button></div></div>`).join("")}</div>
  <div class="row"><button class="pri" id="net">📱 ফোন অফলাইন করো</button><span class="muted" id="sync"></span></div>
  <div id="log" class="muted"></div>`;
const $ = s => app.querySelector(s);
const dbs = { phone, laptop };
let sync = null, queue = Promise.resolve();

async function render(name) {
  const db = dbs[name], box = $("#" + name);
  const { rows } = await db.allDocs({ include_docs: true, conflicts: true });
  box.querySelector("[data-list]").innerHTML = rows.map(({ doc }) => `
    <div class="row" style="margin:3px 0"><span style="flex:1">${doc._id}${doc._conflicts ? ` <span title="কনফ্লিক্ট" style="color:#d97706">⚡${doc._conflicts.length}</span>` : ""}</span>
    <button data-db="${name}" data-id="${doc._id}" data-d="-1">−</button><b>${doc.qty}</b>
    <button data-db="${name}" data-id="${doc._id}" data-d="1">+</button></div>`).join("");
  box.querySelector("[data-st]").textContent = `${rows.length}টা`;
}
const renderAll = () => Promise.all(["phone", "laptop"].map(render));
const log = m => $("#log").insertAdjacentHTML("afterbegin", `<div>${new Date().toLocaleTimeString()} · ${m}</div>`);

async function resolveConflicts(db) {            // নিয়ম: দুই পাশের পরিমাণের মধ্যে বড়টা রাখো
  const { rows } = await db.allDocs({ include_docs: true, conflicts: true });
  for (const { doc } of rows) if (doc._conflicts) {
    const losers = await Promise.all(doc._conflicts.map(rev => db.get(doc._id, { rev })));
    const best = Math.max(doc.qty, ...losers.map(l => l.qty));
    const { _conflicts, ...clean } = doc;
    await db.put({ ...clean, qty: best, by: "merge", at: Date.now() });
    for (const l of losers) await db.remove(l);
    log(`⚡ '${doc._id}' কনফ্লিক্ট: ${[doc, ...losers].map(x => `${x.by}=${x.qty}`).join(" বনাম ")} → বড়টা ${best} রাখা হলো`);
  }
}

function goOnline() {
  sync = phone.sync(laptop, { live: true, retry: true })
    .on("change", info => {
      log(`↔ ${info.direction === "push" ? "ফোন → ল্যাপটপ" : "ল্যাপটপ → ফোন"}: ${info.change.docs.length}টা বদল`);
      queue = queue.then(() => resolveConflicts(phone)).catch(() => {}).then(renderAll);   // একটার পর একটা
    })
    .on("paused", () => $("#sync").textContent = "✓ মিলানো");
  $("#net").textContent = "📱 ফোন অফলাইন করো";
  $("#sync").textContent = "সিঙ্ক চালু";
}
$("#net").onclick = () => {
  if (sync) { sync.cancel(); sync = null; $("#net").textContent = "📶 ফোন অনলাইন করো"; $("#sync").textContent = "📵 ফোন অফলাইন – দুই জায়গায় 'rice' বদলাও"; log("ফোন অফলাইন"); }
  else { log("ফোন আবার অনলাইন – মিলানো শুরু"); goOnline(); }
};
app.onclick = async e => {
  const { db, id, d } = e.target.dataset;
  if (!db) return;
  const doc = await dbs[db].get(id);
  await dbs[db].put({ ...doc, qty: Math.max(0, doc.qty + +d), by: db, at: Date.now() });   // কে, কখন বদলাল
  render(db);
};
for (const name of ["phone", "laptop"])
  $("#" + name).querySelector("[data-add] button").onclick = async () => {
    const input = $("#" + name).querySelector("[data-add] input");
    if (input.value) await dbs[name].put({ _id: input.value.toLowerCase(), qty: 1, by: name }).catch(() => {});
    input.value = ""; render(name);
  };
goOnline();
renderAll();''', hint="প্রজেক্ট", shim=POUCH_SHIM),
    ],
    level="মাঝারি", tag="অফলাইনে চলা, নিজে সিঙ্ক হওয়া ব্রাউজার ডেটাবেস।",
    tasks=["অফলাইন-ফার্স্ট মোবাইল/ওয়েব অ্যাপ", "একাধিক ডিভাইসে ডেটা সিঙ্ক", "মাঠ-পর্যায়ের ডেটা সংগ্রহ (ইন্টারনেট ছাড়া)"],
    caps=["CouchDB প্রোটোকলে দুই দিকে live sync", "রিভিশন ও কনফ্লিক্ট ট্র্যাকিং", "find() (Mango কোয়েরি), map/reduce", "IndexedDB, memory, LevelDB অ্যাডাপ্টার"],
    limits=["সিঙ্কের জন্য CouchDB/Couchbase সার্ভার লাগে", "বড় ডেটায় ধীর হতে পারে", "রিলিজ ধীর হয়ে গেছে"],
    alt="RxDB, Dexie.js (Dexie Cloud), Firebase/Firestore",
)


