for Vis, ax in [(ClassificationReport, axes[0]), (ConfusionMatrix, axes[1])]:
    extra = {"support": True} if Vis is ClassificationReport else {}
    v = Vis(LogisticRegression(max_iter=500), classes=classes, ax=ax, force_model=True, **extra)
    v.fit(X_tr, y_tr)
