cand["pred"] = pred
print(f"\n{u} বেশি পছন্দ করেছে:", ", ".join(f"{r.book} ({r.rating:.0f}★)" for r in fav.itertuples()))
print("তাকে সুপারিশ:", ", ".join(f"{r.book} ({r.pred:.1f})" for r in cand.sort_values("pred", ascending=False).head(4).itertuples()))

emb = learn.model.i_weight.weight[1:].detach().numpy()
names = list(dls.classes["book"][1:])
emb = emb - emb.mean(0)
pc = emb @ np.linalg.svd(emb, full_matrices=False)[2][:2].T
