LOCAL_SHOP = r'''# --- ডেমোর জন্য নিজের ছোট ওয়েবসাইট (আসল কাজে এর বদলে আসল URL) ---
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, urlparse

BOOKS = [(i, t, a, p) for i, (t, a, p) in enumerate([
    ("Gitanjali", "Tagore", 250), ("Gora", "Tagore", 480), ("Himu", "Humayun Ahmed", 200), ("Misir Ali", "Humayun Ahmed", 220),
    ("Feluda Samagra", "Satyajit Ray", 950), ("Lalsalu", "Syed Waliullah", 180), ("Pather Panchali", "Bibhutibhushan", 320),
    ("Devdas", "Sarat Chandra", 160), ("Agnibeena", "Nazrul", 140), ("Amar Bondhu Rashed", "Zafar Iqbal", 230),
    ("Padma Nadir Majhi", "Manik Bandopadhyay", 260), ("Chokher Bali", "Tagore", 300)], 1)]

class Shop(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass
    def page(self, body, code=200, cookie=None):
        self.send_response(code)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        if cookie:
            self.send_header("Set-Cookie", cookie)
        self.end_headers()
        self.wfile.write(f"<html><head><title>বইঘর</title></head><body>{body}</body></html>".encode())
    def do_GET(self):
        u = urlparse(self.path); q = parse_qs(u.query)
        if u.path == "/":
            self.page('<h1>বইঘর</h1><a href="/books?page=1">সব বই</a> <a href="/login">লগইন</a>')
        elif u.path == "/books":
            p = int(q.get("page", ["1"])[0]); items = BOOKS[(p - 1) * 4:p * 4]
            rows = "".join(f'<div class="book"><a href="/book/{i}"><h2>{t}</h2></a><span class="author">{a}</span>'
                           f'<span class="price">৳{pr}</span></div>' for i, t, a, pr in items)
            nxt = f'<a class="next" href="/books?page={p + 1}">পরের পাতা</a>' if p * 4 < len(BOOKS) else ""
            self.page(rows + nxt)
        elif u.path.startswith("/book/"):
            i, t, a, pr = BOOKS[int(u.path.split("/")[-1]) - 1]
            self.page(f'<h1 itemprop="name">{t}</h1><p>লেখক: <b class="author">{a}</b></p><p class="price">৳{pr}</p>'
                      f'<p class="stock">{"স্টকে আছে" if i % 3 else "শেষ"}</p>')
        elif u.path == "/login":
            self.page('<form method="post" action="/login"><input name="user"><input name="password" type="password">'
                      '<input type="hidden" name="csrf" value="tok-42"><button>ঢোকো</button></form>')
        elif u.path == "/orders":
            ok = "session=sumi" in (self.headers.get("Cookie") or "")
            self.page('<table id="orders"><tr><td>#1021</td><td>Gora</td><td>৳480</td></tr>'
                      '<tr><td>#1033</td><td>Himu</td><td>৳200</td></tr></table>' if ok else "<p>আগে লগইন করো</p>", 200 if ok else 403)
        else:
            self.page("নেই", 404)
    def do_POST(self):
        data = parse_qs(self.rfile.read(int(self.headers["Content-Length"])).decode())
        if data.get("csrf") == ["tok-42"] and data.get("password") == ["secret"]:
            self.page(f'<p>স্বাগতম, {data["user"][0]}!</p><a href="/orders">আমার অর্ডার</a>', cookie="session=sumi")
        else:
            self.page("<p class='error'>ভুল পাসওয়ার্ড</p>", 401)

server = ThreadingHTTPServer(("127.0.0.1", 0), Shop)
threading.Thread(target=server.serve_forever, daemon=True).start()
BASE = f"http://127.0.0.1:{server.server_port}"
# --- এখান থেকে আসল স্ক্র্যাপিং কোড ---
'''

