words = lambda s: len(re.findall(r"\w+", s or ""))
rows, corpus = [], []
for name, html in [("News", news), ("Blog", blog), ("Forum", forum)]:
    raw = trafilatura.html2txt(html)                       # সব লেখা (আবর্জনাসহ)
    md = trafilatura.extract(html, output_format="markdown", include_formatting=True, with_metadata=False)
    meta = trafilatura.extract_metadata(html)
    rows.append((name, words(raw), words(md)))
    corpus.append({"source": name, "title": meta.title if meta else None, "text": md})
    print(f"── {name}: {meta.title if meta else ''}\n{md[:180]}…\n")

with open("corpus.jsonl", "w", encoding="utf-8") as f:
    for doc in corpus:
        f.write(json.dumps(doc, ensure_ascii=False) + "\n")
