months = ["জানু", "ফেব্রু", "মার্চ", "এপ্রি", "মে", "জুন", "জুলা", "আগ", "সেপ্টে", "অক্টো", "নভে", "ডিসে"]
loans = [420, 910, 610, 480, 450, 380, 520, 560, 590, 640, 700, 760]          # ফেব্রুয়ারিতে বইমেলা
members = [("রাফিদ", "নবম", 64), ("তাসনিম", "দশম", 58), ("অনন্যা", "অষ্টম", 55), ("ইমরান", "নবম", 51), ("জুই", "সপ্তম", 47)]
books = [(f"বই #{i + 1:03d}", random.choice(["উপন্যাস", "বিজ্ঞান", "ইতিহাস", "কবিতা", "কমিকস"]), random.randint(8, 70))
         for i in range(60)]

# ---- matplotlib → SVG (svg.fonttype=none: লেখা text থাকে, WeasyPrint নিজে বাংলা সাজায়) ----
