# ডেমোতে বানানো PDF দেখাতে PDF.js দিয়ে ক্যানভাসে আঁকা (দেখানো কোডে নেই – শুধু লাইভ ডেমোতে)
PDF_PREVIEW = r'''
const __pdfjs = await import("https://cdn.jsdelivr.net/npm/pdfjs-dist@%s/build/pdf.min.mjs");
__pdfjs.GlobalWorkerOptions.workerSrc = "https://cdn.jsdelivr.net/npm/pdfjs-dist@%s/build/pdf.worker.min.mjs";
window.showPDF = async (bytes, el, { scale = 0.75, max = 6 } = {}) => {
  el.innerHTML = "";
  const pdf = await __pdfjs.getDocument({ data: bytes.slice() }).promise;
  for (let i = 1; i <= Math.min(pdf.numPages, max); i++) {
    const page = await pdf.getPage(i), dpr = window.devicePixelRatio || 1;
    const vp = page.getViewport({ scale: scale * dpr }), c = document.createElement("canvas");
    c.width = vp.width; c.height = vp.height; c.style.width = vp.width / dpr + "px";
    c.style.cssText += ";margin:4px;border-radius:6px;background:#fff;box-shadow:0 3px 12px -6px rgba(76,29,149,.5)";
    el.append(c);
    await page.render({ canvas: c, viewport: vp }).promise;
  }
  return pdf.numPages;
};
''' % (PDFJS_V, PDFJS_V)


