doc.fillOpacity(1).fill("#140e29");
doc.font("Helvetica-Bold").fontSize(24).fillColor("white").text("Tanguar Haor", 30, 40);
doc.font("Helvetica").fontSize(11).fillColor("#ede9fe").text("Sunamganj, Bangladesh - field notes", 30, 72);
