names = det.data["class_name"]
print("পাওয়া গেছে:", {n: int((names == n).sum()) for n in set(names)})
labels = [f"{n} {c:.2f}" for n, c in zip(names, det.confidence)]
out = sv.RoundBoxAnnotator(thickness=3).annotate(img.copy(), det)
