from collections import Counter
import matplotlib.pyplot as plt
import networkx as nx
from flair.data import Sentence
from flair.models import SequenceTagger
from flair.splitter import SegtokSentenceSplitter

news = """The Padma Bridge links Munshiganj and Shariatpur and was built by China Major Bridge Engineering.
BRAC opened a new school programme in Sunamganj with support from UNICEF.
Shakib Al Hasan played for Bangladesh against India in Chattogram.
The World Bank and the Asian Development Bank discussed climate funding in Dhaka.
Grameenphone and Robi expanded 5G coverage in Sylhet and Dhaka.
UNICEF and BRAC distributed flood relief in Sylhet and Sunamganj.
Tamim Iqbal and Shakib Al Hasan joined the Bangladesh team camp in Mirpur.
The Asian Development Bank approved a loan for Chattogram port."""
tagger = SequenceTagger.load("flair/ner-english-fast")
sents = SegtokSentenceSplitter().split(news)
tagger.predict(sents, mini_batch_size=8)

kinds, pairs = {}, Counter()
for s in sents:
    ents = sorted({e.text for e in s.get_spans("ner")})
    for e in s.get_spans("ner"):
        kinds[e.text] = e.get_label("ner").value
    pairs.update(itertools.combinations(ents, 2))
count = Counter(e.text for s in sents for e in s.get_spans("ner"))
print("সবচেয়ে বেশি আসা সত্তা:")
for e, n in count.most_common(8):
    print(f"  {kinds[e]:<4} {e:<28} {n} বার")

G = nx.Graph()
for (a, b), w in pairs.items():
    G.add_edge(a, b, weight=w)
col = {"PER": "#e11d48", "ORG": "#7c3aed", "LOC": "#0d9488", "MISC": "#f59e0b"}
