nx.draw_networkx_edges(G, pos, width=[1 + 2 * G[a][b]["weight"] for a, b in G.edges], edge_color="#6b6288", ax=ax)
nx.draw_networkx_nodes(G, pos, node_size=[300 + 250 * count[n] for n in G], node_color=[col.get(kinds.get(n), "#999") for n in G], ax=ax)
for n, (x, y) in pos.items():
    ax.text(x, y + 0.07, n, color="white", fontsize=9, ha="center")
for k, (t, c) in enumerate(col.items()):
    ax.text(0.01, 0.97 - k * 0.04, {"PER": "person", "ORG": "organisation", "LOC": "place", "MISC": "other"}[t],
            color=c, transform=ax.transAxes, fontsize=11, fontweight="bold")
top = count.most_common(1)[0]
ax.set_title(f"{G.number_of_nodes()} entities from {len(sents)} sentences; {top[0]} is the most connected story thread",
             color="white", loc="left", fontsize=13)
ax.set_axis_off()
plt.show()
