ax.set_ylim(-0.8, 2.6)
ax.set_axis_off()
ax.set_title(f"Dependency parse: '{s.text}'  ->  {len(triples)} subject-verb-object facts extracted from {len(doc.sentences)} sentences",
             color="white", loc="left", fontsize=11)
plt.show()
