P = np.array([[0.40, 0.05, 0.02], [0.05, 0.35, 0.08], [0.02, 0.08, 0.45]])
A, labels = sbm(n=n, p=P, return_labels=True)
print("নোড:", A.shape[0], "| এজ:", int(A.sum() / 2), "| দলভিত্তিক ঘনত্ব:")
for i in range(3):
    print("  ", [round(A[np.ix_(labels == i, labels == j)].mean(), 2) for j in range(3)])
heatmap(A, inner_hier_labels=labels, title="SBM adjacency matrix: three dense blocks", cbar=False, figsize=(7, 7))
