pylib("torch-geometric",
    about=("PyTorch Geometric (PyG) গ্রাফ নিউরাল নেটওয়ার্কের (GNN) সবচেয়ে জনপ্রিয় লাইব্রেরি – GCN, GAT, GraphSAGE, GIN… ৬০+ লেয়ার, মেসেজ-পাসিং বেস-ক্লাস, "
           "ডেটাসেট (Cora, OGB…), মিনি-ব্যাচ, নেইবার-স্যাম্পলিং, হেটেরোজেনিয়াস গ্রাফ। নোড-ক্লাসিফিকেশন, লিংক-প্রেডিকশন, অণুর ধর্ম অনুমান, রেকমেন্ডেশন।"),
    install="pip install torch_geometric\n# (ঐচ্ছিক দ্রুত এক্সটেনশন: pyg_lib, torch_scatter – data.pyg.org থেকে)",
    examples=[
        ex("প্রথম GNN: করাতে-ক্লাবে কে কোন দলে",
           "৩৪ সদস্যের ক্লাব-গ্রাফে প্রতি দল থেকে মাত্র ১ জনের লেবেল জানা; দুই স্তরের GCN প্রতিবেশীদের তথ্য মিশিয়ে বাকিদের দল অনুমান করে।",
           r'''import torch
import torch.nn.functional as F
from torch_geometric.datasets import KarateClub
from torch_geometric.nn import GCNConv

torch.manual_seed(1)
data = KarateClub()[0]
print(data)
train = torch.zeros(data.num_nodes, dtype=torch.bool)
for c in data.y.unique():
    train[(data.y == c).nonzero()[0]] = True              # প্রতি দল থেকে একজন

class GCN(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self.c1, self.c2 = GCNConv(data.num_features, 16), GCNConv(16, int(data.y.max()) + 1)
    def forward(self, x, ei):
        return self.c2(F.relu(self.c1(x, ei)), ei)

model = GCN()
opt = torch.optim.Adam(model.parameters(), lr=0.01, weight_decay=5e-4)
for epoch in range(201):
    opt.zero_grad()
    loss = F.cross_entropy(model(data.x, data.edge_index)[train], data.y[train])
    loss.backward()
    opt.step()
    if epoch % 50 == 0:
        acc = (model(data.x, data.edge_index).argmax(1)[~train] == data.y[~train]).float().mean()
        print(f"epoch {epoch:3d} · loss {loss.item():.3f} · বাকিদের নির্ভুলতা {acc:.0%}")
'''),
        ex("প্রজেক্ট: গ্রাফ কাজে লাগলে কত লাভ – MLP বনাম GCN বনাম GAT",
           "একটা 'সাইটেশন'-ধাঁচের নেটওয়ার্ক: ৫টা বিষয়, প্রতিটা পেপারের শব্দ-ফিচার খুব গোলমেলে কিন্তু একই বিষয়ের পেপার একে অপরকে বেশি উদ্ধৃত করে। "
           "শুধু ফিচার দেখা MLP, প্রতিবেশী-গড় করা GCN, আর মনোযোগ-ভিত্তিক GAT – তিনটার পরীক্ষা-নির্ভুলতা; GCN-এর লুকোনো এমবেডিং ২D-তে।",
           r'''import matplotlib.pyplot as plt
import numpy as np
import torch
import torch.nn.functional as F
from sklearn.manifold import TSNE
from torch_geometric.data import Data
from torch_geometric.nn import GATConv, GCNConv
from torch_geometric.utils import stochastic_blockmodel_graph

torch.manual_seed(0)
sizes = [120] * 5
P = torch.full((5, 5), 0.004) + torch.eye(5) * 0.05
edge_index = stochastic_blockmodel_graph(sizes, P)
y = torch.arange(5).repeat_interleave(120)
centers = torch.randn(5, 32)
x = centers[y] * 0.35 + torch.randn(len(y), 32)               # ফিচার: দুর্বল সংকেত + অনেক নয়েজ
perm = torch.randperm(len(y))
train, val, test = perm[:100], perm[100:200], perm[200:]
data = Data(x=x, edge_index=edge_index, y=y)
print(data, "| গড় প্রতিবেশী:", round(edge_index.size(1) / len(y), 1))

class Net(torch.nn.Module):
    def __init__(self, kind):
        super().__init__()
        self.kind = kind
        if kind == "MLP":
            self.l1, self.l2 = torch.nn.Linear(32, 32), torch.nn.Linear(32, 5)
        elif kind == "GCN":
            self.l1, self.l2 = GCNConv(32, 32), GCNConv(32, 5)
        else:
            self.l1, self.l2 = GATConv(32, 8, heads=4), GATConv(32, 5, heads=1)
    def forward(self, d, hidden=False):
        f = (lambda l, h: l(h)) if self.kind == "MLP" else (lambda l, h: l(h, d.edge_index))
        h = F.elu(f(self.l1, F.dropout(d.x, 0.5, self.training)))
        return h if hidden else f(self.l2, F.dropout(h, 0.5, self.training))

results, models = {}, {}
for kind in ["MLP", "GCN", "GAT"]:
    torch.manual_seed(1)
    m = Net(kind)
    opt = torch.optim.Adam(m.parameters(), lr=0.01, weight_decay=5e-4)
    best, best_test = 0, 0
    for ep in range(200):
        m.train(); opt.zero_grad()
        F.cross_entropy(m(data)[train], y[train]).backward(); opt.step()
        m.eval()
        pred = m(data).argmax(1)
        v = (pred[val] == y[val]).float().mean().item()
        if v >= best:
            best, best_test = v, (pred[test] == y[test]).float().mean().item()
    results[kind], models[kind] = best_test, m
    print(f"{kind}: পরীক্ষা-নির্ভুলতা {best_test:.1%}")

models["GCN"].eval()
H = models["GCN"](data, hidden=True).detach().numpy()
Z = TSNE(perplexity=30, random_state=0).fit_transform(H)
fig, (a1, a2) = plt.subplots(1, 2, figsize=(13, 5), facecolor="#0b0820", gridspec_kw={"width_ratios": [1, 1.3]})
cols = ["#4b4363", "#7c3aed", "#0d9488"]
a1.barh(list(results), list(results.values()), color=cols, height=0.55)
for i, v in enumerate(results.values()):
    a1.text(v + 0.01, i, f"{v:.0%}", va="center", color="white", fontsize=12)
a1.set_xlim(0, 1.1)
a1.set_title("Test accuracy (100 labelled nodes)", color="#c4b5fd", loc="left")
pal = np.array(["#7c3aed", "#0d9488", "#f59e0b", "#e11d48", "#0284c7"])
a2.scatter(Z[:, 0], Z[:, 1], c=pal[y.numpy()], s=10)
a2.set_title("GCN hidden layer (t-SNE), coloured by true topic", color="#c4b5fd", loc="left")
for ax in (a1, a2):
    ax.set_facecolor("#0b0820"); ax.tick_params(colors="#c4b5fd")
    for s in ax.spines.values():
        s.set_visible(False)
a2.set_xticks([]); a2.set_yticks([])
fig.suptitle(f"Using the citation links lifts accuracy from {results['MLP']:.0%} (MLP) to {max(results['GCN'], results['GAT']):.0%}",
             color="white", x=0.02, ha="left", fontsize=14, fontweight="bold")
plt.tight_layout()
plt.show()
''', hint=SHOW),
    ],
    level="উন্নত", tag="গ্রাফ নিউরাল নেটওয়ার্কের মানদণ্ড-লাইব্রেরি।",
    tasks=["নোড-ক্লাসিফিকেশন (পেপার, ব্যবহারকারী, প্রতারণা শনাক্ত)", "লিংক-প্রেডিকশন / রেকমেন্ডেশন", "অণুর ধর্ম অনুমান (গ্রাফ-ক্লাসিফিকেশন)", "বড় গ্রাফে মিনি-ব্যাচ ট্রেনিং"],
    caps=["৬০+ GNN লেয়ার, MessagePassing বেস", "Data/HeteroData, DataLoader, NeighborLoader", "Planetoid, OGB, TUDataset… ডেটাসেট", "torch.compile, explainability"],
    limits=["গ্রাফ-ML-এর ধারণা (মেসেজ পাসিং) আগে বুঝতে হয়", "দ্রুত এক্সটেনশন ইনস্টল ভার্সন-সংবেদনশীল", "খুব বড় গ্রাফে GPU ও স্যাম্পলিং লাগে"],
    alt="dgl, spektral (Keras), jraph (JAX), graspologic",
)

