KG_BN = r'''from rdflib import Graph, Literal, Namespace, RDF, RDFS, XSD

EX = Namespace("http://example.org/bangla/")
g = Graph()
g.bind("ex", EX)
writers = [("Tagore", "রবীন্দ্রনাথ ঠাকুর", "Rabindranath Tagore", 1861), ("Nazrul", "কাজী নজরুল ইসলাম", "Kazi Nazrul Islam", 1899),
           ("Jibanananda", "জীবনানন্দ দাশ", "Jibanananda Das", 1899), ("Humayun", "হুমায়ূন আহমেদ", "Humayun Ahmed", 1948)]
works = [("Gitanjali", "গীতাঞ্জলি", "Tagore", 1910, "Poetry"), ("Gora", "গোরা", "Tagore", 1910, "Novel"),
         ("Agnibeena", "অগ্নিবীণা", "Nazrul", 1922, "Poetry"), ("RupashiBangla", "রূপসী বাংলা", "Jibanananda", 1957, "Poetry"),
         ("Nondito", "নন্দিত নরকে", "Humayun", 1972, "Novel"), ("Himu", "ময়ূরাক্ষী", "Humayun", 1990, "Novel")]
for key, bn, en, born in writers:
    w = EX[key]
    g.add((w, RDF.type, EX.Writer))
    g.add((w, RDFS.label, Literal(bn, lang="bn")))
    g.add((w, RDFS.label, Literal(en, lang="en")))
    g.add((w, EX.born, Literal(born, datatype=XSD.gYear)))
for key, bn, author, year, genre in works:
    b = EX[key]
    g.add((b, RDF.type, EX[genre]))
    g.add((b, RDFS.label, Literal(bn, lang="bn")))
    g.add((b, EX.author, EX[author]))
    g.add((b, EX.published, Literal(year, datatype=XSD.integer)))
g.add((EX.Poetry, RDFS.subClassOf, EX.Work))
g.add((EX.Novel, RDFS.subClassOf, EX.Work))
'''

