pylib("sympy",
    about=("SymPy পাইথনের প্রতীকী গণিত (computer algebra) লাইব্রেরি – সংখ্যা নয়, x, y-র মতো প্রতীক নিয়ে কাজ: সমীকরণ সমাধান, অন্তরীকরণ, সমাকলন, লিমিট, ধারা, "
           "ম্যাট্রিক্স, অবকল সমীকরণ (dsolve), সংখ্যাতত্ত্ব, LaTeX-এ সুন্দর ছাপা, আর সূত্র থেকে দ্রুত NumPy/C কোড (lambdify, codegen)। বিশুদ্ধ পাইথন।"),
    install="pip install sympy",
    examples=[
        pex("বীজগণিত আর ক্যালকুলাস: সমাধান, অন্তরজ, সমাকলন, লিমিট, ধারা",
            "প্রতীক তৈরি করে দ্বিঘাত সমীকরণ, অন্তরজ, নির্দিষ্ট ও অনির্দিষ্ট সমাকলন, লিমিট আর টেইলর ধারা – সাথে প্রতিটার LaTeX রূপ।",
            r'''import sympy as sp

x, y, a = sp.symbols("x y a", real=True)
print("x² − 5x + 6 = 0 →", sp.solve(x**2 - 5*x + 6, x))
print("ax² + x − 1 = 0 →", sp.solve(a*x**2 + x - 1, x))
f = sp.sin(x) * sp.exp(-x)
print("d/dx[sin(x)·e^(−x)] =", sp.simplify(sp.diff(f, x)))
print("∫ x·e^x dx =", sp.integrate(x * sp.exp(x), x))
print("∫₀^∞ e^(−x²) dx =", sp.integrate(sp.exp(-x**2), (x, 0, sp.oo)))
print("lim (sin x)/x, x→0 =", sp.limit(sp.sin(x) / x, x, 0))
print("cos x-এর টেইলর ধারা:", sp.series(sp.cos(x), x, 0, 8))
print("দুই চলকের সমীকরণজোট:", sp.solve([x + y - 10, 2*x - y - 2], [x, y]))
print("\nLaTeX:", sp.latex(sp.Integral(sp.exp(-x**2), (x, 0, sp.oo))))
'''),
        ex("প্রজেক্ট: চায়ের কাপ ঠান্ডা হওয়া – অবকল সমীকরণ থেকে আসল মাপের সাথে মেলানো",
           "নিউটনের শীতলীকরণ সূত্র dT/dt = −k(T − Tঘর) SymPy-র dsolve দিয়ে প্রতীকী সমাধান, প্রাথমিক মান বসিয়ে সূত্র; তারপর শ্রীমঙ্গলের এক কাপ চায়ের "
           "মাপা তাপমাত্রা থেকে k খুঁজে (সমীকরণ সমাধান), lambdify করে দ্রুত NumPy ফাংশন – কখন চা ৬০°C-এ নামবে তার উত্তর আর চার্ট।",
           r'''import matplotlib.pyplot as plt
import numpy as np
import sympy as sp

t, k, Troom, T0 = sp.symbols("t k T_room T_0", positive=True)
T = sp.Function("T")
ode = sp.Eq(T(t).diff(t), -k * (T(t) - Troom))
sol = sp.dsolve(ode, T(t), ics={T(0): T0}).rhs
print("প্রতীকী সমাধান:  T(t) =", sp.simplify(sol))

measured = np.array([[0, 92], [2, 84.5], [5, 75.0], [10, 63.4], [15, 55.1], [20, 49.0]])   # মিনিট, °C
room, start = 26, 92
k_val = sp.nsolve(sol.subs({Troom: room, T0: start, t: 10}) - 63.4, k, 0.05)      # ১০ মিনিটের মাপ থেকে k
print(f"k = {float(k_val):.4f} প্রতি মিনিট")
Tt = sp.Symbol("T_target", positive=True)
t_when = sp.solve(sp.Eq(sol, Tt), t)[0]                                        # প্রতীকী: কখন T = T_target
print("কখন পৌঁছাবে:  t =", sp.simplify(t_when))
t60 = t_when.subs({Troom: room, T0: start, k: k_val, Tt: 60})
print(f"চা ৬০°C-এ নামবে {float(t60):.1f} মিনিটে")

f = sp.lambdify(t, sol.subs({Troom: room, T0: start, k: k_val}), "numpy")
tt = np.linspace(0, 40, 200)
err = np.abs(f(measured[:, 0]) - measured[:, 1]).max()
fig, ax = plt.subplots(figsize=(10, 5))
ax.plot(tt, f(tt), color="#7c3aed", lw=2.5)
ax.scatter(measured[:, 0], measured[:, 1], s=60, color="#e11d48", zorder=3)
ax.axhline(60, color="#f59e0b", ls="--", lw=1)
ax.annotate(f"drinkable at {float(t60):.1f} min", (float(t60), 60), xytext=(float(t60) + 4, 70),
            arrowprops=dict(arrowstyle="->", color="#f59e0b"), color="#b45309")
ax.axhline(room, color="#9ca3af", lw=1)
ax.text(40, room + 1, "room 26°C", ha="right", color="#6b7280")
ax.text(6.5, 80, "measured cup (red dots)", color="#e11d48")
ax.set_title(f"Newton's cooling law fits the Sreemangal tea cup within {err:.1f}°C", loc="left", fontsize=14, pad=28)
ax.text(0, 1.04, f"Solved symbolically with SymPy dsolve, k = {float(k_val):.3f} per minute", transform=ax.transAxes, color="#555")
ax.set_xlabel("minutes")
ax.set_ylabel("°C")
ax.spines[["top", "right"]].set_visible(False)
plt.tight_layout()
plt.show()
''', hint=SHOW),
        pex("ম্যাট্রিক্স, সংখ্যাতত্ত্ব আর সূত্র থেকে C কোড",
            "প্রতীকী ম্যাট্রিক্সের নির্ণায়ক ও আইগেনমান, ফিবোনাচির বন্ধ-সূত্র (rsolve), মৌলিক সংখ্যা, আর একটা সূত্রকে সরাসরি C-ফাংশনে রূপান্তর (ccode)।",
            r'''import sympy as sp

a, b, n = sp.symbols("a b n")
M = sp.Matrix([[2, a], [a, 2]])
print("det =", M.det(), "| আইগেনমান:", M.eigenvals())
print("উল্টো ম্যাট্রিক্স:", sp.simplify(M.inv()))

F = sp.Function("F")
fib = sp.rsolve(F(n) - F(n - 1) - F(n - 2), F(n), {F(0): 0, F(1): 1})
print("\nফিবোনাচির বন্ধ সূত্র:", sp.simplify(fib))
print("প্রথম ১০টা:", [sp.simplify(fib.subs(n, i)) for i in range(10)])

print("\n১০০-এর নিচে মৌলিক:", list(sp.primerange(2, 100)))
print("২০২৬-এর উৎপাদক:", sp.factorint(2026), "| ১০০০তম মৌলিক:", sp.prime(1000))

r, P = sp.symbols("r P", positive=True)
emi = P * r * (1 + r)**n / ((1 + r)**n - 1)                  # মাসিক কিস্তির সূত্র
print("\nEMI সূত্রের C কোড:\n  double emi =", sp.ccode(emi), ";")
print("৳৫ লাখ, মাসিক ০.৮%, ৬০ কিস্তি → ৳", round(float(emi.subs({P: 500000, r: 0.008, n: 60})), 2))
'''),
    ],
    level="মাঝারি", tag="পাইথনে প্রতীকী গণিত – খাতায় যা করো, কম্পিউটারে।",
    tasks=["সমীকরণ সমাধান ও সরলীকরণ", "ক্যালকুলাস, অবকল সমীকরণ", "পদার্থবিদ্যা/প্রকৌশলের সূত্র বের করা", "সূত্র থেকে দ্রুত NumPy/C কোড", "শিক্ষা – ধাপে ধাপে গণিত"],
    caps=["solve, dsolve, integrate, limit, series", "Matrix, সংখ্যাতত্ত্ব, combinatorics", "LaTeX/MathML/প্রিটি-প্রিন্ট", "lambdify, codegen (C, Fortran)", "বিশুদ্ধ পাইথন – Pyodide-এও চলে"],
    limits=["বড় প্রতীকী হিসাবে ধীর", "কিছু সমাকলন বন্ধ-রূপে পারে না", "Mathematica/Maple-এর চেয়ে কম শক্তিশালী কিছু ক্ষেত্রে"],
    alt="sagemath, mpmath, symengine, Mathematica",
)

