N = np.array([[3600,  70,  8,  100],
              [3500, 240, 75,  560],
              [  78,   6,  1,   25],
              [1200, 200, 10,  150],
              [ 230,  29, 27,  990],
              [ 620,  33,  0, 1200]]).T
need = np.array([2200, 60, 18, 1000])
x = cp.Variable(6, nonneg=True)
limits = cp.hstack([x[0] <= 0.6, x[2] <= 3, x[4] <= 0.4]) if False else None
cons = [N @ x >= need, x[0] <= 0.6, x[2] <= 3, x[4] <= 0.4]     # অতিরিক্ত ভাত/ডিম/শাক নয়
