A = rng.normal(0, 1, (m, n)) / np.sqrt(m)
y = A @ x_true
x = cp.Variable(n)
cp.Problem(cp.Minimize(cp.norm1(x)), [A @ x == y]).solve()
l2 = np.linalg.pinv(A) @ y                                   # তুলনা: সাধারণ least-squares
print(f"{m}টা মাপ, {n}টা অজানা, {k}টা অশূন্য")
print(f"L1 পুনরুদ্ধারের ভুল: {np.linalg.norm(x.value - x_true) / np.linalg.norm(x_true):.2e}")
print(f"L2 (pinv) ভুল:        {np.linalg.norm(l2 - x_true) / np.linalg.norm(x_true):.2f}")
