demand = [0] + list(rng.integers(6, 18, len(names) - 1))
V, CAP = 4, 50
dist = (np.hypot(*(pts[:, None, :] - pts[None, :, :]).transpose(2, 0, 1)) * 1000).astype(int)   # মিটার

man = pywrapcp.RoutingIndexManager(len(pts), V, 0)
rt = pywrapcp.RoutingModel(man)
cb = rt.RegisterTransitCallback(lambda i, j: int(dist[man.IndexToNode(i), man.IndexToNode(j)]))
rt.SetArcCostEvaluatorOfAllVehicles(cb)
dcb = rt.RegisterUnaryTransitCallback(lambda i: int(demand[man.IndexToNode(i)]))
rt.AddDimensionWithVehicleCapacity(dcb, 0, [CAP] * V, True, "Load")
p = pywrapcp.DefaultRoutingSearchParameters()
p.first_solution_strategy = routing_enums_pb2.FirstSolutionStrategy.PATH_CHEAPEST_ARC
p.local_search_metaheuristic = routing_enums_pb2.LocalSearchMetaheuristic.GUIDED_LOCAL_SEARCH
p.time_limit.seconds = 5
sol = rt.SolveWithParameters(p)

routes, total = [], 0
for v in range(V):
    i, path, load, d = rt.Start(v), [], 0, 0
    while not rt.IsEnd(i):
        n = man.IndexToNode(i); path.append(n); load += demand[n]
        j = sol.Value(rt.NextVar(i)); d += rt.GetArcCostForVehicle(i, j, v); i = j
    path.append(0); routes.append(path); total += d
    print(f"ভ্যান {v + 1}: {' → '.join(names[k].split(' (')[0] for k in path)}  · {load}/{CAP} বাক্স · {d / 1000:.1f} km")
print(f"মোট দূরত্ব {total / 1000:.1f} km · মোট চাহিদা {sum(demand)} বাক্স")

cols = ["#7c3aed", "#0d9488", "#f59e0b", "#e11d48"]
