CANVAS_JS = r'''
function canvas(w, h, parent = app) {                       // রেটিনা-স্ক্রিনে ঝকঝকে ক্যানভাস
  const c = document.createElement("canvas"), r = devicePixelRatio || 1;
  c.width = w * r; c.height = h * r; c.style.width = w + "px"; c.style.height = h + "px"; c.style.maxWidth = "100%";
  const g = c.getContext("2d"); g.scale(r, r); parent.append(c); return g;
}
'''

