jslib("JSXGraph",
    about=("JSXGraph ব্রাউজারে ইন্টার‍্যাক্টিভ জ্যামিতি, ফাংশন-গ্রাফ আর সিমুলেশনের লাইব্রেরি (জার্মানির বেয়রয়েট বিশ্ববিদ্যালয়) – বিন্দু টেনে সরালে নির্ভরশীল সব কিছু "
           "(ত্রিভুজ, বৃত্ত, কোণ, মাপ) সাথে সাথে বদলায়। স্লাইডার, ফাংশন, বক্ররেখা, টার্টল, সিমুলেশন; SVG/Canvas, মোবাইলে টাচ সমর্থন। গণিত-শিক্ষার ওয়েবসাইটে খুব জনপ্রিয়।"),
    install='npm install jsxgraph\n<!-- অথবা: <script src="https://cdn.jsdelivr.net/npm/jsxgraph@1.14.1/distrib/jsxgraphcore.js"></script> + jsxgraph.css -->',
    examples=[
        jlive_css("jsxgraph", "ত্রিভুজের পরিবৃত্ত, অন্তর্বৃত্ত আর কোণ – বিন্দু টেনে দেখো",
              "A, B, C বিন্দু টানো: পরিবৃত্ত (বেগুনি), অন্তর্বৃত্ত (সবুজ), তিন কোণ আর ক্ষেত্রফল সাথে সাথে বদলায় – কোণের যোগফল সবসময় ১৮০°। "
              "ত্রিভুজ সমকোণী হলে পরিকেন্দ্র অতিভুজের মাঝখানে চলে আসে – নিজে পরীক্ষা করো।",
              r'''app.innerHTML = `<div id="box" style="width:100%;height:330px;border-radius:14px;background:#fff"></div>
<div class="row"><span id="info" class="mono"></span></div>`;
const brd = JXG.JSXGraph.initBoard("box", { boundingbox: [-6, 5, 6, -4], axis: true, showCopyright: false,
  showNavigation: false, pan: { enabled: false }, zoom: { enabled: false } });
const P = (x, y, n) => brd.create("point", [x, y], { name: n, size: 5, fillColor: "#7c3aed", strokeColor: "#4c1d95", label: { fontSize: 15 } });
const A = P(-3, -2, "A"), B = P(3.5, -2, "B"), C = P(0.5, 3, "C");
brd.create("polygon", [A, B, C], { fillColor: "#ede9fe", fillOpacity: 0.5, borders: { strokeColor: "#4c1d95", strokeWidth: 2 } });
brd.create("circumcircle", [A, B, C], { strokeColor: "#7c3aed", strokeWidth: 1.5, dash: 2, center: { name: "O", size: 3 } });
brd.create("incircle", [A, B, C], { strokeColor: "#0d9488", strokeWidth: 1.5, center: { name: "I", size: 3, fillColor: "#0d9488" } });
const ang = (p, q, r) => brd.create("angle", [p, q, r], { radius: 0.7, fillColor: "#f59e0b", fillOpacity: 0.35, strokeColor: "#b45309",
  name: () => JXG.toFixed(JXG.Math.Geometry.trueAngle(p, q, r), 1) + "°" });
ang(B, A, C); ang(C, B, A); ang(A, C, B);
const show = () => {
  const a = [JXG.Math.Geometry.trueAngle(B, A, C), JXG.Math.Geometry.trueAngle(C, B, A), JXG.Math.Geometry.trueAngle(A, C, B)];
  const area = Math.abs((B.X() - A.X()) * (C.Y() - A.Y()) - (C.X() - A.X()) * (B.Y() - A.Y())) / 2;
  const kind = a.some(x => Math.abs(x - 90) < 0.5) ? "সমকোণী" : a.some(x => x > 90) ? "স্থূলকোণী" : "সূক্ষ্মকোণী";
  document.getElementById("info").textContent =
    `কোণের যোগফল ${(a[0] + a[1] + a[2]).toFixed(1)}° · ক্ষেত্রফল ${area.toFixed(2)} বর্গ একক · ${kind} ত্রিভুজ`;
};
brd.on("update", show); show();
'''),
        jlive_css("jsxgraph", "প্রজেক্ট: ফুটবল কিক – প্রক্ষেপকের গতিপথ, স্লাইডার আর বাতাসের বাধা",
              "স্লাইডারে গতি, কোণ আর অভিকর্ষ (পৃথিবী/চাঁদ/মঙ্গল) বদলাও – বাধাহীন আদর্শ পথ (বেগুনি) আর বাতাসের বাধাসহ পথ (লাল, সংখ্যাগতভাবে সমাকলিত) পাশাপাশি; "
              "সর্বোচ্চ উচ্চতা, দূরত্ব আর ৩০ মিটার দূরের গোলপোস্টে বল ঢুকল কি না।",
              r'''app.innerHTML = `<div id="box" style="width:100%;height:340px;border-radius:14px;background:#fff"></div>
<div class="row"><button data-g="9.81" class="pri">পৃথিবী</button><button data-g="3.71">মঙ্গল</button><button data-g="1.62">চাঁদ</button>
<span id="info" class="mono"></span></div>`;
const brd = JXG.JSXGraph.initBoard("box", { boundingbox: [-3, 24, 62, -5], axis: true, showCopyright: false, showNavigation: false });
const v = brd.create("slider", [[2, 21], [18, 21], [5, 20, 35]], { name: "v (m/s)", snapWidth: 0.5 });
const th = brd.create("slider", [[2, 18.5], [18, 18.5], [10, 35, 80]], { name: "কোণ°", snapWidth: 1 });
const kd = brd.create("slider", [[2, 16], [18, 16], [0, 0.015, 0.05]], { name: "বাতাসের বাধা k" });
let g = 9.81;
const rad = () => th.Value() * Math.PI / 180;
brd.create("functiongraph", [x => x * Math.tan(rad()) - g * x * x / (2 * (v.Value() * Math.cos(rad())) ** 2), 0, 200],
  { strokeColor: "#7c3aed", strokeWidth: 2.5 });
function drag() {                                    // বাতাসের বাধা: a = −g ĵ − k|v|v (অয়লার পদ্ধতি, dt = ১ মিলিসেকেন্ড)
  let x = 0, y = 0, vx = v.Value() * Math.cos(rad()), vy = v.Value() * Math.sin(rad()); const X = [0], Y = [0];
  for (let i = 0; i < 40000 && y >= 0; i++) { const s = Math.hypot(vx, vy), dt = 0.001;
    vx -= kd.Value() * s * vx * dt; vy -= (g + kd.Value() * s * vy) * dt; x += vx * dt; y += vy * dt; if (i % 20 === 0) { X.push(x); Y.push(y); } }
  return [X, Y];
}
const cur = brd.create("curve", [[0], [0]], { strokeColor: "#e11d48", strokeWidth: 2, dash: 1 });
cur.updateDataArray = function () { [this.dataX, this.dataY] = drag(); };
brd.create("segment", [[30, 0], [30, 2.44]], { strokeColor: "#0d9488", strokeWidth: 5, fixed: true });
brd.create("text", [30.6, 3.4, "গোল"], { color: "#0d9488", fixed: true });
const info = document.getElementById("info");
brd.on("update", () => {
  const V = v.Value(), a = rad(), R = V * V * Math.sin(2 * a) / g, H = (V * Math.sin(a)) ** 2 / (2 * g);
  const [X, Y] = drag(); let yAt30 = null;
  for (let i = 1; i < X.length; i++) if (X[i - 1] <= 30 && X[i] > 30) yAt30 = Y[i];
  info.textContent = `আদর্শ: দূরত্ব ${R.toFixed(1)} m, উচ্চতা ${H.toFixed(1)} m · বাধাসহ দূরত্ব ${X[X.length - 1].toFixed(1)} m · ` +
    (yAt30 !== null && yAt30 >= 0 && yAt30 <= 2.44 ? "⚽ গোল!" : yAt30 === null ? "৩০ m পৌঁছায়নি" : `৩০ m-এ বল ${yAt30.toFixed(1)} m উঁচুতে`);
});
app.querySelectorAll("[data-g]").forEach(b => b.onclick = () => { g = +b.dataset.g;
  app.querySelectorAll("[data-g]").forEach(x => x.classList.toggle("pri", x === b)); brd.update(); });
brd.update();
''', hint="প্রজেক্ট"),
    ],
    level="শুরু", tag="টেনে-সরানো যায় এমন জ্যামিতি আর গ্রাফ – ব্রাউজারে।",
    tasks=["গণিত-শিক্ষার ইন্টার‍্যাক্টিভ পাতা", "জ্যামিতির প্রমাণ দেখানো", "পদার্থবিদ্যার সিমুলেশন (প্রক্ষেপক, দোলক)", "অনলাইন কুইজে গ্রাফ"],
    caps=["নির্ভরশীল জ্যামিতি: বিন্দু, রেখা, বৃত্ত, কোণ, বহুভুজ", "slider, functiongraph, curve, integral", "টাচ/মাউস, SVG/Canvas", "GeoGebra ফাইল পড়তে পারে"],
    limits=["৩D সীমিত (view3d আছে, তবে GeoGebra-র মতো নয়)", "API বিশাল, ডকুমেন্টেশন জায়গায় জায়গায় পুরোনো", "খুব বড় ডেটা-চার্টের জন্য নয়"],
    alt="GeoGebra, Mafs, Desmos, D3",
)

