# ------------------------------------------------------------------ Mafs
MAFS_IMPORT = r'''// esm.sh সব নির্ভরতাকে একই React-এ বাঁধে (?deps=) – দুটো React হলে hooks ভাঙে
const E = "https://esm.sh/", D = "?deps=react@18.3.1,react-dom@18.3.1";
const [Rm, { createRoot }, M] = await Promise.all([import(E + "react@18.3.1"), import(E + "react-dom@18.3.1/client"), import(E + "mafs@0.21.0" + D)]);
const React = Rm.default || Rm, h = React.createElement;
{ const st = document.createElement("style");                    // সাইটের হালকা রঙে Mafs
  st.textContent = ".MafsView{--mafs-bg:#fff;--mafs-fg:#140e29;--mafs-line-color:#ede9fe;--grid-line-subdivision-color:#f5f3ff;--mafs-origin-color:#4c1d95;border-radius:14px}";
  document.head.append(st); }
'''

jslib("Mafs",
    about=("Mafs হলো React-এর জন্য ইন্টার‍্যাক্টিভ গণিতের কম্পোনেন্ট – <Mafs>, <Coordinates.Cartesian>, <Plot.OfX>, <Point>, <Vector>, <Polygon>, আর useMovablePoint দিয়ে টেনে-সরানো বিন্দু। "
           "ঘোষণামূলক (declarative): অবস্থা বদলালে React নিজেই আবার আঁকে। SVG-ভিত্তিক, তাই ঝকঝকে ও দ্রুত; গণিতের ব্যাখ্যামূলক ব্লগ/কোর্সে।"),
    install="npm install mafs react react-dom\n// import \"mafs/core.css\"; import \"mafs/font.css\"\n// বিল্ড ছাড়া ব্রাউজারে: import(\"https://esm.sh/mafs@0.21.0?deps=react@18.3.1,react-dom@18.3.1\")",
    examples=[
        jlive_css("mafs", "টেনে-সরানো বিন্দু দিয়ে সরলরেখা আর ঢাল",
              "দুটো useMovablePoint – টানলে রেখা, ঢাল আর সমীকরণ y = mx + c বদলায়; React-এর ঘোষণামূলক ধাঁচ (JSX ছাড়াই createElement দিয়ে লেখা)।",
              MAFS_IMPORT + r'''const { Mafs, Coordinates, Line, Text, useMovablePoint, Theme } = M;
function App() {
  const p = useMovablePoint([-2, -1], { color: Theme.indigo }), q = useMovablePoint([3, 2], { color: Theme.pink });
  const m = (q.y - p.y) / (q.x - p.x), c = p.y - m * p.x;
  return h(React.Fragment, null,
    h("div", { className: "mono", style: { margin: "0 0 6px" } },
      Number.isFinite(m) ? `y = ${m.toFixed(2)}x ${c >= 0 ? "+" : "−"} ${Math.abs(c).toFixed(2)} · ঢাল ${m.toFixed(2)} · কোণ ${(Math.atan(m) * 180 / Math.PI).toFixed(1)}°` : "উল্লম্ব রেখা (ঢাল অসীম)"),
    h(Mafs, { height: 330, viewBox: { x: [-5, 5], y: [-4, 4] } },
      h(Coordinates.Cartesian, { subdivisions: 2 }),
      h(Line.ThroughPoints, { point1: p.point, point2: q.point, color: Theme.violet }),
      h(Text, { x: q.x, y: q.y, attach: "ne" }, "Q"), h(Text, { x: p.x, y: p.y, attach: "sw" }, "P"),
      p.element, q.element));
}
createRoot(app).render(h(App));
'''),
        jlive_css("mafs", "প্রজেক্ট: রিম্যান সমষ্টি – আয়তক্ষেত্র বাড়ালে ক্ষেত্রফল সমাকলনের কাছে যায়",
              "f(x) = 2 + sin(x)·x/2 বক্ররেখার নিচের ক্ষেত্রফল: বাঁ/ডান/মধ্যবিন্দু পদ্ধতিতে n টা আয়তক্ষেত্র; সীমা a, b টেনে সরাও, n বাড়াও – "
              "ভুল কীভাবে কমে (সঠিক মান সিম্পসন দিয়ে)। ক্যালকুলাসের মূল ধারণা চোখে দেখা।",
              MAFS_IMPORT + r'''const { Mafs, Coordinates, Plot, Polygon, useMovablePoint, Theme } = M;
const f = x => 2 + Math.sin(x) * x / 2;
const simpson = (a, b, n = 1000) => { const hh = (b - a) / n; let s = f(a) + f(b);
  for (let i = 1; i < n; i++) s += f(a + i * hh) * (i % 2 ? 4 : 2); return s * hh / 3; };
function App() {
  const [n, setN] = React.useState(8), [mode, setMode] = React.useState("মধ্য");
  const A = useMovablePoint([0.5, 0], { constrain: "horizontal" }), B = useMovablePoint([6.5, 0], { constrain: "horizontal" });
  const a = Math.min(A.x, B.x), b = Math.max(A.x, B.x), w = (b - a) / n;
  const off = { "বাঁ": 0, "মধ্য": 0.5, "ডান": 1 }[mode];
  const rects = Array.from({ length: n }, (_, i) => { const x0 = a + i * w, y = f(x0 + off * w); return [[x0, 0], [x0 + w, 0], [x0 + w, y], [x0, y]]; });
  const approx = rects.reduce((s, r) => s + w * r[2][1], 0), exact = simpson(a, b);
  return h(React.Fragment, null,
    h("div", { className: "row" }, "n = ", h("input", { type: "range", min: 1, max: 80, value: n, onChange: e => setN(+e.target.value) }), ` ${n} `,
      ...["বাঁ", "মধ্য", "ডান"].map(k => h("button", { key: k, className: k === mode ? "pri" : "", onClick: () => setMode(k) }, k)),
      h("span", { className: "mono" }, ` ≈ ${approx.toFixed(4)} · সঠিক ${exact.toFixed(4)} · ভুল ${Math.abs(approx - exact).toExponential(1)}`)),
    h(Mafs, { height: 310, viewBox: { x: [-0.5, 7.5], y: [-0.5, 5] } },
      h(Coordinates.Cartesian, { xAxis: { lines: 1 }, yAxis: { lines: 1 } }),
      ...rects.map((pts, i) => h(Polygon, { key: i, points: pts, color: Theme.blue, fillOpacity: 0.25, weight: 1 })),
      h(Plot.OfX, { y: f, color: Theme.violet, weight: 3 }), A.element, B.element));
}
createRoot(app).render(h(App));
''', hint="প্রজেক্ট"),
    ],
    level="মাঝারি", tag="React-এ ঘোষণামূলক, টেনে-সরানো যায় এমন গণিত।",
    tasks=["গণিত-ব্যাখ্যার ব্লগ/কোর্স (React/Next.js)", "ক্যালকুলাস/জ্যামিতির ইন্টার‍্যাক্টিভ চিত্র", "শিক্ষা-অ্যাপে অনুশীলন", "ভেক্টর ও রূপান্তর দেখানো"],
    caps=["Coordinates.Cartesian/Polar, Plot.OfX/OfY/Parametric/VectorField", "useMovablePoint (constrain সহ)", "Point, Line, Polygon, Circle, Ellipse, Vector, Text, LaTeX", "Transform, অ্যানিমেশন (useStopwatch)"],
    limits=["শুধু React-এ", "৩D নেই", "এখনো ০.x – API বদলাতে পারে"],
    alt="JSXGraph, GeoGebra, Desmos, D3",
)

