jslib("Astronomy Engine",
    about=("Astronomy Engine (Don Cross) ছোট, নির্ভরশীলতা-ছাড়া জ্যোতির্বিজ্ঞান-গণনার লাইব্রেরি – সূর্য, চাঁদ, গ্রহের অবস্থান (VSOP87, ±১ আর্কমিনিট), উদয়-অস্ত, চাঁদের কলা, "
           "গ্রহণ (সূর্য/চন্দ্র), বিষুব-অয়নান্ত, গ্রহের উজ্জ্বলতা। জাভাস্ক্রিপ্ট, পাইথন, C, C#, Kotlin-এ একই API; ইন্টারনেট/ডেটা-ফাইল লাগে না – মোবাইল অ্যাপেও চলে।"),
    install='npm install astronomy-engine\n<!-- অথবা: <script src="https://cdn.jsdelivr.net/npm/astronomy-engine@2.1.19/astronomy.browser.min.js"></script> -->',
    examples=[
        jlive("astroengine", "এই মুহূর্তে ঢাকার আকাশ: সূর্য, চাঁদ, গ্রহ কোথায় আর কখন উঠবে",
              "তোমার ঘড়ির এখনকার সময় ধরে ঢাকা (২৩.৮১° উ, ৯০.৪১° পূ) থেকে প্রতিটা বস্তুর উচ্চতা-দিগংশ, উজ্জ্বলতা, পরের উদয়-অস্ত (স্থানীয় সময়ে), চাঁদের কলা আর পরের পূর্ণিমা।",
              r'''const obs = new Astronomy.Observer(23.81, 90.41, 10), now = new Date();
const fmt = d => d ? d.date.toLocaleString("bn-BD", { timeZone: "Asia/Dhaka", weekday: "short", hour: "2-digit", minute: "2-digit" }) : "–";
const dir = az => ["উ", "উপূ", "পূ", "দপূ", "দ", "দপ", "প", "উপ"][Math.round(az / 45) % 8];
const names = { Sun: "সূর্য", Moon: "চাঁদ", Mercury: "বুধ", Venus: "শুক্র", Mars: "মঙ্গল", Jupiter: "বৃহস্পতি", Saturn: "শনি" };
const rows = Object.entries(names).map(([b, bn]) => {
  const eq = Astronomy.Equator(b, now, obs, true, true), hz = Astronomy.Horizon(now, obs, eq.ra, eq.dec, "normal");
  const mag = b === "Sun" ? -26.7 : Astronomy.Illumination(b, now).mag;
  return `<tr style="${hz.altitude > 0 ? "" : "opacity:.45"}"><td><b>${bn}</b></td><td class="mono">${hz.altitude.toFixed(1)}°</td><td>${dir(hz.azimuth)} (${hz.azimuth.toFixed(0)}°)</td>
    <td class="mono">${mag.toFixed(1)}</td><td>${fmt(Astronomy.SearchRiseSet(b, obs, +1, now, 2))}</td><td>${fmt(Astronomy.SearchRiseSet(b, obs, -1, now, 2))}</td></tr>`;
});
const phase = Astronomy.MoonPhase(now), illum = Astronomy.Illumination("Moon", now).phase_fraction;
let q = Astronomy.SearchMoonQuarter(now); while (q.quarter !== 2) q = Astronomy.NextMoonQuarter(q);
app.innerHTML = `<div class="muted">ঢাকা · ${now.toLocaleString("bn-BD", { timeZone: "Asia/Dhaka" })} (ধূসর = দিগন্তের নিচে)</div>
<table><tr><th>বস্তু</th><th>উচ্চতা</th><th>দিক</th><th>উজ্জ্বলতা</th><th>পরের উদয়</th><th>পরের অস্ত</th></tr>${rows.join("")}</table>
<div class="card" style="margin-top:8px">🌙 চাঁদের কলা-কোণ ${phase.toFixed(0)}° · আলোকিত ${(illum * 100).toFixed(0)}% · পরের পূর্ণিমা ${q.time.date.toLocaleDateString("bn-BD", { timeZone: "Asia/Dhaka", day: "numeric", month: "long" })}</div>`;
'''),
        jlive("astroengine", "প্রজেক্ট: আকাশ-গম্বুজ – সময় স্লাইডারে টেনে দেখো গ্রহেরা কীভাবে ঘোরে",
              "মাথার ওপরের আকাশকে বৃত্তে আঁকা (কেন্দ্র = মাথার ঠিক ওপর, কিনারা = দিগন্ত): ২৪ ঘণ্টার স্লাইডার টানলে সূর্য, চাঁদ (সঠিক কলাসহ), গ্রহ আর কয়েকটা উজ্জ্বল তারা "
              "সরে; আকাশের রং সূর্যের উচ্চতা অনুযায়ী (দিন/গোধূলি/রাত)। পরের সূর্যগ্রহণ কবে – SearchGlobalSolarEclipse।",
              CANVAS_JS + r'''const obs = new Astronomy.Observer(23.81, 90.41, 10);
const stars = [["লুব্ধক", 6.752, -16.72], ["আর্দ্রা", 5.919, 7.41], ["স্বাতী", 14.261, 19.18], ["অভিজিৎ", 18.616, 38.78], ["চিত্রা", 13.420, -11.16], ["ধ্রুবতারা", 2.53, 89.26]];
const bodies = [["Sun", "#fbbf24", 11], ["Moon", "#e5e7eb", 9], ["Venus", "#fde68a", 5], ["Mars", "#f87171", 4.5], ["Jupiter", "#fcd34d", 5], ["Saturn", "#d6d3d1", 4]];
const bn = { Sun: "সূর্য", Moon: "চাঁদ", Venus: "শুক্র", Mars: "মঙ্গল", Jupiter: "বৃহস্পতি", Saturn: "শনি" };
app.innerHTML = `<div class="row"><input id="t" type="range" min="0" max="1440" step="5" style="flex:1"><span id="clock" class="mono"></span></div><div id="ec" class="muted"></div>`;
const S = Math.min(app.clientWidth - 30, 330), g = canvas(S, S), R = S / 2 - 18;
const base = new Date(); base.setUTCHours(-6, 0, 0, 0);                         // আজ ঢাকার মধ্যরাত
const P = (alt, az) => { const r = R * (90 - alt) / 90, a = (az - 90) * Math.PI / 180; return [S / 2 - r * Math.cos(a + Math.PI), S / 2 + r * Math.sin(a + Math.PI)]; };
function draw() {
  const mins = +document.getElementById("t").value, t = new Date(base.getTime() + mins * 60000);
  const sunAlt = Astronomy.Horizon(t, obs, ...(e => [e.ra, e.dec])(Astronomy.Equator("Sun", t, obs, true, true)), "normal").altitude;
  const sky = sunAlt > 0 ? "#38bdf8" : sunAlt > -6 ? "#6d28d9" : sunAlt > -18 ? "#312e81" : "#0b0820";
  g.clearRect(0, 0, S, S); g.fillStyle = sky; g.beginPath(); g.arc(S / 2, S / 2, R, 0, 7); g.fill();
  g.strokeStyle = "#ffffff33"; [30, 60].forEach(a => { g.beginPath(); g.arc(S / 2, S / 2, R * (90 - a) / 90, 0, 7); g.stroke(); });
  g.fillStyle = "#4c1d95"; g.font = "bold 12px system-ui"; [["উ", 0], ["পূ", 90], ["দ", 180], ["প", 270]].forEach(([n, az]) => { const [x, y] = P(-9, az); g.fillText(n, x - 5, y + 4); });
  g.font = "10px system-ui";
  for (const [n, ra, dec] of stars) { const hz = Astronomy.Horizon(t, obs, ra, dec, "normal"); if (hz.altitude < 0) continue;
    const [x, y] = P(hz.altitude, hz.azimuth); g.fillStyle = "#fff"; g.beginPath(); g.arc(x, y, 1.8, 0, 7); g.fill(); if (sunAlt < -6) g.fillText(n, x + 4, y - 3); }
  for (const [b, col, r] of bodies) { const e = Astronomy.Equator(b, t, obs, true, true), hz = Astronomy.Horizon(t, obs, e.ra, e.dec, "normal");
    if (hz.altitude < 0) continue; const [x, y] = P(hz.altitude, hz.azimuth);
    g.fillStyle = col; g.beginPath(); g.arc(x, y, r, 0, 7); g.fill();
    if (b === "Moon") { const f = Astronomy.Illumination("Moon", t).phase_fraction, waxing = Astronomy.MoonPhase(t) < 180;
      g.fillStyle = "#1e1b4b"; g.beginPath(); g.arc(x, y, r, Math.PI / 2, -Math.PI / 2, !waxing); g.ellipse(x, y, Math.abs(1 - 2 * f) * r, r, 0, -Math.PI / 2, Math.PI / 2, f > 0.5 ? !waxing : waxing); g.fill(); }
    g.fillStyle = sunAlt > 0 ? "#0b0820" : "#ede9fe"; g.font = "bold 11px system-ui"; g.fillText(bn[b], x + r + 3, y + 4); }
  document.getElementById("clock").textContent = t.toLocaleString("bn-BD", { timeZone: "Asia/Dhaka", hour: "2-digit", minute: "2-digit" }) +
    ` · সূর্যের উচ্চতা ${sunAlt.toFixed(1)}°`;
}
const nowMin = Math.round((Date.now() - base.getTime()) / 60000) % 1440;
document.getElementById("t").value = nowMin; document.getElementById("t").oninput = draw; draw();
const ecl = Astronomy.SearchGlobalSolarEclipse(new Date());
document.getElementById("ec").textContent = `পরের সূর্যগ্রহণ (পৃথিবীর কোথাও): ${ecl.peak.date.toLocaleDateString("bn-BD", { day: "numeric", month: "long", year: "numeric" })} – ধরন: ${ecl.kind}` +
  (ecl.latitude !== undefined ? `, কেন্দ্র ${ecl.latitude.toFixed(1)}°, ${ecl.longitude.toFixed(1)}°` : "");
''', hint="প্রজেক্ট"),
    ],
    level="শুরু", tag="ছোট্ট, অফলাইন, নির্ভুল জ্যোতির্বিজ্ঞান – ৬টা ভাষায় একই API।",
    tasks=["নামাজ/রোজা/পূজার সময়ের অ্যাপে সূর্য-চাঁদের হিসাব", "আকাশ-পর্যবেক্ষণ অ্যাপ", "গ্রহণ ও চাঁদের কলার ক্যালেন্ডার", "জ্যোতির্বিজ্ঞান শেখানো"],
    caps=["Equator/Horizon/Ecliptic স্থানাঙ্ক", "SearchRiseSet, SearchAltitude, Seasons", "MoonPhase, SearchMoonQuarter, Illumination", "Lunar/Solar eclipse, transit, libration"],
    limits=["কৃত্রিম উপগ্রহ নেই (তার জন্য Satellite.js)", "নির্ভুলতা ~১ আর্কমিনিট (গবেষণার জন্য JPL ephemeris)", "তারা-তালিকা নিজে দিতে হয়"],
    alt="astronomia, Skyfield (পাইথন), Satellite.js",
)

