mem = dict(l.split(":") for l in c.run("grep -E 'MemTotal|MemAvailable' /proc/meminfo", hide=True).stdout.splitlines())
tot, avail = (int(mem[k].split()[0]) / 1024 for k in ("MemTotal", "MemAvailable"))
