from invoke import task

@task
def clean(c):
    """পুরোনো বিল্ড মুছে ফেলা"""
    c.run("rm -rf build && mkdir -p build")

@task
def test(c, verbose=False):
    """ছোট পরীক্ষা চালানো"""
    c.run("python -c \"assert sum([1, 2, 3]) == 6; print('৩টা পরীক্ষা পাস')\"")
    if verbose:
        print("  (বিস্তারিত মোড)")

@task(pre=[clean, test], help={"version": "রিলিজ সংস্করণ"})
def build(c, version="0.1"):
    """রিপোর্ট বিল্ড করা"""
    c.run(f"echo 'রিপোর্ট সংস্করণ {version}' > build/report.txt")
    r = c.run("wc -c < build/report.txt", hide=True)
    print(f"build/report.txt তৈরি ({r.stdout.strip()} বাইট)")
