import random, sqlite3
from datetime import datetime
from airflow.sdk import dag, task

@dag(schedule="0 2 * * *", start_date=datetime(2026, 1, 1), catchup=False, tags=["sensor"])
def sensor_etl():
    @task
    def extract():                                    # সত্যিকারে: API/ফাইল থেকে
        rnd = random.Random(7)
        return [dict(station=s, hour=h, temp=round(rnd.gauss(27, 3), 1) if rnd.random() > .05 else -999)
                for s in ["Dhaka", "Sylhet", "Khulna"] for h in range(24)]
    @task
    def validate(rows):
        good = [r for r in rows if -10 < r["temp"] < 50]
        print(f"বাদ গেল {{len(rows) - len(good)}}টা খারাপ মাপ")
        return good
    @task
    def transform(rows):
        agg = {{}}
        for r in rows: agg.setdefault(r["station"], []).append(r["temp"])
        return [dict(station=s, mean=round(sum(v) / len(v), 2), n=len(v)) for s, v in agg.items()]
    @task
    def load(rows):
        db = sqlite3.connect("{OUT}")
        db.execute("CREATE TABLE IF NOT EXISTS daily(station TEXT, mean REAL, n INT)")
        db.executemany("INSERT INTO daily VALUES (:station, :mean, :n)", rows); db.commit()
        return len(rows)
    load(transform(validate(extract())))

sensor_etl()
