ax.set_title(f"Learning rate {best.data.params['eta0']} wins and becomes the registered champion (v{mv.version})", loc="left", fontsize=13, pad=26)
ax.text(0, 1.04, "Per-epoch metric history read back from the MLflow tracking store", transform=ax.transAxes, color="#555")
ax.spines[["top", "right"]].set_visible(False)
plt.tight_layout()
plt.show()
