BENTO_SERVICE = r'''# service.py – পাখির বৈশিষ্ট্য (ডানার দৈর্ঘ্য, ঠোঁট, ওজন) থেকে প্রজাতি
import bentoml
import numpy as np
from sklearn.ensemble import RandomForestClassifier

SPECIES = np.array(["shalik", "doel", "machranga", "babui"])

@bentoml.service(resources={"cpu": "1"}, traffic={"timeout": 10})
class BirdClassifier:
    def __init__(self):
        rng = np.random.default_rng(0)
        centers = np.array([[14, 2.5, 110], [10, 1.8, 50], [8, 4.5, 40], [7, 1.2, 25]])
        X = np.vstack([rng.normal(c, [1, .2, 8], (200, 3)) for c in centers])
        self.model = RandomForestClassifier(n_estimators=80, random_state=0).fit(X, np.repeat(SPECIES, 200))
        self.calls = 0

    @bentoml.api(batchable=True, max_batch_size=64, max_latency_ms=200)
    def classify(self, features: np.ndarray) -> np.ndarray:
        self.calls += 1
        return self.model.predict(features)

    @bentoml.api
    def info(self) -> dict:
        return {"species": SPECIES.tolist(), "batched_calls": self.calls}
'''

