LIT_SERVER = r'''# server.py – বহু ছবির শ্রেণিকরণ (এখানে ছোট কৃত্রিম 'মডেল', ব্যাচে চলে)
import time
import numpy as np
import litserve as ls

class ImageAPI(ls.LitAPI):
    def setup(self, device):
        rng = np.random.default_rng(0)
        self.W = rng.normal(0, 1, (64, 5))                  # ৮x৮ ছবি → ৫ শ্রেণি
        self.labels = ["ধান", "পাট", "পানি", "শহর", "বন"]
        self.batch_sizes = []
    def decode_request(self, request):
        return np.asarray(request["pixels"], dtype=float).reshape(64)
    def batch(self, inputs):
        return np.stack(inputs)
    def predict(self, x):
        self.batch_sizes.append(len(x) if x.ndim == 2 else 1)     # ব্যাচ ছাড়া x একটাই ছবি
        time.sleep(0.02)                                     # 'মডেল' প্রতি ব্যাচে ২০ ms
        return x @ self.W
    def unbatch(self, output):
        return list(output)
    def encode_response(self, out):
        k = int(np.argmax(out))
        return {"label": self.labels[k], "score": round(float(np.exp(out[k]) / np.exp(out).sum()), 3),
                "batch_seen": self.batch_sizes[-1]}

if __name__ == "__main__":
    import sys
    api = ImageAPI(max_batch_size=int(sys.argv[2]), batch_timeout=0.05)
    ls.LitServer(api, accelerator="cpu").run(port=int(sys.argv[1]), generate_client_file=False)
'''

