def export_report(rows, uploader, retries=3):
    name = f"rain_{dt.date.today():%Y%m%d}.csv"
    with open(name, "w", newline="", encoding="utf-8") as f:
        w = csv.writer(f); w.writerow(["district", "mm"]); w.writerows(rows)
    buf = io.StringIO(); csv.writer(buf).writerows([["district", "mm"], *rows])
    for attempt in range(1, retries + 1):
        try:
            uploader.send(name, buf.getvalue())
            return name, attempt
        except ConnectionError:
            if attempt == retries:
                raise

ROWS = [["Dhaka", 310], ["Sylhet", 612]]
REAL_DATE = dt.date

class TestExport(unittest.TestCase):
    @mock.patch(f"{__name__}.dt")
    def test_writes_csv_with_dated_name(self, mdt):
        mdt.date.today.return_value = REAL_DATE(2026, 7, 15)      # patch-এর ভেতরে dt নিজেই নকল, তাই আসলটা আগে রাখা
        m = mock.mock_open()
