write("features/steps/library_steps.py", """
    from behave import given, when, then

    class Library:
        def __init__(self): self.copies, self.members = {}, {}
        def borrow(self, who, title):
            m = self.members[who]
            if m["fine"] > 0: return False, "জরিমানা"
            if m["books"] >= 3: return False, "সীমা"
            if self.copies.get(title, 0) == 0: return False, "কপি নেই"
            self.copies[title] -= 1; m["books"] += 1; return True, None

    @given('লাইব্রেরিতে "{title}" এর {n:d} কপি আছে')
    def step_copies(ctx, title, n):
        ctx.lib = Library(); ctx.lib.copies[title] = n

    @given('সদস্য "{who}" এর কাছে {n:d} টা বই আছে')
    def step_member(ctx, who, n):
        ctx.lib.members[who] = {"books": n, "fine": 0}

    @given('"{who}" এর {tk:d} টাকা জরিমানা বকেয়া')
    def step_fine(ctx, who, tk):
        ctx.lib.members[who]["fine"] = tk

    @when('"{who}" "{title}" ধার নিতে চায়')
    def step_borrow(ctx, who, title):
        ctx.ok, ctx.why = ctx.lib.borrow(who, title)

    @then("ধার সফল হবে")
    def step_ok(ctx):
        assert ctx.ok, ctx.why

    @then('ধার প্রত্যাখ্যাত হবে কারণ "{why}"')
    def step_rejected(ctx, why):
        assert not ctx.ok and ctx.why == why, (ctx.ok, ctx.why)

    @then('"{title}" এর {n:d} কপি বাকি থাকবে')
    def step_left(ctx, title, n):
        assert ctx.lib.copies[title] == n
""")
