import time

write("tox.ini", """
    [tox]
    env_list = lint, type, test-py{312,313}
    labels =
        ci = lint, type, test-py312, test-py313

    [testenv:lint]
    skip_install = true
    deps = ruff
    commands = ruff check src tests

    [testenv:type]
    deps = mypy
    commands = mypy --strict src

    [testenv:test-py{312,313}]
    deps = pytest
           coverage
    commands = coverage run -m pytest -q
               coverage report --fail-under=80
""")
def run(label):
    t = time.time(); r = sh(sys.executable, "-m", "tox", "-m", "ci", "-p", "auto", "--parallel-no-spinner", show=False)
    rows = re.findall(r"^\s+(\S+): (OK|FAIL)[^(]*\(([\d.]+)=", r.stdout, re.M)
    print(f"\n{label} – মোট {time.time() - t:.1f}s, exit {r.returncode}")
    for env, st, sec in rows:
        print(f"  {'✓' if st == 'OK' else '✗'} {env:<12} {sec:>6}s")
    return r
