def bigha_to_decimal(b): return b * 33.0           # ১ বিঘা = ৩৩ শতাংশ (প্রচলিত)
def decimal_to_bigha_buggy(d): return round(d / 33.0, 2)   # ভুল: দুই ঘর পর্যন্ত কেটে দেয়
def decimal_to_bigha(d): return d / 33.0
