PARSER = r'''
write("rainparse.py", """
    def parse_line(line):
        \"\"\"'Dhaka, 2026-07-15, 120.5 mm' → (district, date, mm)\"\"\"
        line = line.strip()
        if not line or line.startswith("#"):
            return None
        parts = [p.strip() for p in line.split(",")]
        if len(parts) != 3:
            raise ValueError(f"৩টা ঘর দরকার: {line!r}")
        district, date, amount = parts
        if amount.endswith("mm"):
            mm = float(amount[:-2])
        elif amount.endswith("in"):
            mm = float(amount[:-2]) * 25.4
        elif amount == "trace":
            mm = 0.1
        else:
            raise ValueError(f"একক চিনি না: {amount!r}")
        if mm < 0:
            raise ValueError("ঋণাত্মক বৃষ্টি")
        return district.title(), date, round(mm, 1)

    def summarize(lines):
        totals, bad = {}, 0
        for l in lines:
            try:
                r = parse_line(l)
            except ValueError:
                bad += 1
                continue
            if r:
                totals[r[0]] = totals.get(r[0], 0) + r[2]
        return totals, bad
""")
'''

