    tasks=["ORM-মডেলের টেস্ট fixture", "সম্পর্কিত রেকর্ড (ব্যবহারকারী ↔ অর্ডার) একসাথে", "এজ-কেস অবস্থা (Trait) তৈরি", "ডেমো-ডাটাবেস ভরা"],
    caps=["Factory, DjangoModelFactory, SQLAlchemyModelFactory", "Sequence, Faker, LazyAttribute, Iterator", "SubFactory, RelatedFactory(List), Trait, Params", "build/create/stub, *_batch"],
