TYPED = r'''
write("pipeline.py", """
    from dataclasses import dataclass
    from typing import Protocol, TypedDict

    class Reading(TypedDict):
        station: str
        mm: float

    @dataclass
    class Station:
        name: str
        lat: float
        lon: float

    class Sink(Protocol):
        def write(self, rows: list[Reading]) -> int: ...

    def parse(line: str) -> Reading:
        name, mm = line.split(",")
        return {"station": name, "mm": float(mm)}

    def total(rows: list[Reading]) -> float:
        return sum(r["mm"] for r in rows)

    def nearest(stations: list[Station], lat: float, lon: float) -> Station | None:
        return min(stations, key=lambda s: (s.lat - lat) ** 2 + (s.lon - lon) ** 2, default=None)

    class CsvSink:
        def write(self, rows: list[Reading]) -> int:
            return len(rows)

    def run(sink: Sink, lines: list[str]) -> float:
        rows = [parse(l) for l in lines]
        sink.write(rows)
        return total(rows)

    # ---- ভুলগুলো ----
    rows = [parse("Dhaka,12.5"), parse("Sylhet,30")]
    total(rows[0])                                   # ভুল: তালিকা নয়, একটা Reading
    s = nearest([Station("Dhaka", 23.8, 90.4)], 23.7, "90.4")   # ভুল: str দেওয়া হলো
    print(s.name)                                    # ভুল: s None হতে পারে
    bad: Reading = {"station": "Khulna", "rain": 4.0}    # ভুল: অজানা key
    run(object(), ["a,1"])                           # ভুল: Sink প্রোটোকল মানে না
""")
'''

