HOME_PCAP = r'''
import random
from scapy.all import IP, TCP, UDP, DNS, DNSQR, DNSRR, NTP, Raw, wrpcap

# নিজের বাসার নেটওয়ার্কের কৃত্রিম (benign) ট্রাফিক – কোনো অন্যের ডেটা নয়
random.seed(7)
DEV = {"192.168.0.10": "laptop", "192.168.0.11": "phone", "192.168.0.12": "smart-tv", "192.168.0.20": "nas"}
ROUTER, T0 = "192.168.0.1", 1_780_000_000.0
SITES = {"prothomalo.example": "203.0.113.10", "bdnews.example": "203.0.113.11", "video.example": "203.0.113.50",
         "school-portal.example": "198.51.100.7", "updates.example": "198.51.100.20"}
pkts = []
def add(p, t):
    p.time = T0 + t; pkts.append(p)

for t in range(0, 600):                                   # ১০ মিনিট, প্রতি সেকেন্ড
    for ip in ("192.168.0.10", "192.168.0.11"):
        if random.random() < 0.08:                        # DNS জিজ্ঞাসা + উত্তর
            name = random.choice(list(SITES) + ["typo-site.example"])
            qid = random.randint(1, 65535)
            add(IP(src=ip, dst=ROUTER) / UDP(sport=random.randint(40000, 60000), dport=53) / DNS(id=qid, rd=1, qd=DNSQR(qname=name)), t)
            if name in SITES:
                ans = DNS(id=qid, qr=1, ra=1, qd=DNSQR(qname=name), an=DNSRR(rrname=name, ttl=random.choice([60, 300, 3600]), rdata=SITES[name]))
            else:
                ans = DNS(id=qid, qr=1, ra=1, rcode=3, qd=DNSQR(qname=name))     # NXDOMAIN
            add(IP(src=ROUTER, dst=ip) / UDP(sport=53, dport=40000) / ans, t + random.uniform(0.005, 0.08))
        if random.random() < 0.5:                         # সাধারণ ব্রাউজিং (HTTPS)
            srv = random.choice(["203.0.113.10", "203.0.113.11", "198.51.100.7"])
            add(IP(src=srv, dst=ip) / TCP(sport=443, dport=51000, flags="A") / Raw(b"x" * random.randint(200, 1400)), t + random.random())
    if 300 <= t < 540:                                    # সন্ধ্যায় টিভিতে ভিডিও
        for _ in range(random.randint(6, 9)):
            add(IP(src="203.0.113.50", dst="192.168.0.12") / TCP(sport=443, dport=52000, flags="A") / Raw(b"v" * 1400), t + random.random())
    if 120 <= t < 200:                                    # ল্যাপটপ → NAS ব্যাকআপ (SMB)
        for _ in range(4):
            add(IP(src="192.168.0.10", dst="192.168.0.20") / TCP(sport=50100, dport=445, flags="PA") / Raw(b"b" * 1300), t + random.random())
    if t % 64 == 0:                                       # NTP সময় মেলানো
        add(IP(src="192.168.0.20", dst="198.51.100.123") / UDP(sport=123, dport=123) / NTP(), t)
    if t % 20 == 0:                                       # mDNS ঘোষণা
        add(IP(src="192.168.0.12", dst="224.0.0.251") / UDP(sport=5353, dport=5353) / DNS(qd=DNSQR(qname="_googlecast._tcp.local", qtype="PTR")), t)
pkts.sort(key=lambda p: p.time)
wrpcap("home.pcap", pkts)
'''

