print("timestamp little:", enhex(p32(ts)), "| big:", enhex(p32(ts, endian="big")))

rec = flat({0: p16(sid), 2: p32(ts), 6: p16(rain10), 8: p16(temp10, sign="signed")}, filler=b"\x00", length=12)
print(f"\n১২-বাইটের রেকর্ড ({len(rec)} বাইট):")
print(hexdump(rec))
print("\nআবার পড়া:", dict(station=hex(u16(rec[0:2])), ts=u32(rec[2:6]), rain_mm=u16(rec[6:8]) / 10, temp_c=u16(rec[8:10], sign="signed") / 10))

wrong = u32(rec[2:6], endian="big")
