import time
from pwn import process

pathlib.Path("quiz.c").write_text(r"""
#include <stdio.h>
#include <string.h>
static const char *D[][2] = {{"Dhaka","Dhaka"},{"Gazipur","Dhaka"},{"Sylhet","Sylhet"},{"Moulvibazar","Sylhet"},
  {"Khulna","Khulna"},{"Jessore","Khulna"},{"Rajshahi","Rajshahi"},{"Bogura","Rajshahi"},{"Chattogram","Chattogram"},
  {"Cumilla","Chattogram"},{"Barishal","Barishal"},{"Rangpur","Rangpur"},{"Mymensingh","Mymensingh"}};
int main(void){
  char line[64]; setvbuf(stdout, NULL, _IONBF, 0);
  puts("district-quiz v1. type a district:");
  while (printf("> "), fgets(line, sizeof line, stdin)) {
    line[strcspn(line, "\n")] = 0;
    if (!strcmp(line, "quit")) { puts("bye"); return 0; }
    const char *ans = NULL;
    for (unsigned i = 0; i < sizeof D / sizeof D[0]; i++) if (!strcmp(line, D[i][0])) ans = D[i][1];
    if (ans) printf("division: %s\n", ans); else puts("unknown");
  }
  return 0;
}""")
subprocess.run(["gcc", "-O2", "-o", "quiz", "quiz.c"], check=True)

cases = {"Dhaka": "Dhaka", "Gazipur": "Dhaka", "Moulvibazar": "Sylhet", "Jessore": "Khulna", "Bogura": "Rajshahi",
         "Cumilla": "Chattogram", "Barishal": "Barishal", "Rangpur": "Rangpur", "Mymensingh": "Mymensingh", "Sylhet": "Sylhet",
         "Feni": "Chattogram", "Tangail": "Dhaka"}
io = process("./quiz")
print("ব্যানার:", io.recvline().decode().strip())
ok, fail, t = 0, [], time.perf_counter()
for q, want in cases.items():
    io.recvuntil(b"> ")
    io.sendline(q.encode())
    got = io.recvline().decode().strip().removeprefix("division: ")
    if got == want:
        ok += 1
    else:
        fail.append((q, want, got))
io.recvuntil(b"> ")
for weird in ["", "x" * 200, "Dhaka\x00Sylhet", "ঢাকা"]:        # অদ্ভুত ইনপুট – ক্র্যাশ হয় কি?
    io.sendline(weird.encode())
io.sendline(b"quit")
rest = io.recvall(timeout=3).decode(errors="replace")
