PARAMIKO_ENV = r'''import os
import paramiko

# নিজের অনুমোদিত সার্ভারের তথ্য env থেকে – কোডে পাসওয়ার্ড/চাবি নয়
HOST = os.environ.get("SSH_HOST", "backup.school.example")
PORT = int(os.environ.get("SSH_PORT", "22"))
USER = os.environ.get("SSH_USER", "reports")
KEY = os.environ.get("SSH_KEY", os.path.expanduser("~/.ssh/id_ed25519"))
KNOWN = "lab_known_hosts"                       # এই প্রজেক্টের নিজের known_hosts

class TrustOnFirstUse(paramiko.MissingHostKeyPolicy):
    """প্রথমবার host key-এর fingerprint দেখিয়ে সংরক্ষণ; পরে বদলালে paramiko নিজেই BadHostKeyException দেবে।
    প্রোডাকশনে: আগে থেকে যাচাই করা known_hosts + RejectPolicy।"""
    def missing_host_key(self, client, hostname, key):
        client.get_host_keys().add(hostname, key.get_name(), key)
        client.save_host_keys(KNOWN)
        print(f"[TOFU] নতুন host key {key.get_name()} {key.fingerprint} → {KNOWN}-এ রাখা হলো")

def connect():
    c = paramiko.SSHClient()
    if os.path.exists(KNOWN):
        c.load_host_keys(KNOWN)
    c.set_missing_host_key_policy(TrustOnFirstUse())
    c.connect(HOST, port=PORT, username=USER, key_filename=KEY, look_for_keys=False, allow_agent=False, timeout=10)
    return c
'''

