import json
import pathlib
import time

REMOTE = "/tmp/lab_reports"                      # সার্ভারের রিপোর্ট-ফোল্ডার
LOCAL = pathlib.Path("backup"); LOCAL.mkdir(exist_ok=True)
MANIFEST = LOCAL / "manifest.json"

c = connect()
# ডেমোর জন্য সার্ভারে কয়েকটা রিপোর্ট বানানো (আসল সার্ভারে এগুলো আগে থেকেই থাকে)
