regs = {"EAX": UC_X86_REG_EAX, "EBX": UC_X86_REG_EBX, "ECX": UC_X86_REG_ECX, "EDX": UC_X86_REG_EDX}
print("আগে:", {k: mu.reg_read(v) for k, v in regs.items()})
