fl = mu.reg_read(UC_X86_REG_EFLAGS)
print(f"EFLAGS=0x{fl:x}  ZF={(fl >> 6) & 1} SF={(fl >> 7) & 1} CF={fl & 1}  RIP শেষে = 0x{mu.reg_read(UC_X86_REG_RIP):x}")
