fig, (a1, a2) = plt.subplots(2, 1, figsize=(12, 5.6), sharex=True, gridspec_kw={"height_ratios": [2.2, 1]})
steps = range(len(trace))
a1.step(steps, [t[2] for t in trace], where="post", color="#7c3aed", lw=2)
for step, (off, m, eax, edx) in enumerate(trace):
    if m == "add" and edx in (4, 5, 6):
        a1.annotate(f"+{RAIN[edx]} ({['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][edx]})", (step + 1, eax + RAIN[edx]),
                    xytext=(-30, 12), textcoords="offset points", fontsize=8.5, color="#4c1d95", arrowprops=dict(arrowstyle="-", color="#c4b5fd"))
a1.set_ylabel("EAX (running sum, mm)")
a2.step(steps, [t[3] for t in trace], where="post", color="#0d9488", lw=2); a2.set_ylabel("EDX (index)"); a2.set_xlabel("instruction step")
colors = {"add": "#7c3aed", "inc": "#0d9488", "cmp": "#f59e0b", "jl": "#e11d48", "xor": "#9ca3af"}
