    caps=["x86, ARM, ARM64, RISC-V, MIPS, PPC, SPARC, s390x", "hook: code, block, mem read/write, unmapped, interrupt", "context save/restore, mem_protect", "Capstone/Keystone-এর সাথে জুটি"],
