b1 = ax.bar(xs - w / 2, [cb[s] for s in sev], w, color="#e11d48", label="before")
b2 = ax.bar(xs + w / 2, [ca[s] for s in sev], w, color="#0d9488", label="after fixes")
ax.bar_label(b1, fontsize=10, padding=2); ax.bar_label(b2, fontsize=10, padding=2)
