ax.text(0.99, 0.95, "red = before   teal = after fixes", transform=ax.transAxes, ha="right", fontsize=9.5, color="#374151")
ax.set_ylim(0, max(cb.values()) * 1.25)
ax.set_title(f"Fixing the report tool took Bandit findings from {len(before)} to {len(after)}", loc="left", fontsize=12.5, fontweight="bold", pad=28)
ax.text(0, 1.03, "bandit -r app with pyproject config; one justified '# nosec B603 B607' kept, baseline used to gate new code", transform=ax.transAxes, fontsize=9.5, color="#6b7280")
