RAINKIT_PKG = r'''import pathlib

def w(p, t):
    p = pathlib.Path(p); p.parent.mkdir(parents=True, exist_ok=True); p.write_text(t, encoding="utf-8")

w("rainkit/__init__.py", '"""rainkit – small tools for rain-gauge data."""\nfrom .stats import monthly_total, wettest_month, RainSeries\n')
w("rainkit/stats.py", """from __future__ import annotations


def monthly_total(daily: list[float]) -> list[float]:
    \"\"\"Sum 365 daily values into 12 monthly totals.

    Parameters
    ----------
    daily : list of float
        Daily rainfall in mm for a non-leap year.

    Returns
    -------
    list of float
        Twelve monthly totals.

    Examples
    --------
    >>> monthly_total([1.0] * 365)[:3]
    [31.0, 28.0, 31.0]
    \"\"\"
    days = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    out, i = [], 0
    for d in days:
        out.append(sum(daily[i:i + d])); i += d
    return out


def wettest_month(monthly: list[float]) -> int:
    \"\"\"Return the 1-based index of the wettest month.

    >>> wettest_month([12, 40, 160, 377, 574, 819, 816, 636, 518, 251, 34, 10])
    6
    \"\"\"
    return max(range(12), key=lambda m: monthly[m]) + 1


class RainSeries:
    \"\"\"A station's daily series with metadata.

    Parameters
    ----------
    station : str
        Gauge code, e.g. ``"SYL-01"``.
    values : list of float
        Daily rainfall (mm).
    \"\"\"

    def __init__(self, station: str, values: list[float]):
        self.station, self.values = station, values

    def total(self) -> float:
        \"\"\"Total rainfall over the whole series (mm).\"\"\"
        return sum(self.values)
""")
'''

