BD = r'''import pathlib
import requests

GB = "https://media.githubusercontent.com/media/wmgeolab/geoBoundaries/main/releaseData/gbOpen/BGD/{0}/geoBoundaries-BGD-{0}_simplified.geojson"
def bd(level="ADM2"):
    """ADM1 = ৮ বিভাগ, ADM2 = ৬৪ জেলা, ADM3 = উপজেলা – প্রথমবার নামিয়ে রাখে।"""
    p = pathlib.Path(f"bd_{level}.geojson")
    if not p.exists():
        p.write_bytes(requests.get(GB.format(level), timeout=120).content)
    return str(p)
'''

