S2 = r'''import pystac_client
STAC = "https://earth-search.aws.element84.com/v1"          # AWS-এর উন্মুক্ত Sentinel-2 (কোনো চাবি লাগে না)
def s2_items(bbox, dates, max_cloud=10, limit=50):
    cat = pystac_client.Client.open(STAC)
    s = cat.search(collections=["sentinel-2-l2a"], bbox=bbox, datetime=dates, query={"eo:cloud_cover": {"lt": max_cloud}},
                   sortby=[{"field": "properties.eo:cloud_cover", "direction": "asc"}], max_items=limit)
    return list(s.items())

def covers(item, bbox):
    """দৃশ্যটা কি পুরো এলাকা ঢাকে? (টাইলের কিনারায় পড়লে অর্ধেক ফাঁকা আসে)"""
    from shapely import box
    from shapely.geometry import shape
    return shape(item.geometry).contains(box(*bbox))
'''

