dist.loc[miss, "division"] = fix["division"].values
print("sjoin_nearest দিয়ে ঠিক করা:", dict(zip(dist.district[miss], dist.division[miss])), "· এখন বাকি:", dist.division.isna().sum())
by = dist.dissolve(by="division", aggfunc={"area_km2": "sum", "district": "count"}).rename(columns={"district": "districts"})
print("\n", by[["districts", "area_km2"]].sort_values("area_km2", ascending=False).round(0).to_string())
print(f"\nমোট {dist.area_km2.sum():,.0f} km² (সরকারি হিসাব ~১,৪৭,৫৭০ km² – সরল করা সীমানায় সামান্য কম/বেশি হয়)")
