HIMA = r'''import pathlib
import requests

def himawari(when="20240526_1200", bands=("B13",), segments=("0310", "0410")):
    """NOAA-র উন্মুক্ত Himawari-9 HSD ফাইল (AWS) – বাংলাদেশ ও বঙ্গোপসাগর পড়ে ১০ ভাগের ৩-৪ নম্বর ভাগে।"""
    d, t = when.split("_"); out = []
    for b in bands:
        res = "R20" if b not in ("B01", "B02", "B04", "B03") else ("R05" if b == "B03" else "R10")
        for s in segments:
            fn = pathlib.Path(f"HS_H09_{when}_{b}_FLDK_{res}_S{s}.DAT.bz2")
            if not fn.exists():
                url = f"https://noaa-himawari9.s3.amazonaws.com/AHI-L1b-FLDK/{d[:4]}/{d[4:6]}/{d[6:]}/{t}/{fn.name}"
                fn.write_bytes(requests.get(url, timeout=300).content)
            out.append(str(fn))
    return out
'''

