with rasterio.open("dem.tif") as s:
    crs, tr0, z = s.crs, s.transform, s.read(1)
with rasterio.open("acc.tif") as a, rasterio.open("streams.tif") as sm:
    A, S = a.read(1), sm.read(1)
# নির্গম-বিন্দু: পাহাড় থেকে সমতলে নামার মুখ = ২৫–৬০ মি উচ্চতার স্রোত-কোষের মধ্যে যেখানে সবচেয়ে বেশি পানি জমে
cand = np.where((S > 0) & (z >= 25) & (z <= 60), A, 0)
r_, c_ = np.unravel_index(np.argmax(cand), cand.shape)
x0, y0 = rasterio.transform.xy(tr0, r_, c_)
gpd.GeoDataFrame(geometry=[Point(x0, y0)], crs=crs).to_file("outlet.shp")
