print(f"watershed: {int((ws > 0).sum()):,} কোষ ≈ {area:,.0f} km² · অববাহিকার উচ্চতা {dem[ws > 0].min():.0f}–{dem[ws > 0].max():.0f} m")
ext = [tr.c, tr.c + tr.a * dem.shape[1], tr.f + tr.e * dem.shape[0], tr.f]
fig, ax = plt.subplots(figsize=(10, 8))
ax.imshow(dem, cmap="Greys", extent=ext, vmin=-300, vmax=float(dem.max()) * 1.3)              # হালকা ধূসর ভিত্তি, যাতে নদী আর অববাহিকা চোখে পড়ে
ax.imshow(np.ma.masked_where(~(ws > 0).filled(False), np.ones(ws.shape)), cmap="Purples", alpha=0.45, vmin=0, vmax=1.3, extent=ext)
ax.imshow(np.ma.masked_where(~(st > 0).filled(False), np.log10(acc.filled(1))), cmap="Blues", vmin=2.5, vmax=5.5, extent=ext)
ax.plot(snap.x, snap.y, "o", color="#e11d48", ms=9, mec="white")
ax.set_xlabel("longitude"); ax.set_ylabel("latitude")
ax.set_title(f"The largest river leaving the hills here collects water from about {area:,.0f} km² (purple)", loc="left", fontsize=12.5, fontweight="bold", pad=26)
ax.text(0, 1.02, "Copernicus GLO-30 DEM · WhiteboxTools breach → D8 pointer → flow accumulation → streams (>1000 cells, blue) → watershed (purple)",
        transform=ax.transAxes, fontsize=9, color="#6b7280")
