# ------------------------------------------------------------------ d3-geo
jslib("d3-geo",
    about=("d3-geo হলো D3-র ভূগোল-মডিউল – গোলকের GeoJSON-কে যেকোনো projection-এ SVG/canvas path বানায়: geoPath, ৩০+ projection (Mercator, Equal Earth, Natural Earth, Orthographic, "
           "Azimuthal Equidistant, Albers, Conic…; d3-geo-projection-এ আরো শতাধিক – Robinson, Winkel Tripel…), rotate/clipAngle দিয়ে ঘোরানো গ্লোব, fitSize দিয়ে স্বয়ংক্রিয় মাপ, "
           "geoGraticule, geoCircle, geoDistance/geoLength/geoArea/geoCentroid (গোলকের ওপর আসল হিসাব), geoInterpolate দিয়ে বৃহৎ-বৃত্ত পথ। TopoJSON-এর সাথে মিলে বিশ্ব-মানচিত্রের মান-দণ্ড।"),
    install="npm install d3-geo d3-geo-projection topojson-client\n<!-- বা পুরো d3@7.9.0 (d3-geo ভেতরে আছে) -->",
    examples=[
        jlive("d3geo", "টেনে ঘোরানো যায় এমন অর্থোগ্রাফিক গ্লোব – বাংলাদেশ হাইলাইট, graticule, আর ঢাকা থেকে বৃহৎ-বৃত্ত পথে উড়ে যাওয়া",
              "world-atlas-এর ১১০m TopoJSON → topojson.feature; d3.geoOrthographic, clipAngle ৯০°, মাউস/আঙুলে টানলে d3.drag দিয়ে rotate বদলায় (না টানলে নিজে ঘোরে); "
              "ড্রপডাউনে শহর বেছে নিলে d3.geoInterpolate দিয়ে বৃহৎ-বৃত্ত পথ আঁকা আর উড়োজাহাজ চলে, d3.geoDistance দিয়ে km।",
              r'''const app = document.getElementById("app");
app.innerHTML = `<div class="row"><b>ঢাকা →</b><select id="to"><option value="139.69,35.68">Tokyo</option><option value="-0.13,51.51" selected>London</option><option value="-74.0,40.71">New York</option>
<option value="151.21,-33.87">Sydney</option><option value="39.83,21.42">Makkah</option><option value="-46.63,-23.55">São Paulo</option></select><span id="out" class="muted"></span></div>
<svg id="s" viewBox="0 0 400 340" style="width:100%;height:345px;cursor:grab"></svg>`;
const world = await (await fetch(''' + WORLD + r''')).json();
const land = topojson.feature(world, world.objects.countries);
const bd = land.features.find(f => f.properties.name === "Bangladesh");
const DHAKA = [90.39, 23.73];
const proj = d3.geoOrthographic().fitExtent([[10, 10], [390, 330]], {type: "Sphere"}).rotate([-80, -15]).clipAngle(90);
const path = d3.geoPath(proj), grat = d3.geoGraticule10();
const svg = d3.select("#s");
const sphere = svg.append("path").attr("fill", "#140e29");
const g1 = svg.append("path").attr("fill", "none").attr("stroke", "#4c1d95").attr("stroke-width", 0.5);
const countries = svg.append("g").selectAll("path").data(land.features).join("path").attr("fill", f => f === bd ? "#e11d48" : "#c4b5fd").attr("stroke", "#140e29").attr("stroke-width", 0.4);
const route = svg.append("path").attr("fill", "none").attr("stroke", "#facc15").attr("stroke-width", 2).attr("stroke-dasharray", "5 3");
const plane = svg.append("circle").attr("r", 4.5).attr("fill", "#facc15").attr("stroke", "#140e29");
let dest = [-0.13, 51.51], interp, t = 0, auto = true;
function redraw() { sphere.attr("d", path({type: "Sphere"})); g1.attr("d", path(grat)); countries.attr("d", path);
  route.attr("d", path({type: "LineString", coordinates: [DHAKA, dest]}));
  const p = interp(t), visible = d3.geoDistance(p, [-proj.rotate()[0], -proj.rotate()[1]]) < Math.PI / 2;
  const xy = proj(p); plane.attr("cx", xy[0]).attr("cy", xy[1]).attr("opacity", visible ? 1 : 0); }
function setDest(v) { dest = v.split(",").map(Number); interp = d3.geoInterpolate(DHAKA, dest); t = 0;
  document.getElementById("out").textContent = `বৃহৎ-বৃত্ত দূরত্ব ${Math.round(d3.geoDistance(DHAKA, dest) * 6371).toLocaleString()} km · গ্লোব টেনে ঘোরাও`; }
document.getElementById("to").onchange = e => setDest(e.target.value);
svg.call(d3.drag().on("start", () => auto = false).on("drag", e => { const r = proj.rotate(); proj.rotate([r[0] + e.dx * 0.4, r[1] - e.dy * 0.4]); redraw(); })
  .on("end", () => setTimeout(() => auto = true, 2500)));
setDest(document.getElementById("to").value);
d3.timer(() => { if (auto) { const r = proj.rotate(); proj.rotate([r[0] + 0.15, r[1]]); } t = (t + 0.004) % 1; redraw(); });
'''),
        jlive("d3geo", "প্রজেক্ট: projection-তুলনার এক্সপ্লোরার – ছয়টা প্রক্ষেপণ, ঢাকা থেকে দূরত্বের choropleth আর Tissot-বৃত্তে বিকৃতি",
              "ড্রপডাউনে Equal Earth, Natural Earth, Mercator, Robinson (d3-geo-projection), ঢাকা-কেন্দ্রিক Azimuthal Equidistant (সব দূরত্ব ঢাকা থেকে সঠিক – ৫০০০ km-এর বৃত্ত) আর Orthographic; "
              "দেশের রঙ = ঢাকা থেকে বৃত্ত-দূরত্ব, প্রতি ৩০°-এ একই আকারের (৫°) d3.geoCircle – Mercator-এ মেরুর দিকে কত ফুলে ওঠে চোখে পড়ে; মাউস নিলে দেশ আর km।",
              r'''const app = document.getElementById("app");
app.innerHTML = `<div class="row"><select id="p"><option>Equal Earth</option><option>Natural Earth</option><option>Mercator</option><option>Robinson</option>
<option selected>Azimuthal Equidistant (Dhaka)</option><option>Orthographic</option></select><label><input type="checkbox" id="ti" checked style="padding:0"> Tissot</label><span id="out" class="muted"></span></div>
<svg id="s" viewBox="0 0 480 300" style="width:100%;height:340px;background:#fff;border-radius:12px"></svg>`;
const world = await (await fetch(''' + WORLD + r''')).json();
const land = topojson.feature(world, world.objects.countries);
const DHAKA = [90.39, 23.73];
for (const f of land.features) f.properties.km = d3.geoDistance(DHAKA, d3.geoCentroid(f)) * 6371;
const color = d3.scaleSequential(d3.interpolateRgb("#f5f3ff", "#2e1065")).domain([0, 18000]);
const tissot = []; for (let lat = -60; lat <= 60; lat += 30) for (let lon = -180; lon < 180; lon += 30) tissot.push(d3.geoCircle().center([lon, lat]).radius(5)());
const rings = [5000, 10000, 15000].map(km => ({km, g: d3.geoCircle().center(DHAKA).radius(km / 6371 * 180 / Math.PI)()}));
const P = {"Equal Earth": () => d3.geoEqualEarth(), "Natural Earth": () => d3.geoNaturalEarth1(), "Mercator": () => d3.geoMercator().clipExtent(null),
  "Robinson": () => d3.geoRobinson(), "Azimuthal Equidistant (Dhaka)": () => d3.geoAzimuthalEquidistant().rotate([-DHAKA[0], -DHAKA[1]]).clipAngle(179.9),
  "Orthographic": () => d3.geoOrthographic().rotate([-DHAKA[0], -DHAKA[1]])};
const svg = d3.select("#s");
function draw() {
  const name = document.getElementById("p").value;
  let proj = P[name]();
  proj = name === "Mercator" ? proj.fitExtent([[5, 5], [475, 295]], {type: "LineString", coordinates: [[-179, -70], [179, 80]]}) : proj.fitExtent([[5, 5], [475, 295]], {type: "Sphere"});
  const path = d3.geoPath(proj);
  svg.selectAll("*").remove();
  if (name !== "Mercator") svg.append("path").attr("d", path({type: "Sphere"})).attr("fill", "#faf7ff").attr("stroke", "#c4b5fd");
  svg.append("path").attr("d", path(d3.geoGraticule10())).attr("fill", "none").attr("stroke", "#ede9fe").attr("stroke-width", 0.5);
  svg.append("g").selectAll("path").data(land.features).join("path").attr("d", path).attr("fill", f => color(f.properties.km)).attr("stroke", "#fff").attr("stroke-width", 0.3)
    .on("mousemove", (e, f) => document.getElementById("out").textContent = `${f.properties.name}: ঢাকা থেকে ~${Math.round(f.properties.km).toLocaleString()} km`);
  if (document.getElementById("ti").checked) svg.append("g").selectAll("path").data(tissot).join("path").attr("d", path).attr("fill", "#e11d48").attr("fill-opacity", 0.55);
  if (name.startsWith("Azimuthal")) svg.append("g").selectAll("path").data(rings).join("path").attr("d", r => path(r.g)).attr("fill", "none").attr("stroke", "#f59e0b").attr("stroke-dasharray", "4 3");
  const dhaka = proj(DHAKA); if (dhaka) svg.append("circle").attr("cx", dhaka[0]).attr("cy", dhaka[1]).attr("r", 3.5).attr("fill", "#f59e0b").attr("stroke", "#140e29");
  const area = d3.geoArea(land.features.find(f => f.properties.name === "Bangladesh")) * 6371 ** 2;
  document.getElementById("out").textContent = `${name} · বাংলাদেশ গোলকের ওপর ${Math.round(area).toLocaleString()} km² (d3.geoArea) · মাউস নাও`;
}
document.getElementById("p").onchange = draw; document.getElementById("ti").onchange = draw;
draw();
''', hint=SHOW),
    ],
    level="মাঝারি", tag="GeoJSON → যেকোনো projection-এ SVG/canvas পথ।",
    tasks=["বিশ্ব/দেশের choropleth যেকোনো প্রক্ষেপণে", "ঘোরানো গ্লোব ও বৃহৎ-বৃত্ত পথ", "প্রক্ষেপণের বিকৃতি শেখানো (Tissot)", "নিউজরুম-ধাঁচের স্ট্যাটিক/ইন্টার‍্যাক্টিভ মানচিত্র"],
    caps=["geoPath (SVG/canvas), projection.fitSize/fitExtent, rotate, clipAngle", "৩০+ projection + d3-geo-projection-এ শতাধিক", "geoDistance, geoArea, geoCentroid, geoLength, geoContains (গোলকে)", "geoGraticule, geoCircle, geoInterpolate, geoStream"],
    limits=["টাইল-মানচিত্র নয় (রাস্তা/স্যাটেলাইট নেই)", "বড় GeoJSON-এ SVG ধীর – canvas বা সরলীকরণ", "projection ছাড়া planar হিসাব নেই (JSTS/Turf)"],
    alt="Observable Plot (geo mark), Vega-Lite geoshape, Leaflet, cartopy (পাইথন)",
)

