# ------------------------------------------------------------------ GeoTIFF.js
RAMP_JS = r'''// উচ্চতা → রঙ (নিচু সবুজ → বাদামি → সাদা), সাথে সহজ hillshade
const RAMP = [[0, [22, 101, 52]], [50, [134, 239, 172]], [200, [250, 204, 21]], [600, [180, 83, 9]], [1200, [120, 53, 15]], [1800, [250, 250, 250]]];
const ramp = h => { let i = 1; while (i < RAMP.length - 1 && h > RAMP[i][0]) i++;
  const [a, ca] = RAMP[i - 1], [b, cb] = RAMP[i], t = Math.max(0, Math.min(1, (h - a) / (b - a))); return ca.map((v, k) => v + (cb[k] - v) * t); };
'''

