x, y, z = g.points.T
src = [(1300, 2300, -40, 900), (2900, 1200, -70, 700)]                                   # (x, y, গভীরতা, ছড়ানো) – কাল্পনিক উৎস
c = sum(260 * np.exp(-((x - a) ** 2 + (y - b) ** 2) / (2 * s ** 2) - ((z - d) / 45) ** 2) for a, b, d, s in src)
