# ------------------------------------------------------------------ Open3D
O3D_SNAP = r'''import numpy as np
import open3d as o3d
from open3d.visualization import rendering

def snapshot(geoms, fn, w=900, h=640, eye=(0, -3, 2), center=(0, 0, 0), bg=(0.04, 0.03, 0.13, 1), point=2.5):
    """অফস্ক্রিন রেন্ডার (GPU না থাকলেও EGL/CPU-তে চলে) – নিজের পিসিতে o3d.visualization.draw(...) দিয়ে ইন্টার‍্যাক্টিভ"""
    r = rendering.OffscreenRenderer(w, h)
    r.scene.set_background(bg)
    for k, g in enumerate(geoms):
        m = rendering.MaterialRecord()
        m.shader = "defaultUnlit" if isinstance(g, (o3d.geometry.PointCloud, o3d.geometry.LineSet)) else "defaultLit"
        m.point_size = point; m.line_width = 2
        r.scene.add_geometry(f"g{k}", g, m)
    r.setup_camera(55, list(center), list(eye), [0, 0, 1])
    o3d.io.write_image(fn, r.render_to_image())
'''

