pcd = o3d.io.read_point_cloud(o3d.data.DemoICPPointClouds().paths[0])
print(f"আসল স্ক্যান: {len(pcd.points):,} বিন্দু · মাপ (m): {np.round(pcd.get_max_bound() - pcd.get_min_bound(), 2)}")
down = pcd.voxel_down_sample(0.02)
down, keep = down.remove_statistical_outlier(nb_neighbors=20, std_ratio=2.0)
down.estimate_normals(o3d.geometry.KDTreeSearchParamHybrid(radius=0.06, max_nn=30))
print(f"voxel ২ সেমি + outlier বাদ: {len(down.points):,} বিন্দু")
