COL = [(0.49, 0.23, 0.93), (0.05, 0.58, 0.53), (0.96, 0.62, 0.04)]
for k in range(3):
    model, idx = rest.segment_plane(distance_threshold=0.02, ransac_n=3, num_iterations=1000)
    pl = rest.select_by_index(idx).paint_uniform_color(COL[k]); planes.append(pl)
    a, b, c, d = model
