topo("নোংরা")
ms.meshing_remove_duplicate_vertices(); ms.meshing_remove_unreferenced_vertices(); ms.meshing_remove_duplicate_faces()
ms.meshing_repair_non_manifold_edges(); ms.meshing_re_orient_faces_coherently()
topo("পরিষ্কার")
before = ms.current_mesh().vertex_matrix().copy()
ms.apply_coord_taubin_smoothing(lambda_=0.5, mu=-0.53, stepsmoothnum=15)
