def look_at(eye, target=(0, 0, 0.42), up=(0, 0, 1)):
    eye, target, up = (np.asarray(v, float) for v in (eye, target, up)); z = eye - target; z /= np.linalg.norm(z); x = np.cross(up, z); x /= np.linalg.norm(x); y = np.cross(z, x)
    T = np.eye(4); T[:3, 0], T[:3, 1], T[:3, 2], T[:3, 3] = x, y, z, eye; return T
