img = rng.normal(90, 12, (N, N)).astype("float32")                           # পটভূমি শব্দ
for cx, cy, r in zip(rng.uniform(0, N, 2500), rng.uniform(0, N, 2500), rng.uniform(8, 40, 2500)):
    x0, x1, y0, y1 = int(max(cx - 3 * r, 0)), int(min(cx + 3 * r, N)), int(max(cy - 3 * r, 0)), int(min(cy + 3 * r, N))
    yy, xx = np.ogrid[y0:y1, x0:x1]
    img[y0:y1, x0:x1] += 900 * np.exp(-((xx - cx) ** 2 + (yy - cy) ** 2) / (2 * r ** 2))
print(f"ছবি {N}×{N} = {N * N / 1e6:.0f} মেগাপিক্সেল · {img.nbytes / 1e6:.0f} MB float32 · মান {img.min():.0f}–{img.max():.0f}")
