cols = [("ambient only", False, False), ("+ diffuse (Lambert)", True, False), ("+ specular (Phong, shininess 40)", True, True)]
fig, axes = plt.subplots(2, 3, figsize=(12, 6.6), facecolor="white")
for r, smooth in enumerate((False, True)):
    for c, (t_, d, s) in enumerate(cols):
        im = frame(d, s, smooth); axes[r, c].imshow(im); axes[r, c].axis("off")
