ti.sync(); tt = time.perf_counter() - t0
p, v = pos.to_numpy(), vel.to_numpy(); t0 = time.perf_counter()
for s in range(20):                                       # numpy-তে মাত্র ২০ ধাপ (একই সূত্র)
    a = np.tile([0.0, -0.05], (N, 1))
