BPY_COMMON = r'''import math
import bpy
import numpy as np

def reset():
    bpy.ops.wm.read_factory_settings(use_empty=True)
    s = bpy.context.scene; s.render.engine = "CYCLES"; s.cycles.device = "CPU"          # GPU থাকলে "GPU"
    s.cycles.samples = 24; s.cycles.use_denoising = True; s.render.film_transparent = False
    w = bpy.data.worlds.new("world"); s.world = w; w.use_nodes = True
    w.node_tree.nodes["Background"].inputs[0].default_value = (0.93, 0.91, 0.98, 1); w.node_tree.nodes["Background"].inputs[1].default_value = 0.6
    return s

def revolve(name, prof, sections=96):
    """প্রোফাইল (ব্যাসার্ধ, উচ্চতা) ঘুরিয়ে বস্তু – কলসি, বাটি, লোটা"""
    verts, faces = [], []
    for r, z in prof:
        for k in range(sections):
            a = 2 * math.pi * k / sections; verts.append((r * math.cos(a), r * math.sin(a), z))
    for i in range(len(prof) - 1):
        for k in range(sections):
            a, b = i * sections + k, i * sections + (k + 1) % sections
            faces.append((a, b, b + sections, a + sections))
    me = bpy.data.meshes.new(name); me.from_pydata(verts, [], faces); me.update()
    ob = bpy.data.objects.new(name, me); bpy.context.collection.objects.link(ob)
    for p in me.polygons:
        p.use_smooth = True
    sub = ob.modifiers.new("subsurf", "SUBSURF"); sub.levels = sub.render_levels = 1
    sol = ob.modifiers.new("solid", "SOLIDIFY"); sol.thickness = 0.02
    return ob

def material(name, color, rough=0.6, metallic=0.0, bump=0.0):
    m = bpy.data.materials.new(name); m.use_nodes = True; nt = m.node_tree; b = nt.nodes["Principled BSDF"]
    b.inputs["Base Color"].default_value = (*color, 1); b.inputs["Roughness"].default_value = rough; b.inputs["Metallic"].default_value = metallic
    if bump:
        tex = nt.nodes.new("ShaderNodeTexNoise"); tex.inputs["Scale"].default_value = 60
        bm = nt.nodes.new("ShaderNodeBump"); bm.inputs["Strength"].default_value = bump
        nt.links.new(tex.outputs["Fac"], bm.inputs["Height"]); nt.links.new(bm.outputs["Normal"], b.inputs["Normal"])
    return m

def stage(size=8):
    bpy.ops.mesh.primitive_plane_add(size=size); fl = bpy.context.active_object; fl.data.materials.append(material("floor", (0.85, 0.83, 0.9), 0.9))
    for loc, rot, energy, sz in [((3, -3, 4), (0.8, 0, 0.8), 600, 3), ((-4, -1, 2.5), (1.2, 0, -1.2), 200, 4), ((0, 4, 3), (-0.9, 0, 0), 300, 3)]:
        d = bpy.data.lights.new("area", "AREA"); d.energy = energy; d.size = sz
        o = bpy.data.objects.new("light", d); o.location = loc; o.rotation_euler = rot; bpy.context.collection.objects.link(o)

def camera(loc, target=(0, 0, 0.45), lens=60):
    c = bpy.data.cameras.new("cam"); c.lens = lens; o = bpy.data.objects.new("cam", c); bpy.context.collection.objects.link(o)
    o.location = loc; tr = o.constraints.new("TRACK_TO")
    e = bpy.data.objects.new("target", None); e.location = target; bpy.context.collection.objects.link(e); tr.target = e
    bpy.context.scene.camera = o
    return o, e
'''

