GS_PY = r'''import math
import torch
from gsplat import rasterization          # CUDA লাগে

device = "cuda"
def camera(w, h, fov=60.0, z=3.0):
    f = 0.5 * w / math.tan(math.radians(fov) / 2)
    K = torch.tensor([[f, 0, w / 2], [0, f, h / 2], [0, 0, 1]], device=device)[None]
    view = torch.eye(4, device=device)[None]; view[0, 2, 3] = z           # world → camera
    return view, K
'''

