for op in (0.2, 0.9):
    rgb, alpha, meta = rasterization(means, quats, scales, torch.full((N,), op, device=device), colors, view, K, W, H)
    imgs.append(rgb[0].permute(2, 0, 1))
    print(f"opacity {op}: ছবি {tuple(rgb.shape)} · গড় alpha {alpha.mean():.2f} · দৃশ্যমান গাউসিয়ান {int((meta['radii'] > 0).any(-1).sum()) if 'radii' in meta else '?'}")
