THREE_IMP = r'''// Three.js ESM – esm.sh একই সংস্করণের three আর addon মিলিয়ে দেয়
const THREE = await import("https://esm.sh/three@0.187.0");
const {OrbitControls} = await import("https://esm.sh/three@0.187.0/examples/jsm/controls/OrbitControls.js");
'''

TERRARIUM_JS = r'''// AWS-এর উন্মুক্ত উচ্চতা-টাইল (Terrarium PNG: উচ্চতা = R·256 + G + B/256 − 32768 মিটার) – z8/193/109 = সিলেট সমতল + মেঘালয়
async function terrarium(z = 8, x = 193, y = 109) {
  const img = new Image(); img.crossOrigin = "anonymous";
  img.src = `https://s3.amazonaws.com/elevation-tiles-prod/terrarium/${z}/${x}/${y}.png`; await img.decode();
  const c = document.createElement("canvas"); c.width = c.height = 256; const g = c.getContext("2d"); g.drawImage(img, 0, 0);
  const d = g.getImageData(0, 0, 256, 256).data, h = new Float32Array(256 * 256);
  for (let i = 0; i < h.length; i++) h[i] = Math.max(0, d[i * 4] * 256 + d[i * 4 + 1] + d[i * 4 + 2] / 256 - 32768);
  return h;                                               // ২৫৬×২৫৬, সারি ধরে উত্তর → দক্ষিণ
}
'''

