# নৌকা একবার বানিয়ে Group-এ রাখি, তারপর আলাদা জায়গায়/মাপে বসাই
def boat():
    g = dw.Group()
    g.append(dw.Path(fill="#140e29").M(-40, 0).L(40, 0).L(28, 14).L(-28, 14).Z())
    g.append(dw.Line(0, 0, 0, -46, stroke="#140e29", stroke_width=2))
    g.append(dw.Path(fill="#faf7ff").M(2, -44).L(30, -6).L(2, -6).Z())
    return g

for x, y, s in [(150, 270, 1.0), (380, 285, .7), (560, 262, .5)]:
    d.append(dw.Use(boat(), 0, 0, transform=f"translate({x},{y}) scale({s})"))

d.append(dw.Text("পদ্মার সন্ধ্যা", 34, 40, 64, fill="#faf7ff", font_family="Noto Sans Bengali, sans-serif", font_weight="bold"))
d.append(dw.Text("drawsvg দিয়ে আঁকা · পুরোটাই ভেক্টর", 14, 42, 92, fill="#ede9fe", font_family="Noto Sans Bengali, sans-serif"))
d.save_svg("padma.svg")
svg = d.as_svg()
print(len(svg), "অক্ষরের SVG ফাইল। শুরুটা:")
print(svg[:260])
