W, H, BASE, TOP = 760, 420, 360, 110
DUR = 6.0
d = dw.Drawing(W, H, animation_config=dw.types.SyncedAnimationConfig(
    duration=DUR, show_playback_progress=True, show_playback_controls=True))
d.append(dw.Rectangle(0, 0, W, H, fill="#0b0820"))
random.seed(3)
for k in range(70):                                 # বৃষ্টির ফোঁটা – লুপে পড়ে
    x, y0, speed = random.uniform(0, W), random.uniform(-H, 0), random.uniform(.8, 1.6)
    drop = dw.Rectangle(x, y0, 1.6, 14, rx=.8, fill="#38bdf8", opacity=.45)
    for t in range(0, 61):
        tt = t * DUR / 60
        drop.add_key_frame(tt, y=(y0 + tt * 260 * speed) % (H + 40) - 20)
    d.append(drop)

peak = int(mm.argmax())
d.append(dw.Text(f"ঢাকা ২০২৪: সবচেয়ে বেশি বৃষ্টি {MONTHS[peak]} মাসে – {bn(round(mm[peak]))} মিমি", 22, 26, 44,
                 fill="#faf7ff", font_family="Noto Sans Bengali", font_weight="bold"))
d.append(dw.Text("মাসিক মোট বৃষ্টি · ERA5 (Open-Meteo) · drawsvg SMIL অ্যানিমেশন", 13, 26, 68, fill="#a5a0c8", font_family="Noto Sans Bengali"))
bw, gap = 46, 12
scale = (BASE - TOP) / mm.max()
for m in range(12):
    x = 40 + m * (bw + gap)
    h = mm[m] * scale
    t0 = .3 + m * .3                                # মাস ধরে পরপর ওঠে
    color = "#0d9488" if m != peak else "#f59e0b"
    bar = dw.Rectangle(x, BASE, bw, 0, fill=color, rx=4)
    bar.add_key_frame(0, y=BASE, height=0)
    bar.add_key_frame(t0, y=BASE, height=0)
    bar.add_key_frame(t0 + .8, y=BASE - h, height=h)
    bar.add_key_frame(DUR, y=BASE - h, height=h)
    d.append(bar)
    lab = dw.Text(bn(round(mm[m])), 12, x + bw / 2, BASE - h - 7, text_anchor="middle", fill="#faf7ff", font_family="Noto Sans Bengali")
    lab.add_key_frame(0, opacity=0); lab.add_key_frame(t0 + .6, opacity=0); lab.add_key_frame(t0 + 1.0, opacity=1); lab.add_key_frame(DUR, opacity=1)
    d.append(lab)
    d.append(dw.Text(MONTHS[m], 12, x + bw / 2, BASE + 18, text_anchor="middle", fill="#c4b5fd", font_family="Noto Sans Bengali"))
d.save_svg("dhaka_rain_animated.svg")
print("অ্যানিমেশন-ট্যাগ:", d.as_svg().count("<animate"), "টা · ব্রাউজারে খুললেই চলে")
