dwg.add(dwg.line((tx, ty + 30 + len(ROOMS) * 20), (tx + 170, ty + 30 + len(ROOMS) * 20), stroke="#140e29"))
dwg.add(dwg.text(f"মোট {total:,}", insert=(tx + 170, ty + 50 + len(ROOMS) * 20), class_="room", text_anchor="end"))
dwg.save(pretty=True)
print(f"{len(ROOMS)}টা ঘর, {len(DOORS)}টা দরজা, {len(WINDOWS)}টা জানালা · মোট {total:,} বর্গফুট · ফাইল floorplan.svg")
