out = {}
for ill in ["D65", "A"]:
    sd_ill = colour.SDS_ILLUMINANTS[ill]
    XYZ = colour.sd_to_XYZ(leaf, cmfs, sd_ill) / 100
    wp = colour.CCS_ILLUMINANTS["CIE 1931 2 Degree Standard Observer"][ill]
    cct = colour.xy_to_CCT(wp, method="McCamy 1992")
    out[ill] = (XYZ, wp)
    print(f"{ill:4s} CCT ≈ {cct:5.0f} K | XYZ {np.round(XYZ, 4)}")

D65 = colour.CCS_ILLUMINANTS["CIE 1931 2 Degree Standard Observer"]["D65"]
def to_srgb(XYZ, wp):
    rgb = colour.XYZ_to_RGB(XYZ, "sRGB", illuminant=wp, chromatic_adaptation_transform="Bradford", apply_cctf_encoding=True)
    return "#" + "".join(f"{int(round(v * 255)):02x}" for v in np.clip(rgb, 0, 1))
print("\nD65-এ sRGB :", to_srgb(*out["D65"]))
Lab65 = colour.XYZ_to_Lab(out["D65"][0], D65)
LabA_raw = colour.XYZ_to_Lab(out["A"][0], D65)                       # চোখ মানিয়ে না নিলে (ক্যামেরার মতো)
LabA_ad = colour.XYZ_to_Lab(colour.chromatic_adaptation(out["A"][0], colour.xy_to_XYZ(out["A"][1]), colour.xy_to_XYZ(D65), method="Von Kries", transform="Bradford"), D65)
print("ΔE2000 D65↔A (adaptation ছাড়া):", round(float(colour.delta_E(Lab65, LabA_raw, method="CIE 2000")), 1))
