ILLS = {"D65": "দিনের আলো (D65)", "A": "টাংস্টেন বাল্ব (A)", "FL2": "টিউবলাইট (FL2)"}
WP = colour.CCS_ILLUMINANTS["CIE 1931 2 Degree Standard Observer"]

def srgb(name, ill):
    XYZ = colour.sd_to_XYZ(CC[name], cmfs, colour.SDS_ILLUMINANTS[ill]) / 100
