plt.style.use("default")                          # colour.plotting-এর নিজস্ব স্টাইল বাদ
plt.rcParams["font.family"] = ["Noto Sans Bengali", "DejaVu Sans"]
fig = plt.figure(figsize=(12, 8.6), facecolor="white")
gs = fig.add_gridspec(2, 2, height_ratios=[1, 1.15], width_ratios=[1.25, 1], hspace=.35)
ax = fig.add_subplot(gs[0, 0])
