import os

(path, text), = fleurs_bn(1)
x, sr = sf.read(path, dtype="float32")
x = x[: 5 * sr]
JOBS = [("wav", "PCM_16"), ("wav", "PCM_24"), ("wav", "FLOAT"), ("flac", "PCM_16"), ("flac", "PCM_24"), ("ogg", "VORBIS"), ("ogg", "OPUS")]
print(f"{'ফাইল':22s} {'আকার':>8s} {'অনুপাত':>7s}  সর্বোচ্চ ত্রুটি")
base = None
for ext, sub in JOBS:
    fn = f"clip_{sub.lower()}.{ext}"
    sr_out = 48000 if sub == "OPUS" else sr                   # OPUS ৪৮ kHz চায়
