WER_PY = r'''
def edit_rate(ref, hyp):
    """Levenshtein দূরত্ব / দৈর্ঘ্য – শব্দে (WER) বা অক্ষরে (CER)"""
    d = list(range(len(hyp) + 1))
    for i in range(1, len(ref) + 1):
        prev, d[0] = d[0], i
        for j in range(1, len(hyp) + 1):
            cur = min(d[j] + 1, d[j - 1] + 1, prev + (ref[i - 1] != hyp[j - 1]))
            prev, d[j] = d[j], cur
    return d[-1] / max(1, len(ref))

import re as _re
def norm(t):
    return _re.sub(r"[^\w\s]", " ", t).split()
'''

