WS_IMP = r'''// wavesurfer.js v7 ESM – মূল আর প্লাগইন একই সংস্করণে
const {default: WaveSurfer} = await import("https://cdn.jsdelivr.net/npm/wavesurfer.js@7.12.12/dist/wavesurfer.esm.js");
const plug = n => import(`https://cdn.jsdelivr.net/npm/wavesurfer.js@7.12.12/dist/plugins/${n}.esm.js`).then(m => m.default);
'''
PODCAST_JS = r'''// ২০ সেকেন্ডের ‘পডকাস্ট’ ব্রাউজারেই: জিঙ্গল → কথার মতো শব্দ (ফরম্যান্ট-ধাঁচ, বিরতিসহ) → জিঙ্গল
function podcast(R = 22050) {
  const N = R * 20, x = new Float32Array(N);
  for (let i = 0; i < N; i++) {
    const t = i / R;
    if (t < 3 || t > 17) {                              // ইনট্রো/আউট্রো জিঙ্গল
      const k = Math.floor(t * 4), f = [440, 554, 659, 880][k % 4];
      x[i] = Math.sin(2 * Math.PI * f * t) * Math.exp(-((t * 4) % 1) * 3) * .5;
    } else {                                            // ‘কথা’: সিলেবল ৫/সে, শব্দের মাঝে বিরতি
      const syl = (t * 5) % 1, word = Math.floor(t * 1.3) % 4 !== 3;
      const env = word ? Math.sin(Math.PI * syl) ** 2 : 0;
      const f0 = 140 + 25 * Math.sin(2 * Math.PI * .7 * t);
      x[i] = env * (Math.sin(2 * Math.PI * f0 * t) * .4 + Math.sin(2 * Math.PI * 700 * t) * .15 + (Math.random() - .5) * .08);
    }
  }
  return x;
}
'''

