import numpy as np
import matplotlib.pyplot as plt
from rdkit import Chem, DataStructs
from rdkit.Chem import rdFingerprintGenerator, Draw
plt.rcParams["font.family"] = ["Noto Sans Bengali", "DejaVu Sans"]

DRUGS = {"paracetamol (ওষুধ)": "CC(=O)NC1=CC=C(C=C1)O", "aspirin (ওষুধ)": "CC(=O)OC1=CC=CC=C1C(=O)O",
         "ibuprofen (ওষুধ)": "CC(C)CC1=CC=C(C=C1)C(C)C(=O)O", "metformin (ওষুধ)": "CN(C)C(=N)N=C(N)N"}
ALL = {**SPICES, **DRUGS}
names = list(ALL)
mols = [Chem.MolFromSmiles(s) for s in ALL.values()]
gen = rdFingerprintGenerator.GetMorganGenerator(radius=2, fpSize=2048)
fps = [gen.GetFingerprint(m) for m in mols]
S = np.array([DataStructs.BulkTanimotoSimilarity(f, fps) for f in fps])
pairs = sorted(((S[i, j], names[i], names[j]) for i in range(len(names)) for j in range(i)), reverse=True)
print("সবচেয়ে কাছের ৫ জোড়া (Tanimoto):")
