v.addLabel(f"H–O–H = {math.degrees(ang):.1f}°   O–H = {r} Å", {"position": {"x": 0, "y": .35, "z": 0}, "backgroundColor": "white", "fontColor": "#1e1b4b", "fontSize": 13, "inFront": True})
