NGL_JS = r'''
import os, sys, shutil
def save_html(fn, views, **kw):
    """nglview.write_html + প্যাকেজের সাথে আসা JS পাশে কপি (nglview-js-widgets 4.0 এখনো npm-এ নেই, তাই CDN থেকে আসে না)।"""
    nv.write_html(fn, views, **kw)
    js = os.path.join(sys.prefix, "share", "jupyter", "nbextensions", "nglview-js-widgets", "index.js")
    if os.path.exists(js):
        shutil.copy(js, os.path.join(os.path.dirname(os.path.abspath(fn)), "nglview-js-widgets.js"))   # requirejs পাতার পাশেই খোঁজে
'''

