u = mda.Universe(PSF, DCD)
print(f"AdK: {u.atoms.n_atoms:,}টা পরমাণু, {len(u.trajectory)}টা ফ্রেম")
core = u.select_atoms("name CA and (resid 1-29 or resid 60-121 or resid 160-214)")
lid = u.select_atoms("name CA and resid 122-159")
nmp = u.select_atoms("name CA and resid 30-59")
d_lid, d_nmp = [], []
for ts in u.trajectory:
    d_lid.append(np.linalg.norm(lid.center_of_mass() - core.center_of_mass()))
    d_nmp.append(np.linalg.norm(nmp.center_of_mass() - core.center_of_mass()))
for f in range(0, len(u.trajectory), 16):
    print(f"ফ্রেম {f:2d}: LID–CORE {d_lid[f]:5.1f} Å | NMP–CORE {d_nmp[f]:5.1f} Å")
print(f"LID {d_lid[-1] - d_lid[0]:+.1f} Å, NMP {d_nmp[-1] - d_nmp[0]:+.1f} Å সরে গেল – ঢাকনা খুলল")

view = nv.show_mdanalysis(u, default=False)
