for k, (name, f) in enumerate(tiles):
    im = Image.open(f).convert("RGB"); sheet.paste(im, ((k % 2) * W, 50 + (k // 2) * H))
    d.text(((k % 2) * W + 16, 60 + (k // 2) * H), name, fill="#7c3aed", font=font)
    os.remove(f)
sheet.save("hemoglobin_four_views.png")
print("ছবি: hemoglobin_four_views.png")
