AW_HTML = r'''
import json
def save_html(widget, fn, height="420px"):
    """anywidget-এর নিজের ESM চালানো স্বয়ংসম্পূর্ণ HTML – নোটবুক ছাড়াই ব্রাউজারে খোলে।"""
    state = {k: v for k, v in widget.get_state().items() if not k.startswith("_")}
    page = """<!doctype html><meta charset="utf-8"><style>body{margin:0} @@CSS@@</style><div id="w" style="position:relative;height:@@HEIGHT@@"></div>
<script type="module">
const state = @@STATE@@, on = {};
const model = {get: k => state[k], set: (k, v) => { state[k] = v; (on["change:" + k] || []).forEach(f => f()); }, save_changes() {}, send() {},
  on: (e, f) => (on[e] = on[e] || []).push(f), off() {}};
const mod = await import(URL.createObjectURL(new Blob([@@ESM@@], {type: "text/javascript"})));
const w = mod.default ?? mod;
if (w.initialize) await w.initialize({model});
await w.render({model, el: document.getElementById("w")});
</script>"""
    page = page.replace("@@CSS@@", str(widget._css)).replace("@@HEIGHT@@", height).replace("@@ESM@@", json.dumps(str(widget._esm))).replace("@@STATE@@", json.dumps(state))
    open(fn, "w", encoding="utf-8").write(page)
'''

