plt.rcParams["font.family"] = ["Noto Sans Bengali", "DejaVu Sans"]

EXP = {"Al": (4.05, 76), "Cu": (3.61, 140), "Ni": (3.52, 180), "Ag": (4.09, 100), "Au": (4.08, 180), "Pt": (3.92, 230)}   # a₀ (Å), B (GPa) – CRC
rows, curves = [], {}
