    eos = EquationOfState(vols, ens, eos="birchmurnaghan")
    v0, e0, B = eos.fit()
    a0 = (4 * v0) ** (1 / 3)
    rows.append((el, a0, a_exp, B / kJ * 1e24, B_exp))
    curves[el] = (np.array(vols) / v0, np.array(ens) - e0)
