cnn = CrystalNN()
print(f"{'খনিজ':30s} {'সূত্র':6s} {'Z':>3s} {'ঘনত্ব':>6s} {'(বই)':>5s} {'space group':12s} {'পদ্ধতি':12s} CN  বন্ধনী")
for name, s in MINERALS.items():
    sga = SpacegroupAnalyzer(s, symprec=.01)
    f = s.composition.reduced_formula
    cat = next(i for i, site in enumerate(s) if site.specie.X < 2.5)            # কম তড়িৎ-ঋণাত্মক = ক্যাটায়ন
    nn = cnn.get_nn_info(s, cat)
    bl = np.mean([s[cat].distance(n["site"]) for n in nn])
    print(f"{name:30s} {f:6s} {len(s):3d} {s.density:6.2f} {EXP_RHO[f]:5.2f} {sga.get_space_group_symbol():12s} {sga.get_crystal_system():12s} {len(nn):2d}  {bl:.2f} Å")
