t = scores["test"]
q = t['pearson_r2_score']
ax.set_title(f"নতুন কাঠামোর অণুতে R² {q:.2f} – " + ("ভালো, তবে নিখুঁত নয়" if q > .7 else "মাঝারি: অচেনা কাঠামোয় কঠিন" if q > .4 else "দুর্বল"), loc="left", fontsize=12.5, weight="bold", pad=26)
ax.text(0, 1.02, f"DeepChem ESOL · ECFP4 + RandomForest · scaffold-split test ({len(test)}টা অণু) · RMSE {t['rms_score']:.2f}", transform=ax.transAxes, fontsize=8.5, color="#64748b")
