lib = np.asarray(adata.X.sum(1)).ravel()
adata.layers["lognorm"] = sparse.csr_matrix(np.log1p(counts / lib[:, None] * 1e3))
adata.obsm["X_2d"] = rng.normal(size=(n_cells, 2)) + np.where(ctype[:, None] == "মেসোফিল", 3, 0)
adata.uns["experiment"] = {"crop": "ধান (BRRI dhan28)", "simulated": True}
