# ------------------------------------------------------------------ pydeseq2
RICE_RNASEQ = r'''
import numpy as np
import pandas as pd
# কৃত্রিম RNA-seq গণনা: ধানের চারা, আলো বনাম অন্ধকার (৬ + ৬ নমুনা, দুই ব্যাচ), ২০০০ জিন – কোন ২০০টা সত্যিই বদলায় তা আমরা জানি
rng = np.random.default_rng(42)
G, n = 2000, 12
genes = ["RBCS1", "LHCB1", "CAB2", "PSBA", "PORA", "ELIP1", "PIF3", "HY5", "CHS1", "PHYA"] + [f"Os{i % 12 + 1:02d}g{10100 + 37 * i:05d}" for i in range(G - 10)]   # অনন্য নাম
meta = pd.DataFrame({"condition": ["light"] * 6 + ["dark"] * 6, "batch": ["b1", "b2"] * 6}, index=[f"S{i + 1:02d}" for i in range(n)])
base = rng.lognormal(4.5, 1.4, G)                         # জিনের স্বাভাবিক প্রকাশ
lfc = np.zeros(G)
true_de = rng.choice(np.arange(10, G), 190, replace=False)
lfc[true_de] = rng.choice([-1, 1], 190) * rng.uniform(.8, 3, 190)
lfc[:7] = [4.5, 4, 3.6, 2.5, -3.5, 3, -2.2]               # চেনা জিন: আলোয় RBCS/LHCB বাড়ে, অন্ধকারে PORA (প্রোটোক্লোরোফিলাইড) বাড়ে
lfc[7], lfc[8], lfc[9] = 2.8, 2.0, -1.6
is_de = lfc != 0
size = rng.uniform(.7, 1.4, n)
batch_eff = np.where(meta.batch.values == "b2", 1.0, 0.0)[None, :] * rng.normal(0, .6, G)[:, None]
mu = base[:, None] * size[None, :] * np.exp2(np.where(meta.condition.values == "light", 1, 0)[None, :] * lfc[:, None]) * np.exp(batch_eff)
disp = .08 + 2 / base
counts = rng.negative_binomial(1 / disp[:, None], 1 / (1 + mu * disp[:, None]))
counts = pd.DataFrame(counts.T, index=meta.index, columns=genes)       # pydeseq2: সারি = নমুনা
'''
pylib("pydeseq2",
    about=("PyDESeq2 হলো বিখ্যাত R-প্যাকেজ DESeq2-এর পাইথন-রূপ: bulk RNA-seq-এর কাঁচা গণনা থেকে ‘কোন জিন দুই অবস্থায় আলাদা প্রকাশ পায়’ (differential expression) – "
           "size-factor দিয়ে নমুনা-গভীরতা সমান করা, negative-binomial মডেলে জিনপ্রতি dispersion (ছোট নমুনায় তথ্য ধার করে), Wald-পরীক্ষা, Benjamini-Hochberg-এ সংশোধিত p, "
           "Cook's distance দিয়ে বেয়াড়া নমুনা, design-ফর্মুলায় ব্যাচ-প্রভাব, আর apeGLM-ধাঁচের LFC shrinkage।"),
    install="pip install pydeseq2",
    examples=[
        ex("প্রজেক্ট: আলো বনাম অন্ধকারে ধানের চারা – DESeq2 চালিয়ে volcano plot, আর ‘সত্যিকারের’ উত্তরের সাথে মিলিয়ে নির্ভুলতা",
           "কৃত্রিম কিন্তু বাস্তবধর্মী গণনা (negative-binomial, ১২ নমুনা × ২০০০ জিন; ১৯০টা এলোমেলো জিন + ১০টা চেনা আলো-নির্ভর জিন সত্যিই বদলায় – যেমন RBCS, LHCB আলোয় বাড়ে, PORA অন্ধকারে)। "
           "DeseqDataSet(design='~condition') → deseq2() → DeseqStats(contrast light vs dark) → results_df; padj < ০.০৫ আর |log2FC| > ১-এ কয়টা পেল, কয়টা সঠিক (precision/recall) – "
           "তারপর লেবেলসহ volcano plot।",
           RICE_RNASEQ + r'''
import matplotlib.pyplot as plt
from pydeseq2.dds import DeseqDataSet
from pydeseq2.ds import DeseqStats
plt.rcParams["font.family"] = ["Noto Sans Bengali", "DejaVu Sans"]

print(f"গণনা-ম্যাট্রিক্স: {counts.shape[0]} নমুনা × {counts.shape[1]} জিন | লাইব্রেরি-আকার {counts.sum(1).min():,}–{counts.sum(1).max():,}")
dds = DeseqDataSet(counts=counts, metadata=meta, design="~condition", quiet=True)
dds.deseq2()
print("size factor:", dds.obs["size_factors"].round(2).tolist())
st = DeseqStats(dds, contrast=["condition", "light", "dark"], quiet=True)
st.summary()
res = st.results_df.dropna(subset=["padj"])
hit = (res.padj < .05) & (res.log2FoldChange.abs() > 1)
truth = pd.Series(is_de, index=genes).loc[res.index]
tp = (hit & truth).sum()
print(f"\nপাওয়া গেল {hit.sum()}টা জিন (padj<০.০৫, |log2FC|>১) | সত্যিকারের পরিবর্তিত {truth.sum()}টা")
print(f"precision {tp / hit.sum() * 100:.1f}% | recall {tp / truth.sum() * 100:.1f}% (ছোট পরিবর্তন ধরা কঠিন)")
print(res.loc[genes[:8], ["baseMean", "log2FoldChange", "padj"]].round(3).to_string())

fig, ax = plt.subplots(figsize=(9.5, 6.4))
y = -np.log10(res.padj.clip(lower=1e-300))
ax.scatter(res.log2FoldChange[~hit], y[~hit], s=7, color="#cbd5e1", edgecolor="none")
up, dn = hit & (res.log2FoldChange > 0), hit & (res.log2FoldChange < 0)
ax.scatter(res.log2FoldChange[up], y[up], s=12, color="#f59e0b", edgecolor="none")
ax.scatter(res.log2FoldChange[dn], y[dn], s=12, color="#7c3aed", edgecolor="none")
for g in genes[:8]:
    if g in res.index:
        ax.annotate(g, (res.log2FoldChange[g], y[g]), xytext=(6, 4), textcoords="offset points", fontsize=9, weight="bold", color="#1e1b4b")
ax.axhline(-np.log10(.05), ls="--", lw=.8, color="#94a3b8"); ax.axvline(1, ls=":", lw=.8, color="#94a3b8"); ax.axvline(-1, ls=":", lw=.8, color="#94a3b8")
ax.text(.99, .97, f"আলোয় বাড়ে: {up.sum()}", transform=ax.transAxes, ha="right", color="#b45309", fontsize=11, weight="bold")
ax.text(.01, .97, f"অন্ধকারে বাড়ে: {dn.sum()}", transform=ax.transAxes, color="#6d28d9", fontsize=11, weight="bold")
ax.set_xlabel("log2 fold-change (আলো / অন্ধকার)"); ax.set_ylabel("−log10(adjusted p)")
for s in ("top", "right"):
    ax.spines[s].set_visible(False)
ax.set_title(f"আলোয় RuBisCO আর আলো-ধরার জিন সবচেয়ে বেশি জ্বলে – {hit.sum()}টা জিন বদলেছে, {tp / hit.sum() * 100:.0f}% সঠিক", loc="left", fontsize=12.5, weight="bold", pad=26)
ax.text(0, 1.03, "PyDESeq2 · কৃত্রিম RNA-seq (ধানের চারা, ৬+৬ নমুনা, ২০০০ জিন, ২০০টা সত্যিকারের পরিবর্তন জানা) · Wald-পরীক্ষা, BH-সংশোধন", transform=ax.transAxes, fontsize=9, color="#64748b")
plt.tight_layout(); plt.savefig("rice_volcano.png", dpi=150); plt.close()
''', hint=SHOW),
        ex("ব্যাচ-প্রভাব আর LFC shrinkage: ‘~batch + condition’ ডিজাইন কতটা বাড়তি জিন ধরে, আর MA-প্লটে shrink করা fold-change",
           "একই ডেটায় দুই ব্যাচের (b1/b2 – আলাদা দিনে সিকোয়েন্সিং) প্রভাব ইচ্ছে করে রাখা। design '~condition' বনাম '~batch + condition' – দ্বিতীয়টায় ব্যাচের ভ্যারিয়েন্স আলাদা হয়, "
           "তাই বেশি সত্যিকারের জিন ধরা পড়ে (recall বাড়ে)। তারপর lfc_shrink – কম গণনার জিনের ফোলানো fold-change ছোট হয়ে আসে; MA-প্লটে আগে-পরে।",
           RICE_RNASEQ + r'''
import matplotlib.pyplot as plt
from pydeseq2.dds import DeseqDataSet
from pydeseq2.ds import DeseqStats
plt.rcParams["font.family"] = ["Noto Sans Bengali", "DejaVu Sans"]

def run(design):
    dds = DeseqDataSet(counts=counts, metadata=meta, design=design, quiet=True); dds.deseq2()
    st = DeseqStats(dds, contrast=["condition", "light", "dark"], quiet=True); st.summary()
    return dds, st
truth = pd.Series(is_de, index=genes)
out = {}
for design in ("~condition", "~batch + condition"):
    dds, st = run(design)
    r = st.results_df.dropna(subset=["padj"])
    hit = (r.padj < .05)
    tp = (hit & truth.loc[r.index]).sum()
    out[design] = (dds, st)
    print(f"{design:20s}: {hit.sum():4d}টা জিন (padj<০.০৫) | সঠিক {tp} | precision {tp / hit.sum() * 100:5.1f}% | recall {tp / truth.sum() * 100:5.1f}%")

dds, st = out["~batch + condition"]
raw = st.results_df.copy()
coeff = [c for c in dds.varm["LFC"].columns if "condition" in c][0]
st.lfc_shrink(coeff=coeff)
shr = st.results_df
low = raw.baseMean < 20
print(f"\nshrink-এর আগে কম গণনার (<২০) জিনে |LFC|-এর গড় {raw.log2FoldChange[low].abs().mean():.2f}, পরে {shr.log2FoldChange[low].abs().mean():.2f}")

fig, axs = plt.subplots(1, 2, figsize=(12, 4.6), sharey=True)
for ax, (lab, r) in zip(axs, (("shrink-এর আগে", raw), ("shrink-এর পরে (apeGLM-ধাঁচ)", shr))):
    sig = r.padj < .05
    ax.scatter(np.log10(r.baseMean + 1)[~sig], r.log2FoldChange[~sig], s=5, color="#cbd5e1", edgecolor="none")
    ax.scatter(np.log10(r.baseMean + 1)[sig], r.log2FoldChange[sig], s=8, color="#7c3aed", edgecolor="none")
    ax.axhline(0, color="#64748b", lw=.8); ax.set_title(lab, loc="left", fontsize=11)
    ax.set_xlabel("log10(গড় গণনা + ১)")
    for s in ("top", "right"):
        ax.spines[s].set_visible(False)
axs[0].set_ylabel("log2 fold-change")
fig.suptitle("shrink করলে কম-গণনার জিনের ফোলানো fold-change শূন্যের দিকে নামে", x=.02, ha="left", fontsize=13.5, weight="bold")
plt.tight_layout(); plt.savefig("rice_ma_shrink.png", dpi=150); plt.close()
'''),
    ],
    level="উন্নত", tag="bulk RNA-seq-এ differential expression – DESeq2 পাইথনে।",
    tasks=["দুই অবস্থায় জিন-প্রকাশের তুলনা", "volcano/MA প্লট", "ব্যাচ-প্রভাব নিয়ন্ত্রণ", "পরবর্তী pathway-বিশ্লেষণের জিন-তালিকা"],
    caps=["DeseqDataSet(counts, metadata, design formula)", "size factor, dispersion trend, Wald test, BH padj, Cook's outlier refit", "DeseqStats(contrast), summary, results_df, lfc_shrink", "AnnData-ভিত্তিক, n_cpus দিয়ে সমান্তরাল"],
    limits=["কাঁচা গণনা লাগে (TPM/FPKM নয়)", "LRT/জটিল contrast R-এর DESeq2-এর চেয়ে কম", "প্রতি অবস্থায় কম নমুনায় ক্ষমতা কম"],
    alt="DESeq2/edgeR/limma (R), scanpy.tl.rank_genes_groups (single-cell), pertpy",
)

