import matplotlib.pyplot as plt
from skbio.diversity import alpha_diversity
from skbio.diversity.alpha import observed_features
from skbio.stats import subsample_counts
plt.rcParams["font.family"] = ["Noto Sans Bengali", "DejaVu Sans"]

ad = pd.DataFrame({m: alpha_diversity(m, counts.values, ids=counts.index) for m in ("observed_features", "shannon", "simpson", "chao1")})
ad["habitat"] = meta.habitat
summ = ad.groupby("habitat")[["observed_features", "shannon", "simpson", "chao1"]].mean().sort_values("shannon", ascending=False)
print("জলাশয়ের ধরন অনুযায়ী গড় alpha-বৈচিত্র্য:"); print(summ.round(2).to_string())
best = summ.index[0]; worst = summ.index[-1]
dom = counts[meta.habitat == "খামার"].sum().sort_values(ascending=False)
print(f"\nখামারে সবচেয়ে বেশি: {', '.join(dom.index[:3])} – মোটের {dom.iloc[:3].sum() / dom.sum() * 100:.0f}%")

fig, (a1, a2) = plt.subplots(1, 2, figsize=(12.5, 4.8), gridspec_kw={"width_ratios": [1, 1.25]})
COL = {"হাওর": "#0d9488", "পুকুর": "#7c3aed", "খামার": "#f59e0b", "শহুরে লেক": "#e11d48"}
order = list(summ.index)
for k, h in enumerate(order):
    v = ad.shannon[ad.habitat == h]
    a1.scatter(np.full(len(v), k) + rng.uniform(-.12, .12, len(v)), v, color=COL[h], s=40, zorder=3)
    a1.hlines(v.mean(), k - .3, k + .3, color=COL[h], lw=3)
a1.set_xticks(range(len(order)), order); a1.set_ylabel("Shannon সূচক (H′)")
a1.set_title("প্রতিটা নমুনা (বিন্দু) আর গড় (দাগ)", loc="left", fontsize=11)
depths = np.arange(10, 401, 15)
for pond in PONDS:
    c = counts.loc[f"{pond} #1"].values
    curve = [np.mean([observed_features(subsample_counts(c, d, seed=s)) for s in range(5)]) for d in depths]
    h = PONDS[pond][0]
    a2.plot(depths, curve, color=COL[h], lw=1.8, alpha=.9)
    a2.text(depths[-1] + 5, curve[-1], pond.split(" (")[1].rstrip(")"), color=COL[h], fontsize=8.5, va="center")
a2.set_xlabel("গোনা জীবের সংখ্যা (subsample)"); a2.set_ylabel("পাওয়া প্রজাতির সংখ্যা")
a2.set_title("rarefaction: আরও খুঁজলে আর কত নতুন প্রজাতি?", loc="left", fontsize=11); a2.set_xlim(0, 470)
for a in (a1, a2):
    for s in ("top", "right"):
        a.spines[s].set_visible(False)
fig.suptitle(f"{best}-এ জীববৈচিত্র্য সবচেয়ে বেশি, {worst}-এ সবচেয়ে কম", x=.02, ha="left", fontsize=14, weight="bold")
fig.text(.02, .905, "কৃত্রিম জরিপ-ডেটা (৮ জলাশয় × ৩ নমুনা, ৩০ ধরনের জীব, নমুনাপ্রতি ৪০০টা গোনা) · scikit-bio alpha_diversity, subsample_counts", fontsize=9, color="#64748b")
