import nbformat
from nbclient import NotebookClient
from nbconvert import HTMLExporter
def run_notebook(cells, html):
    nb = nbformat.v4.new_notebook(cells=[nbformat.v4.new_code_cell(c) for c in cells])
    NotebookClient(nb, timeout=300, kernel_name="python3").execute()
    for c in nb.cells:
        for o in c.get("outputs", []):
            if o.get("output_type") == "stream":
                print(o["text"], end="")
    body, _ = HTMLExporter(template_name="classic").from_notebook_node(nb)
    open(html, "w", encoding="utf-8").write(body)
    print("→", html)
