import numpy as np
import matplotlib.pyplot as plt
import mdtraj as md
from MDAnalysisTests.datafiles import PSF, DCD
plt.rcParams["font.family"] = ["Noto Sans Bengali", "DejaVu Sans"]

top = md.load_psf(PSF)
t = md.load_dcd(DCD, top=top)
print(t, "|", t.topology.n_residues, "অবশিষ্টাংশ")
_, phi = md.compute_phi(t); _, psi = md.compute_psi(t)
phi, psi = np.degrees(phi).ravel(), np.degrees(psi).ravel()
alpha = ((phi > -100) & (phi < -30) & (psi > -80) & (psi < -10)).mean()
beta = ((phi > -170) & (phi < -60) & (psi > 90) & (psi < 180)).mean()
print(f"{len(phi):,}টা (phi, psi) জোড়া | α-অঞ্চলে {alpha * 100:.0f}%, β-অঞ্চলে {beta * 100:.0f}%")
ss = md.compute_dssp(t, simplified=True)
H, E = (ss == "H").mean(axis=1), (ss == "E").mean(axis=1)
print(f"DSSP: হেলিক্স {H[0] * 100:.0f}% → {H[-1] * 100:.0f}%, শিট {E[0] * 100:.0f}% → {E[-1] * 100:.0f}% (প্রথম → শেষ ফ্রেম)")
flip = np.mean(ss[0] != ss[-1])
print(f"প্রথম আর শেষ ফ্রেমে secondary structure বদলেছে {flip * 100:.1f}% অবশিষ্টাংশে")

fig, (a1, a2) = plt.subplots(1, 2, figsize=(12.5, 5), gridspec_kw={"width_ratios": [1, 1.2]})
h = a1.hist2d(phi, psi, bins=90, range=[[-180, 180], [-180, 180]], cmap="Purples", cmin=1)
