a1.text(-63, -42, "α", fontsize=18, color="#e11d48", weight="bold", ha="center", va="center")
a1.text(-120, 135, "β", fontsize=18, color="#e11d48", weight="bold", ha="center", va="center")
a1.text(60, 45, "বাঁ-হাতি α", fontsize=9, color="#475569", ha="center")
a1.set_title("Ramachandran (সব ফ্রেম)", loc="left", fontsize=11); a1.set_aspect("equal")
f = np.arange(t.n_frames)
a2.plot(f, H * 100, color="#7c3aed", lw=2.4); a2.plot(f, E * 100, color="#f59e0b", lw=2.4)
a2.text(f[-1], H[-1] * 100, " হেলিক্স", color="#7c3aed", va="center"); a2.text(f[-1], E[-1] * 100, " শিট", color="#b45309", va="center")
a2.set_ylim(0, 70); a2.set_xlim(0, f[-1] + 14); a2.set_xlabel("ফ্রেম (বন্ধ → খোলা)"); a2.set_ylabel("অবশিষ্টাংশের %")
a2.set_title("DSSP: প্রতি ফ্রেমে secondary structure", loc="left", fontsize=11)
for s in ("top", "right"):
    a2.spines[s].set_visible(False)
fig.suptitle(f"ঢাকনা খুললেও AdK-এর ভাঁজ অটুট – মাত্র {flip * 100:.0f}% অবশিষ্টাংশের গঠন বদলায়", x=.01, ha="left", fontsize=14, weight="bold")
