# ------------------------------------------------------------------ NGL Viewer
jslib("NGL Viewer",
    about=("NGL Viewer হলো WebGL-এ আণবিক গঠন আর MD-trajectory দেখার লাইব্রেরি (nglview-এর ইঞ্জিন): Stage → loadFile (rcsb://, URL, ফাইল, Blob), বহু রকম representation "
           "(cartoon, ribbon, ball+stick, licorice, surface, spacefill, hyperball, label, distance), শক্তিশালী selection-ভাষা, trajectory-প্লেয়ার, ছায়া/আলো, ছবি-রপ্তানি।"),
    install="npm install ngl      // অথবা <script src=\"https://cdn.jsdelivr.net/npm/ngl@2.5.0/dist/ngl.js\">",
    examples=[
        jlive("ngl", "প্রোটিন আর লিগ্যান্ড: 4HHB – cartoon, surface, hyperball হিম; representation বদলের বোতাম",
              "NGL.Stage-এ rcsb://4HHB লোড, autoView; বোতামে representation-সেট: ‘cartoon + হিম’, ‘surface (হাইড্রোফোবিসিটি রং)’, ‘ব্যাকবোন ট্রেস + হিম hyperball’, ‘spacefill’। "
              "selection-ভাষা – 'HEM', ':A', 'protein and hydrophobic' ইত্যাদি; ‘ঘোরাও’ setSpin। হোভার করলে নিচে অবশিষ্টাংশের নাম।",
              r"""const app = document.getElementById("app");
app.innerHTML = `<div class="row" id="btns"></div><div id="v" style="position:relative;height:320px;border-radius:14px;overflow:hidden"></div><div id="info" class="mono muted">লোড হচ্ছে…</div>`;
const stage = new NGL.Stage("v", {backgroundColor: "#140e29"});
const comp = await stage.loadFile("rcsb://4HHB", {defaultRepresentation: false});
const SETS = {
  "cartoon + হিম": () => { comp.addRepresentation("cartoon", {colorScheme: "chainname"}); comp.addRepresentation("ball+stick", {sele: "HEM", colorScheme: "element"}); },
  "surface": () => { comp.addRepresentation("surface", {sele: "protein", colorScheme: "hydrophobicity", opacity: .9}); comp.addRepresentation("ball+stick", {sele: "HEM"}); },
  "trace + hyperball": () => { comp.addRepresentation("backbone", {colorScheme: "residueindex"}); comp.addRepresentation("hyperball", {sele: "HEM", colorValue: "#f59e0b"}); },
  "spacefill": () => comp.addRepresentation("spacefill", {colorScheme: "chainname"}),
};
function use(k) { comp.removeAllRepresentations(); SETS[k](); document.querySelectorAll("#btns button").forEach(b => b.classList.toggle("pri", b.textContent === k)); }
Object.keys(SETS).forEach(k => { const b = document.createElement("button"); b.textContent = k; b.onclick = () => use(k); document.getElementById("btns").append(b); });
const sp = document.createElement("button"); sp.textContent = "ঘোরাও"; sp.onclick = () => { stage.toggleSpin(); sp.classList.toggle("pri"); }; document.getElementById("btns").append(sp);
use("cartoon + হিম"); comp.autoView();
const s = comp.structure, chains = new Set();
let nres = 0;
s.eachResidue(r => { nres++; chains.add(r.chainname); }, new NGL.Selection("protein"));
document.getElementById("info").textContent = `4HHB: ${s.atomCount.toLocaleString()} পরমাণু · প্রোটিনে ${nres} অবশিষ্টাংশ, ${chains.size}টা চেইন (${[...chains].join(", ")}) — হোভার করো`;
stage.signals.hovered.add(p => { if (p && p.atom) document.getElementById("info").textContent = `হোভার: ${p.atom.resname} ${p.atom.resno} · চেইন ${p.atom.chainname} · ${p.atom.atomname}`; });
new ResizeObserver(() => requestAnimationFrame(() => stage.handleResize())).observe(document.getElementById("v"));
"""),
        jlive("ngl", "পানির অণুর অ্যানিমেশন: ২৭টা পানি – বাঁকা-টানা কম্পন আর এলোমেলো চলা, trajectory-প্লেয়ারে",
              "JS-এ নিজে বানানো ৬০ ফ্রেমের বহু-মডেল PDB (৩×৩×৩ জালে ২৭টা পানির অণু; প্রতিটার O–H বন্ধনী টানা-কম্পন আর H–O–H কোণের বাঁক-কম্পন, সাথে ধীর এলোমেলো সরণ ও ঘূর্ণন) – "
              "NGL-এ asTrajectory দিয়ে লোড, TrajectoryPlayer-এ লুপ। দুটো পাশের অণুর O–O দূরত্ব distance-representation-এ লাইভ। চিত্রটা শেখানোর জন্য – আসল MD নয়।",
              r"""const app = document.getElementById("app");
app.innerHTML = `<div class="row"><button id="pp" class="pri">❚❚ থামাও</button><span id="info" class="mono"></span></div><div id="v" style="position:relative;height:340px;border-radius:14px;overflow:hidden"></div>`;
const N = 3, F = 60, sp = 3.1, rOH = .9572, ang = 104.52 * Math.PI / 180;
let pdb = "", rnd = (s => () => (s = (s * 16807) % 2147483647) / 2147483647)(7);
const mols = [];
for (let i = 0; i < N; i++) for (let j = 0; j < N; j++) for (let k = 0; k < N; k++)
  mols.push({c: [i * sp, j * sp, k * sp], ph: rnd() * 6.28, rot: [rnd() * 6.28, rnd() * 6.28], v: [rnd() - .5, rnd() - .5, rnd() - .5]});
const f3 = x => x.toFixed(3).padStart(8);
for (let f = 0; f < F; f++) {
  pdb += `MODEL     ${String(f + 1).padStart(4)}\n`;
  let n = 1;
  mols.forEach((m, r) => {
    const t = f / F * 2 * Math.PI, str = rOH * (1 + .04 * Math.sin(3 * t + m.ph)), bend = ang * (1 + .06 * Math.sin(2 * t + m.ph));
    const a = m.rot[0] + .3 * Math.sin(t + m.ph), b = m.rot[1] + .2 * t;
    const O = m.c.map((c, d) => c + .35 * Math.sin(t + m.ph + d) * m.v[d] * 2);
    const H = s => { const x = str * Math.sin(s * bend / 2), y = str * Math.cos(bend / 2);
      return [O[0] + x * Math.cos(b), O[1] + y * Math.cos(a) - x * Math.sin(b) * Math.sin(a), O[2] + y * Math.sin(a) + x * Math.sin(b) * Math.cos(a)]; };
    [["OW", O, "O"], ["HW1", H(1), "H"], ["HW2", H(-1), "H"]].forEach(([nm, p, el]) => {
      pdb += `HETATM${String(n++).padStart(5)} ${nm.padEnd(4)} HOH A${String(r + 1).padStart(4)}    ${f3(p[0])}${f3(p[1])}${f3(p[2])}  1.00  0.00          ${el.padStart(2)}\n`; });
  });
  pdb += "ENDMDL\n";
}
const stage = new NGL.Stage("v", {backgroundColor: "#faf7ff"});
const comp = await stage.loadFile(new Blob([pdb], {type: "text/plain"}), {ext: "pdb", asTrajectory: true});
comp.addRepresentation("ball+stick", {aspectRatio: 2.2, radiusScale: 1.1});
comp.addRepresentation("distance", {atomPair: [["1:A.OW", "2:A.OW"], ["1:A.OW", "4:A.OW"]], labelColor: "#4c1d95", color: "#e11d48", labelSize: 2.2});
comp.autoView(); stage.setRock(true, [0, 1, 0], .006);         // সামান্য দোলা – গভীরতা বোঝা যায়
const traj = comp.addTrajectory();
const player = new NGL.TrajectoryPlayer(traj.trajectory, {step: 1, timeout: 60, mode: "loop", interpolateType: "linear"});
player.play();
document.getElementById("info").textContent = `${mols.length}টা পানির অণু · ${F} ফ্রেম · লাল রেখা = O–O দূরত্ব (Å)`;
document.getElementById("pp").onclick = e => { if (player.isRunning) { player.pause(); e.target.textContent = "▶ চালাও"; } else { player.play(); e.target.textContent = "❚❚ থামাও"; } };
new ResizeObserver(() => requestAnimationFrame(() => stage.handleResize())).observe(document.getElementById("v"));
"""),
    ],
    level="শুরু", tag="WebGL-এ গঠন আর trajectory – nglview-এর ইঞ্জিন।",
    tasks=["প্রোটিন-লিগ্যান্ড ইন্টারঅ্যাকটিভ চিত্র", "MD-trajectory প্লেব্যাক", "শিক্ষামূলক অণুর অ্যানিমেশন", "ছবি-রপ্তানি (makeImage)"],
    caps=["Stage.loadFile (rcsb://, URL, File, Blob; pdb, cif, mmtf, sdf, gro, dcd, xtc…)", "representation: cartoon, ball+stick, licorice, surface, hyperball, distance, label…", "selection-ভাষা, colorScheme (chainname, residueindex, hydrophobicity, bfactor)", "TrajectoryPlayer, signals (hovered/clicked), makeImage"],
    limits=["রক্ষণাবেক্ষণ ধীর", "খুব বড় গঠনে Mol* দ্রুত", "ডকুমেন্টেশন পুরোনো"],
    alt="Mol*, 3Dmol.js, nglview (পাইথন), JSmol",
)

