# ------------------------------------------------------------------ IGV.js
TOYJS = r"""// ব্রাউজারেই খেলনা-জিনোম: ৫ kb রেফারেন্স, জিন (BED), coverage (bedGraph), ভ্যারিয়েন্ট (VCF) – সব data-URI
const rnd = (s => () => (s = (s * 16807) % 2147483647) / 2147483647)(42);
const L = 5000, ref = Array.from({length: L}, () => "ACGT"[Math.floor(rnd() * 4)]).join("");
const uri = (txt, mime = "text/plain") => `data:${mime};base64,` + btoa(unescape(encodeURIComponent(txt)));
const fasta = ">toyChr\n" + ref.match(/.{1,60}/g).join("\n") + "\n";
const bed = ["toyChr\t200\t1500\tgeneA\t0\t+", "toyChr\t1700\t2600\tgeneB\t0\t-", "toyChr\t3000\t4600\tgeneC\t0\t+"].join("\n");
let bg = "";
for (let i = 0; i < L; i += 50) { const dip = i >= 3800 && i < 4100; bg += `toyChr\t${i}\t${i + 50}\t${Math.round((dip ? 2 : 30) + 6 * Math.sin(i / 300) + rnd() * 4)}\n`; }
const VAR = [[1200, "het"], [2049, "hom"], [3333, "het"], [4400, "het"]];
const vcf = "##fileformat=VCFv4.2\n##contig=<ID=toyChr,length=5000>\n##FORMAT=<ID=GT,Number=1,Type=String,Description=\"Genotype\">\n#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\tFORMAT\tনমুনা১\n" +
  VAR.map(([p, z], k) => { const r = ref[p - 1], a = "ACGT".replace(r, "")[k % 3]; return `toyChr\t${p}\tsnp${k + 1}\t${r}\t${a}\t60\tPASS\t.\tGT\t${z === "hom" ? "1/1" : "0/1"}`; }).join("\n") + "\n";
"""
