a2.set_xticks(cs); a2.set_ylim(0, 105); a2.set_xlabel("কর্মী (c)"); a2.set_ylabel("৫ মিনিটের কম অপেক্ষা (%)")
a2.set_title("বার = সিমুলেশন, লাল দাগ = তত্ত্ব", loc="left", fontsize=11)
fig.suptitle(f"ঘণ্টায় ১১০ রোগী সামলাতে {need} জন কর্মী: তখন ৯০%-এর বেশি রোগী ৫ মিনিটের কম অপেক্ষা করেন", x=.01, ha="left", fontsize=13.5, weight="bold")
