a1.set_xticks([]); a1.set_yticks([]); plt.colorbar(im, ax=a1, fraction=.046, label="°C")
hs = [1 / r[0] for r in res]
a2.loglog(hs, [r[1] for r in res], "o-", color="#7c3aed", lw=2); a2.text(hs[0], res[0][1] * 1.2, f"পুরো পাত: ঢাল {rates[-1]:.1f}", color="#7c3aed", fontsize=9, ha="right")
