PIL_BN = r'''
import os
from PIL import Image, ImageDraw, ImageFont
BN_REG = os.environ.get("BN_FONT", "NotoSansBengali-Regular.ttf")
BN_BOLD = os.environ.get("BN_FONT_BOLD", BN_REG)
def ft(size, bold=False):
    return ImageFont.truetype(BN_BOLD if bold else BN_REG, size, layout_engine=ImageFont.Layout.RAQM)   # raqm = বাংলা shaping
'''

