# ------------------------------------------------------------------ Motion
MOTION_REACT = "https://esm.sh/motion@14.10.1/react?deps=react@18.3.1,react-dom@18.3.1"

jslib("Motion",
    about=("Motion (motion.dev, আগে Framer Motion) – ওয়েবের অ্যানিমেশন লাইব্রেরি, দুই রূপে: ভ্যানিলা JS (animate, scroll, inView, spring, stagger – হার্ডওয়্যার-ত্বরিত "
           "Web Animations API-র ওপর, দরকারে JS-এ) আর React (motion.div, layout অ্যানিমেশন, AnimatePresence, drag, whileHover/whileTap, Reorder)। "
           "সবচেয়ে বড় বৈশিষ্ট্য সত্যিকারের পদার্থবিজ্ঞানের spring: stiffness (k), damping (c), mass (m) – সময়-নির্দিষ্ট easing নয়, স্প্রিং-সমীকরণ। "
           "MIT লাইসেন্স।"),
    install='npm install motion\n// ভ্যানিলা: import { animate, spring } from "motion"\n// React:   import { motion } from "motion/react"',
    examples=[
        jlive("motion", "Motion-এর spring কি সত্যিই পদার্থবিজ্ঞান? প্রতি ফ্রেমের মান বনাম বিশ্লেষণী অবমন্দিত দোলকের সমাধান",
              "animate(0 → ১, {type: 'spring', stiffness k, damping c, mass m}) চালিয়ে onUpdate-এ প্রতি ফ্রেমের মান আর সময় রেকর্ড। একই সমীকরণ m·x″ + c·x′ + k(x − ১) = ০, "
              "x(০) = ০, x′(০) = ০-এর বিশ্লেষণী সমাধান: ζ = c/(২√(km)), ωₙ = √(k/m); ζ < ১ হলে x = ১ − e^(−ζωₙt)[cos ω_d t + (ζωₙ/ω_d) sin ω_d t], "
              "ζ = ১ ও ζ > ১-এর সূত্রও আলাদা। লেখচিত্রে বিন্দু = Motion, রেখা = তত্ত্ব; সর্বোচ্চ ভুল আর ওভারশুট (তত্ত্বে e^(−πζ/√(১−ζ²)))। "
              "স্লাইডার বদলে ζ < ১ (দোলে), = ১ (সংকট), > ১ (ধীরে বসে) দেখো। Motion শেষে restDelta-র মধ্যে এলে মান ১-এ স্থির করে – তাই শেষ বিন্দুটা বাদ।",
              r'''const app = document.getElementById("app");
const {animate} = Motion;
app.innerHTML = `<div class="row"><label class="muted">k <input id="k" type="range" min="20" max="600" value="180"></label><span id="kv" class="mono"></span>
<label class="muted">c <input id="c" type="range" min="1" max="60" value="8"></label><span id="cv" class="mono"></span>
<label class="muted">m <input id="m" type="range" min=".5" max="4" step=".1" value="1"></label><span id="mv" class="mono"></span><button id="go" class="pri">▶ চালাও</button></div>
<div style="display:flex;gap:10px;align-items:center"><div style="width:64px;height:250px;background:#f5f3ff;border-radius:10px;position:relative">
<div id="box" style="position:absolute;left:12px;width:40px;height:40px;border-radius:10px;background:#7c3aed;top:0"></div></div>
<canvas id="cv2" style="flex:1;height:250px;background:#fff;border-radius:10px;border:1px solid #e9e3fb"></canvas></div><div id="st" class="mono" style="font-size:12px;margin-top:6px"></div>`;
const cv = document.getElementById("cv2"), g = cv.getContext("2d");
const W = cv.width = cv.clientWidth * 2, H = cv.height = 500; g.scale(2, 2);
const v = id => +document.getElementById(id).value;
function theory(k, c, m) {
  const wn = Math.sqrt(k / m), z = c / (2 * Math.sqrt(k * m));
  if (z < 1) { const wd = wn * Math.sqrt(1 - z * z); return {z, f: t => 1 - Math.exp(-z * wn * t) * (Math.cos(wd * t) + z * wn / wd * Math.sin(wd * t))}; }
  if (Math.abs(z - 1) < 1e-9) return {z, f: t => 1 - Math.exp(-wn * t) * (1 + wn * t)};
  const r1 = -wn * (z - Math.sqrt(z * z - 1)), r2 = -wn * (z + Math.sqrt(z * z - 1));
  return {z, f: t => 1 + (r2 * Math.exp(r1 * t) - r1 * Math.exp(r2 * t)) / (r1 - r2)};
}
function lbl() { ["k", "c", "m"].forEach(id => document.getElementById(id + "v").textContent = v(id)); }
let anim = null;
function run() {
  lbl(); if (anim) anim.stop();
  const k = v("k"), c = v("c"), m = v("m"), th = theory(k, c, m), rec = [];
  const T = Math.min(4, 8 / (th.z * Math.sqrt(k / m)) + .3);
  let t0 = null;
  anim = animate(0, 1, {type: "spring", stiffness: k, damping: c, mass: m, restDelta: 1e-4, restSpeed: 1e-3,
    onUpdate: x => { const now = performance.now(); if (t0 === null) t0 = now; rec.push([(now - t0) / 1000, x]);
      document.getElementById("box").style.top = (x * 200) + "px"; },
    onComplete: () => draw(rec.slice(0, -1), th, T, k, c, m)});
  setTimeout(() => draw(rec.slice(0, -1), th, T, k, c, m), T * 1000 + 50);
}
function draw(rec, th, T, k, c, m) {
  const w = W / 2, h = H / 2, X = t => 34 + t / T * (w - 44), Y = x => h - 22 - x / 1.7 * (h - 40);
  g.clearRect(0, 0, w, h); g.strokeStyle = "#e4e4e7"; g.beginPath(); g.moveTo(34, Y(1)); g.lineTo(w, Y(1)); g.stroke();
  g.fillStyle = "#6b6288"; g.font = "11px system-ui"; g.fillText("১", 22, Y(1) + 4); g.fillText("০", 22, Y(0) + 4); g.fillText(`${T.toFixed(1)} সে`, w - 40, h - 6);
  g.strokeStyle = "#0d9488"; g.lineWidth = 2.5; g.beginPath();
  for (let i = 0; i <= 300; i++) { const t = T * i / 300; i ? g.lineTo(X(t), Y(th.f(t))) : g.moveTo(X(t), Y(th.f(t))); } g.stroke();
  g.fillStyle = "#7c3aed"; let err = 0;
  // Motion-এর প্রথম ফ্রেমের সময়-শূন্য আমাদের t0-এর সাথে এক ফ্রেম পর্যন্ত সরে থাকতে পারে → সামান্য সময়-সরণ ফিট করে নিই
  let best = [1e9, 0];
  for (let s = -0.04; s <= 0.04; s += 0.001) { let e = 0; rec.forEach(([t, x]) => { if (t <= T) e = Math.max(e, Math.abs(x - th.f(t + s))); }); if (e < best[0]) best = [e, s]; }
  err = best[0];
  rec.forEach(([t, x]) => { if (t <= T) { g.beginPath(); g.arc(X(t), Y(x), 2.2, 0, 7); g.fill(); } });
  const peak = Math.max(...rec.map(r => r[1])), osTh = th.z < 1 ? Math.exp(-Math.PI * th.z / Math.sqrt(1 - th.z * th.z)) : 0;
  document.getElementById("st").innerHTML = `ζ = ${th.z.toFixed(3)} (${th.z < .999 ? "কম-অবমন্দিত: দোলে" : th.z < 1.001 ? "সংকট-অবমন্দিত" : "অতি-অবমন্দিত"}) · ωₙ = ${Math.sqrt(k / m).toFixed(2)} rad/s · ` +
    `ফ্রেম ${rec.length}টা<br>ওভারশুট: Motion ${((peak - 1) * 100).toFixed(2)}% · তত্ত্ব ${(osTh * 100).toFixed(2)}% · সর্বোচ্চ |ভুল| = <b>${err.toExponential(1)}</b> (সময়-সরণ ${(best[1] * 1000).toFixed(0)} ms)`;
}
["k", "c", "m"].forEach(id => document.getElementById(id).oninput = lbl);
document.getElementById("go").onclick = run;
run();
''', hint=SHOW),
        jlive("esm", "React-এ drag আর layout অ্যানিমেশন: টেনে সাজানো কাজের তালিকা (Reorder) + সোয়াইপ-কার্ড (drag, বেগ দিয়ে সিদ্ধান্ত)",
              "motion/react (esm.sh, React ১৮.৩.১ + htm, কোনো বিল্ড নেই)। বাঁয়ে Reorder.Group – আইটেম টেনে ওপরে-নিচে নিলে বাকিরা layout-অ্যানিমেশনে নিজে সরে যায়, "
              "নতুন ক্রম নিচে লেখা। ডানে কার্ডের স্তূপ: drag='x', dragConstraints আর dragElastic; ছাড়ার মুহূর্তে onDragEnd-এর offset আর velocity দেখে সিদ্ধান্ত – "
              "|দূরত্ব| > ১২০ px অথবা |বেগ| > ৫০০ px/s হলে কার্ড উড়ে যায় (AnimatePresence-এর exit), নইলে spring-এ ফেরে। মাপা offset/velocity পর্দায়।",
              f'const MOTION = "{MOTION_REACT}";\n' + r'''const app = document.getElementById("app");
app.innerHTML = '<div class="muted">লোড হচ্ছে…</div>';
const [React, {createRoot}, {motion, AnimatePresence, Reorder, useMotionValue, useTransform}, htmMod] = await Promise.all([
  import("https://esm.sh/react@18.3.1"), import("https://esm.sh/react-dom@18.3.1/client"), import(MOTION), import("https://esm.sh/htm@3.1.1")]);
const html = htmMod.default.bind(React.createElement);
const {useState} = React;
const TASKS = ["বৃষ্টির ডেটা নামানো", "ডেটা পরিষ্কার", "চার্ট বানানো", "রিপোর্ট লেখা", "সহকর্মীকে পাঠানো"];
const CARDS = [["সুন্দরবন", "#0d9488"], ["কক্সবাজার", "#0284c7"], ["শ্রীমঙ্গল", "#16a34a"], ["সোনারগাঁও", "#f59e0b"], ["পাহাড়পুর", "#e11d48"]];
function Card({c, onGone, top}) {
  const x = useMotionValue(0), rot = useTransform(x, [-200, 200], [-18, 18]), op = useTransform(x, [-220, 0, 220], [.4, 1, .4]);
  const [info, setInfo] = useState("");
  return html`<${motion.div} drag=${top ? "x" : false} style=${{x, rotate: rot, opacity: op, position: "absolute", inset: 0, background: c[1], borderRadius: 18, color: "#fff",
      display: "grid", placeItems: "center", fontSize: 24, fontWeight: 800, cursor: top ? "grab" : "default", boxShadow: "0 8px 24px rgba(20,14,41,.25)"}}
    dragConstraints=${{left: 0, right: 0}} dragElastic=${.9} whileTap=${{scale: 1.04}}
    initial=${{scale: .9, y: 14}} animate=${{scale: top ? 1 : .94, y: top ? 0 : 12}}
    exit=${{x: x.get() > 0 ? 420 : -420, opacity: 0, transition: {duration: .35}}}
    onDragEnd=${(e, i) => { const go = Math.abs(i.offset.x) > 120 || Math.abs(i.velocity.x) > 500;
      setInfo(`offset ${i.offset.x.toFixed(0)} px · বেগ ${i.velocity.x.toFixed(0)} px/s → ${go ? (i.offset.x > 0 ? "পছন্দ ✓" : "বাদ ✗") : "ফিরে এল"}`);
      if (go) onGone(c[0], i.offset.x > 0); }}>
    <div style=${{textAlign: "center"}}>${c[0]}<div style=${{fontSize: 12, fontWeight: 400, opacity: .9}}>${info || "ডানে = পছন্দ · বাঁয়ে = বাদ"}</div></div></${motion.div}>`;
}
function App() {
  const [items, setItems] = useState(TASKS), [deck, setDeck] = useState(CARDS), [log, setLog] = useState([]);
  return html`<div style=${{display: "grid", gridTemplateColumns: "1fr 1fr", gap: 18}}>
    <div><b>টেনে অগ্রাধিকার সাজাও</b>
      <${Reorder.Group} axis="y" values=${items} onReorder=${setItems} style=${{listStyle: "none", padding: 0, margin: "8px 0"}}>
        ${items.map(it => html`<${Reorder.Item} key=${it} value=${it} whileDrag=${{scale: 1.05, boxShadow: "0 8px 20px rgba(124,58,237,.3)"}}
          style=${{padding: "9px 12px", margin: "6px 0", background: "#fff", border: "1px solid #c4b5fd", borderRadius: 12, cursor: "grab", userSelect: "none"}}>☰ ${it}</${Reorder.Item}>`)}
      </${Reorder.Group}><div class="muted">ক্রম: ${items.map((t, i) => `${i + 1}. ${t}`).join(" · ")}</div></div>
    <div><b>কোথায় বেড়াতে যাবে?</b>
      <div style=${{position: "relative", height: 210, marginTop: 8}}>
        <${AnimatePresence}>${deck.slice(0, 3).reverse().map((c, i, arr) => html`<${Card} key=${c[0]} c=${c} top=${i === arr.length - 1}
          onGone=${(n, like) => { setDeck(d => d.slice(1)); setLog(l => [...l, (like ? "✓ " : "✗ ") + n]); }} />`)}</${AnimatePresence}>
        ${deck.length ? "" : html`<button onClick=${() => { setDeck(CARDS); setLog([]); }} style=${{position: "absolute", inset: "80px 30%"}}>আবার</button>`}
      </div><div class="muted">${log.join(" · ") || "কার্ড টেনে ছেড়ে দাও"}</div></div></div>`;
}
app.innerHTML = ""; createRoot(app).render(html`<${App} />`);
'''),
    ],
    level="মাঝারি", tag="spring-পদার্থবিজ্ঞানের ওয়েব-অ্যানিমেশন – ভ্যানিলা JS ও React।",
    tasks=["drag/swipe ইন্টারফেস", "layout বদলের মসৃণ রূপান্তর", "spring-চালিত বোতাম/মোডাল", "scroll ও inView অ্যানিমেশন"],
    caps=["animate (WAAPI-ত্বরিত), spring (stiffness/damping/mass বা duration/bounce)", "scroll(), inView(), stagger(), timeline sequence", "React: motion.*, layout, AnimatePresence, Reorder, drag, gestures", "useMotionValue, useTransform, useSpring"],
    limits=["React-এর সুবিধাগুলো (layout, drag) ভ্যানিলা সংস্করণে সব নেই", "Framer Motion → Motion নাম বদলে আমদানির পথ বদলেছে", "স্প্রিং-এর শেষ ধাপ restDelta-য় হঠাৎ স্থির হয়"],
    alt="GSAP, Anime.js, react-spring, Web Animations API",
)

