a1.text(0, 1.03, f"কল: S=১০০, K=১০৫, r=৫%, σ=২০%, T=১ · BS = {bs:.4f}", transform=a1.transAxes, fontsize=9.5, color="#555")
e, s = np.array(mc).T
a2.errorbar(paths, e, yerr=1.96 * s, fmt="o", color="#0d9488", capsize=4); a2.axhline(0, color="#7c3aed", lw=1)
