import numpy as np, pandas as pd
import talib
import yfinance as yf

df = yf.download("BTC-USD", start="2023-10-01", end="2025-01-01", progress=False, auto_adjust=True)
c = df["Close"].squeeze().astype(float); x = c.values
rsi = talib.RSI(x, 14); mine = rsi_wilder(x, 14)
print(f"RSI: TA-Lib বনাম নিজের Wilder – সর্বোচ্চ পার্থক্য {np.nanmax(np.abs(rsi - mine)):.1e} (প্রথম মান দিন ১৫-এ, দুটোতেই)")
up, mid, lo = talib.BBANDS(x, 20, 2, 2)
roll = c.rolling(20)
print(f"BBANDS মাঝ = SMA২০: পার্থক্য {np.nanmax(np.abs(mid - roll.mean().values)):.1e} · ওপর = মাঝ + ২·σ(ddof=০): {np.nanmax(np.abs(up - (roll.mean() + 2 * roll.std(ddof=0)).values)):.1e}")
print(f"  (ddof=১ নিলে ব্যান্ড গড়ে {np.nanmean((roll.std(ddof=1) / roll.std(ddof=0)).values - 1):.2%} চওড়া হতো – √(২০/১৯))")
macd, sig, hist = talib.MACD(x, 12, 26, 9)
def ema_seed(v, n, start):
    """start দিনে বীজ = শেষ n দিনের SMA, তারপর k = ২/(n+১)"""
    out = np.full(len(v), np.nan); out[start] = v[start - n + 1:start + 1].mean(); k = 2 / (n + 1)
    for i in range(start + 1, len(v)): out[i] = out[i - 1] + k * (v[i] - out[i - 1])
    return out
ok = ~np.isnan(macd); first = int(np.argmax(ok))
naive = ema_seed(x, 12, 11) - ema_seed(x, 26, 25)                  # দুটো EMA নিজের নিজের প্রথম n দিন দিয়ে
mm = ema_seed(x, 12, 25) - ema_seed(x, 26, 25)                     # TA-Lib: দুটোই দিন ২৬-এ শুরু
sg = ema_seed(np.nan_to_num(mm), 9, 25 + 8)
print(f"MACD লাইন: সরল বীজে সর্বোচ্চ পার্থক্য {np.abs(macd[ok] - naive[ok]).max():.1e} (শুরুর দিকে) · TA-Lib-এর মতো একসাথে বীজে {np.abs(macd[ok] - mm[ok]).max():.1e}")
print(f"সিগন্যাল-রেখা (MACD-এর EMA৯, প্রথম ৯ মানের SMA-বীজ): সর্বোচ্চ পার্থক্য {np.abs(sig[ok] - sg[ok]).max():.1e} · প্রথম মান দিন {first + 1}-এ")
s = slice(np.where(c.index >= "2024-01-01")[0][0], None); idx = c.index[s]
print(f"২০২৪-এ RSI > ৭০ ছিল {int((rsi[s] > 70).sum())} দিন, < ৩০ ছিল {int((rsi[s] < 30).sum())} দিন")

fig, (a1, a2, a3) = plt.subplots(3, 1, figsize=(11.5, 7.6), sharex=True, gridspec_kw={"height_ratios": [2.2, 1, 1]})
a1.fill_between(idx, lo[s], up[s], color="#ede9fe"); a1.plot(idx, mid[s], color="#a78bfa", lw=1); a1.plot(idx, x[s], color="#140e29", lw=1.3)
a1.set_ylabel("$"); a1.text(idx[5], up[s][~np.isnan(up[s])].max() * .97, "বেগুনি ব্যান্ড = SMA২০ ± ২σ", fontsize=10, color="#7c3aed")
a2.plot(idx, rsi[s], color="#7c3aed", lw=1.3); a2.axhline(70, color="#e11d48", ls=":"); a2.axhline(30, color="#0d9488", ls=":"); a2.set_ylabel("RSI ১৪"); a2.set_ylim(10, 95)
a2.fill_between(idx, 70, rsi[s], where=rsi[s] > 70, color="#e11d48", alpha=.25)
a3.bar(idx, hist[s], color=np.where(hist[s] >= 0, "#0d9488", "#e11d48"), width=1); a3.plot(idx, macd[s], color="#140e29", lw=1); a3.plot(idx, sig[s], color="#f59e0b", lw=1); a3.set_ylabel("MACD")
a1.set_title(f"বিটকয়েন ২০২৪: RSI ৭০-এর ওপরে {int((rsi[s] > 70).sum())} দিন – শক্ত ঊর্ধ্বগতি ‘অতিক্রীত’ সংকেত দিয়েও থামেনি", loc="left", fontsize=13, weight="bold", pad=26)
a1.text(0, 1.03, "TA-Lib: BBANDS(২০, ২σ), RSI(১৪, Wilder), MACD(১২, ২৬, ৯) · প্রতিটা নিজের সূত্রে যাচাই করা", transform=a1.transAxes, fontsize=9.5, color="#555")
