import time
import numpy as np, pandas as pd
import ccxt

OPT = {"requests_trust_env": True}          # সিস্টেমের proxy/সার্টিফিকেট সেটিং মেনে চলো (অফিস/বিশ্ববিদ্যালয়ের নেটওয়ার্কে দরকার হয়)
EX = {"Kraken": ccxt.kraken(OPT), "Coinbase": ccxt.coinbaseexchange(OPT), "Bitstamp": ccxt.bitstamp(OPT)}
rows = []
for k in range(6):
    for name, ex in EX.items():
        try:
            t = ex.fetch_ticker("BTC/USD")
            rows.append(dict(snap=k, ex=name, bid=t["bid"], ask=t["ask"], last=t["last"], ts=pd.Timestamp.now(tz="UTC")))
        except Exception as e:
            print(f"{name}: {type(e).__name__}")
    time.sleep(2)
d = pd.DataFrame(rows); d["mid"] = (d.bid + d.ask) / 2; d["spread_bps"] = (d.ask - d.bid) / d.mid * 1e4
d["vs_avg_bps"] = d.groupby("snap").mid.transform(lambda m: (m / m.mean() - 1) * 1e4)
print(f"সময় (UTC): {d.ts.min():%Y-%m-%d %H:%M:%S} – {d.ts.max():%H:%M:%S}")
print(d.groupby("ex")[["mid", "spread_bps", "vs_avg_bps"]].agg(["mean", "min", "max"]).round(2).to_string())
best = []
for k, g in d.groupby("snap"):
    hb, la = g.loc[g.bid.idxmax()], g.loc[g.ask.idxmin()]
