a1.axhline(0, color="#a1a1aa"); a1.set_xlabel("সেকেন্ড"); a1.set_ylabel("তিনটার গড় থেকে দূরত্ব (bps)"); a1.set_xlim(-.5, 13)
a1.set_title(f"একই বিটকয়েন, তিন দাম – গড় থেকে সর্বোচ্চ {d.vs_avg_bps.abs().max():.1f} bps দূরে", loc="left", fontsize=12.5, weight="bold", pad=24)
a1.text(0, 1.03, f"BTC/USD মধ্য-দাম ≈ ${d.mid.mean():,.0f} · ccxt পাবলিক টিকার, চাবি ছাড়া", transform=a1.transAxes, fontsize=9.5, color="#555")
sp = d.groupby("ex").spread_bps.mean().sort_values()
a2.barh(sp.index, sp.values, color=[cols[i] for i in sp.index]); sp_usd = d.groupby("ex").apply(lambda g: (g.ask - g.bid).mean())[sp.index]
[a2.text(v, i, f" {v:.3f} bps (${u:.2f})", va="center") for i, (v, u) in enumerate(zip(sp.values, sp_usd.values))]
a2.set_xlim(right=sp.max() * 1.45)
a2.set_xlabel("গড় স্প্রেড (bps)"); a2.set_title("সবচেয়ে সরু স্প্রেড: " + sp.index[0], loc="left", fontsize=12.5, weight="bold", pad=24)
plt.tight_layout()
