pk_c = max(last, key=lambda k: last[k].loc[2021:].max()); pk = last[pk_c].loc[2021:]
LOC = {"বাংলাদেশ": "বাংলাদেশে", "ভারত": "ভারতে", "পাকিস্তান": "পাকিস্তানে", "শ্রীলঙ্কা": "শ্রীলঙ্কায়", "নেপাল": "নেপালে"}
