from PySide6.QtWidgets import QApplication, QWidget, QFormLayout, QDoubleSpinBox, QLabel, QHBoxLayout, QGroupBox
from PySide6.QtCore import Qt
from PySide6.QtTest import QTest

RATE = 122.0                                    # ১ ডলার = কত টাকা (উদাহরণ)
class Pair(QGroupBox):
    def __init__(self, title, safe):
        super().__init__(title); self.safe, self.calls = safe, 0
        self.taka = QDoubleSpinBox(prefix="৳ ", maximum=1e9, decimals=2, singleStep=100)
        self.usd = QDoubleSpinBox(prefix="$ ", maximum=1e7, decimals=2)
        self.note = QLabel(); self.note.setWordWrap(True)
        f = QFormLayout(self); f.addRow("টাকা", self.taka); f.addRow("ডলার", self.usd); f.addRow(self.note)
        self.taka.valueChanged.connect(self.from_taka); self.usd.valueChanged.connect(self.from_usd)
    def _set(self, box, v):
        if self.safe: box.blockSignals(True)            # অন্য বাক্স বদলালে তার signal যেন ফিরে না আসে
        box.setValue(v)
        if self.safe: box.blockSignals(False)
    def from_taka(self, v): self.calls += 1; self._set(self.usd, v / RATE); self.show_note()
    def from_usd(self, v):  self.calls += 1; self._set(self.taka, v * RATE); self.show_note()
    def show_note(self): self.note.setText(f"slot ডাকা হয়েছে {self.calls} বার")

app = QApplication(sys.argv)
w = QWidget(); w.setWindowTitle("টাকা ↔ ডলার (১ $ = ৳ ১২২)")
row = QHBoxLayout(w); naive, safe = Pair("সরল (ভুল)", False), Pair("blockSignals দিয়ে (ঠিক)", True)
