PIL_BN = r'''
from PIL import Image, ImageDraw, ImageFont
BN_FONT = os.environ.get("BN_FONT", "NotoSansBengali-Regular.ttf")
def bn_rgba(text, size=24, color=(20, 14, 41, 255)):
    """বাংলা লেখা HarfBuzz (Pillow-raqm) দিয়ে শেপ করে স্বচ্ছ RGBA ছবি"""
    f = ImageFont.truetype(BN_FONT, size, layout_engine=ImageFont.Layout.RAQM)
    x0, y0, x1, y1 = f.getbbox(text, language="bn"); im = Image.new("RGBA", (x1 - x0 + 4, y1 - y0 + 4), (0, 0, 0, 0))
    ImageDraw.Draw(im).text((2 - x0, 2 - y0), text, font=f, fill=color, language="bn"); return im
'''

