''' + PIL_BN + r'''
from kivy.app import App
from kivy.lang import Builder
from kivy.clock import Clock
from kivy.graphics.texture import Texture
from kivy.uix.image import Image as KImage
from kivy.core.window import Window

Window.size = (900, 560); Window.clearcolor = (0.98, 0.97, 1, 1)
def bn_widget(text, size=30, color=(76, 29, 149, 255)):
    im = bn_rgba(text, size, color).transpose(Image.FLIP_TOP_BOTTOM)   # Kivy-র টেক্সচারের y-অক্ষ নিচ থেকে
    tex = Texture.create(size=im.size, colorfmt="rgba"); tex.blit_buffer(im.tobytes(), colorfmt="rgba", bufferfmt="ubyte")
    return KImage(texture=tex, size_hint=(None, None), size=im.size)

KV = """
#:import C kivy.utils.get_color_from_hex
<Big@Button>:
    font_size: 22
    background_normal: ""
    background_color: C("#7c3aed")
<Crop@ToggleButton>:
    group: "crop"
    font_size: 22
    background_normal: ""
    background_color: C("#ede9fe") if self.state == "normal" else C("#0d9488")
    color: (0.1, 0.05, 0.2, 1) if self.state == "normal" else (1, 1, 1, 1)
BoxLayout:
    orientation: "vertical"
    padding: 18
    spacing: 12
    BoxLayout:
        id: title
        size_hint_y: None
        height: 50
    BoxLayout:
        size_hint_y: None
        height: 64
        spacing: 10
        Crop:
            text: "Rice"
        Crop:
            text: "Jute"
        Crop:
            text: "Wheat"
        Crop:
            text: "Mustard"
    BoxLayout:
        size_hint_y: None
        height: 56
        spacing: 10
        Spinner:
            id: district
            text: "Mymensingh"
            values: ["Mymensingh", "Rangpur", "Bogura", "Jessore", "Sylhet", "Faridpur"]
            font_size: 20
        TextInput:
            id: area
            hint_text: "Plot area (decimal)"
            input_filter: "float"
            multiline: False
            font_size: 22
    BoxLayout:
        size_hint_y: None
        height: 56
        Label:
            text: "Plant height: %d cm" % round(height.value)
            color: 0.1, 0.05, 0.2, 1
            font_size: 20
            size_hint_x: 0.4
        Slider:
            id: height
            min: 0
            max: 200
            value: 90
            cursor_size: 44, 44
    Label:
        id: msg
        color: 0.88, 0.11, 0.28, 1
        font_size: 18
    Big:
        id: save
        text: "Save record"
        size_hint_y: None
        height: 72
"""
class Survey(App):
    def build(self):
        root = Builder.load_string(KV); root.ids.title.add_widget(bn_widget("মাঠ-জরিপ · ফসলের তথ্য"))
        root.ids.save.bind(on_release=self.save); self.saved = []
        return root
    def crop(self):
        from kivy.uix.togglebutton import ToggleButton
        down = [b for b in ToggleButton.get_widgets("crop") if b.state == "down"]; return down[0].text if down else None
    def save(self, *_):
        ids = self.root.ids; c = self.crop(); a = float(ids.area.text or 0)
        if not c or a <= 0:
            ids.msg.text = "Choose a crop and enter an area > 0"; return False
        rec = dict(crop=c, district=ids.district.text, area_decimal=a, height_cm=round(ids.height.value))
        with open("survey.jsonl", "a", encoding="utf-8") as f: f.write(json.dumps(rec) + "\n")
        self.saved.append(rec); ids.msg.text = f"Saved #{len(self.saved)}: {rec}"; return True
    def on_start(self):
        if os.environ.get("ATLAS_DEMO"): Clock.schedule_once(self.demo, 0.8)
    def demo(self, *_):
        ids = self.root.ids
        for chunk in ("12.5", "abc", ".7"): ids.area.insert_text(chunk)
        print("TextInput-এ '12.5', 'abc', '.7' টাইপ করলে থাকে:", repr(ids.area.text), "(input_filter='float' অক্ষর আর দ্বিতীয় দশমিক-বিন্দু ফেলে দেয়)")
        ids.save.trigger_action(0); print("ফসল না বেছে Save:", ids.msg.text)
        from kivy.uix.togglebutton import ToggleButton
        [b for b in ToggleButton.get_widgets("crop") if b.text == "Jute"][0].state = "down"
        ids.district.text = "Faridpur"; ids.height.value = 143.6; ids.save.trigger_action(0)
        Clock.schedule_once(self.shot, 0.5)
    def shot(self, *_):
        Window.screenshot(name="survey_form.png"); print("ফাইলে:", open("survey.jsonl", encoding="utf-8").read().strip()); self.stop()

if os.path.exists("survey.jsonl") and os.environ.get("ATLAS_DEMO"): os.remove("survey.jsonl")
