    caps=["native widget (Win32/Cocoa/GTK)", "sizer-লেআউট, AUI ডকিং", "TreeCtrl, ListCtrl, dataview, Grid, StyledTextCtrl, html2.WebView", "wx.lib-এ শত শত সাহায্যকারী widget"],
