import os, shutil, zipfile, io
import gi
gi.require_version("Gtk", "3.0"); gi.require_version("Gdk", "3.0")
from gi.repository import Gtk, Gdk, Gio, GLib
from PIL import Image

INBOX = "ইনবক্স"; shutil.rmtree(INBOX, ignore_errors=True); os.makedirs(INBOX)
png = io.BytesIO(); Image.new("RGB", (40, 30), "#7c3aed").save(png, "PNG")
FILES = {"বার্ষিক_প্রতিবেদন_২০২৫.pdf": b"%PDF-1.7\n%\xe2\xe3\n1 0 obj<<>>endobj\n", "প্রচ্ছদ.png": png.getvalue(), "report.txt": png.getvalue(),
         "বৃষ্টি_ঢাকা.csv": "month,mm\n1,6.3\n2,19.5\n".encode(), "সূচিপত্র.md": "# সূচিপত্র\n১. ভূমিকা\n".encode(), "notes.txt": "খসড়া নোট – সম্পাদনা বাকি\n".encode()}
for n, b in FILES.items(): open(os.path.join(INBOX, n), "wb").write(b)
z = io.BytesIO(); zf = zipfile.ZipFile(z, "w"); zf.writestr("[Content_Types].xml", "<Types/>"); zf.writestr("word/document.xml", "<w:document/>"); zf.close()
open(os.path.join(INBOX, "চুক্তিপত্র.docx"), "wb").write(z.getvalue())
GROUP = lambda mime: "ছবি" if mime.startswith("image/") else "ডেটা" if mime in ("text/csv", "application/vnd.ms-excel") else "লেখা" if mime.startswith("text/") or "pdf" in mime or "word" in mime or "opendocument" in mime else "অন্যান্য"

class Organizer(Gtk.Window):
    def __init__(self):
        super().__init__(title="প্রকাশনার ফাইল-সংগঠক"); self.set_default_size(900, 440); self.move(0, 0)
        self.store = Gtk.ListStore(str, str, str, int, str)               # নাম, MIME, দল, আকার, পথ
        self.filter = self.store.filter_new(); self.filter.set_visible_func(self.visible); self.sorted = Gtk.TreeModelSort(model=self.filter)
        self.view = Gtk.TreeView(model=self.sorted)
        for i, h in enumerate(["নাম", "MIME-টাইপ (Gio)", "দল", "বাইট"]):
            c = Gtk.TreeViewColumn(h, Gtk.CellRendererText(), text=i); c.set_sort_column_id(i); c.set_resizable(True); self.view.append_column(c)
        self.search = Gtk.SearchEntry(placeholder_text="খোঁজো…"); self.search.connect("search-changed", lambda e: self.filter.refilter())
        self.side = Gtk.Label(xalign=0); self.btn = Gtk.Button(label="ধরন অনুযায়ী সাজাও"); self.btn.connect("clicked", self.organize)
        left = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=8, margin=12); left.pack_start(self.side, False, False, 0); left.pack_end(self.btn, False, False, 0)
        right = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=6, margin=12); right.pack_start(self.search, False, False, 0)
        sw = Gtk.ScrolledWindow(); sw.add(self.view); right.pack_start(sw, True, True, 0)
        box = Gtk.Box(); box.pack_start(left, False, False, 0); box.pack_start(right, True, True, 0); self.add(box)
        css = Gtk.CssProvider(); css.load_from_data(b"window{background:#faf7ff} button{background:#7c3aed;color:white;border-radius:999px;padding:6px 14px}")
        Gtk.StyleContext.add_provider_for_screen(Gdk.Screen.get_default(), css, Gtk.STYLE_PROVIDER_PRIORITY_APPLICATION); self.scan(INBOX)
    def scan(self, folder):
        self.store.clear(); self.guess = {}
        for root, _, files in os.walk(folder):
            for n in sorted(files):
                p = os.path.join(root, n); head = open(p, "rb").read(512)
                by_name, _ = Gio.content_type_guess(n, head)            # নাম + বাইট (নামের এক্সটেনশন জিতে যায়)
                by_data, unsure = Gio.content_type_guess(None, head)     # শুধু ভেতরের বাইট (‘magic’)
                ctype = by_data if not unsure and by_data != "application/octet-stream" and not Gio.content_type_is_a(by_name, by_data) and by_data.split("/")[0] != "text" else by_name
                mime = Gio.content_type_get_mime_type(ctype) or ctype; self.guess[n] = (Gio.content_type_get_mime_type(by_name), Gio.content_type_get_mime_type(by_data), unsure)
                self.store.append([n, mime, GROUP(mime), os.path.getsize(p), p])
        cnt = {}
        for r in self.store: cnt[r[2]] = cnt.get(r[2], 0) + 1
        self.side.set_markup("<b>ধরন অনুযায়ী</b>\n" + "\n".join(f"{k}: {v}টা" for k, v in sorted(cnt.items()))); self.count = cnt
    def visible(self, model, it, data=None):
        q = self.search.get_text().strip().lower(); return not q or q in model[it][0].lower() or q in model[it][1]
    def organize(self, *_):
        for r in list(self.store):
            dst = os.path.join(INBOX, r[2]); os.makedirs(dst, exist_ok=True)
            Gio.File.new_for_path(r[4]).move(Gio.File.new_for_path(os.path.join(dst, r[0])), Gio.FileCopyFlags.NONE, None, None, None)
        self.scan(INBOX)

win = Organizer(); win.connect("destroy", Gtk.main_quit); win.show_all()
if os.environ.get("ATLAS_DEMO"):
    def demo():
        for r in win.store:
            a, b, u = win.guess[r[0]]; print(f"{r[0]:28s} নামে: {a:28.28s} বাইটে: {b:28.28s}{'(অনিশ্চিত)' if u else ''} → {r[1].split('/')[-1][:40]} [{r[2]}]")
        win.search.set_text("png"); win.filter.refilter(); print("খোঁজ ‘png’ (নামে বা MIME-এ):", [r[0] for r in win.filter])
        win.search.set_text(""); win.btn.clicked()
        on_disk = {d: len(os.listdir(os.path.join(INBOX, d))) for d in sorted(os.listdir(INBOX))}
