from gi.repository import Gtk, Gdk, GLib

BN = str.maketrans("০১২৩৪৫৬৭৮৯", "0123456789")
def norm_phone(s):
    s = re.sub(r"[\s-]", "", s.translate(BN))
    m = re.fullmatch(r"(?:\+?88)?0?(1[3-9]\d{8})", s)
    return "+880" + m.group(1) if m else None
def ok_email(s): return re.fullmatch(r"[^@\s]+@[^@\s]+\.[a-z]{2,}", s.strip(), re.I) is not None
def ok_date(s):
    try: return dt.date.fromisoformat(s.translate(BN)) <= dt.date.today()
    except ValueError: return False
TESTS = [("01712345678", "+8801712345678"), ("+8801912-345678", "+8801912345678"), ("০১৮১২৩৪৫৬৭৮", "+8801812345678"), ("8801312345678", "+8801312345678"),
         ("01212345678", None), ("0171234567", None), ("1712345678", "+8801712345678")]
assert all(norm_phone(a) == b for a, b in TESTS), [(a, norm_phone(a)) for a, b in TESTS]
assert ok_email("rahim@example.com") and not ok_email("rahim@example") and not ok_date("2099-01-01")
print("যাচাই-ফাংশনের ১০টা পরীক্ষা পাস")

DIV = ["ঢাকা", "চট্টগ্রাম", "রাজশাহী", "খুলনা", "বরিশাল", "সিলেট", "রংপুর", "ময়মনসিংহ"]
class Form(Gtk.Window):
    def __init__(self):
        super().__init__(title="খানা-জরিপ: তথ্য সংগ্রহ"); self.set_default_size(620, 400); self.move(0, 0)
        css = Gtk.CssProvider(); css.load_from_data(b"""window{background:#faf7ff} entry.bad{border:2px solid #e11d48;background:#fff1f2} entry.good{border:2px solid #0d9488}
            button.save{background:#7c3aed;color:white;border-radius:999px;padding:6px 18px} label.hint{color:#e11d48}""")
        Gtk.StyleContext.add_provider_for_screen(Gdk.Screen.get_default(), css, Gtk.STYLE_PROVIDER_PRIORITY_APPLICATION)
        g = Gtk.Grid(column_spacing=12, row_spacing=8, margin=16); self.f, self.hint = {}, {}
        for r, (k, label, check, msg) in enumerate([("name", "নাম", lambda s: len(s.strip()) >= 2, "অন্তত ২ অক্ষর"), ("phone", "মোবাইল", norm_phone, "০১৩–০১৯ দিয়ে ১১ অঙ্ক"),
                                                    ("email", "ইমেইল", ok_email, "যেমন nam@example.com"), ("dob", "জন্মতারিখ", ok_date, "YYYY-MM-DD, ভবিষ্যৎ নয়")]):
            e = Gtk.Entry(hexpand=True); e.connect("changed", self.validate, check); self.f[k] = (e, check)
            h = Gtk.Label(label="", xalign=0); h.get_style_context().add_class("hint"); self.hint[e] = (h, msg)
            g.attach(Gtk.Label(label=label, xalign=1), 0, r, 1, 1); g.attach(e, 1, r, 1, 1); g.attach(h, 2, r, 1, 1)
        self.div = Gtk.ComboBoxText(); [self.div.append_text(d) for d in DIV]; self.div.set_active(0)
        self.members = Gtk.SpinButton.new_with_range(1, 20, 1); self.members.set_value(4)
        g.attach(Gtk.Label(label="বিভাগ", xalign=1), 0, 4, 1, 1); g.attach(self.div, 1, 4, 1, 1)
        g.attach(Gtk.Label(label="খানা-সদস্য", xalign=1), 0, 5, 1, 1); g.attach(self.members, 1, 5, 1, 1)
        self.save_btn = Gtk.Button(label="সংরক্ষণ"); self.save_btn.get_style_context().add_class("save"); self.save_btn.connect("clicked", self.save); g.attach(self.save_btn, 1, 6, 1, 1)
        self.info = Gtk.InfoBar(); self.info_lbl = Gtk.Label(label="তথ্য লেখো"); self.info.get_content_area().add(self.info_lbl)
        box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL); box.pack_start(self.info, False, False, 0); box.pack_start(g, True, True, 0); self.add(box); self.saved = 0
    def validate(self, e, check):
        good = bool(check(e.get_text())); sc = e.get_style_context(); sc.remove_class("bad"); sc.remove_class("good")
        if e.get_text(): sc.add_class("good" if good else "bad")
        h, msg = self.hint[e]; h.set_text("" if good or not e.get_text() else msg); return good
    def save(self, *_):
        bad = [k for k, (e, c) in self.f.items() if not self.validate(e, c)]
        if bad:
            self.info.set_message_type(Gtk.MessageType.ERROR); self.info_lbl.set_text("ঠিক করো: " + ", ".join(bad)); return False
        row = [self.f["name"][0].get_text(), norm_phone(self.f["phone"][0].get_text()), self.f["email"][0].get_text(), self.f["dob"][0].get_text().translate(BN),
               self.div.get_active_text(), int(self.members.get_value())]
        new = not os.path.exists("households.csv")
        with open("households.csv", "a", newline="", encoding="utf-8") as fh:
            w = csv.writer(fh); new and w.writerow(["name", "phone", "email", "dob", "division", "members"]); w.writerow(row)
        self.saved += 1; self.info.set_message_type(Gtk.MessageType.INFO); self.info_lbl.set_text(f"সংরক্ষিত #{self.saved}: {row[0]} ({row[4]})"); return True

win = Form(); win.connect("destroy", Gtk.main_quit); win.show_all()
if os.environ.get("ATLAS_DEMO"):
    if os.path.exists("households.csv"): os.remove("households.csv")
    RECS = [("রহিমা খাতুন", "০১৭১১-২৩৪৫৬৭", "rahima@example.com", "১৯৮৮-০৩-১৪", "সিলেট", 5), ("সুমি আক্তার", "+8801812345678", "sumi@example", "2001-07-30", "খুলনা", 3),
            ("সুমি আক্তার", "+8801812345678", "sumi@example.com", "2001-07-30", "খুলনা", 3), ("করিম মিয়া", "01212345678", "karim@example.com", "1975-11-02", "রংপুর", 6)]
    def fill(i):
        if i == len(RECS):
            rows = list(csv.DictReader(open("households.csv", encoding="utf-8")))
            print(f"CSV-তে {len(rows)}টা সারি:", [(r["name"], r["phone"], r["dob"], r["division"]) for r in rows])
            GLib.timeout_add(400, lambda: (snapshot(win, "data_entry.png"), Gtk.main_quit()) and False); return False
        n, p, e, d, dv, m = RECS[i]
        for k, v in zip(("name", "phone", "email", "dob"), (n, p, e, d)): win.f[k][0].set_text(v)
        win.div.set_active(DIV.index(dv)); win.members.set_value(m); ok = win.save()
        print(f"রেকর্ড {i + 1} ({n}): {'সংরক্ষিত' if ok else 'আটকে গেল'} – {win.info_lbl.get_text()}")
        GLib.timeout_add(150, fill, i + 1); return False
    GLib.timeout_add(700, fill, 0)
Gtk.main()
