    caps=["machine: Pin, ADC, PWM, I2C, SPI, UART, Timer, RTC, WDT, deepsleep", "asyncio, network (Wi-Fi), urequests, umqtt", "@micropython.native/viper, const, mpy-cross দিয়ে আগে-কম্পাইল", "mpremote, REPL, Thonny"],
