i2c = FakeI2C(bme_chip, aht_chip, oled_chip)                       # Pi-তে: import board; i2c = board.I2C()
while not i2c.try_lock(): pass
found = i2c.scan(); i2c.unlock()
print("I²C স্ক্যান:", [hex(a) for a in found], "→", {0x38: "AHT20", 0x3C: "SSD1306 OLED", 0x76: "BME280"})
bme, aht, oled = adafruit_bme280.Adafruit_BME280_I2C(i2c, 0x76), adafruit_ahtx0.AHTx0(i2c), adafruit_ssd1306.SSD1306_I2C(128, 64, i2c)
