a1.text(2, rows[2][1] + .4, "BME280", color="#7c3aed"); a1.text(2, rows[2][4] - 1.2, "AHT20 (+০.৩ °C পক্ষপাত)", color="#b45309")
a2.plot(x, [r[2] for r in rows], color="#7c3aed", lw=2); a2.plot(x, [r[5] for r in rows], color="#f59e0b", lw=1.4, ls="--"); a2.set_ylabel("%RH")
a2.set_xticks(range(0, 145, 24), [rows[i][0] if i < 144 else "24:00" for i in range(0, 145, 24)])
