pylib("pyserial",
    about=("pySerial দিয়ে সিরিয়াল-পোর্টে (UART/RS-232/USB-সিরিয়াল – Arduino, GPS, মডেম, ল্যাবের যন্ত্র) পড়া-লেখা: serial.Serial('/dev/ttyUSB0' বা 'COM3', baudrate, timeout), "
           "read/readline/write, in_waiting, reset_input_buffer; serial.tools.list_ports দিয়ে কোন পোর্টে কী লাগানো; serial_for_url দিয়ে বিশেষ পোর্ট – loop:// (নিজের লেখা নিজে পড়া), "
           "spy:// (সব বাইটের হেক্স-লগ), socket:// (নেটওয়ার্কে সিরিয়াল), rfc2217://। এখানে আসল Arduino নেই, তাই লিনাক্সের ছদ্ম-টার্মিনাল (pty) জোড়ায় একটা থ্রেড ‘Arduino’ সেজে লেখে – "
           "পড়ার দিকটা হুবহু আসল পোর্টের মতো pySerial। " + SIM_NOTE),
    install="pip install pyserial",
    examples=[
        ex("Arduino আবহাওয়া-সেন্সরের সিরিয়াল ড্যাশবোর্ড: NMEA-ধাঁচের লাইন ($WX,…*চেকসাম), ৯৬০০ baud-এর আসল গতিতে, মাঝে মাঝে নষ্ট বাইট – পড়া, চেকসাম যাচাই, চার্ট",
           "‘Arduino’ (আলাদা থ্রেড, pty-র মাস্টার-দিক) প্রতি সেকেন্ডে লেখে $WX,ক্রম,তাপ,আর্দ্রতা,চাপ*XX – XX হলো $ আর * -এর মাঝের সব অক্ষরের XOR (GPS-এর NMEA-নিয়ম)। "
           "৯৬০০ baud = প্রতি বাইটে ১০ বিট (স্টার্ট + ৮ + স্টপ) → ~৯৬০ বাইট/সেকেন্ড, তাই প্রতিটা লাইন লিখতে সময় নেয়। ৫%-লাইনে একটা বাইট নষ্ট করা হয় (শব্দ)। পড়ার দিক: "
           "serial.Serial(pty-স্লেভ, 9600, timeout=২) → readline → চেকসাম যাচাই → ভালো লাইন রাখা, নষ্ট লাইন গোনা; হারানো ক্রম-নম্বরও ধরা। শেষে তাপ-আর্দ্রতার চার্ট আর পরিসংখ্যান।",
           PLT_BN + r'''
import os, pty, threading, time, random, math
import serial

master, slave = pty.openpty(); port = os.ttyname(slave)          # আসল কাজে: port = "/dev/ttyUSB0" বা "COM3"
def nmea_cs(body): c = 0; [c := c ^ ord(ch) for ch in body]; return f"{c:02X}"
def arduino(n=90, baud=9600, seed=4):
    rng = random.Random(seed)
    for k in range(n):
        t = 29.0 + 2.5 * math.sin(k / 14) + rng.gauss(0, .15); h = 74 - 8 * math.sin(k / 14) + rng.gauss(0, .5); p = 1007.8 + .4 * math.cos(k / 30)
        body = f"WX,{k},{t:.2f},{h:.1f},{p:.1f}"; line = f"${body}*{nmea_cs(body)}\r\n".encode()
        if rng.random() < 0.05:
            i = rng.randrange(4, len(line) - 5); line = line[:i] + bytes([line[i] ^ 0x04]) + line[i + 1:]      # একটা বিট উল্টে গেল
        if k in (40, 41): continue                                     # দুটো লাইন হারিয়ে গেল
        os.write(master, line); time.sleep(len(line) * 10 / baud)       # ৯৬০০ baud-এর আসল গতি
threading.Thread(target=arduino, daemon=True).start()

good, bad, seqs = [], 0, []
t0 = time.monotonic()
with serial.Serial(port, 9600, timeout=2) as ser:
    print(f"খোলা পোর্ট: {ser.name} · {ser.baudrate} baud · {ser.bytesize}{ser.parity}{ser.stopbits}")
    while True:
        raw = ser.readline()
        if not raw: break                                          # ২ সেকেন্ডে কিছু না এলে শেষ
        s = raw.decode("ascii", "replace").strip()
        if not (s.startswith("$") and "*" in s): bad += 1; continue
        body, cs = s[1:].split("*", 1)
        if nmea_cs(body) != cs[:2]: bad += 1; continue
        _, k, t, h, p = body.split(","); good.append((int(k), float(t), float(h), float(p))); seqs.append(int(k))
el = time.monotonic() - t0 - 2
missing = sorted(set(range(seqs[0], seqs[-1] + 1)) - set(seqs))
print(f"ভালো লাইন {len(good)} · চেকসামে বাতিল {bad} · হারানো/বাতিল ক্রম-নম্বর {missing}")
print(f"গতি: ~{sum(len(f'$WX,{g[0]},{g[1]:.2f},{g[2]:.1f},{g[3]:.1f}*00') + 2 for g in good) / el:.0f} বাইট/সে (৯৬০০ baud-এর সীমা ৯৬০)")
ts = [g[1] for g in good]; print(f"তাপ {min(ts):.2f}–{max(ts):.2f} °C · গড় {sum(ts) / len(ts):.2f} · শেষ চাপ {good[-1][3]} hPa")
fig, ax = plt.subplots(figsize=(10.5, 4))
ax.plot([g[0] for g in good], ts, ".-", color="#e11d48", lw=1.2); ax2 = ax.twinx(); ax2.plot([g[0] for g in good], [g[2] for g in good], ".-", color="#0284c7", lw=1.2)
for m in missing: ax.axvline(m, color="#a1a1aa", ls=":", lw=1)
ax.set_xlabel("ক্রম-নম্বর (প্রতি সেকেন্ডে একটা)"); ax.set_ylabel("তাপমাত্রা (°C)", color="#e11d48"); ax2.set_ylabel("আর্দ্রতা (%)", color="#0284c7")
ax.set_title(f"সিরিয়াল থেকে {len(good)}টা ভালো লাইন – চেকসামে {bad}টা বাতিল, ধূসর দাগে বাদ-পড়া ক্রম", loc="left", fontsize=12.5, weight="bold", pad=24)
ax.text(0, 1.04, "pySerial · ৯৬০০ baud · NMEA-ধাঁচের XOR-চেকসাম · ছদ্ম-টার্মিনালে সিমুলেটেড Arduino", transform=ax.transAxes, fontsize=9.5, color="#555")
plt.tight_layout()
''', hint=SHOW),
        ex("বাইনারি প্রোটোকল আর লগ-ভিউয়ার: COBS-ফ্রেমিং + CRC-16/CCITT, spy:// দিয়ে প্রতিটা বাইটের হেক্স-লগ, আবর্জনার মাঝখান থেকে আবার সিঙ্ক্রোনাইজ",
           "টেক্সট-লাইনের চেয়ে দক্ষ: প্রতিটা প্যাকেট = struct-এ বাঁধা মান + CRC-16/CCITT-FALSE (বহুপদী ০x১০২১, শুরু ০xFFFF; প্রমিত পরীক্ষা: ‘123456789’ → ০x২৯B১), তারপর COBS-এনকোড "
           "(Consistent Overhead Byte Stuffing – ভেতরে কোনো ০x০০ থাকে না, ০x০০ দিয়ে ফ্রেম শেষ)। তাই মাঝপথে যোগ দিলেও পরের ০x০০ থেকে ঠিক ফ্রেম ধরা যায়। pty-জোড়ার এক দিকে ‘যন্ত্র’ লেখে, "
           "অন্য দিকে pySerial পড়ে, সামনে ইচ্ছে করে ১৩ বাইট আবর্জনা আর মাঝে একটা নষ্ট ফ্রেম; spy:// হেক্সডাম্প করে কোন বাইট গেল-এলো। CRC আর COBS নিজের হাতে লেখা – প্রমিত পরীক্ষা-মানে যাচাই।",
           r'''import os, pty, struct
import serial

def crc16_ccitt(data, crc=0xFFFF):
    for b in data:
        crc ^= b << 8
        for _ in range(8): crc = ((crc << 1) ^ 0x1021) & 0xFFFF if crc & 0x8000 else (crc << 1) & 0xFFFF
    return crc
def cobs_encode(data):
    out, block = bytearray(), bytearray()
    for b in data:
        if b == 0: out += bytes([len(block) + 1]) + block; block.clear()
        else:
            block.append(b)
            if len(block) == 254: out += bytes([255]) + block; block.clear()
    return bytes(out + bytes([len(block) + 1]) + block)
def cobs_decode(data):
    out, i = bytearray(), 0
    while i < len(data):
        n = data[i]
        if n == 0 or i + n > len(data) + (1 if i + n == len(data) else 0): raise ValueError("bad COBS")
        out += data[i + 1:i + n]; i += n
        if n < 255 and i < len(data): out.append(0)
    return bytes(out)
print(f"CRC-16/CCITT-FALSE('123456789') = 0x{crc16_ccitt(b'123456789'):04X} (প্রমিত 0x29B1)")
for t in (b"", b"\x00", b"\x00\x00", b"\x11\x22\x00\x33", bytes(range(1, 256))):
    assert cobs_decode(cobs_encode(t)) == t and 0 not in cobs_encode(t)
print("COBS: ৫টা পরীক্ষা (শূন্য-বাইট, ২৫৫-বাইট ব্লকসহ) উল্টো-রূপান্তরে হুবহু ✓")

FMT = "<HhHH"                                              # ক্রম, তাপ×১০০, আর্দ্রতা×১০, চাপ−৯০০ (×১০)
def frame(seq, t, h, p):
    body = struct.pack(FMT, seq, round(t * 100), round(h * 10), round((p - 900) * 10)); return cobs_encode(body + struct.pack("<H", crc16_ccitt(body))) + b"\x00"
master, slave = pty.openpty(); port = os.ttyname(slave)       # ‘যন্ত্র’ লেখে master-এ; আসল কাজে port = "/dev/ttyACM0"
ser = serial.serial_for_url(f"spy://{port}?file=spy.log", timeout=0.3)   # spy:// = আসল পোর্ট + প্রতিটা বাইটের হেক্স-লগ
stream = b"\x13\x37garbage!!\x00\xff" + frame(1, 29.41, 71.5, 1007.6) + frame(2, 29.55, 71.0, 1007.5)
bad = bytearray(frame(3, 29.60, 70.6, 1007.5)); bad[3] ^= 0x10; stream += bytes(bad) + frame(4, 29.72, 70.1, 1007.4) + b"\x00"
os.write(master, stream); data = ser.read(4096); ser.close()
print(f"পাঠানো {len(stream)} বাইট · পড়া {len(data)} বাইট · spy.log-এর প্রথম ৪ লাইন:")
for ln in open("spy.log", encoding="utf-8").read().splitlines()[:4]: print("   ", ln[:96])
ok, rejected = [], []
for chunk in data.split(b"\x00"):
    if not chunk: continue
    try:
        raw = cobs_decode(chunk)
        if len(raw) != struct.calcsize(FMT) + 2: raise ValueError(f"দৈর্ঘ্য {len(raw)}")
        body, (crc,) = raw[:-2], struct.unpack("<H", raw[-2:])
        if crc != crc16_ccitt(body): raise ValueError("CRC মেলেনি")
        s, t, h, p = struct.unpack(FMT, body); ok.append((s, t / 100, h / 10, p / 10 + 900))
    except ValueError as e:
        rejected.append((chunk[:8].hex(" "), str(e)))
print("গৃহীত ফ্রেম:", ok)
print("বাতিল:", rejected)
print(f"ক্রম ৩ (একটা বিট উল্টানো) ধরা পড়েছে? {all(o[0] != 3 for o in ok)} · প্রতি ফ্রেম {len(frame(1, 0, 0, 1000))} বাইট (টেক্সট-লাইনে ~৩২)")
print("ক্রম ১ হারাল কেন: আবর্জনার শেষ বাইট 0xFF আর ফ্রেম ১-এর মাঝে কোনো 0x00 ছিল না, তাই দুটো জুড়ে এক টুকরো → COBS ভাঙা। প্রতিকার: প্রতিটা ফ্রেমের আগেও 0x00 পাঠানো –")
fixed = [c for c in (b"\xff" + b"\x00" + frame(1, 29.41, 71.5, 1007.6)).split(b"\x00") if c]
print("   তাহলে টুকরো হয়:", [c[:4].hex(" ") for c in fixed], "→ দ্বিতীয়টা ফ্রেম ১, ঠিকঠাক পড়া যায়:", (lambda q: (q[0], q[1] / 100, q[2] / 10, q[3] / 10 + 900))(struct.unpack(FMT, cobs_decode(fixed[1])[:-2])))
'''),
    ],
    level="শুরু", tag="সিরিয়াল-পোর্ট (UART/USB-সিরিয়াল) পড়া-লেখার প্রমিত লাইব্রেরি।",
    tasks=["Arduino/ESP32-এর সেন্সর-ডেটা কম্পিউটারে", "GPS/মডেম/ল্যাব-যন্ত্রের সাথে কথা", "সিরিয়াল-লগ ভিউয়ার ও রেকর্ডার", "বাইনারি প্রোটোকল ডিবাগ"],
    caps=["Serial: baudrate, bytesize, parity, stopbits, timeout, RTS/CTS, DTR", "read/readline/read_until/write, in_waiting", "tools.list_ports (VID:PID, বর্ণনা), miniterm", "URL-পোর্ট: loop://, spy://, socket://, rfc2217://, alt://"],
    limits=["asyncio সরাসরি নেই (pyserial-asyncio আলাদা)", "পোর্টের অনুমতি লাগে (লিনাক্সে dialout গ্রুপ)", "২০২০-এর পর নতুন রিলিজ কম – তবু স্থিতিশীল"],
    alt="pyserial-asyncio, Arduino Serial Monitor, minicom, pymodbus (Modbus-RTU)",
)
