from qiskit import QuantumCircuit, transpile
from qiskit.quantum_info import Statevector
from qiskit_aer import AerSimulator

qc = QuantumCircuit(2, 2, name="Bell")
qc.h(0)          # সুপারপজিশন: (|0⟩+|1⟩)/√2
qc.cx(0, 1)      # কিউবিট ০ নিয়ন্ত্রক → কিউবিট ১ উল্টায় → জট
sv = Statevector.from_instruction(qc.remove_final_measurements(inplace=False))
print("স্টেটভেক্টর (ক্রম |q1 q0⟩):", np.round(sv.data, 4))
print("নিখুঁত সম্ভাবনা:", {k: round(v, 4) for k, v in sv.probabilities_dict().items()})

qc.measure([0, 1], [0, 1])
N = 4000
sim = AerSimulator(seed_simulator=2026)
counts = sim.run(transpile(qc, sim), shots=N).result().get_counts()
print("৪০০০ শটের গণনা:", dict(sorted(counts.items())))
se = np.sqrt(0.25 / N)                                    # p = ০.৫ হলে √(p(1−p)/N)
for k in ("00", "11"):
    p = counts.get(k, 0) / N
