ax1.set_title("সার্কিট: H তারপর CX", loc="left", fontsize=12)
ax = fig.add_axes([0.52, 0.14, 0.45, 0.66])
keys = ["00", "01", "10", "11"]; p_meas = [counts.get(k, 0) / N for k in keys]; p_th = [sv.probabilities_dict().get(k, 0) for k in keys]
