ax.errorbar(keys, p_meas, yerr=[se if p > 0 else 0 for p in p_meas], fmt="none", ecolor="#140e29", capsize=5, lw=1.2)
ax.scatter(keys, p_th, marker="_", s=900, color="#e11d48", lw=2.4, zorder=4)
