ax.text(3.35, 0.5, "লাল দাগ = তত্ত্ব ০.৫", color="#e11d48", fontsize=9, va="center")
ax.set_ylim(0, .62); ax.set_ylabel("সম্ভাবনা"); ax.set_title(f"মাপলে শুধু 00 আর 11 – {N} শটে প্রায় সমান ভাগ", pad=26)
subtitle(ax, f"AerSimulator · ত্রুটিদণ্ড = ±১σ = ±{se:.4f} (দ্বিপদ বণ্টন)")
fig.savefig("bell.png", dpi=150, bbox_inches="tight")
