pylib("pyscf",
    about=("PySCF (Python-based Simulations of Chemistry Framework) হলো কোয়ান্টাম রসায়নের ওপেন-সোর্স প্যাকেজ: হার্ট্রি-ফক (RHF/UHF), ঘনত্ব-ফাংশনাল তত্ত্ব (DFT – B3LYP, PBE…), "
           "MP2, কাপলড-ক্লাস্টার (CCSD, CCSD(T)), পূর্ণ কনফিগারেশন-ইন্টারঅ্যাকশন (FCI), CASSCF, পর্যাবৃত্ত কঠিন বস্তু (pbc)। গাউসিয়ান বেসিস-সেট (STO-3G থেকে cc-pVQZ), "
           "জ্যামিতি-অপ্টিমাইজেশন, ডাইপোল, অরবিটাল। সব পাইথনে – ধাপগুলো খুলে দেখা আর নিজের পদ্ধতি লেখা সহজ।"),
    install="pip install pyscf",
    examples=[
        ex("পানির অণু: বেসিস-সেট বড় করলে শক্তি কীভাবে নামে – RHF আর MP2, ডাইপোল-মোমেন্ট পরীক্ষার ১.৮৫ D-এর সাথে",
           "পরীক্ষালব্ধ জ্যামিতি (O–H = ০.৯৫৭২ Å, ∠HOH = ১০৪.৫২°)। STO-3G → 6-31G → 6-31G* → cc-pVDZ → cc-pVTZ: বেসিস যত বড়, ভেরিয়েশনাল নীতি অনুযায়ী HF-শক্তি তত নিচে (কখনো উপরে নয়) – "
           "প্রিন্টে যাচাই। MP2 যোগ করে ইলেকট্রন-সম্পর্ক (correlation) শক্তি। HF ডাইপোল বড় বেসিসে পরীক্ষালব্ধ ১.৮৫ D-এর চেয়ে একটু বেশি হয় (জানা প্রবণতা), আর কুপম্যান্সের "
           "উপপাদ্যে HOMO থেকে আয়নীকরণ-শক্তি বনাম পরীক্ষার ১২.৬২ eV।",
           QC_STYLE + r'''
import time
from pyscf import gto, scf, mp

r, ang = 0.9572, np.radians(104.52)
geom = f"O 0 0 0; H {r} 0 0; H {r * np.cos(ang):.6f} {r * np.sin(ang):.6f} 0"
HARTREE_EV = 27.211386
rows = []
print(f"{'বেসিস':10s} {'ফাংশন':>6} {'E(HF) Eh':>13} {'E_corr(MP2)':>12} {'ডাইপোল D':>9} {'−ε_HOMO eV':>11} {'সময় s':>7}")
for basis in ["sto-3g", "6-31g", "6-31g*", "cc-pvdz", "cc-pvtz"]:
    t0 = time.time()
    mol = gto.M(atom=geom, basis=basis, unit="Angstrom", verbose=0)
    mf = scf.RHF(mol).run(conv_tol=1e-10)
    pt = mp.MP2(mf).run()
    mu = np.linalg.norm(mf.dip_moment(verbose=0))
    homo = mf.mo_energy[mol.nelectron // 2 - 1] * HARTREE_EV
    rows.append((basis, mol.nao, mf.e_tot, pt.e_corr, mu, -homo))
    print(f"{basis:10s} {mol.nao:6d} {mf.e_tot:13.6f} {pt.e_corr:12.6f} {mu:9.3f} {-homo:11.2f} {time.time() - t0:7.2f}")
E = [x[2] for x in rows]
print("HF-শক্তি বেসিস বাড়ার সাথে কখনো বাড়েনি (ভেরিয়েশনাল নীতি)?", all(b <= a + 1e-9 for a, b in zip(E, E[1:])))
print(f"cc-pVTZ: HF ডাইপোল {rows[-1][4]:.3f} D বনাম পরীক্ষা ১.৮৫ D · কুপম্যান্স IE {rows[-1][5]:.2f} eV বনাম পরীক্ষা ১২.৬২ eV")
print(f"MP2 সম্পর্ক-শক্তি (cc-pVTZ) = {rows[-1][3] * HARTREE_EV:.2f} eV – রাসায়নিক বন্ধনের শক্তির মতোই বড়, তাই HF একা যথেষ্ট নয়")

fig, (ax, bx) = plt.subplots(1, 2, figsize=(12, 4.6))
names = [x[0] for x in rows]; xx = np.arange(len(rows))
ax.plot(xx, [x[2] for x in rows], "o-", color="#7c3aed", lw=2, label="HF")
ax.plot(xx, [x[2] + x[3] for x in rows], "s-", color="#0d9488", lw=2)
ax.text(4.1, rows[-1][2], "HF", color="#7c3aed", va="center"); ax.text(4.1, rows[-1][2] + rows[-1][3], "MP2", color="#0d9488", va="center")
ax.set_xticks(xx, [f"{n}\n({x[1]})" for n, x in zip(names, rows)]); ax.set_xlim(-.3, 4.6); ax.set_ylabel("মোট শক্তি (Hartree)")
ax.set_title("বড় বেসিসে শক্তি নামে – ভেরিয়েশনাল নীতি", pad=26); subtitle(ax, "H₂O, পরীক্ষালব্ধ জ্যামিতি · বন্ধনীতে বেসিস-ফাংশন সংখ্যা")
bx.bar(xx, [x[4] for x in rows], color="#c4b5fd", width=.55)
bx.axhline(1.85, color="#e11d48", lw=1.6, ls="--"); bx.text(4.35, 1.86, "পরীক্ষা\n১.৮৫ D", color="#e11d48", fontsize=9, va="bottom", ha="center")
for i, x in enumerate(rows): bx.text(i, x[4] + .03, f"{x[4]:.2f}", ha="center", fontsize=9.5)
bx.set_xticks(xx, names); bx.set_ylim(0, 2.6); bx.set_ylabel("ডাইপোল (Debye)"); bx.grid(axis="x", visible=False)
bx.set_title(f"HF ডাইপোল বড় বেসিসে {rows[-1][4]:.2f} D – পরীক্ষার চেয়ে একটু বেশি", pad=26); subtitle(bx, "HF সাধারণত পোলারিটি বাড়িয়ে দেখায়; MP2/CCSD কাছে আনে")
fig.tight_layout(); fig.savefig("water_basis.png", dpi=150, bbox_inches="tight")
''', hint=SHOW),
        ex("প্রজেক্ট: H₂ অণু ভাঙার বক্ররেখা – RHF ভুল সীমায় যায়, UHF প্রতিসাম্য ভাঙে, FCI নিখুঁত; বন্ধন-দৈর্ঘ্য ও বিয়োজন-শক্তি পরীক্ষার সাথে",
           "দুই প্রোটনের দূরত্ব ০.৪ থেকে ৪ Å। RHF দুই ইলেকট্রনকে এক অরবিটালে জোর করে রাখে, তাই বহুদূরে ‘H⁺ + H⁻’-এর মিশ্রণ – শক্তি অনেক বেশি। UHF-এ আলফা/বিটা অরবিটাল আলাদা হতে "
           "দিলে (HOMO-LUMO মিশিয়ে প্রারম্ভিক অনুমান) কুলসন-ফিশার বিন্দুর পর সঠিক সীমা ২E(H)-এ যায়। দুই ইলেকট্রনের জন্য FCI = সঠিক উত্তর (এই বেসিসে)। cc-pVTZ-এ r_e আর D_e বনাম পরীক্ষা "
           "(r_e = ০.৭৪১৪ Å, D_e = ৪.৭৪৮ eV), সাথে কম্পাঙ্ক ω_e (পরীক্ষা ৪৪০১ cm⁻¹)।",
           QC_STYLE + r'''
from pyscf import gto, scf, fci

EV, BASIS = 27.211386, "cc-pvtz"
def run(R):
    mol = gto.M(atom=f"H 0 0 0; H 0 0 {R}", basis=BASIS, unit="Angstrom", verbose=0)
    rhf = scf.RHF(mol).run(conv_tol=1e-11)
    e_fci = fci.FCI(rhf).kernel()[0]
    uhf = scf.UHF(mol); h = mol.nelectron // 2 - 1; C = rhf.mo_coeff.copy()
    ca, cb = C.copy(), C.copy()                               # HOMO আর LUMO ৪৫° মেশানো → প্রতিসাম্য ভাঙার সুযোগ
    ca[:, h], ca[:, h + 1] = (C[:, h] + C[:, h + 1]) / np.sqrt(2), (C[:, h] - C[:, h + 1]) / np.sqrt(2)
    cb[:, h], cb[:, h + 1] = (C[:, h] - C[:, h + 1]) / np.sqrt(2), (C[:, h] + C[:, h + 1]) / np.sqrt(2)
    occ = rhf.mo_occ / 2
    dm = np.array([ca @ np.diag(occ) @ ca.T, cb @ np.diag(occ) @ cb.T])
    e_uhf = uhf.kernel(dm0=dm)
    if uhf.e_tot > rhf.e_tot: e_uhf = rhf.e_tot                # কাছাকাছি দূরত্বে UHF = RHF
    return rhf.e_tot, e_uhf, e_fci
R = np.r_[np.linspace(0.4, 1.0, 13), np.linspace(1.1, 4.0, 30)]
E = np.array([run(r) for r in R])
Hatom = scf.UHF(gto.M(atom="H 0 0 0", basis=BASIS, spin=1, verbose=0)).run().e_tot
print(f"H পরমাণু (UHF = এই বেসিসে নিখুঁত): {Hatom:.6f} Eh (সত্য −০.৫) · ২E(H) = {2 * Hatom:.6f}")
print(f"R = ৪ Å-এ: RHF {E[-1, 0]:.4f}, UHF {E[-1, 1]:.4f}, FCI {E[-1, 2]:.4f} Eh → RHF-এর ভুল {(E[-1, 0] - 2 * Hatom) * EV:.2f} eV")
from scipy.optimize import minimize_scalar
from scipy.interpolate import CubicSpline
fine = np.linspace(0.65, 0.85, 9); Ef = np.array([run(r)[2] for r in fine]); cs = CubicSpline(fine, Ef)
m = minimize_scalar(cs, bounds=(0.65, 0.85), method="bounded"); re = m.x
mu = 1.00782503 / 2 * 1.66053907e-27
we = np.sqrt(cs(re, 2) * 4.3597447e-18 / 1e-20 / mu) / (2 * np.pi * 2.99792458e10)   # বলধ্রুবক k = E″ (Eh/Å² → N/m), ω = √(k/μ)/(2πc)
De = (2 * Hatom - cs(re)) * EV
print(f"FCI/{BASIS}: r_e = {re:.4f} Å (পরীক্ষা ০.৭৪১৪) · D_e = {De:.3f} eV (পরীক্ষা ৪.৭৪৮) · ω_e = {we:.0f} cm⁻¹ (পরীক্ষা ৪৪০১)")
diff = E[:, 0] - E[:, 1]; i_cf = np.argmax(diff > 1e-6)
print(f"UHF প্রথম RHF-এর নিচে নামে R = {R[i_cf - 1]:.2f} থেকে {R[i_cf]:.2f} Å-এর মাঝে (কুলসন-ফিশার বিন্দু, সাহিত্যে ≈ ১.২ Å)")

fig, ax = plt.subplots(figsize=(10, 5))
ref = 2 * Hatom
for j, (nm, c) in enumerate((("RHF", "#e11d48"), ("UHF", "#f59e0b"), ("FCI (সঠিক)", "#7c3aed"))):
    ax.plot(R, (E[:, j] - ref) * EV, color=c, lw=2.2 if j == 2 else 1.6)
    ax.text(4.06, (E[-1, j] - ref) * EV + (0.35 if j == 1 else -0.35 if j == 2 else 0), nm, color=c, va="center", fontsize=10)
ax.axhline(0, color="#6b6680", lw=1, ls=":"); ax.text(3.0, .15, "২টা আলাদা H পরমাণু", color="#6b6680", fontsize=9)
ax.annotate(f"r_e = {re:.3f} Å\nD_e = {De:.2f} eV", (re, cs(re) * EV - ref * EV), (1.2, -3.6), fontsize=10, color="#7c3aed", arrowprops=dict(arrowstyle="-", color="#7c3aed"))
ax.annotate("কুলসন-ফিশার বিন্দু", (R[i_cf], (E[i_cf, 0] - ref) * EV), (1.7, 1.6), fontsize=9, color="#f59e0b", arrowprops=dict(arrowstyle="-", color="#f59e0b"))
ax.set_xlim(0.35, 4.75); ax.set_ylim(-5.2, 6.8); ax.set_xlabel("H–H দূরত্ব (Å)"); ax.set_ylabel("শক্তি − ২E(H)  (eV)")
ax.set_title(f"বন্ধন ভাঙলে RHF {(E[-1, 0] - ref) * EV:.1f} eV ভুল করে; FCI-তে D_e = {De:.2f} eV (পরীক্ষা ৪.৭৫)", pad=26)
subtitle(ax, f"PySCF · বেসিস {BASIS} · ৪৩টা দূরত্ব · UHF-এর প্রারম্ভিক অনুমানে HOMO/LUMO মিশিয়ে প্রতিসাম্য ভাঙা")
fig.savefig("h2_curve.png", dpi=150, bbox_inches="tight")
''', hint="প্রজেক্ট"),
    ],
    level="উন্নত", tag="পাইথনে কোয়ান্টাম রসায়ন – HF, DFT, MP2, CCSD, FCI।",
    tasks=["অণুর শক্তি, জ্যামিতি ও কম্পাঙ্ক হিসাব", "বিক্রিয়া-শক্তি আর বন্ধন-বিয়োজন শক্তি", "বেসিস-সেট ও পদ্ধতির নির্ভুলতা তুলনা (ক্লাস/গবেষণা)", "কোয়ান্টাম কম্পিউটারের জন্য হ্যামিল্টোনিয়ান বানানো (Qiskit Nature/PennyLane)"],
    caps=["SCF: RHF/UHF/ROHF, DFT (libxc-এর শত শত ফাংশনাল)", "পোস্ট-HF: MP2, CCSD(T), FCI, CASSCF/CASCI, ADC, EOM", "জ্যামিতি-অপ্টিমাইজেশন (geomeTRIC/pyberny), হেসিয়ান", "পর্যাবৃত্ত সিস্টেম (pbc) – কঠিন পদার্থ", "অরবিটাল/ঘনত্ব cube-ফাইলে লেখা"],
    limits=["উইন্ডোজে সরাসরি pip নেই (WSL ব্যবহার করো)", "বড় অণুতে CCSD(T)/FCI খুব ব্যয়বহুল (N⁷, সূচকীয়)", "GUI নেই – অরবিটাল দেখতে আলাদা ভিজুয়ালাইজার লাগে"],
    alt="Psi4, ORCA (বিনামূল্যে একাডেমিক), NWChem, Gaussian (বাণিজ্যিক), xtb (দ্রুত আধা-অভিজ্ঞতালব্ধ)",
)
