# ------------------------------------------------------------------ python-control
pylib("python-control",
    about=("python-control (import control) হলো নিয়ন্ত্রণ-প্রকৌশলের (control systems) পাইথন টুলবক্স – MATLAB-এর Control Toolbox-এর মতো: ট্রান্সফার-ফাংশন (tf) আর স্টেট-স্পেস (ss) মডেল, "
           "feedback/series দিয়ে জোড়া, step_response/forced_response সিমুলেশন, step_info (ওভারশুট, স্থিতিকাল), Bode/Nyquist/root-locus, stability_margins (গেইন/ফেজ-মার্জিন), "
           "pade (সময়-বিলম্ব), lqr/place (স্টেট-ফিডব্যাক), ডিসক্রিট-সময় (sample_system)। PID টিউনিং, মোটর-নিয়ন্ত্রণ, প্রক্রিয়া-নিয়ন্ত্রণ শেখার আর নকশার জন্য।"),
    install="pip install control",
    examples=[
        pex("ডিম ফোটানোর ইনকিউবেটরের তাপমাত্রা: সময়-বিলম্বসহ প্রক্রিয়ায় PI(D) টিউনিং – Padé অনুমান বনাম নিখুঁত বিলম্বের সিমুলেশন",
            "ছোট খামারের ইনকিউবেটরে ৩৭.৭ °C ধরে রাখতে হয়। মডেল: হিটার ১০০ % দিলে ২৫ °C বাড়ে, সময়-ধ্রুবক τ = ১০ মিনিট, সেন্সরে বিলম্ব L = ৬০ s → G(s) = K·e^(−Ls)/(τs + 1)। "
            "SIMC-নিয়মে (Skogestad) PI: τ_c = L, K_c = τ/(K(τ_c + L)), τ_I = min(τ, ৪(τ_c + L))। control.pade দিয়ে বিলম্বকে ৩য়-ক্রমের ট্রান্সফার-ফাংশনে এনে step_info, আর পাশাপাশি "
            "১ সেকেন্ডের ধাপে নিখুঁত বিলম্ব-বাফারসহ নিজের সিমুলেশন – দুটো কতটা মেলে। শেষে ১০ মিনিটে দরজা খোলার (−৩ °C ধাক্কা) পর পুনরুদ্ধার।",
            QC_STYLE + r'''
import control as ct

K, tau, L = 0.25, 600.0, 60.0            # °C/%, s, s
tc = L
Kc = tau / (K * (tc + L)); Ti = min(tau, 4 * (tc + L))
print(f"SIMC PI: Kc = {Kc:.3f} %/°C, τ_I = {Ti:.0f} s (τ_c = L = {L:.0f} s)")
G0 = ct.tf([K], [tau, 1])
num, den = ct.pade(L, 3); D = ct.tf(num, den)
C = ct.tf([Kc * Ti, Kc], [Ti, 0])
T_ref = ct.feedback(C * G0 * D, 1)
t = np.arange(0, 1800, 1.0)
_, y_pade = ct.step_response(T_ref, t)
info = ct.step_info(T_ref, T=t, SettlingTimeThreshold=0.02)
print(f"Padé(3): ওভারশুট {info['Overshoot']:.1f} % · উত্থানকাল {info['RiseTime']:.0f} s · ২ % স্থিতিকাল {info['SettlingTime']:.0f} s · চূড়া {info['Peak']:.3f}")
gm, pm, _sm, wcg, wcp, _wms = ct.stability_margins(C * G0 * D)      # wcg = ফেজ-ক্রসওভার (GM), wcp = গেইন-ক্রসওভার (PM)
print(f"গেইন-মার্জিন {gm:.2f} ({20 * np.log10(gm):.1f} dB) · ফেজ-মার্জিন {pm:.1f}° · ক্রসওভার {wcp:.4f} rad/s")
print(f"বিলম্ব-মার্জিন = PM/ωc = {np.radians(pm) / wcp:.0f} s (আরও এত সেকেন্ড বিলম্ব বাড়লে দোলন শুরু)")

def simulate(setpoint, dist=None, dt=1.0, T=1800, T0=0.0):
    """নিখুঁত বিলম্ব: হিটারের প্রভাব L সেকেন্ড পর পৌঁছায় (বাফার), প্রক্রিয়া = প্রথম-ক্রম (সঠিক এক্সপোনেনশিয়াল ধাপ), PI = সমাকলন + ০–১০০ % সীমা"""
    n = int(T / dt); buf = [0.0] * int(L / dt); y = T0; I = 0.0; ys, us = [], []
    a = np.exp(-dt / tau)
    for k in range(n):
        e = setpoint(k * dt) - y; u = Kc * e + Kc / Ti * I
        if 0 <= u <= 100 or (u > 100 and e < 0) or (u < 0 and e > 0): I += e * dt     # অ্যান্টি-উইন্ডআপ
        u = min(max(u, 0), 100); buf.append(u); ud = buf.pop(0)
        y = a * y + (1 - a) * K * ud + (dist(k * dt) if dist else 0.0)
        ys.append(y); us.append(u)
    return np.array(ys), np.array(us)
y_ex, _ = simulate(lambda s: 1.0)              # একক ধাপ (সীমা ছাড়া অঞ্চলে): তুলনার জন্য
print(f"নিখুঁত বিলম্বের সিমুলেশন বনাম Padé: সর্বোচ্চ তফাত {np.max(np.abs(y_ex - y_pade)):.4f} (এককের অংশ)")
yex_os = (y_ex.max() - 1) * 100; print(f"নিখুঁত বিলম্বে ওভারশুট {yex_os:.1f} % (Padé {info['Overshoot']:.1f} %)")
# পুরো পরিস্থিতি: ঘরের ২৮ °C থেকে ৩৭.৭ °C, ৬০০ s পর দরজা খোলায় −৩ °C (৩০ s-এ ছড়ানো)
room = 28.0
ys, us = simulate(lambda s: 37.7 - room, dist=lambda s: -0.1 if 2400 <= s < 2430 else 0.0, T=4200)
ts = np.arange(len(ys))
within = np.where(np.abs(ys + room - 37.7) > 0.2)[0]
print(f"২৮ → ৩৭.৭ °C: হিটার শুরুতে {us[:5].max():.0f} % (সীমায়) · ±০.২ °C-এ স্থির হয় {within[within < 2400].max() / 60:.1f} মিনিটে"
      f" · দরজা খোলার পর সর্বনিম্ন {(ys[2400:] + room).min():.2f} °C, আবার ±০.২-এ {(within[within > 2400].max() - 2400) / 60:.1f} মিনিটে")

fig, (ax, bx) = plt.subplots(2, 1, figsize=(10, 6.4), sharex=False, gridspec_kw={"height_ratios": [1, 1.25]})
ax.plot(t / 60, y_pade, color="#7c3aed", lw=2.2); ax.plot(t / 60, y_ex, color="#e11d48", lw=1.2, ls="--")
ax.text(18.5, y_pade[-1] + .06, "Padé(3)", color="#7c3aed", fontsize=9.5); ax.text(18.5, y_pade[-1] - .18, "নিখুঁত বিলম্ব", color="#e11d48", fontsize=9.5)
ax.set_xlim(0, 22); ax.set_ylabel("একক ধাপের সাড়া")
ax.set_title(f"SIMC-টিউনড PI: ওভারশুট {info['Overshoot']:.1f} %, ফেজ-মার্জিন {pm:.0f}° – Padé আর নিখুঁত বিলম্ব প্রায় এক", pad=26)
subtitle(ax, f"G(s) = {K}·e^(−{L:.0f}s)/({tau:.0f}s+1) · Kc = {Kc:.2f}, τ_I = {Ti:.0f} s · দুই পদ্ধতির সর্বোচ্চ তফাত {np.max(np.abs(y_ex - y_pade)):.3f}")
bx.plot(ts / 60, ys + room, color="#0d9488", lw=2); bx.axhline(37.7, color="#140e29", lw=1, ls=":")
bx.fill_between(ts / 60, 37.5, 37.9, color="#ccfbf1", alpha=.6); bx.set_ylabel("তাপমাত্রা (°C)")
b2 = bx.twinx(); b2.plot(ts / 60, us, color="#f59e0b", lw=1, alpha=.8); b2.set_ylabel("হিটার (%)", color="#b45309"); b2.grid(False); b2.spines[:].set_visible(False); b2.set_ylim(0, 260)
bx.annotate("দরজা খোলা (−৩ °C)", (40, (ys[2430] + room)), (46, 33.5), fontsize=9.5, arrowprops=dict(arrowstyle="-", color="#140e29"))
bx.set_xlabel("সময় (মিনিট)"); bx.set_xlim(0, 70)
fig.tight_layout(); fig.savefig("incubator_pid.png", dpi=150, bbox_inches="tight")
''', hint=SHOW, pre=BN_PRE),
        pex("প্রজেক্ট: ডিসি-মোটরের অবস্থান-নিয়ন্ত্রণ – ভৌত প্যারামিটার থেকে ট্রান্সফার-ফাংশন, Bode আর Nyquist-এ মার্জিন, আর ‘গেইন-মার্জিন গুণ করলে সত্যিই কি দোলে?’ যাচাই",
            "রোবট-হাত বা সোলার-ট্র্যাকারের মোটর: J = ০.০১ kg·m², b = ০.১ N·m·s, K = ০.০১ (টর্ক/emf-ধ্রুবক), R = ১ Ω, L = ০.৫ H (ক্লাসের পরিচিত মডেল)। θ/V = K / (s[(Js+b)(Ls+R) + K²])। "
            "PD-নিয়ন্ত্রক (ডেরিভেটিভ শুধু মাপা অবস্থানে, Kp এমন যে ৯০° ধাপে ভোল্টেজ ~১২ V) বসিয়ে stability_margins → গেইন-মার্জিন GM, ফেজ-মার্জিন PM। যাচাই: নিয়ন্ত্রক-গেইন ঠিক GM গুণ করলে বদ্ধ-লুপের মেরু কাল্পনিক অক্ষে (বাস্তব অংশ ≈ ০) আর "
            "দোলনের কম্পাঙ্ক = ফেজ-ক্রসওভার ω₁₈₀। সাথে ধাপ-সাড়া (৯০° ঘোরানো) – ছোট মোটরে ভোল্টেজ-সীমা গতি কতটা আটকায় তা সৎভাবে।",
            QC_STYLE + r'''
import control as ct

J, b, K, R, Lm = 0.01, 0.1, 0.01, 1.0, 0.5
s = ct.tf("s")
P = K / (s * ((J * s + b) * (Lm * s + R) + K ** 2))
print("মোটর θ/V = ", np.round(P.num[0][0], 4), "/", np.round(P.den[0][0], 4), " (s-এর ঘাত বড় থেকে ছোট)")
print("উন্মুক্ত-লুপ মেরু:", np.round(ct.poles(P), 4))
Kp, Kd = 8.0, 2.0                                     # Kp = 8 V/rad → ৯০° ধাপে শুরুর ভোল্টেজ 8·π/2 = 12.6 V (১২ V চালকের কাছাকাছি)
Dd = Kd * s / (0.01 * s + 1)                          # ফিল্টারসহ ডেরিভেটিভ (বিশুদ্ধ ডেরিভেটিভ নয়েজ বাড়ায়)
C = Kp + Dd
Lo = C * P                                            # লুপ-ট্রান্সফার (স্থিতিশীলতা এটা দিয়েই)
gm, pm, _sm, wcg, wcp, _wms = ct.stability_margins(Lo)
print(f"গেইন-মার্জিন {gm:.2f} ({20 * np.log10(gm):.1f} dB) at ω₁₈₀ = {wcg:.2f} rad/s · ফেজ-মার্জিন {pm:.1f}° at ωc = {wcp:.2f} rad/s")
for k in (1.0, gm * 0.98, gm, gm * 1.02):
    poles = ct.poles(ct.feedback(k * Lo, 1)); i = np.argmax(poles.real)
    print(f"  গেইন ×{k:6.3f}: সবচেয়ে ডানের মেরু {poles[i].real:+.4f} {poles[i].imag:+.3f}j → {'স্থির' if poles.real.max() < -1e-6 else 'সীমানায়' if abs(poles.real.max()) < 1e-3 else 'অস্থির'}")
pc = ct.poles(ct.feedback(gm * Lo, 1)); w_osc = abs(pc[np.argmax(pc.real)].imag)
print(f"সীমানায় দোলনের কম্পাঙ্ক {w_osc:.3f} rad/s বনাম ω₁₈₀ = {wcg:.3f} rad/s → মিলেছে? {abs(w_osc - wcg) / wcg < 1e-3}")
# ডেরিভেটিভ শুধু মাপা অবস্থানের ওপর: u = Kp(r − y) − D·y → সেটপয়েন্ট বদলালে ‘ডেরিভেটিভ-ঝাঁকুনি’ নেই
Tr = ct.minreal(Kp * P / (1 + Lo), verbose=False); Ur = ct.minreal(Kp / (1 + Lo), verbose=False)
t = np.linspace(0, 8, 4000); _, y = ct.step_response(Tr * (np.pi / 2), t); _, u = ct.step_response(Ur * (np.pi / 2), t)
info = ct.step_info(Tr, T=t)
print(f"৯০° ঘোরানো: ওভারশুট {info['Overshoot']:.2f} % · উত্থানকাল {info['RiseTime']:.2f} s · ২ % স্থিতিকাল {info['SettlingTime']:.2f} s · স্থির-অবস্থার ভুল {abs(1 - info['SteadyStateValue']):.1e}")
print(f"মোটরে সর্বোচ্চ ভোল্টেজ {np.max(np.abs(u)):.1f} V (= Kp·π/2) · এই দুর্বল মোটরে (K = ০.০১) ১২ V-এর মধ্যে রাখতে Kp এর বেশি বাড়ানো যায় না – আরও দ্রুত চাইলে বড় মোটর/গিয়ার বা ভোল্টেজ-সীমা মেনে নকশা (যেমন ট্র্যাপিজয়েড-প্রোফাইল)")

w = np.logspace(-1, 3, 800)
mag, ph, _ = ct.frequency_response(Lo, w)
fig = plt.figure(figsize=(12, 5.6))
a1 = fig.add_axes([0.06, 0.55, 0.52, 0.33]); a2 = fig.add_axes([0.06, 0.1, 0.52, 0.38], sharex=a1); a3 = fig.add_axes([0.66, 0.1, 0.32, 0.78])
a1.semilogx(w, 20 * np.log10(mag), color="#7c3aed", lw=2); a1.axhline(0, color="#6b6680", lw=.8)
a1.vlines(wcg, -20 * np.log10(gm), 0, color="#e11d48", lw=2); a1.text(wcg * 1.15, -10 * np.log10(gm), f"GM {20 * np.log10(gm):.1f} dB", color="#e11d48", fontsize=9.5)
a1.set_ylabel("|L| (dB)"); a1.set_ylim(-80, 60); plt.setp(a1.get_xticklabels(), visible=False)
phd = np.degrees(np.unwrap(ph)); a2.semilogx(w, phd, color="#0d9488", lw=2); a2.axhline(-180, color="#6b6680", lw=.8)
a2.vlines(wcp, -180, -180 + pm, color="#f59e0b", lw=2); a2.text(wcp * 1.15, -180 + pm / 2, f"PM {pm:.0f}°", color="#b45309", fontsize=9.5)
a2.set_ylabel("ফেজ (°)"); a2.set_xlabel("ω (rad/s)")
a1.set_title(f"PD-নিয়ন্ত্রিত মোটর: গেইন-মার্জিন {20 * np.log10(gm):.1f} dB, ফেজ-মার্জিন {pm:.0f}°", pad=26)
subtitle(a1, f"Bode · Kp = {Kp:g}, Kd = {Kd:g} · লাল = GM (ω₁₈₀ = {wcg:.1f} rad/s), কমলা = PM (ωc = {wcp:.2f} rad/s) · ৯০° ধাপে স্থিতিকাল {info['SettlingTime']:.1f} s")
wn = np.logspace(-0.3, 3, 3000); L_c = np.array([complex(Lo(1j * x)) for x in wn])
a3.plot(L_c.real, L_c.imag, color="#7c3aed", lw=1.8); a3.plot(L_c.real, -L_c.imag, color="#c4b5fd", lw=1.2, ls="--")
a3.scatter([-1], [0], marker="+", s=160, color="#e11d48", zorder=4); a3.text(-1, .12, "−১", color="#e11d48", ha="center")
a3.scatter([-1 / gm], [0], s=25, color="#140e29", zorder=4); a3.text(-1 / gm, -.18, f"−1/GM", fontsize=8.5, ha="center")
a3.add_patch(plt.Circle((0, 0), 1, fill=False, color="#e9e5f5", lw=1)); a3.set_xlim(-2, 1); a3.set_ylim(-1.6, 1.6); a3.set_aspect("equal")
a3.set_title("Nyquist (কাছ থেকে)", pad=26); subtitle(a3, "বক্ররেখা −১-কে ঘেরে না → বদ্ধ-লুপ স্থির")
fig.savefig("motor_margins.png", dpi=150, bbox_inches="tight")
''', hint="প্রজেক্ট", pre=BN_PRE),
    ],
    level="মাঝারি", tag="নিয়ন্ত্রণ-প্রকৌশলের টুলবক্স – tf/ss, Bode, Nyquist, PID, LQR।",
    tasks=["PID টিউনিং ও সিমুলেশন (তাপমাত্রা, মোটর, ড্রোন)", "স্থিতিশীলতা-মার্জিন ও ফ্রিকোয়েন্সি-বিশ্লেষণ", "স্টেট-স্পেস নকশা: LQR, পোল-প্লেসমেন্ট, পর্যবেক্ষক", "নিয়ন্ত্রণ-প্রকৌশলের ক্লাস ও ল্যাব"],
    caps=["tf, ss, zpk; series/parallel/feedback; minreal", "step/impulse/forced/initial_response, step_info", "bode_plot, nyquist_plot, root_locus, stability_margins", "pade, sample_system (ডিসক্রিট), c2d", "lqr, lqe, place, acker; ননলিনিয়ার I/O সিস্টেম (nlsys)"],
    limits=["MATLAB/Simulink-এর মতো ব্লক-ডায়াগ্রাম GUI নেই", "সময়-বিলম্ব সরাসরি নয় – pade বা নিজের ডিসক্রিট-সিমুলেশন লাগে", "MIMO-র কিছু উন্নত ফাংশনের জন্য slycot লাগে"],
    alt="scipy.signal, MATLAB Control Toolbox, harold, Julia ControlSystems.jl",
)

# ------------------------------------------------------------------ PySpice
SPICE_PY = r'''
# ---- PySpice ১.৫ + ngspice ৪২-এর জন্য ছোট্ট সামঞ্জস্য-প্যাচ: নতুন ngspice stderr-এ ক্ষতিহীন ‘Note:’/‘Using SPARSE’ লেখে, PySpice সেটাকে ত্রুটি ভাবে
import PySpice.Logging.Logging as Logging
logger = Logging.setup_logging(logging_level="CRITICAL")
import PySpice.Spice.NgSpice.Shared as _S
_exec = _S.NgSpiceShared.exec_command
def _exec_command(self, command, join_lines=True):
    try:
        return _exec(self, command, join_lines)
    except _S.NgSpiceCommandError:
        bad = [l for l in self._stderr if l.strip() and not l.startswith(("Using SPARSE", "Using KLU", "Note:"))]
        if bad: raise
        return self.stdout if join_lines else self._stdout
_S.NgSpiceShared.exec_command = _exec_command
from PySpice.Spice.Netlist import Circuit
from PySpice.Unit import *
'''

pylib("pyspice",
    about=("PySpice হলো পাইথন থেকে SPICE সার্কিট-সিমুলেটর (ngspice, ঐচ্ছিকভাবে Xyce) চালানোর লাইব্রেরি: Circuit অবজেক্টে রোধ, ধারক, আবেশক, উৎস, ডায়োড, ট্রানজিস্টর, সাব-সার্কিট আর "
           ".model যোগ করে নেটলিস্ট বানায়; simulator.operating_point/dc/ac/transient বিশ্লেষণ চালিয়ে ফল NumPy-অ্যারে হিসেবে দেয় (একক-সহ: 1@u_kΩ)। তাই প্যারামিটার-সুইপ, "
           "অপ্টিমাইজেশন, matplotlib-চার্ট – সব পাইথনে। এখানে ngspice ৪২ শেয়ার্ড-লাইব্রেরি; PySpice ১.৫ আর নতুন ngspice-এর মধ্যে একটা ছোট অসামঞ্জস্য আছে, তাই উদাহরণের শুরুতে "
           "৮ লাইনের প্যাচ (কী করছে মন্তব্যে লেখা)।"),
    install="pip install PySpice      # আর ngspice: sudo apt install libngspice0 ngspice (লিনাক্স) · brew install libngspice · উইন্ডোজে pyspice-post-installation --install-ngspice-dll",
    examples=[
        ex("RC-চার্জিং: ১ kΩ + ১০ µF-এ ৫ V ধাপ – SPICE-এর ট্রানজিয়েন্ট বনাম 5(1 − e^(−t/RC)), τ, ৫τ-এ কত %",
           "সবচেয়ে মৌলিক সার্কিট দিয়ে সিমুলেটরকে যাচাই। τ = RC = ১০ ms: t = τ-এ ৬৩.২ %, ৫τ-এ ৯৯.৩ %। ট্রানজিয়েন্টের ফল বিশ্লেষণী সূত্রের সাথে প্রতিটা বিন্দুতে তুলনা – সর্বোচ্চ ভুল, "
           "আর ১০ %→৯০ % উত্থানকাল (তত্ত্বে ২.১৯৭τ)।",
           SPICE_PY + QC_STYLE + r'''
R, C, V = 1e3, 10e-6, 5.0
tau = R * C
cir = Circuit("RC charging")
cir.PulseVoltageSource("in", "in", cir.gnd, initial_value=0 @ u_V, pulsed_value=V @ u_V, pulse_width=1 @ u_s, period=2 @ u_s, delay_time=0 @ u_s,
                       rise_time=1 @ u_ns, fall_time=1 @ u_ns)
cir.R(1, "in", "out", R @ u_Ω)
cir.C(1, "out", cir.gnd, C @ u_F, initial_condition=0 @ u_V)
print(cir)
sim = cir.simulator(temperature=25, nominal_temperature=25)
an = sim.transient(step_time=20 @ u_us, end_time=60 @ u_ms, use_initial_condition=True, max_time=20 @ u_us)
t = np.array(an.time); v = np.array(an["out"])
v_th = V * (1 - np.exp(-np.maximum(t - 1e-9, 0) / tau))
print(f"τ = RC = {tau * 1e3:.1f} ms · সিমুলেশনের বিন্দু {len(t)}টা")
for k in (1, 2, 3, 5):
    vk = np.interp(k * tau, t, v)
    print(f"  t = {k}τ: {vk:.4f} V = {vk / V:.2%}  (তত্ত্ব {1 - np.exp(-k):.2%})")
print(f"সর্বোচ্চ ভুল |v − সূত্র| = {np.max(np.abs(v - v_th)) * 1e3:.3f} mV")
t10, t90 = np.interp(0.1 * V, v, t), np.interp(0.9 * V, v, t)
print(f"১০→৯০ % উত্থানকাল {(t90 - t10) * 1e3:.3f} ms · তত্ত্ব ln(9)·τ = {np.log(9) * tau * 1e3:.3f} ms")

fig, ax = plt.subplots(figsize=(10, 4.4))
ax.plot(t * 1e3, v, color="#7c3aed", lw=2.4)
ax.plot(t[::40] * 1e3, v_th[::40], "o", color="#e11d48", ms=4, mfc="none")
for k in (1, 3, 5):
    vk = np.interp(k * tau, t, v); ax.scatter([k * tau * 1e3], [vk], color="#140e29", zorder=4)
    ax.text(k * tau * 1e3 + .8, vk - .35, f"{k}τ: {vk / V:.1%}", fontsize=9.5)
ax.axhline(V, color="#6b6680", lw=.8, ls=":"); ax.set_xlabel("সময় (ms)"); ax.set_ylabel("ধারকের ভোল্টেজ (V)"); ax.set_ylim(0, 5.6)
ax.text(40, 3.2, "বেগুনি রেখা = ngspice\nলাল বৃত্ত = 5(1 − e^(−t/RC))", fontsize=9.5, color="#4c1d95")
ax.set_title(f"১ τ = {tau * 1e3:.0f} ms-এ ধারক {np.interp(tau, t, v) / V:.1%} ভরে – ngspice আর সূত্রের তফাত {np.max(np.abs(v - v_th)) * 1e3:.2f} mV", pad=26)
subtitle(ax, "PySpice + ngspice · R = 1 kΩ, C = 10 µF, ৫ V ধাপ")
fig.savefig("rc_charging.png", dpi=150, bbox_inches="tight")
'''),
        ex("ফিল্টারের ফ্রিকোয়েন্সি-সাড়া (AC বিশ্লেষণ): RC লো-পাসের −৩ dB = 1/(2πRC), সিরিজ-RLC ব্যান্ড-পাসের f₀ = 1/(2π√LC) আর Q",
           "অডিও বা সেন্সর-সংকেতে নয়েজ কাটার ফিল্টার। RC: ১.৫ kΩ + ১০০ nF → f_c = ১০৬১ Hz। RLC (রোধে আউটপুট): L = ১০ mH, C = ১০০ nF, R = ৫০ Ω → f₀ = ৫০৩৩ Hz, Q = (১/R)√(L/C) = ৬.৩২, "
           "ব্যান্ডপ্রস্থ f₀/Q। AC সুইপ (১০ Hz–১ MHz, দশকে ২০০ বিন্দু) থেকে −৩ dB বিন্দু, শিখর আর ব্যান্ডপ্রস্থ বের করে সূত্রের সাথে, আর −৩ dB-এ ফেজ −৪৫° কিনা।",
           SPICE_PY + QC_STYLE + r'''
def ac_sweep(build):
    cir = Circuit("filter"); cir.SinusoidalVoltageSource("in", "in", cir.gnd, amplitude=1 @ u_V, ac_magnitude=1 @ u_V)
    build(cir)
    an = cir.simulator(temperature=25, nominal_temperature=25).ac(start_frequency=10 @ u_Hz, stop_frequency=1 @ u_MHz, number_of_points=200, variation="dec")
    return np.array(an.frequency), np.array(an["out"])
Rl, Cl = 1.5e3, 100e-9
f, H = ac_sweep(lambda c: (c.R(1, "in", "out", Rl @ u_Ω), c.C(1, "out", c.gnd, Cl @ u_F)))
dB = 20 * np.log10(np.abs(H)); ph = np.degrees(np.angle(H))
fc_th = 1 / (2 * np.pi * Rl * Cl); fc = np.interp(-3.0103, dB[::-1], f[::-1])
print(f"RC লো-পাস: −৩ dB-বিন্দু {fc:.1f} Hz · সূত্র 1/(2πRC) = {fc_th:.1f} Hz · তফাত {abs(fc - fc_th) / fc_th:.2%}")
print(f"  f_c-এ ফেজ {np.interp(fc, f, ph):.2f}° (তত্ত্ব −৪৫°) · ১০ গুণ ওপরে {np.interp(10 * fc_th, f, dB):.2f} dB (তত্ত্ব {20 * np.log10(1 / np.sqrt(1 + 100)):.2f} dB, ঢাল −২০ dB/দশক)")

Lr, Cr, Rr = 10e-3, 100e-9, 50.0
f2, H2 = ac_sweep(lambda c: (c.L(1, "in", "a", Lr @ u_H), c.C(1, "a", "out", Cr @ u_F), c.R(1, "out", c.gnd, Rr @ u_Ω)))
d2 = 20 * np.log10(np.abs(H2)); i0 = int(np.argmax(d2))
f0_th = 1 / (2 * np.pi * np.sqrt(Lr * Cr)); Q_th = np.sqrt(Lr / Cr) / Rr
# −৩ dB বিন্দু শিখরের দুই পাশে (লগ-অক্ষে সূক্ষ্ম রৈখিক অন্তর্বেশন)
lo = np.interp(-3.0103, d2[:i0 + 1], f2[:i0 + 1]); hi = np.interp(-3.0103, d2[i0:][::-1], f2[i0:][::-1])
print(f"\nRLC ব্যান্ড-পাস: শিখর {f2[i0]:.0f} Hz-এ {d2[i0]:.3f} dB · সূত্র f₀ = {f0_th:.1f} Hz (২০০ বিন্দু/দশকে গ্রিড-ধাপ ≈ {f2[i0] * (10 ** (1 / 200) - 1):.0f} Hz)")
print(f"  ব্যান্ডপ্রস্থ {hi - lo:.1f} Hz → Q = f₀/BW = {f0_th / (hi - lo):.3f} · সূত্র Q = (1/R)√(L/C) = {Q_th:.3f} · তত্ত্বে BW = R/(2πL) = {Rr / (2 * np.pi * Lr):.1f} Hz")
print(f"  −৩ dB-বিন্দুর জ্যামিতিক গড় √(f₁f₂) = {np.sqrt(lo * hi):.1f} Hz (= f₀ হওয়ার কথা)")

fig, (ax, bx) = plt.subplots(1, 2, figsize=(12.5, 4.6))
ax.semilogx(f, dB, color="#7c3aed", lw=2.2); ax.axhline(-3, color="#6b6680", lw=.8, ls=":"); ax.axvline(fc_th, color="#e11d48", lw=1, ls="--")
ax.text(fc_th * 1.2, -1.2, f"f_c = {fc:.0f} Hz\n(সূত্র {fc_th:.0f})", color="#e11d48", fontsize=9.5, va="top")
ax.text(2e4, -30, "−২০ dB/দশক", color="#7c3aed", fontsize=9.5, rotation=-26)
ax.set_ylim(-60, 5); ax.set_xlabel("কম্পাঙ্ক (Hz)"); ax.set_ylabel("লাভ (dB)")
ax.set_title(f"RC লো-পাস: −৩ dB ঠিক {fc:.0f} Hz-এ", pad=26); subtitle(ax, "১.৫ kΩ + ১০০ nF · ngspice AC বিশ্লেষণ")
bx.semilogx(f2, d2, color="#0d9488", lw=2.2); bx.axhline(-3, color="#6b6680", lw=.8, ls=":")
bx.axvspan(lo, hi, color="#ccfbf1", alpha=.7); bx.text(np.sqrt(lo * hi), -50, f"BW = {hi - lo:.0f} Hz\nQ = {f0_th / (hi - lo):.2f}", ha="center", fontsize=9.5, color="#115e59")
bx.text(f2[i0] * 1.5, -2, f"f₀ = {f2[i0]:.0f} Hz", color="#0d9488", fontsize=10)
bx.set_xlim(1e2, 2e5); bx.set_ylim(-60, 5); bx.set_xlabel("কম্পাঙ্ক (Hz)")
bx.set_title(f"RLC ব্যান্ড-পাস: f₀ = {f0_th:.0f} Hz, Q = {Q_th:.2f} – সূত্রের সাথে মিল", pad=26); subtitle(bx, "১০ mH + ১০০ nF + ৫০ Ω, আউটপুট রোধে")
fig.tight_layout(); fig.savefig("filters_ac.png", dpi=150, bbox_inches="tight")
'''),
        ex("প্রজেক্ট: মোবাইল-চার্জারের মতো অর্ধ-তরঙ্গ রেকটিফায়ার – ১২ V RMS, ৫০ Hz, 1N4007 ডায়োড, ফিল্টার-ধারক; রিপল বনাম সূত্র V_r ≈ I/(fC)",
           "দেশের বিদ্যুৎ ৫০ Hz। ট্রান্সফরমারের ১২ V RMS (শিখর ১৬.৯৭ V) → 1N4007 (প্রকাশিত SPICE-মডেল) → ৪৭০ µF ‖ ১ kΩ লোড। ধারক প্রতি চক্রে একবার ভরে, বাকি সময় লোডে খালি হয় – রিপল "
           "V_r ≈ V_out/(f R C)। ধারকের মান ১০০–২২০০ µF সুইপ করে রিপল, গড় আউটপুট আর ডায়োডের সর্বোচ্চ (inrush-এর পর স্থির-অবস্থার) কারেন্ট-শিখর। বড় ধারক রিপল কমায়, কিন্তু ডায়োডকে ছোট সময়ে "
           "বড় কারেন্ট দিতে হয় – নকশার আপস চার্টে।",
           SPICE_PY + QC_STYLE + r'''
Vrms, f, Rload = 12.0, 50.0, 1e3
def rectifier(Cf):
    cir = Circuit("half-wave")
    cir.model("D1N4007", "D", IS=7.02767e-9, RS=0.0341512, N=1.80803, EG=1.05743, XTI=5, BV=1000, IBV=5e-8, CJO=1e-11, VJ=0.7, M=0.5, FC=0.5, TT=1e-7)
    cir.SinusoidalVoltageSource("ac", "a", cir.gnd, amplitude=Vrms * np.sqrt(2) @ u_V, frequency=f @ u_Hz)
    cir.R("s", "a", "b", 0.5 @ u_Ω)                       # ট্রান্সফরমারের তারের রোধ
    cir.D(1, "b", "out", model="D1N4007")
    cir.C("f", "out", cir.gnd, Cf @ u_F)
    cir.R("L", "out", cir.gnd, Rload @ u_Ω)
    an = cir.simulator(temperature=25, nominal_temperature=25).transient(step_time=20 @ u_us, end_time=400 @ u_ms, max_time=20 @ u_us)
    t = np.array(an.time); vo = np.array(an["out"]); ib = (np.array(an["a"]) - np.array(an["b"])) / 0.5
    m = t > 0.3                                            # শেষ ৫ চক্র = স্থির অবস্থা
    return t, vo, ib, vo[m].max() - vo[m].min(), vo[m].mean(), ib[m].max(), np.array(an["a"])
t, vo, ib, Vr, Vavg, Ipk, va = rectifier(470e-6)
Vpk = Vrms * np.sqrt(2)
print(f"ইনপুট শিখর {Vpk:.2f} V · আউটপুট শিখর {vo[t > .3].max():.2f} V (ডায়োডে ঝরে {Vpk - vo[t > .3].max():.2f} V)")
print(f"৪৭০ µF: গড় {Vavg:.2f} V · রিপল {Vr:.3f} V · সূত্র V_out/(fRC) = {vo[t > .3].max() / (f * Rload * 470e-6):.3f} V · ডায়োডের কারেন্ট-শিখর {Ipk * 1000:.0f} mA (লোডে গড় {Vavg / Rload * 1000:.1f} mA)")
caps = [100e-6, 220e-6, 470e-6, 1000e-6, 2200e-6]; rows = []
for Cf in caps:
    _t, _v, _i, r, avg, ip, _a = rectifier(Cf)
    rows.append((Cf, r, avg, ip)); print(f"  C = {Cf * 1e6:6.0f} µF: রিপল {r:.3f} V (সূত্র {avg / (f * Rload * Cf):.3f}) · গড় {avg:.2f} V · ডায়োড-শিখর {ip * 1000:5.0f} mA · শিখর/গড় = {ip / (avg / Rload):.0f}×")
print("সূত্রটা ছোট রিপলের অনুমান (ধারক রৈখিকভাবে খালি হয় ধরে) – বড় রিপলে (১০০ µF) সূত্র বাড়িয়ে বলে।")

fig, (ax, bx) = plt.subplots(1, 2, figsize=(12.5, 4.6), gridspec_kw={"width_ratios": [1.35, 1]})
m = (t > 0.34) & (t < 0.38)
ax.plot((t[m] - .34) * 1e3, va[m], color="#c4b5fd", lw=1.4); ax.plot((t[m] - .34) * 1e3, vo[m], color="#7c3aed", lw=2.4)
a2 = ax.twinx(); a2.fill_between((t[m] - .34) * 1e3, 0, ib[m] * 1000, color="#fda4af", alpha=.6); a2.set_ylim(0, Ipk * 1000 * 3.2); a2.set_ylabel("ডায়োড-কারেন্ট (mA)", color="#e11d48")
a2.grid(False); a2.spines[:].set_visible(False); a2.tick_params(colors="#e11d48")
ax.text(1, 15.2, "আউটপুট", color="#7c3aed", fontsize=10); ax.text(11, -14, "ট্রান্সফরমার", color="#8b5cf6", fontsize=9.5)
ax.set_xlabel("সময় (ms)"); ax.set_ylabel("ভোল্টেজ (V)"); ax.set_ylim(-18, 19)
ax.set_title(f"৪৭০ µF-এ রিপল {Vr:.2f} V – ডায়োড চলে প্রতি চক্রের ছোট্ট অংশে, {Ipk * 1000:.0f} mA শিখরে", pad=26)
subtitle(ax, "PySpice + ngspice · ১২ V RMS, ৫০ Hz, 1N4007, ১ kΩ লোড · স্থির অবস্থার দুই চক্র")
Cs = np.array([r[0] for r in rows]) * 1e6
bx.loglog(Cs, [r[1] for r in rows], "o-", color="#7c3aed", lw=2); bx.loglog(Cs, [r[2] / (f * Rload * r[0]) for r in rows], "--", color="#6b6680", lw=1)
bx.text(Cs[-1] * 1.08, rows[-1][1], "রিপল (V)", color="#7c3aed", fontsize=9.5, va="center")
bx.text(Cs[0] * 1.1, rows[0][2] / (f * Rload * rows[0][0]) * 1.25, "সূত্র I/(fC)", color="#6b6680", fontsize=9)
b2 = bx.twinx(); b2.semilogx(Cs, [r[3] * 1000 for r in rows], "s-", color="#e11d48", lw=1.6); b2.set_ylabel("ডায়োড-শিখর (mA)", color="#e11d48"); b2.grid(False); b2.spines[:].set_visible(False); b2.tick_params(colors="#e11d48")
bx.set_xlabel("ফিল্টার-ধারক (µF)"); bx.set_xlim(80, 4000)
bx.set_title("বড় ধারক = কম রিপল, কিন্তু বড় কারেন্ট-ঝাঁকুনি", pad=26); subtitle(bx, "১০০–২২০০ µF সুইপ")
fig.tight_layout(); fig.savefig("rectifier.png", dpi=150, bbox_inches="tight")
''', hint="প্রজেক্ট"),
    ],
    level="মাঝারি", tag="পাইথন থেকে ngspice – সার্কিট সিমুলেশন (DC, AC, ট্রানজিয়েন্ট)।",
    tasks=["ফিল্টার, পাওয়ার-সাপ্লাই, অ্যামপ্লিফায়ারের নকশা-যাচাই", "উপাদানের মান সুইপ ও অপ্টিমাইজেশন", "ইলেকট্রনিক্স ক্লাসের ল্যাব-শিট স্বয়ংক্রিয় করা", "নির্মাতার SPICE-মডেল দিয়ে সার্কিট পরীক্ষা"],
    caps=["Circuit-API: R, L, C, উৎস, D, Q (BJT), M (MOSFET), সাব-সার্কিট", "operating_point, dc, ac, transient, noise, distortion", "একক-ব্যবস্থা (u_kΩ, u_uF…) আর NumPy-ফল", "ngspice শেয়ার্ড-মোড ও Xyce", "KiCad নেটলিস্ট পড়া"],
    limits=["PySpice ১.৫-এর পর রক্ষণাবেক্ষণ ধীর – নতুন ngspice-এর সাথে ছোট প্যাচ লাগে", "ngspice আলাদা ইনস্টল করতে হয়", "স্কিম্যাটিক আঁকার GUI নেই (KiCad/LTspice দিয়ে আঁকো)"],
    alt="LTspice (GUI), ngspice CLI, Xyce, InSpice (PySpice-এর ফর্ক), lcapy (প্রতীকী বিশ্লেষণ)",
)
