import random, collections
random.seed(2026)
CW, CH, T = 15, 10, 24                         # কোষ (প্রস্থ, উচ্চতা), টাইলের মাপ px
W, H = 2 * CW + 1, 2 * CH + 1
grid = [[1] * W for _ in range(H)]             # ১ = দেয়াল, ০ = পথ
stack, seen = [(0, 0)], {(0, 0)}; grid[1][1] = 0
while stack:                                    # রিকার্সিভ ব্যাকট্র্যাকার (স্ট্যাক দিয়ে)
    cx, cy = stack[-1]
    nb = [(cx + dx, cy + dy) for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1))
          if 0 <= cx + dx < CW and 0 <= cy + dy < CH and (cx + dx, cy + dy) not in seen]
    if not nb: stack.pop(); continue
    nx, ny = random.choice(nb)
    grid[cy + ny + 1][cx + nx + 1] = 0         # দুই কোষের মাঝের দেয়াল ভাঙা
    grid[2 * ny + 1][2 * nx + 1] = 0
    seen.add((nx, ny)); stack.append((nx, ny))
opens = sum(r.count(0) for r in grid)
print(f"গোলকধাঁধা {W}×{H} টাইল · খোলা টাইল {opens} = কোষ {CW * CH} + প্যাসেজ {opens - CW * CH} → প্যাসেজ = কোষ − ১? {opens - CW * CH == CW * CH - 1} (তাই নিখুঁত, লুপ নেই)")

def bfs(src):
    dist, prev, q = {src: 0}, {}, collections.deque([src])
    while q:
        x, y = q.popleft()
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            p = (x + dx, y + dy)
            if grid[p[1]][p[0]] == 0 and p not in dist:
                dist[p] = dist[(x, y)] + 1; prev[p] = (x, y); q.append(p)
    return dist, prev
def path_to(prev, src, dst):
    p, out = dst, []
    while p != src: out.append(p); p = prev[p]
    return out[::-1]
start, exit_ = (1, 1), (W - 2, H - 2)
d0, _ = bfs(start)
dead_ends = sum(1 for y in range(1, H, 2) for x in range(1, W, 2)
                if sum(grid[y + dy][x + dx] == 0 for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1))) == 1)
print(f"প্রবেশ → প্রস্থান সবচেয়ে ছোট পথ {d0[exit_]} ধাপ · কানাগলি {dead_ends}টা · সবচেয়ে দূরের টাইল {max(d0.values())} ধাপ")

class Tile(pygame.sprite.Sprite):
    def __init__(self, col, x, y, r=0):
        super().__init__(); self.image = pygame.Surface((T, T), pygame.SRCALPHA)
        pygame.draw.rect(self.image, col, (3, 3, T - 6, T - 6), border_radius=r) if r else self.image.fill(col)
        self.rect = self.image.get_rect(topleft=(x * T, y * T + 40))
class Coin(Tile):
    def __init__(self, x, y):
        super().__init__((0, 0, 0, 0), x, y); pygame.draw.circle(self.image, (245, 158, 11), (T // 2, T // 2), 7)
        pygame.draw.circle(self.image, (253, 230, 138), (T // 2 - 2, T // 2 - 2), 2); self.cell = (x, y)
walls = pygame.sprite.Group(Tile((76, 29, 149), x, y) for y in range(H) for x in range(W) if grid[y][x])
free = [p for p in d0 if p not in (start, exit_)]
coins = pygame.sprite.Group(Coin(*p) for p in random.sample(free, 6))
player = Tile((13, 148, 136), *start, r=7)

route, here, todo = [], start, {c.cell for c in coins}
while todo:                                         # লোভী পরিকল্পনা: প্রতিবার BFS-এ সবচেয়ে কাছের কয়েন
    dist, prev = bfs(here); nxt = min(todo, key=dist.get)
    route += path_to(prev, here, nxt); here = nxt; todo.remove(nxt)
dist, prev = bfs(here); route += path_to(prev, here, exit_)
print(f"সব ৬টা কয়েন নিয়ে বেরোতে পরিকল্পিত পথ {len(route)} ধাপ (শুধু বেরোতে {d0[exit_]})")

screen = pygame.Surface((W * T, H * T + 40))
font = bn_font(20, bold=True)
frames, got, cur = [], 0, start
for step, nxt in enumerate(route + [exit_]):
    for sub in (0.5, 1.0):                          # টাইলের মাঝামাঝি একটা অতিরিক্ত ফ্রেম = মসৃণ
        fx = cur[0] + (nxt[0] - cur[0]) * sub; fy = cur[1] + (nxt[1] - cur[1]) * sub
        player.rect.topleft = (fx * T, fy * T + 40)
        got += len(pygame.sprite.spritecollide(player, coins, dokill=True))
        if step % 2 == 0 or nxt == exit_:
            screen.fill((250, 247, 255)); walls.draw(screen); coins.draw(screen)
            pygame.draw.rect(screen, (225, 29, 72), (exit_[0] * T + 4, exit_[1] * T + 44, T - 8, T - 8), border_radius=3)
            screen.blit(player.image, player.rect)
            txt = f"কয়েন {got}/৬ · ধাপ {step}" if HAS_BN else f"coins {got}/6  step {step}"
            screen.blit(font.render(txt, True, (20, 14, 41)), (12, 8))
            frames.append(screen.copy())
    cur = nxt
print(f"তোলা কয়েন {got}/৬ · অ্যানিমেশনের ফ্রেম {len(frames)}")
gif(frames, "maze_run.gif", 70)

heat = pygame.Surface((W * T, H * T))
mx = max(d0.values())
for y in range(H):
    for x in range(W):
        if grid[y][x]: col = (20, 14, 41)
        else:
            k = d0[(x, y)] / mx; col = (int(250 - 126 * k), int(247 - 189 * k), int(255 - 18 * k))
        heat.fill(col, (x * T, y * T, T, T))
