import math, random, time
from shapely.geometry import Polygon
from shapely.affinity import translate
random.seed(4)
ship_pts = [(20, 0), (40, 44), (20, 34), (0, 44)]
rock_pts = [(30 + r * math.cos(a), 30 + r * math.sin(a)) for a, r in
            [(k * 2 * math.pi / 11, 18 + 12 * random.random()) for k in range(11)]]
def sprite(pts, col, size):
    s = pygame.sprite.Sprite(); s.image = pygame.Surface(size, pygame.SRCALPHA)
    pygame.draw.polygon(s.image, col, pts); s.rect = s.image.get_rect(); s.mask = pygame.mask.from_surface(s.image); return s
ship, rock = sprite(ship_pts, (13, 148, 136), (41, 45)), sprite(rock_pts, (124, 58, 237), (61, 61))
print(f"জাহাজের বাক্স {ship.rect.size}, ভরা পিক্সেল {ship.mask.count()} ({ship.mask.count() / (41 * 45):.0%}) · গ্রহাণু ভরা {rock.mask.count() / 61 ** 2:.0%}")
P_ship, P_rock = Polygon(ship_pts), Polygon(rock_pts)
N = 10000; stats = dict(rect=0, mask=0, true=0, rect_false=0, mask_false=0, mask_miss=0); samples = []
t_rect = t_mask = 0.0
for _ in range(N):
    dx, dy = random.randint(-45, 61), random.randint(-45, 61)
    ship.rect.topleft = (dx, dy); rock.rect.topleft = (0, 0)
    a = time.perf_counter(); r = ship.rect.colliderect(rock.rect); b = time.perf_counter()
    m = pygame.sprite.collide_mask(ship, rock) is not None; c = time.perf_counter()
    t_rect += b - a; t_mask += c - b
    tr = translate(P_ship, dx, dy).intersection(P_rock).area > 1.0      # ১ px²-এর বেশি ছেদ = আসল ধাক্কা
    stats["rect"] += r; stats["mask"] += m; stats["true"] += tr
    stats["rect_false"] += r and not tr; stats["mask_false"] += m and not tr; stats["mask_miss"] += tr and not m
    if len(samples) < 400 and r: samples.append((dx, dy, m, tr))
print(f"{N} অবস্থান: বাক্স বলে ধাক্কা {stats['rect']} · mask বলে {stats['mask']} · আসল জ্যামিতি {stats['true']}")
print(f"বাক্সের মিথ্যা-ধাক্কা {stats['rect_false']} ({stats['rect_false'] / stats['rect']:.1%} ‘ধাক্কা’-ই ভুল) · mask-এর মিথ্যা {stats['mask_false']}, ধরতে-না-পারা {stats['mask_miss']}"
      " (pygame বহুভুজের সীমানার পিক্সেলও ভরে, তাই mask আসল আকারের চেয়ে ~১ px মোটা)")
print(f"গড় সময়: colliderect {t_rect / N * 1e6:.2f} µs · collide_mask {t_mask / N * 1e6:.2f} µs → mask {t_mask / t_rect:.0f} গুণ ধীর; তাই আগে বাক্স, মিললে তবেই mask")

fig, (ax, bx) = plt.subplots(1, 2, figsize=(12, 4.6), gridspec_kw={"width_ratios": [1, 1.1]})
for dx, dy, m, tr in samples:
    ax.scatter(dx + 20, dy + 22, s=10, color="#e11d48" if not m else "#0d9488", alpha=.6)
ax.add_patch(plt.Polygon(rock_pts, color="#c4b5fd", alpha=.9)); ax.add_patch(plt.Rectangle((0, 0), 61, 61, fill=False, ls="--", color="#7c3aed"))
ax.set_xlim(-30, 90); ax.set_ylim(90, -30); ax.set_aspect("equal"); ax.grid(False)
ax.text(-28, -24, "বিন্দু = জাহাজের কেন্দ্র যেখানে বাক্স ‘ধাক্কা’ বলে", fontsize=9, color="#6b6680")
