import random, collections, math
from PIL import Image, ImageDraw
random.seed(9)
CW = CH = 8; W, H = 2 * CW + 1, 2 * CH + 1
g = [[1] * W for _ in range(H)]; st, seen = [(0, 0)], {(0, 0)}; g[1][1] = 0
while st:
    cx, cy = st[-1]; nb = [(cx + a, cy + b) for a, b in ((1, 0), (-1, 0), (0, 1), (0, -1)) if 0 <= cx + a < CW and 0 <= cy + b < CH and (cx + a, cy + b) not in seen]
    if not nb: st.pop(); continue
    nx, ny = random.choice(nb); g[cy + ny + 1][cx + nx + 1] = 0; g[2 * ny + 1][2 * nx + 1] = 0; seen.add((nx, ny)); st.append((nx, ny))
def bfs(s, t):
    prev, q = {s: None}, collections.deque([s])
    while q:
        p = q.popleft()
        for a, b in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            n = (p[0] + a, p[1] + b)
            if g[n[1]][n[0]] == 0 and n not in prev: prev[n] = p; q.append(n)
    out = [t]
    while prev[out[-1]]: out.append(prev[out[-1]])
    return out[::-1]
path = bfs((1, 1), (W - 2, H - 2))
print(f"গোলকধাঁধা {W}×{H} টাইল · সবচেয়ে ছোট পথ {len(path) - 1} টাইল (= {2 * (len(path) - 1)} m, টাইল ২ m)")
