camera.fov = 75
pts = []                                                        # পথের প্রতিটা টাইলের মাঝে ৫ ধাপ
for a, b in zip(path, path[1:]):
    for k in range(5): pts.append((a[0] + (b[0] - a[0]) * k / 5, a[1] + (b[1] - a[1]) * k / 5, math.degrees(math.atan2(b[0] - a[0], b[1] - a[1]))))
pts.append((path[-1][0], path[-1][1], pts[-1][2]))
heading = pts[0][2]; inside = 0; shots = []
for k, (tx, ty, hd) in enumerate(pts):
    d = (hd - heading + 180) % 360 - 180; heading += d * 0.5             # মোড়ে মসৃণ ঘোরা
    camera.position = (tx * 2, 1.6, ty * 2); camera.rotation = (0, heading, 0)
