S = 24; mp = Image.new("RGB", (W * S, H * S), (250, 247, 255)); d = ImageDraw.Draw(mp)
for y in range(H):
    for x in range(W):
        if g[y][x]: d.rectangle([x * S, y * S, x * S + S - 1, y * S + S - 1], fill=(76, 29, 149))
d.line([(x * S + S // 2, y * S + S // 2) for x, y in path], fill=(245, 158, 11), width=5)
for i, k in enumerate((6, len(pts) // 2, len(pts) - 8)):
    x, y = pts[k][0] * S + S // 2, pts[k][1] * S + S // 2; d.ellipse([x - 9, y - 9, x + 9, y + 9], fill=(13, 148, 136)); d.text((x - 3, y - 6), str(i + 1), fill="white")
views = [Image.open(s).convert("RGB").resize((480, 270)) for s in shots]
sheet = Image.new("RGB", (W * S + 20 + 480, max(H * S, 3 * 270 + 20)), (250, 247, 255))
sheet.paste(mp, (0, 0))
for i, v in enumerate(views): sheet.paste(v, (W * S + 20, i * 280))
sheet.save("maze_walk.png")
import os
for s in shots: os.remove(s)
print("ছবি: বাঁয়ে ওপর থেকে মানচিত্র (কমলা = পথ, সবুজ ১–৩ = ক্যামেরার জায়গা), ডানে ওই তিন জায়গার প্রথম-পুরুষ দৃশ্য")
