pylib("pyyaml (yaml)",
    about=("PyYAML হলো পাইথনের সবচেয়ে প্রচলিত YAML পার্সার/লেখক (import yaml): মানুষের পড়ার মতো কনফিগ – ইন্ডেন্টেশন দিয়ে গঠন, তালিকা (-), মন্তব্য (#), অ্যাঙ্কর/অ্যালিয়াস (&, *) আর "
           "মার্জ-চাবি (<<) দিয়ে পুনরাবৃত্তি কমানো, এক ফাইলে অনেক ডকুমেন্ট (---)। safe_load সবসময় – yaml.load (বা unsafe_load) বিশ্বাস-না-করা ফাইলে পাইথন-অবজেক্ট বানিয়ে কোড চালাতে পারে! "
           "YAML ১.১ মেনে চলে: yes/no/on/off বুলিয়ান হয়ে যায় – ‘নরওয়ে সমস্যা’। লেখার সময় allow_unicode=True দিলে বাংলা সরাসরি।"),
    install="pip install pyyaml          # import yaml",
    examples=[
        pex("আঞ্চলিক জলবায়ু-মডেলের সেটিংস YAML-এ: অ্যাঙ্কর আর মার্জ-চাবি দিয়ে পুনরাবৃত্তি কমানো, safe_load বনাম বিপজ্জনক load, আর ‘নরওয়ে সমস্যা’ (NO → False)",
            "তিনটা পরীক্ষা-রান একই মূল সেটিংস নেয় (&base), প্রতিটা শুধু যা বদলায় সেটা লেখে (<<: *base) – YAML-এর সবচেয়ে কাজের কৌশল। safe_load একটা ‘!!python/object/apply:os.system’ ট্যাগ "
            "পেলে থামিয়ে দেয় – সেটা দেখানো (চালানো হয় না!)। আর YAML ১.১-এ উদ্ধৃতি-চিহ্ন ছাড়া NO, yes, on বুলিয়ান – দেশের কোড ‘NO’ (নরওয়ে) False হয়ে যায়; অষ্টাল-ধাঁচের 010 সংখ্যা ৮।",
            r'''
import yaml
CONFIG = """
# আঞ্চলিক জলবায়ু-মডেল (নমুনা) – বঙ্গোপসাগর অঞ্চল
base: &base
  domain: {lat: [20.5, 26.7], lon: [88.0, 92.7]}
  resolution_km: 12
  physics: {microphysics: WSM6, cumulus: KF}
  output_hours: 3
runs:
  - name: monsoon_2024
    <<: *base
    start: 2024-06-01
    days: 92
  - name: hires_test
    <<: *base
    resolution_km: 4          # শুধু এটা বদলালাম
    start: 2024-07-01
    days: 5
  - name: cyclone_remal
    <<: *base
    physics: {microphysics: Thompson, cumulus: none}
    start: 2024-05-24
    days: 5
partners: {countries: [BD, IN, NO], open_data: yes}
"""
cfg = yaml.safe_load(CONFIG)
for r in cfg["runs"]:
    print(f"{r['name']:14s} রেজোলিউশন {r['resolution_km']:2d} km · {r['physics']['microphysics']:8s} · শুরু {r['start']} ({type(r['start']).__name__}) · {r['days']} দিন · আউটপুট {r['output_hours']} ঘণ্টা পরপর")
print("লক্ষ করো: মার্জ-চাবি অগভীর – cyclone_remal-এর physics পুরোটাই বদলেছে, একটা-একটা চাবি মেশেনি")
print("\nনরওয়ে সমস্যা: countries =", cfg["partners"]["countries"], "· open_data =", cfg["partners"]["open_data"], "→ 'NO' উদ্ধৃতি-চিহ্নে লেখো: \"NO\"")
print("অষ্টাল:", yaml.safe_load("code: 010"), "· স্ট্রিং চাইলে:", yaml.safe_load('code: "010"'))
DANGER = "!!python/object/apply:os.system ['echo হ্যাক হয়ে গেলে এই লাইন চলত']"
try: yaml.safe_load(DANGER)
except yaml.constructor.ConstructorError as e: print("\nsafe_load থামাল:", str(e).splitlines()[0])
print("(yaml.load(..., Loader=yaml.UnsafeLoader) এটা চালিয়ে দিত – অবিশ্বস্ত ফাইলে কখনো নয়)")
class NoAlias(yaml.SafeDumper):                       # একই অবজেক্ট বারবার এলেও &id001/*id001 না লিখে পুরোটা লেখো
    def ignore_aliases(self, data): return True
with open("model_runs.yaml", "w", encoding="utf-8") as f:
    yaml.dump({"runs": cfg["runs"]}, f, Dumper=NoAlias, allow_unicode=True, sort_keys=False, default_flow_style=False)
print("\nডিফল্ট safe_dump হলে শেয়ার-করা অংশে অ্যালিয়াস বসত:", "&id001" in yaml.safe_dump({"runs": cfg["runs"]}))
print("\nmodel_runs.yaml (অ্যাঙ্কর গলে গিয়ে পূর্ণ রূপ):\n" + open("model_runs.yaml", encoding="utf-8").read()[:400] + "…")
print("libyaml (C, দ্রুত) আছে?", yaml.__with_libyaml__)
'''),
        pex("প্রজেক্ট: নিরাপদ সেটিংস-লোডার – নিজের ধরন (dataclass) YAML-এ লেখা-পড়া, এক ফাইলে অনেক ডকুমেন্ট (---), ভুলের লাইন-নম্বর আর C-লোডারের গতি",
            "SafeDumper/SafeLoader-এ নিজের ‘!station’ ট্যাগ যোগ করে একটা dataclass লেখা-পড়া (অবিশ্বস্ত কোড চালানোর ঝুঁকি ছাড়াই)। একটা ফাইলে তিনটা স্টেশনের ডকুমেন্ট – safe_load_all। "
            "ইন্ডেন্টেশনের ভুল থাকলে MarkedYAMLError কোন লাইন-কলামে তা জানায়। শেষে বড় ফাইলে বিশুদ্ধ-পাইথন SafeLoader বনাম libyaml-এর CSafeLoader-এর সময়।",
            r'''
import yaml, dataclasses, time
@dataclasses.dataclass
class Station:
    name: str; lat: float; lon: float; sensors: list
def st_rep(d, s): return d.represent_mapping("!station", dataclasses.asdict(s))
def st_con(l, node): return Station(**l.construct_mapping(node, deep=True))
yaml.add_representer(Station, st_rep, Dumper=yaml.SafeDumper)
yaml.add_constructor("!station", st_con, Loader=yaml.SafeLoader)
try: yaml.add_constructor("!station", st_con, Loader=yaml.CSafeLoader)
except AttributeError: pass
stations = [Station("ঢাকা", 23.78, 90.38, ["rain", "temp"]), Station("সিলেট", 24.90, 91.88, ["rain"]), Station("কক্সবাজার", 21.43, 92.00, ["rain", "wind", "pressure"])]
text = yaml.safe_dump_all(stations, allow_unicode=True, sort_keys=False, explicit_start=True)
open("stations.yaml", "w", encoding="utf-8").write(text)
print(text)
back = list(yaml.safe_load_all(open("stations.yaml", encoding="utf-8")))
print("ফেরত: ধরন", type(back[0]).__name__, "· হুবহু এক?", back == stations, "· সেন্সর সবচেয়ে বেশি:", max(back, key=lambda s: len(s.sensors)).name)
BROKEN = """station: ঢাকা
sensors:
  - rain
   - temp
interval: 60
"""
try: yaml.safe_load(BROKEN)
except yaml.MarkedYAMLError as e:
    m = e.problem_mark; print(f"\nভুল ধরা পড়ল: লাইন {m.line + 1}, কলাম {m.column + 1} – {e.problem}")
    print("   ", BROKEN.splitlines()[m.line], "\n    " + " " * m.column + "^")
big = yaml.safe_dump({"readings": [{"station": f"BD-{i % 300:03d}", "t": i // 300, "rain_mm": round(i % 97 * 0.7, 1)} for i in range(20000)]})
for name, L in (("SafeLoader (বিশুদ্ধ পাইথন)", yaml.SafeLoader), ("CSafeLoader (libyaml, C)", getattr(yaml, "CSafeLoader", None))):
    if L is None: print(name, "– নেই"); continue
    t0 = time.perf_counter(); d = yaml.load(big, Loader=L); dt = time.perf_counter() - t0
    print(f"{name:28s}: {len(big) / 1e6:.2f} MB পড়তে {dt * 1000:.0f} ms · {len(d['readings'])} রিডিং")
''', hint="প্রজেক্ট"),
    ],
    level="শুরু", tag="পাইথনের প্রচলিত YAML পার্সার – safe_load, অ্যাঙ্কর, মাল্টি-ডকুমেন্ট।",
    tasks=["অ্যাপ/মডেলের কনফিগ ফাইল", "CI/CD, Docker Compose, Kubernetes-এর YAML পড়া", "পরীক্ষার ডেটা (fixtures)", "মানুষের সম্পাদনাযোগ্য ডেটা-ক্যাটালগ"],
    caps=["safe_load/safe_dump, *_all (মাল্টি-ডকুমেন্ট)", "অ্যাঙ্কর/অ্যালিয়াস, মার্জ-চাবি", "নিজের ট্যাগ (representer/constructor)", "libyaml-এর C-লোডার (দ্রুত)", "MarkedYAMLError-এ লাইন-কলাম"],
    limits=["YAML ১.১: yes/no/NO বুলিয়ান, 010 অষ্টাল", "লিখলে মন্তব্য আর বিন্যাস হারায় (ruamel.yaml রাখে)", "yaml.load অবিশ্বস্ত ফাইলে বিপজ্জনক"],
    alt="ruamel.yaml (রাউন্ড-ট্রিপ, YAML ১.২), strictyaml, tomllib (TOML), pydantic-settings",
)

