import os, time, fastparquet as fp
df = sensor_table()
print(f"টেবিল {len(df):,} সারি × {df.shape[1]} কলাম · মেমরিতে {df.memory_usage(deep=True).sum() / 1e6:.1f} MB · dtypes: {dict(df.dtypes.astype(str))}")
res = []
t0 = time.perf_counter(); df.to_csv("sensors.csv", index=False); tw = time.perf_counter() - t0
t0 = time.perf_counter(); back = pd.read_csv("sensors.csv"); tr = time.perf_counter() - t0
res.append(("CSV", os.path.getsize("sensors.csv"), tw, tr, None)); print(f"CSV            : {os.path.getsize('sensors.csv') / 1e6:6.1f} MB · লেখা {tw:.2f} s · পড়া {tr:.2f} s · time-কলাম ফেরে {back.time.dtype}")
for comp in ("SNAPPY", "GZIP", "ZSTD"):
    fn = f"sensors_{comp.lower()}.parquet"
    t0 = time.perf_counter(); fp.write(fn, df, compression=comp, row_group_offsets=50_000); tw = time.perf_counter() - t0
    t0 = time.perf_counter(); b = fp.ParquetFile(fn).to_pandas(); tr = time.perf_counter() - t0
    t0 = time.perf_counter(); fp.ParquetFile(fn).to_pandas(columns=["station", "rain_mm"]); tc = time.perf_counter() - t0
    same = dict(b.dtypes) == dict(df.dtypes) and b.reset_index(drop=True).equals(df)
    res.append((f"Parquet {comp.lower()}", os.path.getsize(fn), tw, tr, tc))
    print(f"Parquet {comp.lower():6s} : {os.path.getsize(fn) / 1e6:6.1f} MB · লেখা {tw:.2f} s · পড়া {tr:.2f} s (২ কলাম {tc:.2f} s) · ধরন+মান হুবহু? {same}")
csv_size = res[0][1]; best = min(res[1:], key=lambda r: r[1])
print(f"সবচেয়ে ছোট: {best[0]} – CSV-এর {best[1] / csv_size:.0%} আকার")
pf = fp.ParquetFile("sensors_zstd.parquet")
print(f"row-group {len(pf.row_groups)}টা · প্রথমটার temp_c সীমা (ফাইলের পরিসংখ্যান থেকে):", pf.statistics["min"]["temp_c"][0], "–", pf.statistics["max"]["temp_c"][0])

fig, ax = plt.subplots(figsize=(10, 3.8))
names = [r[0] for r in res]; sizes = [r[1] / 1e6 for r in res]
ax.barh(names, sizes, color=["#e11d48"] + ["#7c3aed"] * 3); ax.invert_yaxis()
for i, r in enumerate(res): ax.text(sizes[i] + .3, i, f"{sizes[i]:.1f} MB · পড়া {r[3]:.2f} s", va="center", fontsize=9.5)
ax.set_xlim(0, max(sizes) * 1.4); ax.set_xlabel("ফাইলের আকার (MB)"); ax.grid(axis="y", visible=False)
ax.set_title(f"একই ৩.৫ লাখ সারি: Parquet ({best[0].split()[1]}) CSV-এর মাত্র {best[1] / csv_size:.0%}", loc="left", weight="bold", pad=26)
ax.text(0, 1.03, "fastparquet · ৪০ স্টেশন × ৮৬৪০ ঘণ্টা (নমুনা) · Parquet ধরন রাখে, CSV রাখে না", transform=ax.transAxes, fontsize=9.5, color="#6b6680")
fig.savefig("parquet_sizes.png", dpi=150, bbox_inches="tight")
for f in os.listdir():
    if f.startswith("sensors"): os.remove(f)
''', hint=SHOW),
        ex("প্রজেক্ট: মাস-অনুযায়ী ভাগ করা (partitioned) আর্কাইভ – partition_on, filters-এ অদরকারি ফোল্ডার না পড়া, নতুন মাস append, আর একই ফাইল pyarrow দিয়ে পড়ে মেলানো",
           "partition_on=['month'] দিলে আর্কাইভ হয় month=1/, month=2/… ফোল্ডার – বর্ষার (জুন–সেপ্টেম্বর) বিশ্লেষণে শুধু ৪টা ফোল্ডার পড়া হয় (filters)। প্রথমে ১১ মাস লেখা, তারপর ডিসেম্বর "
           "append=True দিয়ে যোগ; _metadata ফাইল হালনাগাদ। filters দিয়ে কতগুলো row-group পড়া হলো, পুরোটা পড়ে pandas-এ ছাঁকলে যা আসে তার সাথে মিল, আর pyarrow.parquet দিয়ে একই ডেটাসেট পড়ে হুবহু তুলনা।",
           SENSOR_DF + r'''
import os, shutil, time, fastparquet as fp
df = sensor_table()
shutil.rmtree("archive", ignore_errors=True)
first, dec = df[df.month < 12], df[df.month == 12]
fp.write("archive", first, partition_on=["month"], file_scheme="hive", compression="ZSTD")
fp.write("archive", dec, partition_on=["month"], file_scheme="hive", compression="ZSTD", append=True)
dirs = sorted(d for d in os.listdir("archive") if d.startswith("month="))
print(f"ফোল্ডার {len(dirs)}টা: {dirs[:3]} … {dirs[-1]} · _metadata আছে? {os.path.exists('archive/_metadata')}")
pf = fp.ParquetFile("archive")
print(f"মোট row-group {len(pf.row_groups)} · সারি {pf.count():,} (মূল টেবিল {len(df):,})")
t0 = time.perf_counter(); full = pf.to_pandas(); t_full = time.perf_counter() - t0
from fastparquet.api import filter_row_groups
wet_rg = filter_row_groups(pf, [("month", "in", [6, 7, 8, 9])])
t0 = time.perf_counter(); wet = pf.to_pandas(filters=[("month", "in", [6, 7, 8, 9])]); t_wet = time.perf_counter() - t0
print(f"বর্ষা-ফিল্টার: পড়া row-group {len(wet_rg)}/{len(pf.row_groups)} · সারি {len(wet):,} · সময় {t_wet:.2f} s (পুরোটা {t_full:.2f} s)")
manual = full[full.month.isin([6, 7, 8, 9])]
print("filters-এর ফল আর পুরোটা পড়ে ছাঁকার ফল এক?", len(manual) == len(wet) and np.isclose(manual.rain_mm.sum(), wet.rain_mm.sum()))
s = wet.groupby("month", observed=True).rain_mm.agg(["sum", "mean"])
print("বর্ষার মাসিক মোট বৃষ্টি (সব স্টেশন, নমুনা):", {int(k): round(float(v), 0) for k, v in s["sum"].items()})
import pyarrow.parquet as pq
tb = pq.read_table("archive").to_pandas()
cols = ["time", "station", "temp_c", "rh", "rain_mm"]
a = full.sort_values(["time", "station"])[cols].reset_index(drop=True); b = tb.sort_values(["time", "station"])[cols].reset_index(drop=True)
print(f"pyarrow দিয়ে পড়া: {len(tb):,} সারি · মান হুবহু এক? {a.equals(b)} · month কলামের ধরন pyarrow-এ {tb.month.dtype} (পার্টিশন-চাবি = ক্যাটেগরি)")
size = sum(os.path.getsize(os.path.join(r, f)) for r, _, fs in os.walk("archive") for f in fs)
print(f"আর্কাইভের মোট আকার {size / 1e6:.1f} MB")
shutil.rmtree("archive")
