# ------------------------------------------------------------------ zarr
CUBE_PY = r'''
import numpy as np
def temp_cube(days=365, ny=120, nx=100, seed=3):
    """নমুনা তাপমাত্রা-কিউব (দিন × অক্ষাংশ × দ্রাঘিমা): মৌসুমি চক্র + উত্তর-দক্ষিণ ঢাল + আবহাওয়ার নয়েজ"""
    rng = np.random.default_rng(seed)
    d = np.arange(days)[:, None, None]; y = np.linspace(26.6, 20.6, ny)[None, :, None]; x = np.linspace(88.0, 92.7, nx)[None, None, :]
    T = 26 + 4.5 * np.sin((d - 100) / 365 * 2 * np.pi) - 0.6 * (y - 23.6) * np.cos((d - 15) / 365 * 2 * np.pi) + 0.1 * (x - 90)
    return (T + rng.normal(0, 0.7, (days, ny, nx))).astype("float32")
'''

pylib("zarr",
    about=("Zarr হলো chunk-ভিত্তিক বহুমাত্রিক অ্যারে-ফরম্যাট আর তার পাইথন লাইব্রেরি – ‘ক্লাউড-বান্ধব HDF5’: প্রতিটা chunk আলাদা ফাইল/অবজেক্ট, তাই S3/GCS থেকে শুধু দরকারি টুকরো "
           "সমান্তরালে পড়া যায়, অনেক প্রসেস একসাথে আলাদা chunk লিখতে পারে। Zarr ৩: গ্রুপ, অ্যাট্রিবিউট, কোডেক-পাইপলাইন (zstd, blosc, gzip), sharding (অনেক chunk এক ফাইলে), "
           "একত্রিত মেটাডেটা। xarray (to_zarr/open_zarr) আর Dask-এর সাথে জলবায়ু-ডেটায় সবচেয়ে জনপ্রিয় – CMIP6, ERA5-এর ক্লাউড-কপি Zarr-এ।"),
    install="pip install zarr          # ক্লাউড: pip install zarr fsspec s3fs",
    examples=[
        ex("মৌসুমি তাপমাত্রার ডেটা-কিউব: Zarr ৩-এ লেখা, ডিস্কে chunk-ফাইলের গঠন, অ্যাট্রিবিউট, আর এক দিনের মানচিত্র ও এক জায়গার সময়-সারি পড়া",
           "৩৬৫ দিন × ১২০ × ১০০ গ্রিডের নমুনা তাপমাত্রা (বাংলাদেশের বাক্স)। chunks=(৩০, ৬০, ৫০) – প্রতি ৩০ দিন আর ৪ ভাগে ভাগ; zstd সংকোচন। ডিস্কে zarr.json (মেটাডেটা) আর c/… chunk-ফাইল গুনে দেখা, "
           "অ্যাট্রিবিউটে একক ও স্থানাঙ্ক। তারপর NumPy-র মতো স্লাইস: ১৫ জুনের মানচিত্র আর ঢাকার গ্রিড-বিন্দুর সারা বছর – প্রতিটায় কয়টা chunk-ফাইল পড়তে হলো।",
           CUBE_PY + PLT_BN + r'''
import zarr, os, shutil
from zarr.codecs import ZstdCodec
T = temp_cube()
shutil.rmtree("bd_temp.zarr", ignore_errors=True)
root = zarr.open_group("bd_temp.zarr", mode="w")
root.attrs.update({"title": "বাংলাদেশ দৈনিক গড় তাপমাত্রা (নমুনা)", "units": "degC", "lat": [26.6, 20.6], "lon": [88.0, 92.7], "start": "2024-01-01"})
arr = root.create_array("t2m", shape=T.shape, chunks=(30, 60, 50), dtype="float32", compressors=ZstdCodec(level=3))
arr[:] = T
files = [os.path.join(r, f) for r, _, fs in os.walk("bd_temp.zarr") for f in fs]
chunk_files = [f for f in files if f"{os.sep}c{os.sep}" in f]
size = sum(os.path.getsize(f) for f in files)
print(f"অ্যারে {arr.shape} {arr.dtype} · chunk {arr.chunks} · chunk-ফাইল {len(chunk_files)} (= {-(-365 // 30)}×2×2) · মেটাডেটা: {[os.path.relpath(f, 'bd_temp.zarr') for f in files if f.endswith('zarr.json')]}")
print(f"ডিস্কে {size / 1e6:.2f} MB · কাঁচা {T.nbytes / 1e6:.2f} MB → সংকোচন {T.nbytes / size:.2f}× · উদাহরণ chunk-পথ: {os.path.relpath(sorted(chunk_files)[0], 'bd_temp.zarr')}")
z = zarr.open_group("bd_temp.zarr", mode="r")
print("অ্যাট্রিবিউট:", dict(z.attrs)["title"], "·", dict(z.attrs)["units"])
d = 166                                                            # ১৫ জুন (০-ভিত্তিক দিন)
day_map = z["t2m"][d]; chunks_map = 1 * 2 * 2
iy, ix = int((26.6 - 23.81) / 6.0 * 119), int((90.41 - 88.0) / 4.7 * 99)        # ঢাকার নিকটতম গ্রিড-বিন্দু
series = z["t2m"][:, iy, ix]; chunks_ts = -(-365 // 30)
print(f"১৫ জুনের মানচিত্র {day_map.shape}: গড় {day_map.mean():.2f} °C · পড়া chunk {chunks_map}")
print(f"ঢাকার সময়-সারি {series.shape}: উষ্ণতম দিন {int(series.argmax()) + 1} (নমুনার সূত্রে গড় চক্রের শিখর ১৯১তম দিন – নয়েজে সরে যায়), শীতলতম {int(series.argmin()) + 1} · পড়া chunk {chunks_ts}")
print("মূলের সাথে হুবহু মিল?", np.array_equal(series, T[:, iy, ix]) and np.array_equal(day_map, T[d]))
fig, (ax, bx) = plt.subplots(1, 2, figsize=(12, 4.4), gridspec_kw={"width_ratios": [1, 1.5]})
im = ax.imshow(day_map, extent=[88, 92.7, 20.6, 26.6], cmap="RdYlBu_r"); ax.scatter([90.41], [23.81], color="#140e29", s=30); ax.text(90.5, 23.9, "ঢাকা", fontsize=9)
cb = fig.colorbar(im, ax=ax, shrink=.85); cb.set_label("°C"); ax.grid(False)
ax.set_title("১৫ জুনের মানচিত্র", loc="left", weight="bold", pad=26); ax.text(0, 1.03, f"পড়া chunk {chunks_map}টা", transform=ax.transAxes, fontsize=9.5, color="#6b6680")
bx.plot(np.arange(1, 366), series, color="#c4b5fd", lw=1); bx.plot(np.arange(1, 366), np.convolve(series, np.ones(15) / 15, "same"), color="#7c3aed", lw=2)
bx.set_xlim(8, 358); bx.set_xlabel("বছরের দিন"); bx.set_ylabel("°C")
bx.set_title("ঢাকার গ্রিড-বিন্দু, সারা বছর", loc="left", weight="bold", pad=26); bx.text(0, 1.03, f"পড়া chunk {chunks_ts}টা · গাঢ় রেখা = ১৫ দিনের চলমান গড়", transform=bx.transAxes, fontsize=9.5, color="#6b6680")
fig.tight_layout(); fig.savefig("zarr_cube.png", dpi=150, bbox_inches="tight")
''', hint=SHOW),
        ex("প্রজেক্ট: chunk-আকারের আপস – ‘মানচিত্র-বান্ধব’ বনাম ‘সময়-সারি-বান্ধব’ chunk, দুই রকম পড়ায় কত chunk আর কত সময়; কোডেক তুলনা আর sharding",
           "একই কিউব তিনভাবে: (১, ১২০, ১০০) – প্রতিদিন এক chunk (মানচিত্র পড়তে দারুণ); (৩৬৫, ১০, ১০) – প্রতিটা ছোট বাক্সের পুরো বছর (সময়-সারিতে দারুণ); (৩০, ৬০, ৫০) – মাঝামাঝি। "
           "প্রতিটায় ১০টা এলোমেলো মানচিত্র আর ১০টা এলোমেলো সময়-সারি পড়ার সময়, আর তত্ত্বে কত chunk ছুঁতে হয়। সাথে zstd বনাম gzip বনাম blosc-এর আকার, আর sharding (অনেক chunk এক ফাইলে) "
           "দিয়ে ফাইলের সংখ্যা কমানো – ক্লাউডে যা খুব জরুরি।",
           CUBE_PY + PLT_BN + r'''
import zarr, os, shutil, time
from zarr.codecs import ZstdCodec, GzipCodec, BloscCodec
T = temp_cube(); D, NY, NX = T.shape
layouts = {"মানচিত্র-বান্ধব (1,120,100)": (1, 120, 100), "মাঝামাঝি (30,60,50)": (30, 60, 50), "সময়-সারি-বান্ধব (365,10,10)": (365, 10, 10)}
rng = np.random.default_rng(0); days = rng.integers(0, D, 10); pts = rng.integers(0, [NY, NX], (10, 2))
rows = []
for name, ch in layouts.items():
    p = "lay.zarr"; shutil.rmtree(p, ignore_errors=True)
    a = zarr.create_array(p, shape=T.shape, chunks=ch, dtype="float32", compressors=ZstdCodec(level=3)); a[:] = T
    a = zarr.open_array(p, mode="r")
    t0 = time.perf_counter(); [a[d] for d in days]; t_map = (time.perf_counter() - t0) / 10
    t0 = time.perf_counter(); [a[:, y, x] for y, x in pts]; t_ts = (time.perf_counter() - t0) / 10
    n_map = (-(-NY // ch[1])) * (-(-NX // ch[2])); n_ts = -(-D // ch[0])
    nfiles = sum(len(fs) for _, _, fs in os.walk(p)); rows.append((name, t_map * 1000, t_ts * 1000, n_map, n_ts, nfiles))
    print(f"{name:30s}: মানচিত্র {t_map * 1000:6.1f} ms ({n_map:3d} chunk) · সময়-সারি {t_ts * 1000:6.1f} ms ({n_ts:3d} chunk) · ফাইল {nfiles}")
print()
for cname, codec in (("zstd-3", ZstdCodec(level=3)), ("gzip-5", GzipCodec(level=5)), ("blosc-lz4 + shuffle", BloscCodec(cname="lz4", clevel=5, shuffle="shuffle"))):
    p = "codec.zarr"; shutil.rmtree(p, ignore_errors=True)
    t0 = time.perf_counter(); a = zarr.create_array(p, shape=T.shape, chunks=(30, 60, 50), dtype="float32", compressors=codec); a[:] = T; tw = time.perf_counter() - t0
    size = sum(os.path.getsize(os.path.join(r, f)) for r, _, fs in os.walk(p) for f in fs)
    print(f"কোডেক {cname:20s}: {size / 1e6:5.2f} MB ({T.nbytes / size:.2f}×) · লেখা {tw * 1000:.0f} ms")
p = "shard.zarr"; shutil.rmtree(p, ignore_errors=True)
a = zarr.create_array(p, shape=T.shape, chunks=(30, 60, 50), shards=(390, 120, 100), dtype="float32", compressors=ZstdCodec(level=3)); a[:] = T
nf = sum(len(fs) for _, _, fs in os.walk(p))
print(f"\nsharding (১৩×২×২ = ৫২টা chunk এক shard-এ): ফাইল {nf}টা, আগে ছিল {rows[1][5]} · মান হুবহু? {np.array_equal(zarr.open_array(p, mode='r')[:], T)}")
for q in ("lay.zarr", "codec.zarr", "shard.zarr"): shutil.rmtree(q)
fig, ax = plt.subplots(figsize=(10, 4.2))
y = np.arange(len(rows))
ax.barh(y - .18, [r[1] for r in rows], .34, color="#0d9488"); ax.barh(y + .18, [r[2] for r in rows], .34, color="#f59e0b")
for i, r in enumerate(rows):
    ax.text(r[1] + .3, i - .18, f"মানচিত্র {r[1]:.1f} ms ({r[3]} chunk)", va="center", fontsize=9, color="#0f766e")
    ax.text(r[2] + .3, i + .18, f"সময়-সারি {r[2]:.1f} ms ({r[4]} chunk)", va="center", fontsize=9, color="#b45309")
ax.set_yticks(y, [r[0] for r in rows]); ax.invert_yaxis(); ax.set_xlabel("এক বার পড়ার গড় সময় (ms)"); ax.grid(axis="y", visible=False)
ax.set_xlim(0, max(max(r[1], r[2]) for r in rows) * 1.6)
fast_ts = min(rows, key=lambda r: r[2]); fast_map = min(rows, key=lambda r: r[1])
ax.set_title(f"ভুল chunk-এ একই পড়া {rows[0][2] / rows[2][2]:.0f}× ({'সময়-সারি'}) বা {rows[2][1] / rows[0][1]:.0f}× (মানচিত্র) ধীর – মাঝামাঝিটা দুটোতেই চলনসই", loc="left", weight="bold", pad=26)
ax.text(0, 1.03, "zarr ৩ · ৩৬৫ × ১২০ × ১০০ float32 (নমুনা) · ১০টা এলোমেলো দিন/বিন্দু পড়ার গড়", transform=ax.transAxes, fontsize=9.5, color="#6b6680")
fig.savefig("zarr_chunks.png", dpi=150, bbox_inches="tight")
''', hint="প্রজেক্ট"),
    ],
    level="মাঝারি", tag="ক্লাউড-বান্ধব chunk-ভিত্তিক বহুমাত্রিক অ্যারে (Zarr ৩)।",
    tasks=["জলবায়ু/আবহাওয়ার ডেটা-কিউব (xarray + Zarr)", "S3/GCS-এ বড় অ্যারে রেখে টুকরো করে পড়া", "অনেক প্রসেস থেকে সমান্তরালে লেখা (Dask)", "মাইক্রোস্কোপি/ইমেজিং (OME-Zarr)"],
    caps=["গ্রুপ, অ্যারে, অ্যাট্রিবিউট (zarr.json)", "chunks, shards, কোডেক-পাইপলাইন (zstd, blosc, gzip)", "যেকোনো স্টোর: লোকাল, মেমরি, zip, fsspec (S3/GCS)", "NumPy-ধাঁচের স্লাইস, resize, append", "xarray/Dask-এর সাথে নিখুঁত মিল"],
    limits=["Zarr ২ → ৩-এ API ও ফরম্যাট বদলেছে (পুরোনো কোড ভাঙে)", "অনেক ছোট chunk = অনেক ফাইল (sharding লাগে)", "লেনদেন/লক নেই – একই chunk দুজন লিখলে গোলমাল"],
    alt="h5py/HDF5, netCDF4, TileDB, xarray",
)
