import numpy as np
from web3 import Web3, EthereumTesterProvider
art = compile_rain()
w3 = Web3(EthereumTesterProvider()); owner, rep1, rep2, stranger = w3.eth.accounts[:4]
r = w3.eth.wait_for_transaction_receipt(w3.eth.contract(abi=art["abi"], bytecode=art["bin"]).constructor().transact({"from": owner}))
c = w3.eth.contract(address=r.contractAddress, abi=art["abi"])
print(f"ডিপ্লয়: ঠিকানা {r.contractAddress[:12]}… · গ্যাস {r.gasUsed:,} · রানটাইম-কোড {len(w3.eth.get_code(r.contractAddress))} বাইট")
for who in (rep1, rep2): c.functions.addReporter(who).transact({"from": owner})
STATIONS = {1: "ঢাকা", 2: "সিলেট", 3: "চট্টগ্রাম"}
rng = np.random.default_rng(14); sent = {s: 0 for s in STATIONS}; gas = {rep1: 0, rep2: 0}
for day in range(1, 11):
    for s in STATIONS:
        v = int(rng.gamma(1.4, {1: 120, 2: 260, 3: 170}[s]))              # ০.১ mm একক (নমুনা)
        who = rep1 if s != 2 else rep2
        rr = w3.eth.wait_for_transaction_receipt(c.functions.report(s, day, v).transact({"from": who}))
        sent[s] += v; gas[who] += rr.gasUsed
for label, fn in (("অনুমতিহীন ঠিকানা", lambda: c.functions.report(1, 11, 50).transact({"from": stranger})),
                  ("অসম্ভব মান ১৬০০ mm", lambda: c.functions.report(1, 11, 16000).transact({"from": rep1}))):
    try: fn(); print(label, "→ গৃহীত?!")
    except Exception as e: print(f"{label:18s} → ফিরিয়ে দিল: {str(e).split('reverted: ')[-1][:40]}")
head = w3.eth.block_number
print(f"\nএক্সপ্লোরার: ব্লক ০–{head} স্ক্যান")
allev = c.events.Reading.get_logs(from_block=0, to_block=head)
syl = c.events.Reading.get_logs(from_block=0, to_block=head, argument_filters={"station": 2})
print(f"মোট Reading ইভেন্ট {len(allev)} · শুধু সিলেট (indexed টপিক-ফিল্টার) {len(syl)}")
e0 = syl[0]; print(f"উদাহরণ ইভেন্ট: ব্লক {e0.blockNumber}, লেনদেন {e0.transactionHash.hex()[:14]}…, args = {dict(e0.args)}")
from eth_utils import keccak
raw_log = next(l for l in w3.eth.get_logs({"address": c.address, "fromBlock": 0, "toBlock": head}) if l["transactionHash"] == e0.transactionHash)
sig_hash = keccak(text="Reading(uint16,uint32,uint32,address)")
print(f"কাঁচা লগ: টপিক[০] {raw_log['topics'][0].hex()[:16]}… = keccak(‘Reading(uint16,uint32,uint32,address)’)? {raw_log['topics'][0] == sig_hash} · "
      f"টপিক[১] station = {int.from_bytes(raw_log['topics'][1], 'big')}, টপিক[২] day = {int.from_bytes(raw_log['topics'][2], 'big')} (indexed), বাকিটা data-তে {len(raw_log['data'])} বাইট")
ok = True
for s, name in STATIONS.items():
    ev_sum = sum(e.args.tenthsMm for e in allev if e.args.station == s); onchain = c.functions.total(s).call()
    ok &= ev_sum == onchain == sent[s]
    print(f"  {name:9s}: ইভেন্টের যোগফল {ev_sum / 10:7.1f} mm · total() {onchain / 10:7.1f} mm · পাঠানো {sent[s] / 10:7.1f} mm")
print("তিনটা হিসাব হুবহু এক?", ok, "· রিপোর্টারপ্রতি গ্যাস:", {k[:8] + "…": v for k, v in gas.items()})
days = np.arange(1, 11); fig, ax = plt.subplots(figsize=(10, 4.2)); cols = {1: "#7c3aed", 2: "#0d9488", 3: "#f59e0b"}
for s, name in STATIONS.items():
    v = [next(e.args.tenthsMm for e in allev if e.args.station == s and e.args.day == d) / 10 for d in days]
    ax.plot(days, np.cumsum(v), "o-", color=cols[s], lw=2); ax.text(10.2, np.cumsum(v)[-1], f"{name} {np.sum(v):.0f} mm", color=cols[s], va="center")
ax.set_xlim(.6, 11.8); ax.set_xlabel("দিন"); ax.set_ylabel("ক্রমযোজিত বৃষ্টি (mm)")
ax.set_title(f"চেইনের {len(allev)}টা ইভেন্ট থেকে আবার গড়া হিসাব = কন্ট্র্যাক্টের total() (নমুনা ডেটা)", loc="left", weight="bold", pad=26)
ax.text(0, 1.03, "web3.py + eth-tester · RainLog.sol (solc 0.8.28) · get_logs দিয়ে পড়া", transform=ax.transAxes, fontsize=9.5, color="#6b6680")
fig.savefig("rainlog_events.png", dpi=150, bbox_inches="tight")
