_P_CV0 = r'''import cv2
import numpy as np
import matplotlib.pyplot as plt
from skimage import data            # নমুনা ছবি; নিজের ছবি হলে: img = cv2.imread("photo.jpg")

plt.rcParams.update({"font.family": ["Noto Sans Bengali", "DejaVu Sans"]})

img = cv2.cvtColor(data.coffee(), cv2.COLOR_RGB2BGR)   # OpenCV রাখে BGR ক্রমে!
print("মাপ (উচ্চতা, প্রস্থ, চ্যানেল):", img.shape, img.dtype)

gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)           # Y = 0.299R + 0.587G + 0.114B
blur = cv2.GaussianBlur(img, (0, 0), sigmaX=4)         # σ = ৪ px ঝাপসা
small = cv2.resize(img, None, fx=0.5, fy=0.5, interpolation=cv2.INTER_AREA)
edges = cv2.Canny(cv2.GaussianBlur(gray, (5, 5), 0), 60, 150)

# যাচাই: OpenCV-র gray আর হাতের সূত্র কি মেলে?
b, g, r = [img[..., i].astype(float) for i in range(3)]
mine = 0.299 * r + 0.587 * g + 0.114 * b
print(f"gray: OpenCV বনাম সূত্র – সর্বোচ্চ পার্থক্য {np.abs(gray - mine).max():.2f} (শুধু রাউন্ডিং)")
sharp0 = cv2.Laplacian(gray, cv2.CV_64F).var()                     # তীক্ষ্ণতার মাপ
sharp1 = cv2.Laplacian(cv2.cvtColor(blur, cv2.COLOR_BGR2GRAY), cv2.CV_64F).var()
print(f"ঝাপসা করার পর তীক্ষ্ণতা (Laplacian variance): {sharp0:.0f} → {sharp1:.0f}")
print(f"অর্ধেক মাপ: {small.shape[:2]} · কিনারা-পিক্সেল {100 * (edges > 0).mean():.1f} %")

for name, im in [("gray.jpg", gray), ("blur.jpg", blur), ("small.jpg", small), ("edges.png", edges)]:
    cv2.imwrite(name, im)

# চার ধাপ এক ছবিতে (matplotlib চায় RGB, তাই BGR → RGB)
fig, axs = plt.subplots(1, 4, figsize=(14, 3.4), facecolor="white")
panels = [(cv2.cvtColor(img, cv2.COLOR_BGR2RGB), "আসল (BGR → RGB)", None),
          (gray, "সাদা-কালো", "gray"),
          (cv2.cvtColor(blur, cv2.COLOR_BGR2RGB), "Gaussian ঝাপসা, σ = 4", None),
          (edges, "Canny কিনারা", "gray_r")]
for ax, (im, title, cmap) in zip(axs, panels):
    ax.imshow(im, cmap=cmap); ax.set_axis_off()
    ax.set_title(title, loc="left", fontsize=11, weight="bold", color="#1f1a33")
fig.suptitle("একটা ছবি, চার রকম OpenCV কাজ – প্রতিটা এক লাইনের কোড", x=0.01, ha="left", fontsize=14, weight="bold")
fig.text(0.01, 0.86, f"Laplacian-ভ্যারিয়েন্স (তীক্ষ্ণতা) {sharp0:.0f} → ঝাপসায় {sharp1:.1f} · "
         f"Canny-তে {100 * (edges > 0).mean():.1f} % পিক্সেল কিনারা", fontsize=10, color="#6b6680")
fig.tight_layout(rect=(0, 0, 1, 0.9))
fig.savefig("1_opencv_basics.png", dpi=150)
plt.close(fig)
print("৪টা ছবি + 1_opencv_basics.png সেভ হয়েছে ✔")
'''

_P_CV1 = r'''import cv2
import numpy as np
import matplotlib.pyplot as plt
from skimage import data            # শুধু নমুনা ছবির জন্য (অফলাইনে আসে)

plt.rcParams.update({"font.family": ["Noto Sans Bengali", "DejaVu Sans"]})

# ২৪টা প্রাচীন মুদ্রার সাদা-কালো ছবি (scikit-image-এর নমুনা) – আসল প্রজেক্টে cv2.imread("photo.jpg")
gray = data.coins()
img = cv2.cvtColor(gray, cv2.COLOR_GRAY2BGR)

# ১) noise কমানো, তারপর Canny – থ্রেশহোল্ড ছবির median থেকে স্বয়ংক্রিয় (±৩৩ % নিয়ম)
blur = cv2.GaussianBlur(gray, (5, 5), 1.4)
med = float(np.median(blur))
lo, hi = int(max(0, 0.67 * med)), int(min(255, 1.33 * med))
edges = cv2.Canny(blur, lo, hi)
print(f"Canny থ্রেশহোল্ড (median {med:.0f} থেকে): নিচু {lo}, উঁচু {hi}")

# ২) সরল পথ: closing দিয়ে কিনারা জোড়া → বাইরের contour গোনা
kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (5, 5))
closed = cv2.morphologyEx(edges, cv2.MORPH_CLOSE, kernel, iterations=2)
contours, _ = cv2.findContours(closed, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
n_contour = sum(cv2.contourArea(c) >= 300 for c in contours)
print(f"Canny + contour: {n_contour}টা বস্তু (পাশাপাশি মুদ্রা জুড়ে যায়, ঝাপসা কিনারা হারায়)")

# ৩) ভালো পথ: Hough বৃত্ত-রূপান্তর – প্রতিটা কিনারা-বিন্দু সম্ভাব্য কেন্দ্রে "ভোট" দেয়
med5 = cv2.medianBlur(gray, 5)
found = cv2.HoughCircles(med5, cv2.HOUGH_GRADIENT_ALT, dp=1.5, minDist=30,
                         param1=150, param2=0.8, minRadius=15, maxRadius=45)[0]
found = sorted(found.tolist(), key=lambda c: (round(c[1] / 70), c[0]))     # সারি ধরে নম্বর
r = np.array([c[2] for c in found])
print(f"HoughCircles (ALT): {len(found)}টা মুদ্রা · ব্যাসার্ধ {r.min():.1f}–{r.max():.1f} px, গড় {r.mean():.1f}")

# ৪) থ্রেশহোল্ড বদলালে গণনা কতটা বদলায়? (স্থিতিশীলতা যাচাই)
p2s = np.arange(15, 46, 2.5)
classic = []
for p2 in p2s:
    c = cv2.HoughCircles(med5, cv2.HOUGH_GRADIENT, dp=1.2, minDist=35, param1=100,
                         param2=float(p2), minRadius=15, maxRadius=45)
    classic.append(0 if c is None else c.shape[1])
alt = []
for q in (0.6, 0.7, 0.8, 0.9):
    c = cv2.HoughCircles(med5, cv2.HOUGH_GRADIENT_ALT, dp=1.5, minDist=30, param1=150,
                         param2=q, minRadius=15, maxRadius=45)
    alt.append(0 if c is None else c.shape[1])
c27 = cv2.HoughCircles(med5, cv2.HOUGH_GRADIENT, dp=1.2, minDist=35, param1=100, param2=27.5, minRadius=15, maxRadius=45)[0]
gap = np.array([min(np.hypot(x - a, y - b) for a, b, _ in c27) for x, y, _ in found])
same = int(np.sum(gap < 0.5 * r))                 # কেন্দ্র অর্ধেক ব্যাসার্ধের মধ্যে = একই মুদ্রা
print(f"ক্লাসিক (param2=27.5) আর ALT একই মুদ্রা পেয়েছে: {same}/{len(found)}টা · "
      f"কেন্দ্রের দূরত্ব মধ্যমা {np.median(gap):.1f} px, সর্বোচ্চ {gap.max():.1f} px")
plateau = [float(p) for p, k in zip(p2s, classic) if k == 24]
print("ক্লাসিক Hough, param2 →", dict(zip(p2s.tolist(), classic)))
print("ALT Hough, param2 0.6/0.7/0.8/0.9 →", alt)

# ৫) শোকেস ছবি
BG, INK, MUTE, ACC, GOLD = "#0b0820", "#f3efff", "#a59fc4", "#2dd4bf", "#f59e0b"
fig = plt.figure(figsize=(13, 6.4), facecolor=BG)
ax = fig.add_axes([0.015, 0.05, 0.56, 0.78]); ax.set_axis_off()
out = img.copy()
for x, y, rr in found:
    cv2.circle(out, (round(x), round(y)), round(rr), (191, 212, 45), 2, cv2.LINE_AA)
ax.imshow(cv2.cvtColor(out, cv2.COLOR_BGR2RGB))
for i, (x, y, rr) in enumerate(found, 1):
    ax.text(x, y, str(i), color="white", fontsize=8.5, ha="center", va="center", weight="bold",
            bbox=dict(boxstyle="circle,pad=0.18", fc="#7c3aed", ec="none", alpha=.85))

ax2 = fig.add_axes([0.64, 0.50, 0.34, 0.30], facecolor=BG)
d = 2 * r
ax2.bar(np.arange(1, len(d) + 1), d, color=ACC, width=.72)
ax2.axhline(d.mean(), color=GOLD, lw=1.1, ls="--")
ax2.text(len(d) + .4, d.mean() + 1.5, f"গড় {d.mean():.0f} px", color=GOLD, fontsize=8.5, ha="right", va="bottom")
ax2.text(0, 1.06, "প্রতিটা মুদ্রার ব্যাস (পিক্সেল)", transform=ax2.transAxes, color=INK, fontsize=11, weight="bold")
ax2.set_xticks(range(1, len(d) + 1, 2)); ax2.set_xlim(.3, len(d) + .7)

ax3 = fig.add_axes([0.64, 0.09, 0.34, 0.27], facecolor=BG)
ax3.axhline(24, color=MUTE, lw=.8, ls=":")
ax3.plot(p2s, classic, color="#f472b6", lw=2, marker="o", ms=4)
ax3.text(p2s[0], 24.6, "আসল 24", color=MUTE, fontsize=8.5)
if plateau:
    ax3.axvspan(min(plateau) - 1, max(plateau) + 1, color=ACC, alpha=.15, lw=0)
ax3.text(0, 1.06, "ক্লাসিক Hough: ভোট-সীমা (param2) বনাম গণনা", transform=ax3.transAxes, color=INK, fontsize=11, weight="bold")
ax3.set_xlabel("param2 (কম = বেশি বৃত্ত মেনে নেয়)", color=MUTE, fontsize=8.5)
for a in (ax2, ax3):
    for s_ in a.spines.values(): s_.set_visible(False)
    a.tick_params(colors=MUTE, labelsize=8)

ok = "✓" if len(found) == 24 else "✗"
fig.text(0.015, 0.93, f"Hough বৃত্ত খুঁজে পেল {len(found)}টা মুদ্রা – আসল 24 {ok}; সরল contour পেয়েছিল মাত্র {n_contour}টা",
         color=INK, fontsize=15.5, weight="bold")
fig.text(0.015, 0.885, f"Canny থ্রেশহোল্ড median-নিয়মে {lo}/{hi} · ALT Hough চার রকম param2-তে গণনা {sorted(set(alt))} · "
         f"বড়-ছোট মুদ্রার ব্যাসে {r.max() / r.min():.1f} গুণ পার্থক্য", color=MUTE, fontsize=10)
fig.savefig("coins_counted.png", dpi=150, facecolor=BG)
plt.close(fig)
print("coins_counted.png সেভ হয়েছে ✔")
'''

