_P_IO0 = r'''import os
import numpy as np
import imageio.v3 as iio

# বাংলাদেশের পতাকা, সরকারি মাপে (পতাকা বিধিমালা ১৯৭২):
#   দৈর্ঘ্য : প্রস্থ = ১০ : ৬ · লাল বৃত্তের ব্যাসার্ধ = দৈর্ঘ্যের ১/৫
#   বৃত্তের কেন্দ্র: খুঁটির দিক থেকে দৈর্ঘ্যের ৯/২০ দূরে, উচ্চতার ঠিক মাঝখানে
W, H = 1000, 600
GREEN, RED = np.array([0, 106, 78]), np.array([244, 42, 65])     # প্রচলিত হেক্স মান #006A4E, #F42A41
cx, cy, R = W * 9 / 20, H / 2, W / 5

# মসৃণ কিনারার জন্য প্রতি পিক্সেলে ৪×৪টা নমুনা বিন্দু (supersampling)
S = 4
ys, xs = (np.arange(H * S) + .5) / S, (np.arange(W * S) + .5) / S
inside = ((xs[None, :] - cx) ** 2 + (ys[:, None] - cy) ** 2) <= R ** 2
cover = inside.reshape(H, S, W, S).mean(axis=(1, 3))             # প্রতি পিক্সেলে লালের ভাগ (০–১)
flag = (GREEN * (1 - cover[..., None]) + RED * cover[..., None]).round().astype(np.uint8)

iio.imwrite("1_bangladesh_flag.png", flag)
iio.imwrite("flag_q85.jpg", flag, quality=85)

# আবার পড়ে যাচাই
png = iio.imread("1_bangladesh_flag.png")
jpg = iio.imread("flag_q85.jpg")
print("PNG:", png.shape, png.dtype, f"{os.path.getsize('1_bangladesh_flag.png') / 1024:.1f} KB",
      "· আসলের সাথে সর্বোচ্চ পার্থক্য:", int(np.abs(png.astype(int) - flag).max()), "(lossless)")
mse = np.mean((jpg.astype(float) - flag) ** 2)
print(f"JPEG q85: {os.path.getsize('flag_q85.jpg') / 1024:.1f} KB · PSNR {10 * np.log10(255 ** 2 / mse):.1f} dB "
      f"· সর্বোচ্চ পিক্সেল-ভুল {int(np.abs(jpg.astype(int) - flag).max())} (বৃত্তের কিনারায়)")
print("→ সমতল রঙের ছবিতে PNG ছোটও, নিখুঁতও; JPEG ক্যামেরার তোলা ছবির (ফটো) জন্য")

# ছবি থেকেই মাপ উদ্ধার: লালের ভাগ = (pixel − সবুজ)·(লাল − সবুজ) / |লাল − সবুজ|²
d = RED - GREEN
a = np.clip(((png.astype(float) - GREEN) @ d) / (d @ d), 0, 1)
area = a.sum()
yy, xx = np.mgrid[0:H, 0:W] + .5
mx, my = (a * xx).sum() / area, (a * yy).sum() / area
print(f"মাপা কেন্দ্র x = {mx / W:.4f}·দৈর্ঘ্য (নিয়ম 0.4500), y = {my / H:.4f}·প্রস্থ (নিয়ম 0.5000)")
print(f"মাপা ব্যাসার্ধ = {np.sqrt(area / np.pi) / W:.4f}·দৈর্ঘ্য (নিয়ম 0.2000) · অনুপাত {W / H:.4f} (10:6 = 1.6667)")
'''

_P_IO1 = r'''import numpy as np
import imageio.v3 as iio

# সিমুলেটেড "ইনফ্রারেড স্যাটেলাইট" ঘূর্ণিঝড় – আসল ডেটা নয়, পদার্থবিদ্যার ঠিক দিকগুলো রাখা হয়েছে:
#   উত্তর গোলার্ধে ঘূর্ণিঝড় ঘোরে ঘড়ির কাঁটার উল্টো দিকে (Coriolis), মেঘের বাহু ভেতরের দিকে
#   উল্টো-ঘড়ি পাক খায়, মাঝে পরিষ্কার "চোখ", তার চারপাশে সবচেয়ে ঠান্ডা (উঁচু) মেঘের দেয়াল।
# আসল প্রজেক্টে: frames = [iio.imread(p) for p in sorted(Path("snapshots").glob("*.png"))]
H, W, N = 240, 240, 36
OMEGA = 2 * np.pi / 36            # প্রতি ফ্রেমে ১০° ঘোরে
yy, xx = np.mgrid[0:H, 0:W].astype(float)

# উজ্জ্বলতা (০ = উষ্ণ সমুদ্র, ১ = সবচেয়ে ঠান্ডা মেঘ) → enhanced-IR রঙ
STOPS = np.array([0, .35, .6, .78, .9, 1.0])
COLS = np.array([[12, 30, 58], [70, 84, 104], [205, 210, 220], [255, 255, 255], [80, 200, 255], [255, 70, 90]])

def colorize(b):
    return np.stack([np.interp(b, STOPS, COLS[:, c]) for c in range(3)], -1).astype(np.uint8)

def storm(t):
    cx, cy = 70 + 2.6 * t, 190 - 3.6 * t           # উত্তর-উত্তরপূর্বে সরে (বঙ্গোপসাগরের মতো পথ)
    dx, dy = xx - cx, cy - yy                       # dy উপরে ধনাত্মক → θ পর্দায় উল্টো-ঘড়ি
    r, th = np.hypot(dx, dy) + 1e-6, np.arctan2(dy, dx)
    arms = 0.5 + 0.5 * np.cos(2 * (th - OMEGA * t) + 3.2 * np.log(r / 12))   # লগারিদমিক সর্পিল বাহু
    fine = 0.5 + 0.5 * np.cos(7 * (th - OMEGA * t) + 9 * np.log(r / 12))    # সরু মেঘ-রেখা
    b = 0.80 * np.exp(-((r - 15) / 6) ** 2)                                  # চোখের দেয়াল
    b += (0.62 * arms ** 1.5 + 0.22 * fine * arms) * np.exp(-r / 95) * np.clip((r - 8) / 10, 0, 1)
    b += 0.30 * np.exp(-r / 30)                                              # কেন্দ্রের ঘন মেঘ-চাদর
    b *= 1 - np.exp(-(r / 7) ** 4)                                           # পরিষ্কার চোখ
    return np.clip(b, 0, 1), (cx, cy)

frames, centres = [], []
for t in range(N):
    b, c = storm(t)
    frames.append(colorize(b)); centres.append(c)
iio.imwrite("cyclone.gif", np.stack(frames), duration=100, loop=0)

# যাচাই ১: GIF আবার পড়া
back = iio.imread("cyclone.gif", index=None)
meta = iio.immeta("cyclone.gif")
err = np.abs(back[..., :3].astype(int) - np.stack(frames)).mean()
print(f"cyclone.gif: {back.shape[0]} ফ্রেম, {back.shape[2]}×{back.shape[1]} px, "
      f"ফ্রেম-সময় {meta.get('duration')} ms, লুপ {meta.get('loop')}")
print(f"GIF-এ সর্বোচ্চ ২৫৬ রঙ → গড় পিক্সেল-ভুল {err:.2f} (০–২৫৫ স্কেলে)")

# যাচাই ২: ছবি থেকে ঘূর্ণনের দিক মাপা – কেন্দ্রের চারপাশে r = 35 px বৃত্তে উজ্জ্বলতা পড়ে
# পরপর দুই ফ্রেমের বৃত্তাকার cross-correlation-এর শিখর = কত ডিগ্রি ঘুরল
ang = np.deg2rad(np.arange(360))
def ring(t):
    cx, cy = centres[t]
    g = back[t, ..., :3].astype(float).mean(-1)
    px = np.clip((cx + 35 * np.cos(ang)).round().astype(int), 0, W - 1)
    py = np.clip((cy - 35 * np.sin(ang)).round().astype(int), 0, H - 1)
    v = g[py, px]; return v - v.mean()
shifts = []
for t in range(N - 1):
    a, b2 = ring(t), ring(t + 1)
    cc = np.fft.ifft(np.conj(np.fft.fft(a)) * np.fft.fft(b2)).real
    s = int(np.argmax(cc)); shifts.append(s if s <= 180 else s - 360)
# দুই বাহু থাকায় ছবি ১৮০° পরপর একই – শিফট ±৯০°-এর মধ্যে ধরা হয়
shifts = [((s + 90) % 180) - 90 for s in shifts]
m = np.median(shifts)
print(f"মাপা ঘূর্ণন: প্রতি ফ্রেমে {m:+.0f}° (সেট করা +{np.degrees(OMEGA):.0f}°) → "
      f"{'উল্টো-ঘড়ি ✓ উত্তর গোলার্ধের ঘূর্ণিঝড়' if m > 0 else 'ঘড়ির কাঁটার দিকে ✗'}")
d = np.hypot(np.diff([c[0] for c in centres]), np.diff([c[1] for c in centres])).mean()
print(f"কেন্দ্র সরেছে ফ্রেমপ্রতি {d:.2f} px উত্তর-উত্তরপূর্বে")
'''

_P_SP1 = r'''import numpy as np
import matplotlib.pyplot as plt
from scipy import signal, linalg

plt.rcParams.update({"font.family": ["Noto Sans Bengali", "DejaVu Sans"]})

# নমুনা ডেটা (কল্পিত সেন্সর, বাস্তবসম্মত মাপ): উপকূলীয় নদীর পানির উচ্চতা, ৩০ দিন, প্রতি ৫ মিনিটে
# জোয়ারের উপাদানগুলোর পর্যায়কাল জ্যোতির্বিজ্ঞান থেকে নির্দিষ্ট (ঘণ্টা):
TIDES = {"M2": (12.4206012, 1.05, 40),   # চাঁদের অর্ধ-দৈনিক: (পর্যায়কাল, বিস্তার m, দশা °)
         "S2": (12.0000000, 0.48, 75),   # সূর্যের অর্ধ-দৈনিক
         "K1": (23.9344696, 0.17, 200),  # দৈনিক
         "O1": (25.8193417, 0.08, 160)}
fs = 12                                          # ঘণ্টায় ১২টা রিডিং
t = np.arange(0, 30 * 24, 1 / fs)                # ঘণ্টা
truth = 2.8 + sum(A * np.cos(2 * np.pi * t / P - np.radians(ph)) for P, A, ph in TIDES.values())
rng = np.random.default_rng(7)
raw = truth + rng.normal(0, 0.10, t.size)        # ঢেউ/সেন্সরের noise
bad = rng.choice(t.size, 60, replace=False)
raw[bad] += rng.choice([-1, 1], 60) * rng.uniform(0.8, 2.0, 60)   # ভুল spike (পাখি, ভাসমান বস্তু…)

# ১) spike ধরা ও সরানো: চলমান median থেকে ৬×MAD-এর বেশি দূরে = spike
med = signal.medfilt(raw, kernel_size=7)
res = raw - med
mad = 1.4826 * np.median(np.abs(res))
spike = np.abs(res) > 6 * mad
despiked = np.where(spike, med, raw)
hit = np.isin(np.flatnonzero(spike), bad).sum()
print(f"spike: ঢোকানো 60টা, ধরা পড়ল {spike.sum()}টা (সঠিক {hit}, ভুল-সতর্কতা {spike.sum() - hit})")

# ২) Butterworth low-pass (৩ ঘণ্টার চেয়ে দ্রুত দোলন বাদ), filtfilt = দশা-বিকৃতি শূন্য
b, a = signal.butter(N=4, Wn=1 / 3, btype="low", fs=fs)
clean = signal.filtfilt(b, a, despiked)
w, h = signal.freqz(b, a, worN=[1 / 12.4206012, 1 / 3], fs=fs)
print(f"filtfilt-এর লাভ: M2 কম্পাঙ্কে {np.abs(h[0]) ** 2:.5f} (≈1 → জোয়ার অক্ষত), "
      f"কাট-অফে {np.abs(h[1]) ** 2:.3f} (= −৬ dB, দুবার চালানোয়)")
print(f"ভুল (RMS, আসলের তুলনায়): কাঁচা {np.sqrt(np.mean((raw - truth) ** 2)):.3f} m → "
      f"পরিষ্কার {np.sqrt(np.mean((clean - truth) ** 2)):.3f} m")

# ৩) হারমোনিক বিশ্লেষণ: least-squares দিয়ে প্রতিটা উপাদানের বিস্তার ও দশা উদ্ধার
cols = [np.ones_like(t)]
for P, _, _ in TIDES.values():
    cols += [np.cos(2 * np.pi * t / P), np.sin(2 * np.pi * t / P)]
X = np.column_stack(cols)
coef, *_ = linalg.lstsq(X, clean)
fit = {}
for k, (name, (P, A, ph)) in enumerate(TIDES.items()):
    c, s = coef[1 + 2 * k], coef[2 + 2 * k]
    fit[name] = (np.hypot(c, s), np.degrees(np.arctan2(s, c)) % 360)
    print(f"  {name}: বিস্তার {fit[name][0]:.3f} m (আসল {A:.2f}) · দশা {fit[name][1]:5.1f}° (আসল {ph})")
rayleigh = 1 / (1 / 12 - 1 / 12.4206012) / 24
print(f"M2 আর S2 আলাদা করতে অন্তত {rayleigh:.2f} দিনের রেকর্ড লাগে (Rayleigh) – আছে 30 দিন ✓")

# ৪) ভরা কটাল / মরা কটাল: দৈনিক জোয়ার-ভাটার পার্থক্য
day = (t // 24).astype(int)
rng_day = np.array([clean[day == d].max() - clean[day == d].min() for d in range(30)])
AM, AS = fit["M2"][0], fit["S2"][0]
print(f"দৈনিক পার্থক্য: সর্বোচ্চ {rng_day.max():.2f} m (দিন {rng_day.argmax() + 1}), সর্বনিম্ন {rng_day.min():.2f} m "
      f"(দিন {rng_day.argmin() + 1}) · তত্ত্ব ≈ 2(M2±S2) = {2 * (AM + AS):.2f} / {2 * (AM - AS):.2f} m · K1+O1 যোগ-বিয়োগ করে সর্বোচ্চ ±{2 * (fit['K1'][0] + fit['O1'][0]):.2f} m")

peaks, _ = signal.find_peaks(clean, distance=fs * 10)
print(f"৩০ দিনে জোয়ারের চূড়া {len(peaks)}টা · গড় ব্যবধান {np.diff(t[peaks]).mean():.2f} ঘণ্টা (M2 = 12.42)")

# ৫) শোকেস চার্ট
BG, INK, MUTE, ACC, PINK, GOLD = "#0b0820", "#f3efff", "#a59fc4", "#2dd4bf", "#f472b6", "#f59e0b"
fig = plt.figure(figsize=(13, 7.4), facecolor=BG)
ax = fig.add_axes([0.05, 0.50, 0.92, 0.32], facecolor=BG)
ax.plot(t / 24, clean, color=ACC, lw=.7)
dphi = np.radians(fit["S2"][1] - fit["M2"][1])
env = np.abs(AM + AS * np.exp(1j * (2 * np.pi * t * (1 / 12 - 1 / 12.4206012) - dphi)))
ax.plot(t / 24, 2.8 + env, color=GOLD, lw=1, ls="--"); ax.plot(t / 24, 2.8 - env, color=GOLD, lw=1, ls="--")
for d in (rng_day.argmax(), rng_day.argmin()):
    lab = "ভরা কটাল" if d == rng_day.argmax() else "মরা কটাল"
    ax.annotate(f"{lab}\nদিন {d + 1}: {rng_day[d]:.2f} m", (d + .5, clean[day == d].max()), xytext=(0, 14),
                textcoords="offset points", ha="center", color=INK, fontsize=9,
                arrowprops=dict(arrowstyle="-", color=MUTE, lw=.8))
ax.set_xlim(0, 30); ax.set_ylim(0.6, 5.4)
ax.set_xlabel("দিন", color=MUTE, fontsize=9); ax.set_ylabel("উচ্চতা (m)", color=MUTE, fontsize=9)
ax.text(0, 1.06, "30 দিন, filter-এর পর – সোনালি রেখা = M2+S2 থেকে হিসাব করা খাম", transform=ax.transAxes,
        color=INK, fontsize=11, weight="bold")

ax2 = fig.add_axes([0.05, 0.08, 0.55, 0.30], facecolor=BG)
z = (t >= 96) & (t < 132)
ax2.plot(t[z], raw[z], ".", color=MUTE, ms=2, alpha=.6)
zs = z & spike
ax2.plot(t[zs], raw[zs], "o", mfc="none", mec=PINK, ms=7, mew=1.4)
ax2.plot(t[z], clean[z], color=ACC, lw=2)
pz = peaks[(t[peaks] >= 96) & (t[peaks] < 132)]
ax2.plot(t[pz], clean[pz], "v", color=GOLD, ms=8)
ax2.text(0, 1.06, "36 ঘণ্টা কাছ থেকে: ধূসর = কাঁচা, গোলাপি বৃত্ত = ধরা পড়া spike, ▼ = জোয়ার", transform=ax2.transAxes,
         color=INK, fontsize=11, weight="bold")
ax2.set_xlabel("ঘণ্টা", color=MUTE, fontsize=9)

ax3 = fig.add_axes([0.68, 0.08, 0.29, 0.30], facecolor=BG)
names = list(TIDES); x = np.arange(len(names))
ax3.bar(x - .18, [TIDES[n][1] for n in names], .34, color="#4c3d7a")
ax3.bar(x + .18, [fit[n][0] for n in names], .34, color=ACC)
for i, n in enumerate(names):
    ax3.text(i + .18, fit[n][0] + .03, f"{fit[n][0]:.2f}", color=INK, fontsize=8.5, ha="center")
ax3.set_xticks(x, names)
ax3.text(0, 1.06, "বিস্তার: আসল (বেগুনি) বনাম উদ্ধার (সবুজ)", transform=ax3.transAxes, color=INK, fontsize=11, weight="bold")
for a_ in (ax, ax2, ax3):
    for s_ in a_.spines.values(): s_.set_visible(False)
    a_.tick_params(colors=MUTE, labelsize=8.5)
    a_.grid(color="#2a2346", lw=.6); a_.set_axisbelow(True)

errM = abs(fit["M2"][0] - TIDES["M2"][1]) / TIDES["M2"][1] * 100
fig.text(0.05, 0.935, f"60টা spike আর noise সত্ত্বেও M2 জোয়ারের বিস্তার উদ্ধার {fit['M2'][0]:.3f} m – ভুল {errM:.1f} %",
         color=INK, fontsize=16, weight="bold")
fig.text(0.05, 0.895, f"নমুনা ডেটা · median+MAD দিয়ে spike, Butterworth filtfilt (কাট-অফ 3 ঘণ্টা), least-squares হারমোনিক ফিট · "
         f"ভরা/মরা কটালের চক্র {rayleigh:.2f} দিন", color=MUTE, fontsize=10)
fig.savefig("river_tide.png", dpi=150, facecolor=BG)
plt.close(fig)
print("river_tide.png সেভ হয়েছে ✔")
'''


