_P_SK2 = r'''import numpy as np
import matplotlib.pyplot as plt
from scipy import ndimage as ndi
from skimage import data, filters, measure, segmentation, color

plt.rcParams.update({"font.family": ["Noto Sans Bengali", "DejaVu Sans"]})

coins = data.coins()                                     # ২৪টা মুদ্রার নমুনা ছবি
elevation = filters.sobel(coins)                         # কিনারা = "পাহাড়ের চূড়া"
otsu = filters.threshold_otsu(coins)
markers = np.zeros_like(coins)
markers[coins < 30] = 1                                  # নিশ্চিত পটভূমি (খুব অন্ধকার)
markers[coins > 150] = 2                                 # নিশ্চিত মুদ্রা (খুব উজ্জ্বল)
print(f"চিহ্ন দেওয়া পিক্সেল: পটভূমি {100 * (markers == 1).mean():.1f} %, মুদ্রা {100 * (markers == 2).mean():.1f} %, "
      f"বাকি {100 * (markers == 0).mean():.1f} % ঠিক করবে watershed")
seg = segmentation.watershed(elevation, markers)         # চিহ্ন থেকে পানি ভরা – কিনারায় এসে থামে
mask = ndi.binary_fill_holes(seg == 2)
def drop_small(m, n=60):                                 # ≤ n পিক্সেলের টুকরো বাদ (সব skimage সংস্করণে একই)
    lab = measure.label(m)
    keep = np.bincount(lab.ravel()) > n; keep[0] = False
    return keep[lab]
mask = drop_small(mask)
labels = measure.label(mask)

# তুলনা: শুধু Otsu থ্রেশহোল্ড দিলে কী হতো?
naive = measure.label(drop_small(coins > otsu))
# প্রতিটা watershed-মুদ্রার সাথে Otsu-র সবচেয়ে ভালো মেলানো টুকরোর IoU (ছেদ ÷ মিলন)
iou = []
for r in measure.regionprops(labels):
    w = labels == r.label
    ids = [i for i in np.unique(naive[w]) if i > 0]
    iou.append(max([(w & (naive == i)).sum() / (w | (naive == i)).sum() for i in ids], default=0))
iou = np.array(iou)
good = int((iou > 0.8).sum())
print(f"Otsu-র টুকরো কোনো মুদ্রার সাথে ভালোভাবে মেলে (IoU > 0.8): {good}/{labels.max()} · সবচেয়ে খারাপ IoU {iou.min():.2f}")
props = measure.regionprops(labels)
d = np.array([r.equivalent_diameter_area for r in props])
ecc = np.array([r.eccentricity for r in props])
print(f"watershed: {labels.max()}টা মুদ্রা (আসল 24) · শুধু Otsu (সীমা {otsu:.0f}): {naive.max()}টা টুকরো")
print(f"ব্যাস {d.min():.1f}–{d.max():.1f} px, গড় {d.mean():.1f} · eccentricity মধ্যমা {np.median(ecc):.2f} (বৃত্তে ০)")

fig, axes = plt.subplots(1, 4, figsize=(18, 5.4), facecolor="white")
axes[0].imshow(coins, cmap="gray")
axes[0].set_title("১ · আসল ছবি", fontweight="bold", loc="left")
axes[1].imshow(elevation, cmap="magma")
axes[1].set_title("২ · Sobel: কিনারা = উঁচু পাহাড়", fontweight="bold", loc="left")
axes[2].imshow(segmentation.mark_boundaries(coins, labels, color=(0.49, 0.23, 0.93), mode="thick"))
axes[2].set_title("৩ · watershed-এর সীমানা", fontweight="bold", loc="left")
axes[3].imshow(color.label2rgb(labels, image=coins, bg_label=0, alpha=0.45))
for r in props:
    y, x = r.centroid
    axes[3].text(x, y, str(r.label), color="white", ha="center", va="center", fontsize=9, fontweight="bold")
axes[3].set_title(f"৪ · {labels.max()}টা মুদ্রা, নম্বরসহ", fontweight="bold", loc="left")
for ax in axes:
    ax.set_axis_off()
ok = "✓" if labels.max() == 24 else "✗"
fig.suptitle(f"watershed আলাদা করল {labels.max()}টা মুদ্রা (আসল 24 {ok}) – শুধু Otsu থ্রেশহোল্ডে ঠিক মেলে {good}টা",
             fontsize=17, fontweight="bold", x=0.01, ha="left")
fig.text(0.01, 0.865, f"চিহ্ন: <30 = পটভূমি, >150 = মুদ্রা · মাঝের {100 * (markers == 0).mean():.0f} % পিক্সেলের ভাগ্য ঠিক করে "
         f"Sobel-পাহাড় · Otsu-তে সবচেয়ে খারাপ মুদ্রার IoU মাত্র {iou.min():.2f} · ব্যাস {d.min():.0f}–{d.max():.0f} px",
         fontsize=11, color="#6b6680")
plt.tight_layout(rect=(0, 0, 1, 0.86))
plt.show()
'''
_P_SK3 = r'''import numpy as np
import matplotlib.pyplot as plt
from scipy import ndimage as ndi
from skimage import color, data, exposure, filters, transform

plt.rcParams.update({"font.family": ["Noto Sans Bengali", "DejaVu Sans"]})

img = data.astronaut()                       # ৫১২×৫১২ রঙিন নমুনা ছবি
gray = color.rgb2gray(img)

hsv = color.rgb2hsv(img)
hsv[..., 0] = (hsv[..., 0] + 0.45) % 1.0     # রঙের চাকা ০.৪৫ পাক = ১৬২° ঘোরানো
hue_shift = color.hsv2rgb(hsv)
poster = (np.floor(img / 64) * 64 + 32).astype(np.uint8)     # প্রতি চ্যানেলে ৪টা ধাপ
edges = filters.sobel(gray)
clahe = exposure.equalize_adapthist(img, clip_limit=0.03)
swirl = transform.swirl(img, center=(220, 260), strength=8, radius=220)

# যাচাই – প্রতিটা ফিল্টার যা করার কথা তাই করেছে কি?
n0 = len(np.unique(img.reshape(-1, 3), axis=0))
n1 = len(np.unique(poster.reshape(-1, 3), axis=0))
print(f"আলাদা রঙ: আসলে {n0:,}টা → পোস্টারে {n1}টা (সর্বোচ্চ 4³ = 64)")
h0, h1 = color.rgb2hsv(img)[..., 0], color.rgb2hsv(hue_shift)[..., 0]
sat = color.rgb2hsv(img)[..., 1] > 0.2                       # ধূসর পিক্সেলে hue অর্থহীন
dh = np.angle(np.mean(np.exp(2j * np.pi * (h1 - h0)[sat]))) / (2 * np.pi) * 360 % 360
print(f"মাপা hue ঘূর্ণন (বৃত্তাকার গড়): {dh:.1f}° (সেট করা 162°)")
def local_contrast(g, k=15):                                 # k×k জানালায় উজ্জ্বলতার std-র গড়
    m = ndi.uniform_filter(g, k)
    return np.sqrt(np.clip(ndi.uniform_filter(g * g, k) - m * m, 0, None)).mean()
c0, c1 = local_contrast(gray), local_contrast(color.rgb2gray(clahe))
print(f"স্থানীয় কনট্রাস্ট (15×15 জানালা): আসল {c0:.4f} → CLAHE {c1:.4f} ({100 * (c1 / c0 - 1):+.0f} %) · "
      f"পুরো ছবির std {gray.std():.3f} → {color.rgb2gray(clahe).std():.3f} (CLAHE বাড়ায় স্থানীয়টা)")
print(f"Sobel: কিনারার মধ্যমা {np.median(edges):.4f}, শীর্ষ 1 % > {np.quantile(edges, .99):.3f}")
# skimage-এর swirl: দূরত্ব ρ-তে ঘোরার কোণ = strength · exp(−ρ / (ln2 · radius / 5))
for rho in (0, 50, 100, 220):
    print(f"  swirl ρ = {rho:3d} px → ঘোরে {np.degrees(8 * np.exp(-rho / (np.log(2) * 220 / 5))):7.2f}°")

panels = [
    ("আসল", img, None),
    ("Sobel কিনারা", edges, "magma"),
    (f"CLAHE: স্থানীয় কনট্রাস্ট {100 * (c1 / c0 - 1):+.0f} %", clahe, None),
    (f"ঘূর্ণি: কেন্দ্রে {np.degrees(8):.0f}°, 220 px দূরে {np.degrees(8 * np.exp(-5 / np.log(2))):.1f}°", swirl, None),
    (f"পোস্টার: {n0:,} → {n1}টা রঙ", poster, None),
    (f"রঙ ঘোরানো {dh:.0f}°", hue_shift, None),
]
fig, axes = plt.subplots(2, 3, figsize=(15, 11.4), facecolor="white")
for ax, (title, im, cmap) in zip(axes.flat, panels):
    ax.imshow(im, cmap=cmap)
    ax.set_title(title, fontsize=14, fontweight="bold", loc="left")
    ax.set_axis_off()
fig.suptitle("একটা ছবি, ছয়টা ফিল্টার – প্রতিটার ফল সংখ্যায় মেপে দেখা", fontsize=21, fontweight="bold", x=0.01, y=0.985, ha="left")
fig.subplots_adjust(left=.01, right=.99, top=.915, bottom=.01, wspace=.04, hspace=.1)
plt.show()
'''
_P_CV2X = r'''import cv2
import numpy as np
import matplotlib.pyplot as plt
from skimage import data            # শুধু নমুনা ছবির জন্য; নিজের ছবি হলে cv2.imread("cat.jpg")

plt.rcParams.update({"font.family": ["Noto Sans Bengali", "DejaVu Sans"]})

img = cv2.cvtColor(data.chelsea(), cv2.COLOR_RGB2BGR)

# কার্টুন: রং মসৃণ করা (bilateral = কিনারা রেখে ঝাপসা) + মোটা কালো কিনারা
smooth = img.copy()
for _ in range(5):
    smooth = cv2.bilateralFilter(smooth, d=9, sigmaColor=40, sigmaSpace=9)
gray = cv2.medianBlur(cv2.cvtColor(img, cv2.COLOR_BGR2GRAY), 7)
edges = cv2.adaptiveThreshold(gray, 255, cv2.ADAPTIVE_THRESH_MEAN_C, cv2.THRESH_BINARY, 9, 4)
cartoon = cv2.bitwise_and(smooth, smooth, mask=edges)

sketch_gray, sketch_color = cv2.pencilSketch(img, sigma_s=60, sigma_r=0.07, shade_factor=0.06)
painting = cv2.stylization(img, sigma_s=80, sigma_r=0.45)
detail = cv2.detailEnhance(img, sigma_s=12, sigma_r=0.2)

# প্রতিটা ইফেক্টে টেক্সচার কতটা বদলাল: Laplacian-ভ্যারিয়েন্স (বড় = বেশি সূক্ষ্ম খুঁটিনাটি)
def texture(im):
    g = im if im.ndim == 2 else cv2.cvtColor(im, cv2.COLOR_BGR2GRAY)
    return cv2.Laplacian(g, cv2.CV_64F).var()

def lab_chroma(im):            # রঙের তীব্রতা (CIELAB-এর a,b দূরত্ব)
    lab = cv2.cvtColor(im, cv2.COLOR_BGR2LAB).astype(float)
    return np.hypot(lab[..., 1] - 128, lab[..., 2] - 128).mean()

base = texture(img)
panels = [("আসল", img), ("কার্টুন", cartoon), ("পেন্সিল স্কেচ", sketch_gray),
          ("রঙিন পেন্সিল", sketch_color), ("তেলরঙ (stylization)", painting), ("খুঁটিনাটি বাড়ানো", detail)]
print(f"{'ইফেক্ট':<22}{'টেক্সচার':>10}{'আসলের তুলনায়':>15}")
for name, im in panels:
    print(f"{name:<22}{texture(im):>10.0f}{texture(im) / base:>14.2f}×")
print(f"কার্টুনে কালো কিনারা: {100 * (edges == 0).mean():.1f} % পিক্সেল · bilateral-এর পর টেক্সচার "
      f"{texture(smooth) / base:.2f}× (রং সমান হয়েছে, কিনারা রয়ে গেছে)")
print(f"রঙের তীব্রতা (LAB chroma): আসল {lab_chroma(img):.1f} → খুঁটিনাটি বাড়ানো {lab_chroma(detail):.1f} "
      f"(detailEnhance টেক্সচার বাড়ায়, রঙ প্রায় একই রাখে)")
print("মনে রাখো: কার্টুন/স্কেচে টেক্সচার-মান বড় কারণ মোটা কালো রেখা আঁকা হয় – এটা 'বেশি খুঁটিনাটি' নয়")

fig, axes = plt.subplots(2, 3, figsize=(15, 8.5), facecolor="white")
for ax, (title, im) in zip(axes.flat, panels):
    shown = im if im.ndim == 2 else cv2.cvtColor(im, cv2.COLOR_BGR2RGB)
    ax.imshow(shown, cmap="gray" if im.ndim == 2 else None)
    ax.set_title(title, fontsize=14, fontweight="bold", loc="left")
    ax.set_axis_off()
k_sm = texture(smooth) / base
fig.suptitle(f"কার্টুনের রহস্য: bilateral 5 বার চালিয়ে সূক্ষ্ম টেক্সচার {k_sm:.2f}× – তারপর {100 * (edges == 0).mean():.0f} % পিক্সেলে কালো রেখা",
             fontsize=18, fontweight="bold", x=0.01, y=0.985, ha="left")
fig.text(0.01, 0.92, f"টেক্সচার = Laplacian-ভ্যারিয়েন্স · খুঁটিনাটি বাড়ানো {texture(detail) / base:.1f}× · "
         f"তেলরঙ {texture(painting) / base:.2f}× · রঙের তীব্রতা (LAB) {lab_chroma(img):.1f} → {lab_chroma(detail):.1f}",
         fontsize=11, color="#6b6680")
fig.subplots_adjust(left=.01, right=.99, top=.85, bottom=.01, wspace=.04, hspace=.14)
plt.show()
'''
_P_PD2 = r'''import numpy as np
import pandas as pd
import matplotlib.pyplot as plt

plt.rcParams.update({"font.family": ["Noto Sans Bengali", "DejaVu Sans"]})

# কল্পিত শেয়ারের দাম (নমুনা ডেটা): দৈনিক রিটার্ন ~ N(0.06 %, 1.7 %), মাঝে ৪০ দিনের পতন
rng = np.random.default_rng(21)
dates = pd.bdate_range("2025-01-01", periods=320)       # শুধু কর্মদিবস
ret = rng.normal(0.0006, 0.017, len(dates))
ret[150:190] -= 0.006                                   # একটা পতনের সময়
df = pd.DataFrame({"close": 100 * np.exp(np.cumsum(ret)),
                   "volume": rng.gamma(4, 2.5e5, len(dates))}, index=dates)

df["ma20"] = df["close"].rolling(20).mean()
df["ma50"] = df["close"].rolling(50).mean()
std = df["close"].rolling(20).std()
df["upper"], df["lower"] = df["ma20"] + 2 * std, df["ma20"] - 2 * std
peak = df["close"].cummax()
drawdown = df["close"] / peak - 1
trough = drawdown.idxmin()
start = df.loc[:trough, "close"].idxmax()

# যাচাই ১: সর্বোচ্চ পতন – cummax-এর ফল বনাম সব (i ≤ j) জোড়া পরীক্ষা
c = df["close"].to_numpy()
brute = min(c[j] / c[:j + 1].max() - 1 for j in range(len(c)))
print(f"সর্বোচ্চ পতন: {drawdown.min():.2%} ({start.date()} → {trough.date()}, {len(df.loc[start:trough]) - 1} কর্মদিবস) · "
      f"সব জোড়া পরীক্ষায় {brute:.2%} ✓")
# যাচাই ২: বার্ষিক অস্থিরতা – লগ-রিটার্নের std × √252 বনাম সেট করা 1.7 % × √252
lr = np.log(df["close"]).diff().dropna()
se = 0.017 * np.sqrt(252) / np.sqrt(2 * len(lr))             # std-অনুমানের প্রত্যাশিত ভুল σ/√(2n)
print(f"বার্ষিক অস্থিরতা: মাপা {lr.std() * np.sqrt(252):.1%}, সেট করা {0.017 * np.sqrt(252):.1%} "
      f"(n = {len(lr)} দিনে প্রত্যাশিত নমুনা-ভুল ±{se:.1%}, বিচ্যুতি {(lr.std() * np.sqrt(252) - 0.017 * np.sqrt(252)) / se:+.1f}σ)")
# যাচাই ৩: বলিঙ্গার ব্যান্ডের ভেতরে কত দিন? (স্বাভাবিক বণ্টনে ±2σ ≈ 95 %, কিন্তু দাম স্বাধীন নয়)
ok = df["upper"].notna()
inside = ((df["close"] >= df["lower"]) & (df["close"] <= df["upper"]))[ok].mean()
print(f"ব্যান্ডের ভেতরে: {inside:.1%} দিন (ব্যান্ড চলমান গড় থেকে মাপা, তাই 95 % থেকে আলাদা হতে পারে)")
cross = np.sign(df["ma20"] - df["ma50"]).diff().fillna(0)
print(f"20/50 দিনের গড়ের ছেদ: {int((cross > 0).sum())} বার ওপরে, {int((cross < 0).sum())} বার নিচে")

fig, (ax, axv) = plt.subplots(2, 1, figsize=(13, 7.8), sharex=True,
                              height_ratios=[3.2, 1], facecolor="white")
ax.fill_between(df.index, df["lower"], df["upper"], color="#7c3aed", alpha=0.10, lw=0)
ax.plot(df.index, df["close"], color="#140e29", lw=1.5)
ax.plot(df.index, df["ma20"], color="#7c3aed", lw=1.4)
ax.plot(df.index, df["ma50"], color="#d97706", lw=1.9)
ax.axvspan(start, trough, color="#e11d48", alpha=0.07, lw=0)
end = df.index[-1]
labels = sorted([(df[c_].iloc[-1], lab, colr) for c_, lab, colr in
                 [("close", "দাম", "#140e29"), ("ma20", "২০ দিনের গড়", "#7c3aed"), ("ma50", "৫০ দিনের গড়", "#d97706")]])
ys = [labels[0][0]]
for v, _, _ in labels[1:]:
    ys.append(max(v, ys[-1] + 3.2))                    # লেবেল যেন একটার ওপর আরেকটা না পড়ে
for (v, lab, colr), y in zip(labels, ys):
    ax.annotate(lab, (end, v), xytext=(end + pd.Timedelta(days=6), y), color=colr, fontsize=10,
                fontweight="bold", va="center")
ax.text(df.index[25], df["upper"].iloc[25] + 3, "বলিঙ্গার ব্যান্ড (±2σ)", color="#7c3aed", fontsize=9.5)
ax.annotate(f"সর্বোচ্চ পতন {drawdown.min():.0%}", xy=(trough, df.loc[trough, "close"]),
            xytext=(start + pd.Timedelta(days=90), df["close"].min() - 1), ha="left", va="center",
            arrowprops=dict(arrowstyle="->", color="#e11d48"), color="#e11d48", fontweight="bold")
ax.set_ylabel("দাম (৳)")
ax.grid(color="#eee")
ax.set_xlim(df.index[0], end + pd.Timedelta(days=40))

up = df["close"].diff() >= 0
axv.bar(df.index, df["volume"] / 1e6, color=np.where(up, "#0d9488", "#e11d48"), width=1.0)
axv.set_ylabel("ভলিউম (মিলিয়ন)")
axv.text(0, 1.04, "সবুজ = দাম বাড়ার দিন, লাল = কমার দিন", transform=axv.transAxes, fontsize=9, color="#6b6680")
for a in (ax, axv):
    for s in ("top", "right", "left"):
        a.spines[s].set_visible(False)
ax.set_title(f"কল্পিত শেয়ার: চূড়া থেকে {len(df.loc[start:trough]) - 1} কর্মদিবসে {-drawdown.min():.0%} পতন – চলমান গড়, বলিঙ্গার ব্যান্ড ও ভলিউম",
             loc="left", fontsize=17, fontweight="bold", pad=28)
ax.text(0, 1.03, f"নমুনা ডেটা · বার্ষিক অস্থিরতা {lr.std() * np.sqrt(252):.0%} · {inside:.0%} দিন বলিঙ্গার ব্যান্ডের ভেতরে · "
        f"pandas rolling(), cummax()", transform=ax.transAxes, fontsize=10, color="#6b6680")
plt.tight_layout()
plt.show()
'''

